    "summary": "쇼와 40년대부터 50년대 초, 일본 전역이 안보 문제와 오일쇼크로 골머리를 앓고 있던 무렵이었다. 중간 정도의 키와 체격, 둥근 얼굴에 참으로 성실해 보이는 한 남자가, 장내를 가득 메워 넘칠 듯한 청중 앞에서 무슨 뜻인지 알 수 없는 말, 이른바 ...",
    "body": "쇼와 40년대부터 50년대 초, 일본 전역이 안보 문제와 오일쇼크로 골머리를 앓고 있던 무렵이었다. 중간 정도의 키와 체격, 둥근 얼굴에 참으로 성실해 보이는 한 남자가, 장내를 가득 메워 넘칠 듯한 청중 앞에서 무슨 뜻인지 알 수 없는 말, 이른바 ‘이고(異語·いごん)’로 상대에게 질문하고 있었다. 상대도 그와 똑같은 종류의 말로 대답했다. 장내에서는 기침 소리 하나 들리지 않았다. 사람들은 기이하다는 듯 그 광경을 숨죽여 지켜보았다. 물론 두 사람이 무슨 이야기를 나누는지는 아무도 알지 못했다.\n\n잠시 뒤 남자가 일본어로 풀이해 주면, 그제야 회장에 있던 사람들도 “과연 그렇구나” 하며 이해할 수 있었다.\n\n남자는 상대 쪽으로 몸을 돌려 한쪽 손바닥을 머리 위에서 내리비추듯 펼치기도 하고, 조금 떨어진 자리에서 조용히 원을 그리기도 했다. 알 수 없는 말은 계속 이어졌다.\n\n그러자 상대는 북받치는 감정을 더는 억누를 수 없었던지, 둑이 터지듯 마음속 생각을 쏟아내기 시작했다.\n\n“붓·다―.” 쥐어짜는 듯한 목소리가 장내 가득 퍼졌다.\n\n그리고 매달리기라도 하듯 엎드려 손을 내밀며 외쳤다.\n\n“관자재자 붓다―.” 남자가 말했다.\n\n“그대는 용케도 나를 찾아와 주었습니다. 이번 생에도 다시 함께해 나갑시다….” 남자도 손수건을 눈에 대고 있었다. 회장 안에서도 흐느끼는 소리가 들렸다.\n\n“리야 오 에레… 소레 포코라… 파니야 인다….” 곧이어 남자의 해설이 붙었다. 한 단락이 끝났을 때 남자는 이렇게 말했다.\n\n“잘생긴 얼굴이 이렇게 돼 버렸네요….” 그가 쑥스러운 듯 웃자 회장에서도 웃음이 터졌다.\n\n“거짓말이 아닙니다. 진실입니다. 정말입니다. 여러분도 모두 과거에 태어나 살았던 체험을 지니고 있습니다. 여러분 마음의 실타래를 하나씩 풀어 가면 그 모든 것을 알 수있습니다…. 옷깃만 스쳐도 타생의 인연이라 하지요! 감사합니다.”\n\n그러자 장내는 술렁임과 박수의 소용돌이에 휩싸였다. 남자의 설명에 따르면 사람은 태어나고 죽기를 거듭하며, 2,500년 전 고대 인도 시대에 인연이 있었던 사람들이 시공을 넘어 다시 만났을 때는 그리움이 북받쳐 어찌할 수 없다고 한다.\n\n또한 영혼은 영원하여 죽는 일 없이 계속 살아가므로, 지금의 자신이 올바르게 살지 않는다면 저세상에서든 다음에 지상계에 태어났을 때든 반드시 이치가 맞게 된다고 했다. 남에게는 거짓말을 할 수 있어도 자기 자신에게는 거짓말할 수 없는 ‘선아(善我)’의 자기가 모든 것을 심판하고 철저히 반성하게 만든다는 말로 남자는 이야기를 맺었다.",
    "notes": "번역·제작 메모\n\n• 異語・いごん은 원문 고유 표현이므로 첫 등장에서는 일본어 표기를 병기했다.\n\n• 원문의 袖すり合うも多少の縁은 통상적인 속담 袖すり合うも他生の縁과 동음인 표현이다. 한국어에서는 뜻이 전달되도록 “옷깃만 스쳐도 타생의 인연”으로 옮겼다.\n\n• 초자연적 체험을 객관적 사실로 단정하지 말고 “이 기록은 이렇게 전한다”는 서술 틀을 유지한다.",
