    "summary": "그리고 놀랍게도 쇼와 51년(1976년) 6월, 자신이 예언한 죽음을 바로 앞둔 때에 남자는 이런 말까지 거듭 쏟아냈다. “나는 3억 6천5백만 년 전에 일곱 대천사와 함께 이 지구로 날아온 중심령 엘 란티이다.” 또 이렇게 말했다. “모세가 설한 유...",
    "body": "그리고 놀랍게도 쇼와 51년(1976년) 6월, 자신이 예언한 죽음을 바로 앞둔 때에 남자는 이런 말까지 거듭 쏟아냈다.\n\n“나는 3억 6천5백만 년 전에 일곱 대천사와 함께 이 지구로 날아온 중심령 엘 란티이다.” 또 이렇게 말했다.\n\n“모세가 설한 유대교, 석가가 설한 불교, 예수가 설한 기독교, 아마테라스 오미카미가 설한 고신도(현대의 신사신도가 아니다), 마호메트가 설한 이슬람교를 하나로 만들기 위해 육신을 받은 것이다.” 그뿐만이 아니었다.\n\n“신리(神理)는 하나이며, 잘못된 종교를 바로잡는 데 나의 사명이 있었다.”\n\n이처럼 엄청난 말을 남기고 세상을 떠난 남자가 있었다.\n\n“붓다니 엘 란티니, 일본의 동화(同和) 문제에 빛을 밝히기 위해서라니, 농담도 정도껏 하라고 해.”\n\n“영혼이 영원하다고…?”\n\n“저세상이라고… 죽으면 그걸로 끝인 게 당연하잖아.”\n\n“이 빌어먹을 자식!” 남자가 전도를 시작한 뒤부터 이런 온갖 욕설이 어디선가 들려왔다.\n\n그러나 남자는 자신만만하게 다시 말했다.\n\n“곧바로 믿어서는 안 됩니다. 의심하고 또 의심하여 끝까지 철저히 의심하십시오. 더는 의심할 여지가 없어졌을 때, 그때 믿으십시오.” 성경의 구절을 끌어다가 남의 말을 되풀이하며 흉내 내는 강연자가 많은 가운데, 이 남자의 입에서 튀어나오는 말은 모두 기상천외했다. 지금까지 단 한 번도 들어 본 적 없는 이야기의 연속이었다. 그러는 사이 한 사람, 두 사람씩 모여들어 남자의 강연장은 언제나 초만원을 이루었다.\n\n마침내는 기존 신흥종교 한 곳이 2만 명 혹은 3만 명이라고 하던 신자들을 이끌고 소속을 바꾸었다. 작은 단체가 큰 종교단체를 흡수한 전대미문의 합병극이 벌어져 종교계를 깜짝 놀라게 하기도 했다.\n\n남자는 그 밖에도 산더미처럼 많은 ‘엄청난 이야기’를 남겼다. 수많은 저서와 강연 영상, 녹음테이프, 그리고 강연을 들으러 온 사람들의 마음에 많은 신리를 새기고, 예언한 대로 쇼와 51년(1976년) 6월, 48세 9개월의 젊은 나이로 생을 마쳤다. 이 낯선 남자의 이름은 다카하시 신지. 편집자는 이 남자야말로 석가와 예수와 모세의 본체이며, 지구 창생기에 일곱 대천사와 함께 날아온 참된 메시아, 곧 참된 구세주 엘 란티였다고 말한다.",
    "notes": "번역·제작 메모\n\n• 同和問題는 일본의 부락 차별 문제를 가리킬 때 사용된 표현이다. 쇼츠에서는 배경 설명 없이 단어만 제시하면 오해하기 쉬우므로 짧은 화면 주석이 필요하다.\n\n• 마지막 문장은 다카하시 본인의 인적 약력이 아니라 편집자의 신앙적 결론이다.\n\n• 1976년 6월 25일 사망은 GLA의 현재 공개 약력에서도 확인되지만, 엘 란티 및 환생에 관한 문장은 종교적 주장으로 구분한다.",
