    "contentType": "웹마스터의 집필 경위 + 단체 내부 사정에 관한 회고 + 출생 약력",
    "summary": "웹마스터의 혼잣말웹마스터가 이런 첫머리로 시작한 원고를 소노가시라 히로치카(園頭広周) 선생에게 내놓은 것은 헤이세이 초, 후쿠오카 근교 스센지(周船寺)에 있는 도장 부지를 답사하던 때였다. 선생이 세상을 떠난 지금에 와서는 ‘그것도 물어볼걸, 이것도 ...",
    "body": "웹마스터의 혼잣말웹마스터가 이런 첫머리로 시작한 원고를 소노가시라 히로치카(園頭広周) 선생에게 내놓은 것은 헤이세이 초, 후쿠오카 근교 스센지(周船寺)에 있는 도장 부지를 답사하던 때였다. 선생이 세상을 떠난 지금에 와서는 ‘그것도 물어볼걸, 이것도 물어볼걸’ 하는 여러 생각이 머릿속을 맴돈다. 그러나 다카하시 신지 선생과 소노가시라 히로치카 선생, 두 대천사가 모두 떠난 뒤에는 우리라도 지혜를 짜내 할 수 있는 방법으로 그 뜻을 이어 가야 한다. 두 선생이 남긴 방대한 정법 자료와 진리·신리의 가르침을 하나도 빠짐없이 인류 공동의 자산으로 공개할 생각이다. 소노가시라 선생이 세상을 떠난 뒤, 회원이 얼마 남지 않은 국제정법협회도 ‘감사의 모임’과 ‘무슨무슨 신교육’이라는 두 갈래로 나뉘었다. 그런 가운데 「인간 다카하시 신지」 원고는 ‘감사의 모임’ 회지에 연재되게 되었다. 그런데 다카하시 신지 선생을 ‘신지는’ 또는 ‘다카하시는’ 하고 존칭 없이 쓴 것이 그들의 노여움을 산 듯했다. 인류의 각자에게 ‘선생’이나 ‘사(師)’ 같은 존칭을 붙이면 연재를 계속하겠다는 조건이었으므로, 웹마스터가 즉시 거절했고 결국 연재는 중단될 수밖에 없었다. 주인공에게 존칭을 붙이지 않는 것은 서술의 세계에서는 상식이다. ‘어쩌면 저렇게 속이 좁을까’ 하며 한동안 분개했으나, 이것도 내 마음을 닦는 수행인가 싶어 5년의 공백 끝에 생각을 바꾸었다. 웹마스터도 공부하는 셈 치고 존칭과 경칭을 갖추어 정중하게 써 보려 한다. 놀라운 출생의 비밀일본 전역에 금융공황이 몰아치던 쇼와 2년(1927년), 여름이 끝나고 고원의 산들바람이 뺨을 어루만지던 9월 24일, 옥처럼 귀한 사내아이가 태어났다. 많은 가족에게 둘러싸여 유난히 귀하게 자랐다고 한다. 사륜구동차와 캠핑객들이 모여 여름밤의 소란을 일으키는 바람에 눈살을 찌푸리는 주민도 많다는 곳, 아사마 산바람이 부는 신슈 사쿠 고원의 한쪽, 나카고미 마을이었다. 어려서 세상을 떠난 두 아이를 제외하면 열 자녀 가운데 남자 셋, 여자 일곱의 한가운데였으며, 다카하시 신지 선생은 가난한 농가의 둘째 아들로 태어났다. 본명은 하루오(治男, 또는 春男로도 표기됨)였다. 성인이 된 뒤 신지로 이름을 바꾸었다. 같은 지역에 같은 성과 이름을 가진 사람이 있어 우편물 등이 뒤섞였기 때문인 듯하다.",
    "notes": "번역·제작 메모\n\n• 원문은 출생일을 9월 24일로 적는다. 공개 약력에서 다른 날짜가 제시되는 경우가 있어, 영상 자막에 정확한 일자를 넣기 전에는 별도 사료 확인이 필요하다. 보존 번역에서는 원문을 바꾸지 않았다.\n\n• 이 항목에는 ‘집필을 둘러싼 내부 사정’과 ‘출생’이라는 서로 다른 사건이 들어 있어 쇼츠 두 편으로 나누는 편이 자연스럽다.",
