    "title": "신지 선생의 어머니를 찾아가다",
    "origTitle": "",
    "contentType": "소노가시라 히로치카 일행의 방문 회고 + 어머니의 직접 증언으로 소개된 문장 + 우연한 사건에 관한 편집자",
    "summary": "이 글의 저자에게 정법을 가르친 스승은 전 국제정법협회 회장 소노가시라 히로치카였다. 그는 쇼와 55년(1980년) 신지 선생의 생가를 찾아갔다. 그때 82세였던 어머니는 새로 지은 집에 혼자 살며 안경도 보청기도 없이 바느질을 하고 있었다고 한다. ...",
    "body": "이 글의 저자에게 정법을 가르친 스승은 전 국제정법협회 회장 소노가시라 히로치카였다. 그는 쇼와 55년(1980년) 신지 선생의 생가를 찾아갔다.\n\n그때 82세였던 어머니는 새로 지은 집에 혼자 살며 안경도 보청기도 없이 바느질을 하고 있었다고 한다. 회장 일행이 신지 선생에 관해 여러 이야기를 듣는 동안, 어머니는 자꾸 대화를 끊고 안쪽으로 들어갔다. 무엇을 하시나 했더니 어느새 세 사람 몫의 점심을 차려 와 꼭 먹고 가라며 권했다고 한다.\n\n그때 신지 선생의 어머니는 다음과 같이 말문을 열었다.\n\n“내가 아침 일찍 일어나 밥 지을 준비를 하곤 했는데, 아직 결혼한 지 얼마 되지 않았을 때였어요. 어느 날 다리 위를 걷고 있는데 내 몸 둘레가 한순간 황금빛으로 빛나는 겁니다.\n\n그러자 나는 나이면서도 내가 아닌 듯한 느낌이 들었고, 하늘에서 목소리가 들려왔어요.” 또 이렇게 말했다고 한다.\n\n“그 아이는 부모에게 걱정을 끼치지 않으려고 무슨 일이든 혼자서 하는 아이였어요. 하루오(治男, 春男)는 죽었지만 죽지 않았습니다. 하루오는 지금도 살아 있습니다.” 어머니는 자기 자신에게 타이르듯 이 말을 여러 번 되풀이했다고 한다. 당시에는 각 현에서 뛰어난 아이 대여섯 명만 갈 수 있었다는 유년학교에도, 합격 통지서가 온 뒤에야 부모가 응시 사실을 알았을 정도였다고 한다. 그런데 그날 우연이라고 하기에는 기이한 일이 일어났다. 신지 선생이 태어나 자란 집은 그가 어머니를 위해 새집을 지으면서 절반이 헐려 통로가 되어 있었다. 남은 절반도 일행이 찾아온 바로 그날 철거할 예정이었으나, 우연히 비가 내리는 바람에 작업이 취소되었다. 그 덕분에 집은 사진으로 남았다. 그야말로 아슬아슬한 순간이었다.",
    "notes": "번역·제작 메모\n\n• 幼年学校은 문맥상 당시의 군 유년학교를 가리키는 것으로 보이지만, 정확한 학교명이 제시되지 않았으므로 문에서는 원문 수준의 명칭만 유지했다.\n\n• 점심 준비와 지폐를 건네는 장면은 008번으로 이어진다. 쇼츠를 한 편으로 만들 때는 두 항목을 묶어 ‘어머니의 인품’에 초점을 둘 수도 있다.",
