    "origTitle": "",
    "contentType": "웹마스터의 답사 기록 + 소노가시라 일행의 방문담 연속 부분 + 다카하시 신지의 종교적 주장 + 편집자의 해",
    "summary": "웹마스터가 다카하시 신지 선생의 고향을 찾아가다웹마스터가 그곳을 찾은 때는 헤이세이 4년(1992년) 3월 20일부터 22일까지였다. 20일에는 남은 눈조차 보이지 않을 만큼 맑았고, 21일에는 엄청난 눈이 내렸다. 덕분에 맑은 날의 신지 선생 생가 ...",
    "body": "웹마스터가 다카하시 신지 선생의 고향을 찾아가다웹마스터가 그곳을 찾은 때는 헤이세이 4년(1992년) 3월 20일부터 22일까지였다. 20일에는 남은 눈조차 보이지 않을 만큼 맑았고, 21일에는 엄청난 눈이 내렸다. 덕분에 맑은 날의 신지 선생 생가 모습과 폭설 속의 집을 모두 사진으로 찍을 수 있었다. 두 번째 뇌출혈에서 회복한 직후라 후유증 때문에 영상이 조금 흔들린 점은 아쉽지만, 사진은 선명하게 잘 나왔다. 전화번호부에서 고덴공업(高電工業)을 찾아내고 그 주소까지 가까이 찍어 둔 것을 보면 취재에 들인 정성이 드러난다. 취재 노트를 보면 첫날 오전 6시 하카타에서 첫 신칸센을 타고 오전 11시에 나고야에 도착했다. 정오에 나고야에서 주오 본선 특급을 타고 오후 3시에 나가노, 다시 신에쓰 본선 특급으로 오후 4시에 고모로, 고모로에서 고우미선 보통열차로 오후 5시에 나메즈역에 닿았다. 하카타에서 생가까지 열차로 12시간이 걸린 여정이었다. 이야기를 계속한다. 어머니는 그리운 듯 신지 선생의 키를 재어 표시해 둔 기둥의 흠집을 가리켰다. 헤어질 때는 품속에서 종이 꾸러미를 내밀었다. 일행은 한사코 거절할 수도 없어 받아 들었다고 한다. 먼 규슈에서 찾아온 사람을 생각하는 배려와 마음 씀씀이가 아프도록 전해지는 사례다. 꾸러미를 열어 보니 1만 엔이 들어 있었다고 한다. 여러 기록과 강연을 보아도 신지 선생은 특히 어머니의 영향을 많이 받은 듯하다. 이에 편집자는 신지 선생이 과거생의 어머니에 관해 단언한 내용을 더 보탠다. 석가의 어머니였던 마야간에이 2년(1625년), 신지 선생은 인도에서 석가의 어머니였던 마야에게 말했다고 한다.\n\n“이번에도 나의 어머니가 되어 주십시오.”\n\n그러나 마야는 이렇게 답했다고 한다.\n\n“이번에는 쉬게 해 주세요. 죄송하지만 인도에 있었을 때 너무 고생했습니다.” 그래서 이번에는 마리아이자 니치렌의 어머니였던 이에게 부탁하게 되었다는 것이다. 어째서 이런 이야기가 나왔는지를 설명하면 이렇다. 마야는 출산을 위해 친정으로 돌아가던 길에 오늘날 네팔의 룸비니에서 석가를 낳았다.\n\n그러나 산후 회복이 좋지 않아 일주일 만에 세상을 떠났다고 한다. 그런 일이 있었으니 마야가 몹시 고생했음은 틀림없을 것이라고 편집자는 말한다. 원문은 놀랍게도 석가가 역아였다고 주장한다. 그 때문에 마야가 세상을 떠났다는 것이다. 그러나 이 일마저 석가가 지상계에서 스스로 깨달음을 얻어 인류의 구세주가 되게 하기 위한 하나의 방편이었고, 천상계의 계획에 따라 마야가 천국으로 불려 갔다고 설명한다. 이 말을 듣고 “천상계가 어떻게 저렇게 무자비한 일을 할 수 있나” 하고 놀랄 사람도 있을 것이다. 하지만 이 글은 우리가 영원한 생명이며 이번 세상으로 끝나는 존재가 아니고, 죽더라도 다시 태어난다고 말한다.\n\n이처럼 천상계의 계획에 참여하는 일은 영혼에게 위대한 공적이 되어 칭송받게 된다는 것이다. 그렇다 해도 마야에게는 몹시 힘든 일이었을 것이라고 편집자는 맺는다.",
    "notes": "번역·제작 메모\n\n• 첨부 강연록의 1974년 3월 31일 모리오카 강연에도 ‘어머니가 되어 달라고 부탁했으나 거절당했다’는 유사한 발언이 확인된다. 다만 세부 표현이 웹 글과 다르므로 강연록의 추가 문장은 번역에 섞지 않았다.\n\n• 마야가 역아 출산 때문에 사망했다는 문장은 이 웹 자료의 주장이다. 역사·의학적 확정 사실처럼 표현하지 않는다.\n\n• 여행기와 종교적 이야기가 분리되어 있으므로 쇼츠는 두 편으로 나누는 것이 좋다.",
