    "title": "성장 과정의 불가사의 - 생사의 경계를 수십 차례 오가다",
    "origTitle": "「高橋信次師物語」 真のメシヤの記録 11　八起正法先生編",
    "contentType": "",
    "summary": "열 살이던 해 가을, 9월 3일 밤 8시였다. 그때까지 이렇다 할 병을 앓은 적이 없던 신지 선생은 갑자기 심장이 멎어 죽은 듯한 상태가 되었다고 한다. 그날은 세 시간쯤 지나 다시 숨을 쉬기 시작했지만, 그 뒤부터 밤 8시만 되면 딸꾹질이 나고 숨을...",
    "body": "열 살이던 해 가을, 9월 3일 밤 8시였다. 그때까지 이렇다 할 병을 앓은 적이 없던 신지 선생은 갑자기 심장이 멎어 죽은 듯한 상태가 되었다고 한다. 그날은 세 시간쯤 지나 다시 숨을 쉬기 시작했지만, 그 뒤부터 밤 8시만 되면 딸꾹질이 나고 숨을 내쉴 수만 있는 상태가 되었다. 그러다가 4~5초 만에 심장이 완전히 멎곤 했다. 이런 상태가 계속되자 부모님은 어찌할 방도를 찾지 못한 채 당황할 수밖에 없었다. 심장이 멎어 축 늘어진 신지 선생의 몸을 끌어안고 귓가에서 “하루오! 얘, 하루오야!” 하고 이름을 부르거나, 어떻게든 숨을 되돌리려고 몸을 흔들고 또 흔들었다고 한다. 식구들도 아무것도 할 수 없었다. 저마다 그의 이름을 부르다가 서로 얼굴을 마주 보며, 걱정스러운 눈으로 가만히 바라볼 뿐이었다고 한다.\n\n한편 ‘또 하나의 신지 선생’은 이 모든 과정을 이불 위쪽에서 내려다보며 전부 알고 있었다. 가족을 걱정시키고 싶지 않아 이렇게 소리쳤다.\n\n“봐, 나야. 걱정하지 마. 여기야, 여기 있다고!” 하지만 아무도 그의 존재를 알아차리지 못한 듯했다.\n\n이윽고 의사가 찾아왔다. 입술은 포도색으로 변하고 얼굴은 창백했으며 팔다리는 버들가지처럼 축 늘어져 있었다. 의사는 신지 선생을 진찰한 뒤 더는 손쓸 방도가 없다는 표정으로 강심제 주사를 놓거나 관장을 할 뿐이었다. 그동안에도 또 하나의 신지 선생은 그 모든 광경을 지켜보고 있었다. 그러다 어느 순간 코끝에 약 냄새가 확 느껴지면 심장이 다시 뛰기 시작했고, 또 하나의 신지 선생은 본래 자신의 육체로 돌아왔다. 이러한 분신 현상이 정기적으로 여러 차례 일어났다고 한다. 그 시간은 15분에서 길게는 몇 시간에 이르렀다. 그 뒤로는 의사도 진단을 내리지 못했다. 나중에는 “또 그 일인가. 이제는 나도 감당할 수 없네”라며 아예 찾아오지 않았고, 가족들도 별다른 방도가 없어 걱정스러운 마음으로 경과만 지켜보았다고 한다.",
