    "summary": "의사에게마저 포기당한 신지 선생을 두고 부모님은 아무런 방도도 찾지 못했다. 마침내 견디다 못해 여러 신사에 데려가 기도하게 하고, 가까운 침구사를 찾아가 치료도 받게 했다고 한다. 신지 선생은 자전거 짐받이에 타고 여러 치료를 받으러 다녔다. 그때 ...",
    "body": "의사에게마저 포기당한 신지 선생을 두고 부모님은 아무런 방도도 찾지 못했다. 마침내 견디다 못해 여러 신사에 데려가 기도하게 하고, 가까운 침구사를 찾아가 치료도 받게 했다고 한다. 신지 선생은 자전거 짐받이에 타고 여러 치료를 받으러 다녔다. 그때 아버지의 자전거에서 자주 굴러떨어졌던 모양이다. 신지 선생은 웃으며 이렇게 회상했다.\n\n“머리가 혹투성이여서 울퉁불퉁합니다.” 그런 체험이 한동안 이어진 뒤, 분신 현상이 나타나지 않게 될 무렵부터 신지 선생은 마을 변두리의 작은 하쿠산 신사에 다녔다. 매일 아침저녁 6시에 두 차례 신사 건물을 청소하고, 명상에 잠겨 기도하는 것이 일과였다. 그러던 어느 날 작은 일이 하나 일어났다. 신지 선생이 어머니와 함께 나리타산을 참배했을 때였다. 먹빛 승복을 입고 둥근 만주갓을 깊이 눌러써 얼굴을 가린 낯선 행각승이 신지 선생의 머리를 쓰다듬으며 말했다.\n\n“병은 머지않아 나을 것이다.”\n\n그리고 이상한 말을 하나 더 했다.\n\n“너의 눈은 이중공(二重孔)이다. 열심히 공부하면 영력을 지니게 될 것이다.” 이중공이란 무엇인가. 하나는 이 눈으로 볼 수 있는 세계를 보는 눈이고, 다른 하나는 저세상과 미래 세계까지 모두 투시하는 능력을 가리킨다고 한다. 신지 선생과 어머니는 그 말을 듣고 깜짝 놀랐다. 그 말대로 병은 반년쯤 지나 완전히 나았고, 그 뒤로는 또 하나의 신지 선생이 자신의 육체에서 빠져나오는 일도 없었다.",
