    "contentType": "",
    "summary": "불가사의한 승려그 뒤에도 앞서 만난 승려와 같은 모습을 한 행각승들이 놀고 있던 신지 선생에게 여러 이야기를 건넸다. 한 승려는 과자를 주며 이렇게 말했다. “오늘 밤은 이 강가에 머물러 지낼 테니, 저녁때까지 네가 모르는 공부를 가르쳐 주마.” 신지...",
    "body": "불가사의한 승려그 뒤에도 앞서 만난 승려와 같은 모습을 한 행각승들이 놀고 있던 신지 선생에게 여러 이야기를 건넸다. 한 승려는 과자를 주며 이렇게 말했다.\n\n“오늘 밤은 이 강가에 머물러 지낼 테니, 저녁때까지 네가 모르는 공부를 가르쳐 주마.” 신지 선생이 승려 곁에 앉으면 그는 신지 선생의 앞날에 관해 다정하게 이끌어 주었고, “마음이라는 것이 모든 것의 근원이다”와 같은 어려운 가르침도 전해 주었다. 어떤 때에는 비슷한 모습의 행각승이 집으로 찾아와 “신지는 건강하게 잘 지내고있습니까?”라고 말을 건네기도 했다.\n\n이처럼 신지 선생의 집에는 이상할 만큼 행각승들이 자주 찾아왔으며, 그들은 신지 선생에게 올바른 마음을 가르쳐 주고 떠난 듯하다.\n\n그러나 신지 선생은 학문을 그다지 좋아하지 않았다. 그래도 신과 부처에 관한 이야기가 나오면 마치 되살아난 사람처럼 활기를 띠었다. 학교에서 돌아오면 가방을 내던지고 산과 들을 뛰어다니는 나날을 보냈다. 심령술사 토니에 관하여\n\n낯선 행각승이 찾아올 때마다 가르침을 주고 이끌었다는 일은 불가사의하다고 하면 참으로 불가사의한 일이다.\n\n한편 필리핀의 토니는 그리스도의 분신이라고 한다. 그 역시 신지 선생과 비슷한 불가사의한 체험을 했으므로, 저자는 그의 자서전에서 그 내용을 소개하려 한다. 이렇게 쓰면 어떤 영적인 암시를 풍기는 이야기처럼 들릴 수도 있다. 그러나 신지 선생이 남긴 말 가운데 실제로 다음과 같은 내용이 있다는 것이다.\n\n“필리핀에서 예수의 분신(5)이 육체라는 배를 타고 수행하고 있다.” 그 인물이 바로 필리핀의 심령술사 안토니오 아그파오아, 통칭 토니(1939~1982, 쇼와 57년)라고 한다. 그를 모르는 사람도 있겠지만, 한때 텔레비전 등에서는 필리핀 심령 투어를 앞다투어 보도했다. 수많은 심령술사 가운데 가장 널리 이름이 알려진 사람이 토니였다. 예수라고 하면 말할 것도 없이 그리스도를 가리킨다. 저자는 그 분신인 만큼 토니의 영적 능력도 상상할 수 없을 정도였으리라고 말한다. 저자는 토니의 자서전에 신지 선생과 같은 체험이 기록되어 있다는 사실을 참으로 불가사의하게 여긴다.",
    "notes": "",
