    "title": "토니의 자서전과 증상만",
    "origTitle": "「高橋信次師物語」 真のメシヤの記録 15　八起正法先生編",
    "contentType": "",
    "summary": "이제 그 자서전 이야기를 해 보자. 토니가 일곱 살이었을 때, 검게 물들인 비단 같은 옷을 입고 허리에 흰 끈을 두른 흰 수염의 남자가 나타났다고 한다. 토니가 ‘아포’라고 부른 그 남자는 토니를 산속 오두막으로 데려갔다. 그곳에는 신기하게도 토니의 ...",
    "body": "이제 그 자서전 이야기를 해 보자. 토니가 일곱 살이었을 때, 검게 물들인 비단 같은 옷을 입고 허리에 흰 끈을 두른 흰 수염의 남자가 나타났다고 한다. 토니가 ‘아포’라고 부른 그 남자는 토니를 산속 오두막으로 데려갔다. 그곳에는 신기하게도 토니의 몸에 꼭 맞는 옷이 준비되어 있었다. 아포는 그곳에서 토니에게 여러 사물의 조화, 곧 ‘심포니’와 마음에 관해 가르쳤다고 한다. 토니는 혼자 있을 때도 언제나 아포의 존재를 느꼈다. 아포는 그에게 명상을 가르치고, 사물과 동물 안에 깃든 조화를 배우며 그것들과 하나가 되는 법 등을 일러 주었다. 일정한 교육 기간이 끝나자 아포의 모습은 사라졌고, 그 뒤로는 토니의 마음속에서 영적으로 가르침을 이어 갔다고 자서전은 상세히 기록한다.\n\n이처럼 사명과 목적을 지니고 태어난 사람에게는 천상계의 협력으로 영인이 물질화 현상을 일으키거나 인간의 모습을 취해 이 세상에 나타나, 불가사의한 방식으로 협력하며 가르침을 주는 듯하다고 저자는 말한다. 사명 있는 빛의 천사가 증상만에 빠지면여기서 한 가지 덧붙여 둘 것이 있다. 토니의 영적인 힘이 높아지고 세계적으로 명성이 퍼지자, 세계 곳곳에서 사람들이 그의 곁으로 한꺼번에 몰려들었다. 그 뒤 토니가 증상만(録上慢)에 빠져 돈과 여자에 탐닉하자, 그의 영적인 힘도 한때 사라졌다. 자서전에는 그가 “힘이 사라져 버렸어. 어떻게 된 거지? 힘이 나오지 않아!”라며 괴로워한 일이 기록되어 있다고 한다.\n\n그러나 뜻밖에도 심령 투어로 찾아온 일본인 여성과 맺은 육체관계가 원인이 되어, 안타깝게도 쇼와 57년(1982년)에 뇌출혈로 젊은 나이에 세상을 떠났다고 원문은 서술한다. 국제정법협회 소노가시라 히로치카 회장의 월간지 『정법』에는 회장이 바기오까지 날아가 토니에게 다음과 같이 충고했다는 내용도 실려 있다고 한다.\n\n“지금과 같은 방식으로 살아서는 안 된다고 충고하고 왔다.” 다카하시 신지 선생의 첫째 제자로 자타가 공인하던 소노가시라 회장이 신지 선생이 세상을 떠난 뒤에도 스승의 뜻을 이어 가기 위해 얼마나 고심했는지 짐작할 수 있다는 것이 저자의 설명이다.",
    "notes": "",
