    "title": "토니의 사례와 1본체·5분신의 법칙",
    "origTitle": "「高橋信次師物語」 真のメシヤの記録 16　八起正法先生編",
    "contentType": "",
    "summary": "조금만 더 보충해 두자. 토니는 바기오에 명상 도장이라고도 할 수 있는 육각당을 세웠다. 그러나 그다지 신성한 장소는 아니었던 모양인지, 앞서 일어난 필리핀 대지진으로 완전히 무너져 파묻혔다고 한다. 여기에 한 가지 이야기를 더 덧붙이면 이렇다. 토니...",
    "body": "조금만 더 보충해 두자. 토니는 바기오에 명상 도장이라고도 할 수 있는 육각당을 세웠다.\n\n그러나 그다지 신성한 장소는 아니었던 모양인지, 앞서 일어난 필리핀 대지진으로 완전히 무너져 파묻혔다고 한다. 여기에 한 가지 이야기를 더 덧붙이면 이렇다. 토니가 또래 아이들과 공놀이를 하던 어린 시절이었다. 놀이에 싫증이 난 토니는 몸을 움직이지 않고 영적인 힘으로 공을 되받아치고 있었다. 그러다 공이 초가지붕에 걸려 내려오지 않자 온 힘을 다해 여러 차례 힘을 주었다. 그 순간 공에서 갑자기 불길이 뿜어져 나와 집이 모두 타 버렸다.\n\n그러자 아포가 슬픈 얼굴로 나타나 말했다.\n\n“마음을 다잡고 반성하라.” 그 뒤 토니가 반성해 가는 광경이 자서전에 상세히 기록되어 있다고 한다.\n\n이처럼 신지 선생과 토니에게는 지금까지 서술한 것과 같은 영계의 불가사의한 일들이 있었다는 것이다.\n\n또한 신지 선생이 예고한 말 가운데에는 다음과 같은 내용도 있다.\n\n“지금부터 150년쯤 지나면 예수의 본체가 미국 시카고에 태어난다.” 원문은 괄호 안에 “쇼와 48년(1973년) 현재로부터 180년 뒤”라고도 적고 있다. 그렇다면 문제는 더욱 엄중해진다. 정법의 가르침에 따르면 본체는 자기 자신의 마음뿐 아니라 분신이 지닌 마음의 경향성까지 바로잡아야 한다. 따라서 그때 시카고에 태어나는 예수의 본체는 분신 토니의 카르마, 곧 업과 마음의 경향성까지 바로잡아야 한다는 것이다. 저자는 이를 두고 안타까운 일이라고 말한다. 영계의 법칙이든 신리든 그것이 진실이라면, 분신 토니에게 여성을 대하는 마음이 다소 약한 경향성이 있을 경우 본체 예수가 시카고에 나타나 부활했을 때 ‘마’가 바로 그 약점을 파고들 것이라고 보기 때문이다.\n\n이처럼 사명과 목적을 지닌 사람에게는 특히 엄격한 기준이 따른다는 사실을 알아야 한다. 그러나 구세주가 되려면 그것도 당연한 일인지 모른다고 저자는 덧붙인다. 그런데 앞에서부터 ‘분신(5)’과 ‘본체’라는 말을 사용했다. 그것이 무엇을 뜻하는지 의문을 품을 사람도 있을 것이다. 그러므로 이제 ‘1본체와 5분신’의 법칙을 간단히 설명해 보자. 이는 신지 선생이 자신의 수호령과 지도령으로부터 “식물의 세포에서 배워라. 동물에게서 배워라”라는 주의를 끊임없이 받아 신리에 도달한 것이라고 한다. 다음 내용은 복잡한 이론이다. 저자는 독자에게 학창 시절을 떠올리며 차분히 읽어 달라고 당부하고, 일부러 요약하지 않은 채 그대로 제시한다.",
    "notes": "",
