    "contentType": "",
    "summary": "인간은 대자연계를 이루는 구성원에 지나지 않는다. 식물은 핵, 곧 하나의 본체를 중심으로 그 둘레의 원형질막·액포·색소체·세포막이라는 네 요소로 구성된다. 따라서 본체 하나와 분신 넷의 관계가 된다. 동물의 경우에는 핵, 곧 하나의 본체를 중심으로 원...",
    "body": "인간은 대자연계를 이루는 구성원에 지나지 않는다. 식물은 핵, 곧 하나의 본체를 중심으로 그 둘레의 원형질막·액포·색소체·세포막이라는 네 요소로 구성된다. 따라서 본체 하나와 분신 넷의 관계가 된다. 동물의 경우에는 핵, 곧 하나의 본체를 중심으로 원형질막·미토콘드리아·골지체·중심체·지방립이라는 다섯 분신이 있으므로, 본체 하나와 분신 다섯의 관계가 된다. 이와 마찬가지로 광물의 경우에는 원자번호에 핵 하나를 더한 수가 본체와 분신의 수가 된다. 예를 들어 탄소의 원자번호는 6이다. 핵 하나와 핵 바깥의 음전자 여섯으로 이루어져 있으므로, 본체 하나와 분신 여섯의 관계가 된다는 것이다.\n\n이처럼 인간도 동물이므로 본체 하나와 분신 다섯의 관계인 것은 틀림없다. 그러나 인간의 경우에는 특히 대우주가 신의 대의식(大意識)을 모체로 하여 열·빛·전기·자기·중력이라는 다섯 요소로 이루어져 있기 때문에, 인간의 생명체도 이에 맞추어 본체 하나인 대의식과 다섯 요소인 분신 다섯의 조합으로 이루어져 있다고 한다. 인간을 ‘소우주’라고 부르는 까닭도 생명의 성립이 이처럼 대우주의 구성과 같은 방식으로 이루어져 있기 때문이다. 생명과 물질은 모두 세 단계의 과정으로 이루어진다. 지구에 생명이 깃드는 것은 태양과 달과 지구라는 삼위일체의 구성에 따른다. 지구, 곧 지상은 기권·수권·암권으로 이루어져 있으며, 원자는 핵외전자·중성자·양전자로 이루어져 있다. 전기는 양성(+), 중성(N), 음성(-)으로 이루어지고, 세포는 크게 원형질·세포질·핵이라는 세 요소로 구성된다. 물질이 성립하는 과정에서는 첫째로 우주의 대의식이 출발점이 된다. 둘째로 열·빛·전기·자기·중력의 에너지가 결합하며, 셋째로 물질이라는 현상화가 이루어진다. 생명도 이와 마찬가지다. 첫째로 우주의 대의식에서 출발하여, 둘째로 개별 생명이 저세상인 실재계에 태어나고, 셋째로 현상계인 이 세상에 모습을 드러낸다. 한 번 현상계에 나온 생명체는 이 세상과 저세상 사이에서 전생을 거듭한다. 이 세상에 태어날 때는 부모라는 매개, 곧 인연을 거쳐 모습을 드러낸다. 다시 말해 대의식에서 갈라져 나온 생명은 저세상·부모·이 세상이라는 과정을 밟으며 순환의 법 안에서 살아가도록 짜여 있다는 것이다. 다음은 인간이 어떤 순서로 다시 태어나는지에 관한 이야기다.",
    "notes": "",
