    "title": "생명체, 곧 영혼의 전생윤회 순서",
    "origTitle": "「高橋信次師物語」 真のメシヤの記録 18　八起正法先生編",
    "contentType": "",
    "summary": "영혼이 태어나고 죽기를 되풀이하는 전생윤회는 어떤 순서로 이루어지는가. 원칙적으로는 차례대로 이루어진다고 한다. A가 나오면 다음은 B, B 다음은 C가 되는 식으로 A라는 핵과 B·C·D·E·F라는 분신이 차례로 현상계에 나와 수행하는 것이 원칙이다...",
    "body": "영혼이 태어나고 죽기를 되풀이하는 전생윤회는 어떤 순서로 이루어지는가. 원칙적으로는 차례대로 이루어진다고 한다. A가 나오면 다음은 B, B 다음은 C가 되는 식으로 A라는 핵과 B·C·D·E·F라는 분신이 차례로 현상계에 나와 수행하는 것이 원칙이다. 다만 전생윤회의 과정에는 수행을 쌓는 사람도 있는 반면, 지옥계에 떨어져 ‘곁길로 벗어나는 사람’도 있다. 이 때문에 전체의 균형이 무너지는 경우에는 저세상에서 서로 의논하여 앞의 원칙에 얽매이지 않고 순서를 조정한다. 가령 A가 짧은 기간에 두 번이나 세 번 현상계, 곧 이 세상에 나와 수행하기도 한다.\n\n그러나 이런 경우는 비교적 드물며, 대부분은 차례대로 나와 수행한다고 한다. 앞에서 말한 ‘곁길로 벗어나는 사람’은 대단히 중요한 문제 가운데 하나다. 인간의 영혼은 천상계로 돌아간 사람만 이 세상에 전생하여 다시 태어날 수 있다는 것이다. 이 문제를 다른 각도에서 조금 더 깊이 생각하면, 곁길로 벗어나 어두운 지옥 세계에 머물게 된 사람은 그곳에서 곧바로 이 세상에 다시 태어날 수 없다는 뜻이다. 다시 말해 지옥 세계에서 바로 지상계에 태어날 수는 없다는 것이다. 성급하고 쉽게 격분하는 현대인에게는 매우 심각한 문제다. 먼저 천상계로 돌아간 다음 이 세상에 육체를 지니고 태어나야 하므로, 그 과정에서 순서의 혼란이 일어난다. 어떤 혼란인가 하면, 원래의 차례대로 진행할 수 없어 서로 의논한 뒤 이 세상에 나올 순서를 결정해야 하는 혼란이다. 그렇다면 저세상의 천국, 곧 천상계는 어떤 곳일까?",
