    "title": "육군유년학교",
    "origTitle": "「高橋信次師物語」 真のメシヤの記録 21　八起正法先生編",
    "contentType": "",
    "summary": "신지 선생은 공부를 그다지 잘하는 편은 아니었지만, 신불에 관한 이야기만 나오면 기다렸다는 듯 눈을 빛냈다. 그러나 학교에 들어가자 타고난 재능을 발휘하며 눈에 띄게 진급했다. 히라가 소학교(현재의 시로야마 소학교)를 졸업한 뒤 노자와 중학교(현재의 ...",
    "body": "신지 선생은 공부를 그다지 잘하는 편은 아니었지만, 신불에 관한 이야기만 나오면 기다렸다는 듯 눈을 빛냈다.\n\n그러나 학교에 들어가자 타고난 재능을 발휘하며 눈에 띄게 진급했다. 히라가 소학교(현재의 시로야마 소학교)를 졸업한 뒤 노자와 중학교(현재의 노자와키타 고등학교로, 명문 진학교로 알려져 있다)에 입학했으나 2년 만에 중퇴하고, 성적이 우수한 학생을 선발하기로 유명했던 센다이 육군유년학교에 입학했다. 당시 부모님은 합격 통지서가 도착하고 나서야 그가 시험을 치렀다는 사실을 처음 알았다고 한다. 아무리 느긋한 시대였다고 해도 이례적인 일이었다. 자녀가 많은 가난한 농가에서 자란 신지 선생이 학비와 식비 걱정을 끼치지 않으려고 전원 기숙사제이고 학비까지 모두 지원되는 학교를 선택했다는 사실은 특별히 기록할 만하다고 저자는 말한다. 검도와 다카하시 신지 선생중학교 때부터 시작한 검도는 그 뒤 신지 선생의 생애에 적지 않은 영향을 미쳤다. 신지 선생의 장녀 게이코의 저서에는, 어린 시절 딸이 별것 아닌 장난을 치면 성급하게 “이 녀석!” 하고 목도를 치켜드는 일도 있었다고 적혀 있다.\n\n또한 수제자들을 이끌고 모두 아홉 명가량이 참가한 시가고원 특별 연수에서는, 의식을 통일하기 위해 강습 중간중간 검도복으로 갈아입고 전원이 함께 검을 휘두르는 기본 연습을 했던 듯하다. 당시 기념사진을 보면 모두가 즐겁게 웃고 있으며, 중간 정도의 체격인 신지 선생과 그중 키가 가장 큰 소노가시라 히로치카 회장의 모습이 유난히 인상적이라고 한다. 그러면 당시 특별 연수의 모습을 간단히 적어 보자. 오전은 반성하는 시간이었다. 각자 벽이나 창 쪽을 바라보기도 하고, 눈을 감거나 하늘을 올려다보기도 하면서 자신의 인생을 계속 반성했다.\n\n한편 신지 선생은 다른 방에서 사람마다 어떻게 반성하고 있는지를 영시(録視)와 투시로 보고 있었던 듯하다. 그러다 상태를 살피러 온 신지 선생이 갑자기 말했다.\n\n“여러분의 반성은 제자리만 맴돌 뿐 조금도 진전이 없습니다. 이제부터는 종이에 적으십시오. 그것을 제가 보겠습니다.” 그 뒤 각자는 복잡한 표정으로 반성 내용을 적기 시작했다. 정법에서 말하는 반성은 간단히 설명하면 다음과 같은 방식이다.",
    "notes": "",
