    "title": "정법이 가르치는 반성의 방법",
    "origTitle": "「高橋信次師物語」 真のメシヤの記録 22　八起正法先生編",
    "contentType": "",
    "summary": "먼저 돈 문제, 이성 문제, 형제자매와의 문제처럼 항목마다 주제를 정하고, 그 주제에 따라 반성해 가는 방법이 있다. 또 하나는 한 살부터 다섯 살, 다섯 살부터 열 살, 열 살부터 열다섯 살까지, 또는 열 살까지와 열 살부터 스무 살, 스무 살부터 ...",
    "body": "먼저 돈 문제, 이성 문제, 형제자매와의 문제처럼 항목마다 주제를 정하고, 그 주제에 따라 반성해 가는 방법이 있다. 또 하나는 한 살부터 다섯 살, 다섯 살부터 열 살, 열 살부터 열다섯 살까지, 또는 열 살까지와 열 살부터 스무 살, 스무 살부터 서른 살까지라는 식으로 삶을 5년이나 10년 단위로 나누는 방법이다. 그 시기마다 부모·형제자매·선생님·친구· 주변 사람들을 어떻게 대했는지, 곧 화를 내지는 않았는지, 푸념하지는 않았는지, 불평불만을 말하지는 않았는지, 욕망을 노골적으로 드러내지는 않았는지 등을 돌아보며 지금까지의 전 생애를 고요한 마음으로 반성하는 것이다. 원문은 신지 선생이 이처럼 다른 방에 있으면서도 사람의 마음에 기록된 모든 내용을 자유롭게 알아내거나 볼 수 있는 힘, 곧 투시력을 지니고 있었다고 서술한다. 수호령에게 묻는다어째서 이런 일이 가능할까 하고 의문을 품을 수도 있을 것이다. 저자는 각자의 수호령에게 물으면 간단한 일이라고 설명한다. 이에 관해 조금 더 말해 보자. 사람은 태어나고 죽기를 되풀이하는 가운데, 지구 인류가 탄생한 3억 6천5백만 년 전부터 수만 번, 수십만 번에 이르는 인생 체험을 지니고 있다는 것이다. 물론 베타별에 있던 당시부터, 아니 그보다 전부터 계산한다면 이미 천문학적인 숫자가 될지도 모른다. 그 점은 잠시 제쳐 두자. 예를 들어 현세의 바로 전에는 500년 전, 그 전에는 1,200년 전, 다시 그 전에는 2,000년 전에 태어난 사람이 있다고 하자. 그러면 현세와 가장 가까운 500년 전의 사람이 주로 수호령이 되어, 현세의 인물이 태어난 뒤부터 지금까지의 모든 일을 보고 알고 있다는 것이다. 그렇다면 그 사람의 전 생애를 모두 아는 수호령에게 물으면 무엇이든 전부 알 수 있다는 이야기가 된다. 그렇다고 지금의 당신이 누구를 가리지 않고 모든 비밀을 드러내겠는가. 보통은 조개처럼 입을 굳게 다물 것이다. 그것은 당연하다.\n\n그러나 존경하고 신뢰할 수 있는 사람에게라면 두말없이 털어놓듯이, 질문하는 상대가 지닌 빛의 양과 영역, 곧 상대의 인격이나 인간성에 따라서는 수호령도 마음을 열고 하나도 남김없이 고백할 것이라고 저자는 설명한다.",
    "notes": "",
