    "contentType": "",
    "summary": "다카하시 신지 선생이나 소노가시라 히로치카 회장처럼 인간성을 초월한 사람이라면 전혀 문제가 없을 것이라고 원문은 말한다. 그러나 저자는 세상의 많은 영능력자가 여우나 뱀 같은 동물령 또는 인간의 지옥령에게 빙의되어, 다시 말해 그것들이 달라붙거나 협력...",
    "body": "다카하시 신지 선생이나 소노가시라 히로치카 회장처럼 인간성을 초월한 사람이라면 전혀 문제가 없을 것이라고 원문은 말한다. 그러나 저자는 세상의 많은 영능력자가 여우나 뱀 같은 동물령 또는 인간의 지옥령에게 빙의되어, 다시 말해 그것들이 달라붙거나 협력함으로써 영능력을 나타낸다고 생각한다. 그러므로 실례를 무릅쓰고 말하면 그들의 인격이 그다지 높지 않으며, 여러 일을 물어도 맞기도 하고 틀리기도 하는 까닭은 이러한 사정을 헤아리면 이해할 수 있다는 것이다. 특히 신지 선생의 능력은 정확히 100퍼센트였다고 저자는 주장한다. 그 말이 무엇인가 하면, 신지 선생은 쇼와 40년대(1965~1974년)에 미궁에 빠질 듯한 여러 사건을 해결했다는 것이다. 그가 그 유명한 3억 엔 사건을 다루려고 했을 때, 천상계로부터 다음과 같은 충고를 받았다고 한다.\n\n“사건 해결사 같은 일을 계속하다가는 그것이 불편한 자에게 끔찍한 일을 당한다.” 그 뒤로는 이런 부탁을 모두 거절하게 되었다고 한다. 저자가 한 가지 더 말하려는 것은 사건의 조기 해결이 반드시 각 사람의 영혼 공부에 도움이 되는 것은 아니므로, 미궁에 빠지는 일도 그 나름대로 어쩔 수 없다는 주장이다. 그 뜻은 이렇다. 사건에서는 가해자와 피해자 모두에게 ‘원인과 결과’, 곧 악한 원인은 악한 결과를 낳는다는 원칙이 엄연히 작용한다. 따라서 해결에 오랜 시간이 걸리면 모든 당사자가 그 긴 세월 동안 인생이란 무엇인지, 죽음이란 무엇인지, 양심의 가책이란 무엇인지, 마음의 평안이란 무엇인지, 사건의 해결이란 무엇인지를 진지하게 생각하게 된다. 그렇게 고민하고 괴로워하는 일이 영혼의 공부가 된다는 것이다. 신지 선생처럼 높은 인격과 올바른 영능력을 지닌 사람이라면 수호령에게 “3억 엔을 빼앗은 사람이 누구입니까?” 하고 묻는 것만으로 아무것도 아닌 일이 된다고 원문은 설명한다. 저자는 이제부터 이 책에서 밝히려는 내용을 억지로 끼워 맞추지 않더라도 뒷받침할 사실을 얼마든지 들 수 있다고 말한다. 당시 『해리 포터』라는 마법 이야기가 화제가 되어 전 세계에서 수억 권이나 팔린 듯하다고 원문은 덧붙인다.\n\n“사실은 소설보다 기이하다”라는 말이 있다. 따라서 다카하시 신지 선생이 나타냈다는 기적 또는 불가사의한 현상은 사실 그 자체이자 진실 그 자체이며, ‘사실은 소설보다 기이하다’라는 격언에 꼭 들어맞는다고 저자는 주장한다. 오히려 소설처럼 꿈이 담겨 있지 않아 재미없을지도 모른다고도 덧붙인다.",
    "notes": "",
