    "title": "기적은 꿈을 앞당겨 실현한 것",
    "origTitle": "「高橋信次師物語」 真のメシヤの記録 24　八起正法先生編",
    "contentType": "",
    "summary": "『해리 포터』의 부제인 ‘현자의 돌’도 예로부터 연금술, 곧 비금속이나 물질에서 순금을 만들어 내는 일을 인류의 염원과 꿈으로 삼아 온 데서 비롯되었다고 이해할 수 있다. 저자는 뒤에서 자세히 설명할 신지 선생의 금가루 현상도 바로 연금술과 같다고 말...",
    "body": "『해리 포터』의 부제인 ‘현자의 돌’도 예로부터 연금술, 곧 비금속이나 물질에서 순금을 만들어 내는 일을 인류의 염원과 꿈으로 삼아 온 데서 비롯되었다고 이해할 수 있다. 저자는 뒤에서 자세히 설명할 신지 선생의 금가루 현상도 바로 연금술과 같다고 말한다. 처음 나타났을 때에는 뜨거웠으며 무게도 40~50그램이나 되어 분석할 수 있는 물질이었다고 한 제자의 저서에 보고되어 있다는 것이다. 저자는 신지 선생의 일들이 그만큼 진실했다고 단언한다. 꿈이 꿈으로 남아 있으면 좋지만, 꿈이 사실이 되는 순간 꿈도 희망도 사라져 버린다는 것이다. 기적은 꿈을 앞당겨 실현한 것이며, 신지 선생의 경우가 바로 그러했다고 말한다. 이제 이야기를 본래의 흐름으로 되돌려 계속해 보자. 전쟁은 갈수록 격렬해졌고, 친구가 죽으면서 그 허무함은 더욱 커져 갔다. 신지 선생은 열여덟 살 때 자신에게 친절하게 대해 준 한 여성을 짝사랑했지만, 수줍어서 아무 말도 하지 못했다. 이는 소년 시절의 한 추억이었다. 다카하시 신지와 돌고래의 방벽신지 선생은 육군유년학교에서 사관학교로 진학해 항공 장교가 된 뒤 출병했다. 당시 바다에서 12시간 동안 표류하다가 해방함(海防艦)에 구조된 일이 있었다고 한다. 기이하게도 돌고래들이 신지 선생 곁으로 다가와 준 덕분에 미군의 기관총 사격을 피할 수 있었지만, 그의 몸에는 총탄 파편이 여러 개 남았다는 것이다. 제자 한 사람은 신지 선생이 흰 피부에 남은 여러 줄의 흉터를 보여 준 적이 있다고 기록했다. 돌고래는 돌고래 쇼에서도 볼 수 있듯 영리한 동물로 알려져 있다. 그러나 이 경우에는 천상계의 지시 같은 무언가가 있었던 것일까 하고 저자는 묻는다. 당시 상처를 입고 쓰러진 돌고래가 많았을 것이라 추정하면서, 어리석은 인간이 일으킨 전쟁 때문에 자신을 희생해 가며 신지 선생을 구한 돌고래들에게 진심으로 경의를 표한다고 저자는 말한다.",
    "notes": "",
