    "contentType": "",
    "summary": "빛의 천사에게는 동물이 신의 사자, 곧 원문에서 말하는 ‘쓰카이히메(使い姫)’로 나타나 협력한다고 한다. 석가에게는 원숭이가 나타나 위기에서 구해 주었고, 빛의 천사 엘리야가 통치자에게 박해받을 때에는 새들이 물고기와 과일을 날라다 주어 굶주림을 견디...",
    "body": "빛의 천사에게는 동물이 신의 사자, 곧 원문에서 말하는 ‘쓰카이히메(使い姫)’로 나타나 협력한다고 한다. 석가에게는 원숭이가 나타나 위기에서 구해 주었고, 빛의 천사 엘리야가 통치자에게 박해받을 때에는 새들이 물고기와 과일을 날라다 주어 굶주림을 견디게 했다는 것이다.\n\n또한 신지 선생이 전도를 시작한 뒤 이즈 해안에서 여러 사람과 함께 있을 때 돌고래와 이야기를 나누었다고 전해진다. 이와 관련하여 전쟁 중에 일어났다는 또 하나의 불가사의한 사례를 들어 보자. 영적 국방의 전조신지 선생의 제자인 소노가시라 회장이 중국에 출병했을 때 기관총 사격을 받았다고 한다. 회장은 바로 이때라고 생각하고 ‘이곳에 전쟁이 있다’는 관념을 버린 채 털썩 자리에 앉았다. 군도를 세워 두고 명상을 시작하자 주변에 떨어지는 폭탄과 탄환이 하나같이 폭발하지 않고 불발된 채 떨어졌다는 것이다. 아무것도 두려워하지 않고 부동명왕처럼 명상하는 모습이 몹시 분했던 모양인지, 마지막 비행기는 초저공으로 날아와 조종석 덮개를 열고 수류탄을 던졌다. 그러고는 원망스러운 듯 포기하고 돌아갔다고 한다. 평안한 마음의 세계는 밝은 광명의 세계이고 전쟁은 어두운 암흑의 세계이므로, 어둠이 빛에 의해 사라졌다는 것이 저자의 설명이다. 전적으로 공상과학의 세계 같은 이야기지만, 정법의 세계에서는 이와 같은 일들이 당연한 일처럼 무수히 입에 오르내린다고 한다. 요컨대 마음과 의식의 세계는 그만큼 중요하며, 생각은 사물을 만들어 내고 악한 탄환까지 불발시킨다고 저자는 주장한다. 국제적으로 핵무장이 진행되는 가운데 세계 유일의 원자폭탄 피폭국인 일본은 이러한 영적 국방을 실천하는 일이 시급하다고도 말한다. 인간은 영성에 눈을 뜨고 그 위대함에 감사해야 한다는 것이다. 물론 이 이야기 하나뿐이라면 우연이라고 치부할 수도 있을 것이다.\n\n그러나 저자는 앞으로 자세히 서술하듯 빛의 천사와 관련된 이러한 기이한 체험의 일치를 억지로 끼워 맞추지 않고도 얼마든지 들 수 있다고 말한다. 지금까지 빛의 천사와 관련된 현상, 곧 신지 선생과 소노가시라 회장의 기적을 하나하나 길게 서술했지만, 소노가시라 회장에게는 또 다음과 같은 일도 있었다.",
