    "contentType": "",
    "summary": "마찬가지로 전지에서 있었던 일이다. 출병지로 “전출을 명한다”라는 전보 한 통이 도착해 소노가시라 회장은 가섬(ガ 島)을 군에 징용된 어선으로 탈출했다. 닉슨 전 미국 대통령이 지휘하는 군함의 공격을 받았지만, 흘수가 얕은 어선이라 어뢰가 배 밑으로 ...",
    "body": "마찬가지로 전지에서 있었던 일이다. 출병지로 “전출을 명한다”라는 전보 한 통이 도착해 소노가시라 회장은 가섬(ガ 島)을 군에 징용된 어선으로 탈출했다. 닉슨 전 미국 대통령이 지휘하는 군함의 공격을 받았지만, 흘수가 얕은 어선이라 어뢰가 배 밑으로 지나가기만 했다는 것이다. 더욱 다행스럽게도 서로 포격하던 중 닉슨의 군함에 있는 증기 배관을 명중시킨 듯했다. 증기가 하늘 높이 솟구치며 군함이 운항을 멈추자, 회장 일행은 이때다 하고 황급히 달아났다. 그러나 기쁨도 잠시뿐이었다. 그들이 빠져나온 가섬의 전원이 옥쇄했다는 비보가 기다리고 있었다고 한다. 저자는 이제는 세상을 떠난 소노가시라 히로치카 회장의 눈물 어린 강연을 그립게 떠올리며 컴퓨터 앞에 앉아 이 글을 쓰고 있다고 말한다. 앞에서 빛의 천사에게는 동물이 쓰카이히메, 곧 신의 사자로 나타나 협력한다는 이야기를 간단히 설명했다. 다음은 소노가시라 회장에게 신의 사자로 나타났다는 비둘기 이야기다. 소노가시라 히로치카 회장과 비둘기 사자소노가시라 회장이 ‘생장의 집(生長の家)’ 강사였을 무렵, 도장에서 연수를 시작하면 비둘기 한 마리가 찾아왔다. 강의를 듣는 듯한 몸짓을 하거나 사람들의 둥근 모임 속으로 들어와 좀처럼 떠나지 않았다고 한다. 강습회가 열리는 동안 비둘기는 거듭 찾아와 사람들 사이에 끼었다. 당시 사진도 많이 남아 있으며, 모두가 신기하다며 놀랐다고 한다. 마찬가지로 소노가시라 회장이 이끌던 국제정법협회의 오다와라 연수회에서도 비둘기 한 마리가 날아와 언제까지나 회장의 강연을 듣는 듯한 모습을 보였고, 이 역시 사진으로 남아 있다고 한다. 다음은 회장이 세상을 떠난 직후 저자가 썼다는 비둘기 일화다. 이는 『정법 감사의 모임』 기관지와 정법 홈페이지에 공개한 글에서 발췌\n\n한 것이라고 한다. 원문은 주소를 www.shoho.com/이라고 밝히고, 2003년 5월 1일 현재 5년 반 동안 접속 수가 55만 건에 이르렀다고 적고 있다. 다만 현재는 운영이 중단된 상태라고 덧붙인다.",
    "notes": "",
