    "title": "종이 위에 나타난 예언의 글자",
    "origTitle": "「高橋信次師物語」 真のメシヤの記録 28　八起正法先生編",
    "contentType": "",
    "summary": "이 무렵부터 가까운 친구가 미래에 관한 예언을 부탁하면 종이 한 장 위에 글자가 나타났고, 놀랍게도 그 내용이 백발백중이었다고 한다. 종이 위에 글자로 예언이 나타난다는 것은 마치 텔레비전 마술쇼 같은 이야기다. 이에 관해서 저술가 가미노고 도시아키(...",
    "body": "이 무렵부터 가까운 친구가 미래에 관한 예언을 부탁하면 종이 한 장 위에 글자가 나타났고, 놀랍게도 그 내용이 백발백중이었다고 한다. 종이 위에 글자로 예언이 나타난다는 것은 마치 텔레비전 마술쇼 같은 이야기다. 이에 관해서 저술가 가미노고 도시아키(上之録利明)가 취재한 내용이 있으므로, 원문은 이를 요약해 소개한다. 부인 가즈에는 다음과 같이 말했다고 한다.\n\n“결혼하고 얼마 지나지 않았을 때의 일입니다. 아는 사람과 신에 관한 이야기를 나누고 있었어요. 믿기 어려운 이야기도 나오지요. 누군가 ‘거짓말이겠지요’라는 식으로 말하면, 소원을 종이 위에 적어 보라고 합니다. 그 종이를 촛불 위에 대고 무언가를 염원하는가 싶더니, 종이 위에 소원에 대한 답이 글자로 떠오르는 겁니다. 처음에는 저도 종이에 미리 답을 써 두었다가 불에 쬐어 글씨가 나타나게 하는 방식이 아닐까 의심했습니다. 그래서 직접 문구점에서 종이를 사 오기도 했지요. 하지만 어떤 종이를 사용해도 그때그때 적은 소원에 대한 답이 제대로 나왔습니다.” 가미노고는 이와 같이 기록했다고 한다. 저자는 신지 선생의 경우에는 마술이 아니라 마법과도 같은 생생한 사실들이 있기 때문에, 독자들이 믿어 줄지 늘 걱정된다고 말한다. 졸업 자격을 얻지 못하다이 무렵 신지 선생은 여러 종교를 편력하며 다양한 종교 단체를 찾아다니기도 했다. 그러나 그곳에서 광신하거나 맹신하는 사람들을 보면서 아편의 무서움만 느꼈다고 한다. 그런데 신지 선생은 주로 니혼대학교에서 공부했지만, 한동안 도쿄대학교에도 다녔다고 원문은 서술한다.\n\n그러나 졸업 논문의 주제가 “신적 에너지는 아래로는 아메바에서 위로는 대우주에 이르기까지”였고, 다소 규격에서 벗어난 내용이었던 탓인지 교수에게 비웃음을 샀다고 한다. 그 때문에 졸업 자격을 얻지 못했던 듯하다고 원문은 설명한다. 저자는 위대한 각자(覚者)의 졸업을 인정하지 않은 일이 유감스럽다고 말한다. 그러나 판에 찍어 낸 듯한 규격화된 학생을 조립 라인처럼 만들어 내는 현대 대학의 사고방식으로 보면 당연한 결과였을 것이라고도 평한다.\n\n또한 신지 선생은 의학과 천문학도 공부했지만, 자신만의 방식으로 공부하면 그것으로 충분했다고 한다.",
    "notes": "",
