    "contentType": "",
    "summary": "스물다섯 살 때 신지 선생은 전기 관련 일을 하기 위해 도쿄도 오타구 가미이케가미에 작은 공장을 빌리고, 대여섯 명의 종업원과 함께 일했다. 주로 자동 제어 장치를 만들었는데, 신지 선생 역시 피와 살을 지닌 한 청년이라는 점에서는 다르지 않았던 듯하...",
    "body": "스물다섯 살 때 신지 선생은 전기 관련 일을 하기 위해 도쿄도 오타구 가미이케가미에 작은 공장을 빌리고, 대여섯 명의 종업원과 함께 일했다. 주로 자동 제어 장치를 만들었는데, 신지 선생 역시 피와 살을 지닌 한 청년이라는 점에서는 다르지 않았던 듯하다. 욕망에 사로잡히고 이성에 대한 동경이 어느새 마음을 차지하면서, 그 문제로 점차 고민하게 되었다. 결혼과 인연신지 선생이 훗날 아내가 되는 가즈에를 처음 만난 것은 쇼와 28년(1953년), 신지 선생이 스물여섯 살 때 거래처 전기 제조업체에서였다. 거래 때문에 드나드는 사이 가즈에에게 마음이 끌렸다. 당시 신지 선생은 가즈에에게 자신의 미래와 마흔여덟 살까지 이어질 전 생애를 예고하고, 사업상의 실패와 문제도 모두 성실하고 솔직하게 이야기했다고 한다. 가즈에는 구마가야의 청과상 집안에서 태어났다. 성년식을 맞자 무슨 일이 있어도 도쿄에 나가고 싶어 했다고 한다. 그래서 부모를 설득한 뒤 지인의 소개로 니혼바시에 있는 전기 제조업체에 취직했고, 얼마 지나지 않아 신지 선생을 알게 되었다. 마이트레야에 관하여\n\n신지 선생이 가즈에에 관해 남겼다는 말을 요약하면 다음과 같다. 가즈에는 인도에서 석가가 살던 시대에 마이트레야(マイトレーヤー)라고 불렸으며, 석가 교단 최초의 여성 단원 네 사람 가운데 하나였다. 글을 읽고 쓸 줄 아는 총명한 여성이었다고 한다. 석가 교단에서 맡은 일은 “오늘 밤 어느 곳에서 석가의 설법이 있습니다”라고 알리기 위해 낮 동안 종과 북을 울리며 돌아다니거나, 석가의 신변을 부지런하고 세심하게 보살피는 일이었다. 석가가 세상을 떠난 뒤에는 고향으로 돌아가 제자들에게 불교를 가르쳤으며, 석가가 예고한 미래에 관해 자세히 기록해 남겼기 때문에 미래불이라 불렸다는 것이다. 더욱이 마이트레야는 이름을 바꾸어 미로쿠(미륵)라고 불렸고, 타레야 또는 사치라고도 했으며, 사치(サチ)·사이와이(幸)·사치코(幸子)라는 말의 어원이 되었다고 원문은 설명한다.",
    "notes": "",
    "image": "https://raw.githubusercontent.com/concario17-max/shinji/33f81d5266c36192c933d734494bd922df4702d8/images/stories/029.webp",
