    "summary": "결혼은 했지만 어음 부도로 회사가 도산하면서 신지 선생은 사업에 실패해 무일푼이 되었다. 신지 선생은 그 원인이 미숙한 경영에 있었다고 스스로 고백했는데, 이 실패는 그에게 좋은 경험이 되었던 듯하다. 결혼 전에 이미 도산을 예고했고, 결혼한 뒤 실제...",
    "body": "결혼은 했지만 어음 부도로 회사가 도산하면서 신지 선생은 사업에 실패해 무일푼이 되었다. 신지 선생은 그 원인이 미숙한 경영에 있었다고 스스로 고백했는데, 이 실패는 그에게 좋은 경험이 되었던 듯하다. 결혼 전에 이미 도산을 예고했고, 결혼한 뒤 실제로 회사가 도산하면서 모든 일이 한꺼번에 닥친 모양이었다. 신지 선생은 우에노의 지하도에서 며칠을 보내기도 했던 듯하다. 당시 신지 선생 부부는 아파트에서 살았으므로 열쇠 하나만 들고 어디든 갈 수 있을 만큼 단출한 처지였다. 직업을 잃은 신지 선생은 이웃 사람들의 상담을 들어 주고 그들이 건네는 적은 사례금으로 생활을 이어 갔다. 신지 선생은 자신의 책에서 다음과 같이 말했다.\n\n“이웃 사람들과 교류하는 가운데 불가사의한 현상이 시작되었고, 예언은 거의 모두 적중했다. 상담하러 온 사람들이 비좁은 아파트를 가득 메울 때도 있었다.\n\n그러나 왜 예언이 맞는지는 나 자신도 대답할 수 없었다. 그래서 나 자신도 그것을 믿지는 않았으며, 사악한 마음도 없었다.” 장녀 게이코의 탄생쇼와 31년(1956년), 신지 선생이 스물아홉 살 때 장녀 게이코가 태어났다. 아내 가즈에는 다음과 같이 말했다.\n\n“선생님은 태어날 아이가 모두 딸이라고 미리 말했기 때문에 여자아이 물건만 준비했습니다.” 그 뒤 둘째 딸도 태어났다.",
