    "contentType": "",
    "summary": "이러한 일이 어떻게 일어나는지를 설명하면서 신지 선생은 저세상 영들의 협력으로 이루어지는 것이므로 자유자재로 가능하다고 말했다고 한다. 한때 눈에서 진주를 꺼내거나 만주 속에서 다이코쿠 신상을 꺼내던 사람도 있었다. 그러나 저자가 단도직입적으로 말하자...",
    "body": "이러한 일이 어떻게 일어나는지를 설명하면서 신지 선생은 저세상 영들의 협력으로 이루어지는 것이므로 자유자재로 가능하다고 말했다고 한다. 한때 눈에서 진주를 꺼내거나 만주 속에서 다이코쿠 신상을 꺼내던 사람도 있었다. 그러나 저자가 단도직입적으로 말하자면, 핵심은 저세상에서 협력하는 영의 질 또는 수준에 있다는 것이다. 폭포수를 맞는 수행과 같은 육체 수행을 하거나 기도를 거듭해 나타나는 것은 대부분 동물령 또는 인간의 지옥령이라고 여겨지므로, 주의 깊게 정견(正見)할 필요가 있다고 저자는 말한다. 모세·석가모니·예수의 영적 능력은 올바른 빛의 천사들이 협력하여 이루어진 듯하다고 설명한다. 성경에는 예수가 빵 한 조각으로 수천, 수만 명을 도왔다고 기록되어 있는데, 신지 선생은 저세상 영들의 협력으로 빵의 물질화 현상이 일어나 실제로 많은 사람이 구원받은 것이라고 말했다고 한다.\n\n그러나 눈에서 진주를 꺼낸다는 사람은 진주를 많이 꺼내 목걸이라도 만들 생각인 것일까. 저자는 그것과는 생각하는 차원 자체가 전혀 다르다고 말하고 싶다고 한다. 올바르게 생각하는 사람이라면 그 힘으로 빵이나 우유를 만들어 아프리카에서 굶어 죽어 가는 아이들을 돕겠다고 생각하지 않겠느냐고 묻는다. 돈벌이에 빠지다신지 선생은 언제나 생활 기반에 뿌리를 두고 신불에 관해 생각했다고 한다. 그 무렵 신지 선생의 처남은 몸이 약했기 때문에 창가학회에 광신적으로 빠져들었고, 당연히 신지 선생의 집에도 절복하러 찾아왔다. 그러나 지용보살(地涌菩薩)은 강압적인 절복으로 불법을 설하지 않는 법이다. 투쟁과 파괴의 상념과 행위는 보살의 마음이 아니라고 신지 선생은 하나하나 비판했다고 한다. 이 무렵에는 사업도 순조롭게 성장하고 있었다. 신지 선생은 경제력이 없으면 사람들을 구할 수도 없다고 생각하여 돈을 버는 데 전념했고, 그 때문에 본래 가야 할 길과 다른 방향으로 나아가기 시작했다. 그 결과 신지 선생은 종업원과의 의사소통 문제, 회사 내부의 혼란, 가정의 혼란이라는 소용돌이 속으로 들어가게 되었다.",
    "notes": "",
