    "contentType": "",
    "summary": "쇼와 43년(1968년), 신지 선생이 마흔한 살 때의 일이다. 2월 무렵부터 신지 선생의 주변에서 불가사의한 현상이 일어나기 시작했다. 아버지가 세상을 떠난 뒤 신지 선생은 불단 앞에서 명상하는 일을 일과로 삼았다. 2월 3일 오전 1시, 신지 선생...",
    "body": "쇼와 43년(1968년), 신지 선생이 마흔한 살 때의 일이다. 2월 무렵부터 신지 선생의 주변에서 불가사의한 현상이 일어나기 시작했다. 아버지가 세상을 떠난 뒤 신지 선생은 불단 앞에서 명상하는 일을 일과로 삼았다. 2월 3일 오전 1시, 신지 선생이 불전에 등불을 밝히고 마음의 조화를 꾀하고 있을 때 바람도 없는데 갑자기 등불의 불꽃이 25센티미터 높이로 치솟았다고 한다. 본래라면 3센티미터가량이어야 할 불꽃이었다. 그 뒤 불꽃은 저절로 작아졌다가 연꽃 모양으로 변했고, 마지막에는 연밥 모양으로 바뀌었다. 신지 선생을 비롯한 사람들이 그 변화를 놀라서 지켜보았다고 한다. 2월 5일에는 촛불이 약 22센티미터까지 치솟고 불꽃 끝이 둘로 갈라졌다. 점차 연꽃처럼 변하더니 15분 뒤에는 연밥과 똑같은 모습이 되었다고 한다. 가족은 그저 어안이 벙벙한 채 지켜보았다. 이윽고 신지 선생 앞에 ‘육체의 조상’이라고 자칭하는 14대 전 조상이 나타나 이름을 밝혔다. 그는 신지 선생이 태어난 사쿠 지역이 전국시대에 가이의 다케다 세력에게 지배받던 때의 신지 선생의 육체적 조상이었다고 한다. 이는 뒤에 나올 ‘영혼의 조상’과 대비되는 용어이다.\n\n“나는 그대의 조상인 다케노조 한쿠로 도모유키(竹之丞半九郎友幸)다. 14대 전 미나모토노 요리토모의 후손으로 다케다 신겐의 휘하에 들어갔다고 전해진다.” 그 뒤 조상은 신지 선생에게 계속 이야기했다. 센고쿠다이라의 숲에서 전사한 일과 무덤을 조사하면 그 수수께끼가 풀릴 것이라는 말까지 자세히 설명했다고 한다.\n\n“그 무덤 안에는 나와 아들의 머리가 들어 있다. 갑옷과 칼은 아마 완전히 녹슬었을 것이다.”\n\n또한 “이제 내가 육체의 조상으로서 그대에게 이 사실을 말할 수 있어 기쁘다”고 전했다. 그 뒤 신지 선생이 이 이야기를 사쿠 사람들에게 하자 실제로 머리 두 개와 녹슨 쇠붙이가 있었다는 사실이 확인되었다고 원문은 서술한다. 그 조상은 또 이렇게 말했다고 한다.\n\n“육체적 자손을 사쿠 땅에 남긴 것도 언젠가 이 일을 알아주기를 바랐기 때문이다.” 이 무렵부터 신지 선생이 육체의 조상이라는 문제를 탐구할 구체적인 실마리도 하나씩 풀리기 시작했다. 신지 선생은 육체의 조상이란 이 지구에 적응한 육체로서 신불이 보존한 것이며, 그 육체는 영혼이 타는 배라는 사실을 깨달아 갔다고 한다.\n\n이어서 신지 선생이 밝혔다는 사례를 통해 육체의 조상과 영혼의 조상을 설명해 보자.",
    "notes": "",
