    "title": "육체의 조상과 영혼의 조상",
    "origTitle": "「高橋信次師物語」 真のメシヤの記録 36　八起正法先生編",
    "contentType": "",
    "summary": "육체의 조상이란 다카하시 집안의 아버지와 ○○ 집안의 어머니가 결혼하여 열 남매 가운데 둘째 아들로 다카하시 신지 선생이 태어났다는 식의 혈연, 혈통, 혈족 관계를 가리킨다. 일반적으로 조상이라고 하면 이것을 뜻한다. 한편 영혼의 조상은 다음과 같이 ...",
    "body": "육체의 조상이란 다카하시 집안의 아버지와 ○○ 집안의 어머니가 결혼하여 열 남매 가운데 둘째 아들로 다카하시 신지 선생이 태어났다는 식의 혈연, 혈통, 혈족 관계를 가리킨다. 일반적으로 조상이라고 하면 이것을 뜻한다.\n\n한편 영혼의 조상은 다음과 같이 이어진다고 원문은 설명한다. 3억 6천5백만 년 전, 일곱 대천사와 함께 UFO, 곧 반중력 광자 우주선을 타고 지구에 온 참된 메시아 엘란티에서 시작한다. 그 계보는 1만 년 전 아틀란티스의 아가샤 대왕, 3,150년 전의 모세(저세상에서도 모세라고 부른다), 2,500년 전의 석가모니(저세상에서는 칸타레라고 부른다), 2천 년 전의 예수 그리스도(저세상에서는 이마니엘 예수 그리스도 또는 인마넬 예수 그리스도라고 부른다), 20세기의 다카하시 신지 선생으로 이어진다고 한다. 엘란티가 지구 창세 때 최초의 본체이고, 아가샤 대왕·모세·석가모니·그리스도는 그 분령(分録)이며, 다카하시 신지 선생은 다음 본체라는 것이다.\n\n이처럼 정법(正法)에서는 혈연관계가 아닌 영혼과 영의 이어짐 및 관계를 영혼의 조상이라고 부른다고 한다. 석가모니의 생명 계보원문은 생명이 영원한 인간에게는 혈연관계가 없더라도 혈통보다 영혼의 영적 계보가 더 중요하다고 설명한다.\n\n또한 석가모니는 저세상에서 칸타레라고 불리며, 그의 영적 계보를 풀어 보면 다음과 같다고 한다. 본체 석가모니(인도) → 분신 불공삼장(不空三録, 인도) → 분신 천태지의(天台智録, 중국) → 분신 전교대사(사이초, 일본) → 분신 구쿄(空教, 일본) → 분신 기도 다카요시(기도 고고로, 일본). 석가모니로 태어나기 직전의 분신은 중인도에서 왕의 아들로 태어났고, 그보다 앞선 생명은 리엔트 아르 크라드(リエ ント・アール・クラード)라는 이름으로 남아메리카 안데스산맥 기슭에서 태어났다고 한다. 더 앞선 생명은 아틀란티스 제국의 아가샤 대왕으로서 신리를 설했다는 것이다. 원문은 이어서 모세·석가모니·예수에 관해 더 살펴보겠다고 한다.",
    "notes": "",
