    "contentType": "",
    "summary": "원문은 기독교에서 예수·성령·교회를 삼위일체라고 전하지만, 신지 선생은 그것이 잘못이라고 말했다고 서술한다. 신지 선생은 진실한 삼위일체란 엘란티 안에서 모세·석가모니·예수를 가리키는 것이라고 바로잡았다는 것이다. 유대교와 불교와 기독교의 신리는 하나...",
    "body": "원문은 기독교에서 예수·성령·교회를 삼위일체라고 전하지만, 신지 선생은 그것이 잘못이라고 말했다고 서술한다. 신지 선생은 진실한 삼위일체란 엘란티 안에서 모세·석가모니·예수를 가리키는 것이라고 바로잡았다는 것이다. 유대교와 불교와 기독교의 신리는 하나이며, 인간이 종교 문제로 대립하고 서로 다투는 일은 참으로 슬픈 일이라고 저자는 말한다. 그런데 예수가 기원 1년에 태어나 서기 연도와 같은 나이를 거쳤다는 이야기는 상식처럼 알려져 있다. 그러나 신지 선생은 사실 예수가 기원전 32년에 태어났다고 정정했다고 한다. 그렇다면 서기 2003년은 실제로는 2035년이 되는 것이 아니겠느냐고 원문은 묻는다. 그 이야기는 잠시 접어 두고, 이어서 예수의 생명 계보를 설명한다. 예수의 생명 계보본체 예수 그리스도 → 분신 클라리오(크라이오라고도 하며, 기원전 4000년 이집트) → 분신 마그네치오(기원전 2000 년 이집트) → 본체 예수(기원전 32년 이스라엘) → 분신 마그가리스(서기 200년 이스라엘) → 분신 포아이 신 포아이 신포(서기 400년경 중국) → 분신 바로인(서기 1500년경 영국) → 분신 안토니오 아그파오아, 통칭 토니(앞서 말했듯 쇼와 57년인 1982년에 사망, 필리핀).",
