    "contentType": "",
    "summary": "앞에서 예수의 분신인 통칭 토니가 여성 문제 때문에 괴로워하다 뇌혈관 장애로 일찍 세상을 떠났다고 설명했다. 원문은 150년 뒤, 곧 쇼와 48년인 1973년을 기준으로는 180년 뒤에 시카고에서 태어날 예수의 본체가 분신 토니의 카르마, 곧 업과 마...",
    "body": "앞에서 예수의 분신인 통칭 토니가 여성 문제 때문에 괴로워하다 뇌혈관 장애로 일찍 세상을 떠났다고 설명했다. 원문은 150년 뒤, 곧 쇼와 48년인 1973년을 기준으로는 180년 뒤에 시카고에서 태어날 예수의 본체가 분신 토니의 카르마, 곧 업과 마음의 경향성까지 바로잡아야 하므로 안타까운 일이라고 말한다. 분신은 자기 마음의 수행만 하면 되지만, 본체는 자기뿐 아니라 분신의 마음이 지닌 경향성까지 바로잡고 수정해야 하므로 그 책임이 막중하다는 것이다. 다시 한번 강조하자면, 일반적으로 조상은 육체의 조상을 가리키지만 영혼은 영원하므로 영혼의 조상도 특별히 마음에 새겨야 한다고 원문은 설명한다. 이렇게 신지 선생은 육체가 ‘영혼이 타는 배에 지나지 않는다’는 사실을 깨달아 갔다고 한다. 그 뒤 신지 선생이 가까운 사람들에게 빛을 주어 마음을 조화시키자 영적 현상이 잇달아 일어나게 되었다고 한다. 그 무렵에도 회사 일은 여전히 바빴다. 신지 선생은 아사쿠사에 건물을 짓기 시작했기 때문에 낮에는 아사쿠사의 건설 현장과 공장을 오가며 쫓기듯 지냈던 듯하다. 영적 현상그러던 1968년(쇼와 43년) 7월 3일, 마침내 신지 선생의 주변에 올 것이 왔다고 원문은 서술한다. 신지 선생이 많은 사람에게 빛을 주자 그 주변에서 영적 현상이 잇달아 일어났다. 신지 선생은 이를 통해 자기 능력 이외의 작용이 움직이고 있다는 사실을 깨달았다고 한다. 영적 현상에 관해 여러 이야기를 나누던 어느 날, 신지 선생의 처남이 “제게도 꼭 현상을 보여 주십시오”라고 부탁했다. 오전 1시, 신지 선생이 처남의 마음을 조화시키고 손바닥으로 빛을 보내자 처남의 입에서 옛 무사의 목소리가 흘러나와 말하기 시작했다고 한다. 처남은 자기 입을 통해 말이 나오는데도 자신이 무언가를 말하고 있다는 사실에 몹시 놀랐다. 원문에 따르면 신지 선생은 처남을 지배하는 영을 볼 수 없었으므로, 다소 무책임한 일처럼 보이지만 처남의 입을 통해 흘러나오는 말을 믿을 수밖에 없었다고 한다. 세상에는 영매나 구치요세(口寄せ, 영을 불러 말을 전하는 행위)가 있지만, 신지 선생은 별도로 무엇을 모시지 않았고 늘 자택 응접실에서 실험했다고 한다. 대부분의 영매나 구치요세는 제단을 마련하고 경을 외우면 영이 나타나는 듯하지만, 신지 선생에게는 아무런 도구도 필요하지 않았다는 것이다.\n\n또한 신지 선생 집안이 대대로 믿어 온 종파는 조동종이었던 듯하지만 그 영향은 보이지 않았다고 원문은 말한다.",
    "notes": "",
