    "title": "처남의 입을 통해 말한 영",
    "origTitle": "「高橋信次師物語」 真のメシヤの記録 39　八起正法先生編",
    "contentType": "",
    "summary": "7월 5일의 일이다. 처남의 입을 통해 다음과 같은 말이 나왔다고 한다. “이 사람이 쇼와 40년(1965년) 2월 자동차 사고를 당해 7일 동안 의식을 잃었을 때, 그를 구한 것은 바로 나다.” 이는 중학교 3학년 3학기에 자동차와 오토바이가 정면으...",
    "body": "7월 5일의 일이다. 처남의 입을 통해 다음과 같은 말이 나왔다고 한다.\n\n“이 사람이 쇼와 40년(1965년) 2월 자동차 사고를 당해 7일 동안 의식을 잃었을 때, 그를 구한 것은 바로 나다.” 이는 중학교 3학년 3학기에 자동차와 오토바이가 정면으로 충돌한 사고를 당한 처남이 의식을 잃고 죽음의 문턱을 헤맬 때, 지금 처남의 입을 통해 말하는 영이 협력하여 그를 구했다는 중대한 이야기였다고 원문은 설명한다. 신지 선생의 처남은 당시 사정을 다음과 같이 말했다. 처남의 말\n\n“제가 교통사고에서 회복하자 매형에 관한 일을 모두 알게 되었습니다. 가끔 매형이 거짓말을 하면 제가 그것을 알아차렸기 때문에, 매형은 저를 보고 ‘악마냐?’고 말하기도했습니다. 그런데 매형이 깨달음을 얻은 순간 제 영적 능력도 사라졌고, 저는 평범한 사람으로 돌아왔습니다.” 7월 6일, 신지 선생은 자신이 줄곧 탐구해 온 ‘또 하나의 자신’을 마침내 발견할 수 있는 단계에 이르렀다. 7월 7일 밤, 신지 선생이 다시 처남을 중심으로 실험하자 역시 영적 현상이 일어났다.\n\n그러나 그날 밤의 영은 일본인이 아니었고 전날까지 나타난 영과 달리 말도 통하지 않았다. 이에 신지 선생이 “어제까지 말씀하시던 영으로 바꾸어 주십시오”라고 하자 어제의 영으로 바뀌었다고 한다.",
    "notes": "",
