    "contentType": "",
    "summary": "영은 신지 선생의 처남의 입을 통해 말하고 있었다. 처남의 연기라고 하기에는 너무나 정교했기 때문에 신지 선생은 믿지 않을 수 없었다. 그러자 바로 그 순간, 마음속으로 생각한 것에 대한 대답이 신지 선생의 마음에 되돌아왔다. “믿는 것은 당연한 일이...",
    "body": "영은 신지 선생의 처남의 입을 통해 말하고 있었다. 처남의 연기라고 하기에는 너무나 정교했기 때문에 신지 선생은 믿지 않을 수 없었다.\n\n그러자 바로 그 순간, 마음속으로 생각한 것에 대한 대답이 신지 선생의 마음에 되돌아왔다.\n\n“믿는 것은 당연한 일이다.” 도무지 어찌할 수 없게 된 신지 선생은 마음을 굳히고 용기를 내어 원 투 스리에게 물었다.\n\n“저를 지켜 주시는 분은 누구십니까?”\n\n“그러면 잠시 기다려라.” 그로부터 1분쯤 지나자 포아이 신 포아이 신포라는 영이 처남을 지배했다. 그가 말하기 시작한 언어는 옛 중국말과 같았다고 한다. 이름을 기억할 수 없었던 신지 선생이 “한 번 더 성함을 가르쳐 주십시오”라고 두세 번 되풀이하자, 그 영은 마치 중국인이 문법을 무시한 채 말하는 것 같은 서툰 일본어로 신지 선생을 꾸짖었다.\n\n“이 바보야. 너처럼 어리석은 자와는 더 말하지 않겠다. 이 바보 같은 자야.” 7월 3일을 경계로 신지 선생은 음식도 목으로 넘길 수 없는 상태가 되었다. 평소 하던 일도 손에 잡히지 않았고, 직원들이 업무에 관해 물어도 건성으로 대답했다. 정신적 충격이란 바로 이런 것이리라 싶을 만큼, 늘 다른 사람이 마음속에 함께 살고 있는 듯하여 견딜 수 없었다고 한다. 7월 8일 밤신지 선생이 밤 9시쯤 집에 돌아오자 응접실에서는 원 투 스리를 비롯한 여러 영이 처남의 육체를 지배하고 있는 듯했다. 원 투 스리는 신지 선생과 마주치자마자 추궁했다.\n\n“나는 원 투 스리다. 당신은 지금까지 무엇을 하고 있었나?” 이제 처남은 예전처럼 명상하지 않아도 의식을 지배당하고 있었다. 신지 선생이 “예, 아사쿠사의 건설 현장에서 협의하고 있었습니다”라고 대답하자, 원 투 스리는 꾸짖었다.\n\n“또 거짓말을 하는군. 현장에는 낮까지만 있었을 텐데.” 그러고는 신지 선생이 파친코를 해서 담배 세 갑을 탄 일, 요릿집에서 게이샤를 불러 술을 마신 일, 심지어 그 게이샤의 이름까지 말했다고 한다. 추궁이 끝없이 이어지자 신지 선생은 생각하는 일조차 그만두려 했지만 그것도 마음대로 되지 않았다. 그래서 신지 선생은 ‘보지 않고, 말하지 않고, 듣지 않는’ 태도를 굳게 지켜 보자고 생각했다고 한다.",
    "notes": "",
