    "title": "수호령이 내린 사흘의 기한",
    "origTitle": "「高橋信次師物語」 真のメシヤの記録 42　八起正法先生編",
    "contentType": "",
    "summary": "신지 선생은 이 세 원숭이의 가르침이 천태대사 지의(天台大師智録), 곧 석가모니의 분신인 천태지의의 가르침이라고 밝혔다고 한다. 그러나 영은 신지 선생이 마음속으로 생각하는 것까지 파고들어 지적했다. 신지 선생이 “에라, 이제는 될 대로 되라” 하고 ...",
    "body": "신지 선생은 이 세 원숭이의 가르침이 천태대사 지의(天台大師智録), 곧 석가모니의 분신인 천태지의의 가르침이라고 밝혔다고 한다. 그러나 영은 신지 선생이 마음속으로 생각하는 것까지 파고들어 지적했다. 신지 선생이 “에라, 이제는 될 대로 되라” 하고 소파에 앉아 있자, 이번에는 포아이 신 포아이 신포가 원 투 스리와 교대하여 다음과 같이 말했다.\n\n“나는 너의 수호령이다. 전생에 너와 친구였고, 함께 불교를 배운 동료이기도 하다. 네가 지상계에 태어났을 때부터 너를 지켜 왔지만, 너만큼 손이 많이 가는 남자도 없었다. 지금까지와 같은 마음가짐으로 살면 지옥으로 갈 것이며, 네 가정과 회사도 모두 와해될 것이다.” 전생에 함께 불교를 공부했다고 해도 신지 선생에게는 아무런 기억이 없었다. 자신은 일본인인데 어째서 외국인이 지켜 주는 것일까 하는 의문도 들었다고 한다.\n\n“어떤 방식으로 저를 지켜 주고있습니까?” 신지 선생이 묻자 그 영은 다음과 같이 알렸다.\n\n“네가 선한 마음을 지니도록 네 마음속에서 이끌고 있다.” 또 이렇게도 말했다.\n\n“본래라면 수호령 따위는 하고 싶지도 않지만, 약속했기 때문에 지키고 있는 것이다.”\n\n그리고 한층 더 엄하게 명령했다고 한다.\n\n“다른 영과 바꾸고 싶을 정도다. 약속하지 않았다면 내가 맡을 일이 아니지만, 너 같은 인간을 지키려면 엄하게 하지 않을 수 없으므로 내가 하는 것이다. 지금부터 사흘의 유예를 줄 테니 깨달아라. 우주의 어디로 달아나도, 죽는다 해도 붙잡을 것이니 각오하고 깨달아라.” 수호령은 7월 9일부터 사흘 안에 모든 방침을 바로잡으라고 기한을 정했지만, 신지 선생은 무엇을 어떻게 해야 할지 알 수 없었다. 신지 선생의 모든 것이 수호령에게는 한눈에 환히 보였으며, 마음을 바로잡을 때까지 자신들은 눈을 떼지 않겠다는 말까지 했다고 한다. 신지 선생의 고뇌는 보통이 아니었다. 불과 나흘 만에 8킬로그램이나 빠졌고 음식도 넘기지 못했으며, 집안 분위기는 얼어붙은 듯 변해 버렸다는 것이다.",
    "notes": "",
