    "title": "7월 12일, 답을 찾아 사찰로",
    "origTitle": "「高橋信次師物語」 真のメシヤの記録 43　八起正法先生編",
    "contentType": "",
    "summary": "7월 12일. 어떻게든 해야 한다는 조바심은 커졌지만, 기한으로 정해진 날이 와도 신지 선생은 어찌할 도리가 없었다. 신지 선생은 수호령에 관한 의문을 고야산의 수행승에게 물었으나 다음과 같은 대답만 들었다. “그런 이야기는 들어 본 적도 없습니다.”...",
    "body": "7월 12일. 어떻게든 해야 한다는 조바심은 커졌지만, 기한으로 정해진 날이 와도 신지 선생은 어찌할 도리가 없었다. 신지 선생은 수호령에 관한 의문을 고야산의 수행승에게 물었으나 다음과 같은 대답만 들었다.\n\n“그런 이야기는 들어 본 적도 없습니다.” 하는 수 없이 우에노의 간에이지(寛永寺) 문까지 두드렸다.\n\n“가장 높은 분을 만나고 싶습니다. 이러이러한 사정이 있으니 꼭 저를 구해 주십시오.” 신지 선생이 애원했지만 상대는 냉담하게 대답했다.\n\n“그런 일은 저도 알 수없습니다.” 그런데 그 노승의 손이 아파 보였다. 신지 선생은 “통증을 없애 드리지요”라고 말하고 일념으로 힘을 집중하여 약 5분 만에 통증을 멎게 했다고 한다. 노승은 조언했다.\n\n“지바의 나카야마사(中山寺)에 가면 알 수 있을지도 모릅니다. 한번 가 보시는 것이 어떻겠습니까?” 신지 선생은 택시를 타고 나카야마사로 갔다. 산문에 걸터앉아 생각에 잠겼고, 침울한 마음으로 자기 자신을 반성했다. 이제 남은 기한은 얼마 되지 않았다. 다른 사람에게서 만족스러운 답을 얻으려 했던 것은 자기 자신으로부터 달아나려 한 일이었다고 신지 선생은 되돌아보았다는 것이다.",
    "notes": "",
