    "title": "마음의 출항",
    "origTitle": "「高橋信次師物語」 真のメシヤの記録 44　八起正法先生編",
    "contentType": "",
    "summary": "그 한 주 동안 신지 선생은 마음이 가라앉고 자기 자신을 완전히 잃었다. 그러나 선한 행위를 되찾고 악한 생각과 행위를 버리기 위해 진심으로 반성했다. 원 투 스리와 신포도 악마일지 모른다. 신이 나약한 인간을 괴롭힐 리 없다. 오늘 밤은 설령 죽임을...",
    "body": "그 한 주 동안 신지 선생은 마음이 가라앉고 자기 자신을 완전히 잃었다. 그러나 선한 행위를 되찾고 악한 생각과 행위를 버리기 위해 진심으로 반성했다. 원 투 스리와 신포도 악마일지 모른다. 신이 나약한 인간을 괴롭힐 리 없다. 오늘 밤은 설령 죽임을 당해도 좋다. 그들이 악마라면 내가 선으로 바꾸어 놓겠다. 신지 선생은 이렇게 큰 결심을 했다. 마침내 마음도 차분해졌으며, 원 투 스리와 신포에게 맞서는 길밖에는 없다고 마음먹었다. 게이세이 전철을 타고 국철 전철로 갈아타 집으로 돌아가는 동안 신지 선생의 마음에는 평온함이 되살아났다고 한다. 신지 선생은 아내에게 자신의 결심을 말했다.\n\n“오늘 밤 살해당할지도 몰라. 어떤 현상이 일어날지 모르지만 이제는 괜찮아. 그들과 맞서서, 만일 악이라면 선으로 바꾸어 놓겠어.”\n\n그러자 신지 선생의 마음속에서 신포의 목소리가 들려왔다.\n\n“지금과 같은 마음을 잊지 마라.” 아내는 “여보, 마음을 굳게 먹고 새롭게 출발해요”라고 격려했다.\n\n잠시 뒤 처남이 돌아왔다. 원 투 스리는 처남의 입을 통해 신포와 같은 말을 했다고 한다. 이어 원 투 스리는 평소와 달리 자애가 가득한 부드러운 말로 이렇게 전했다.\n\n“오늘 밤은 네 마음이 올바르게 바뀌었으므로 천상계가 빛으로 가득 차 축하 잔치가 열린다. 이곳에서도 함께 축하하자.” 이렇게 신지 선생의 가족 모두가 새롭게 태어난 가정을 위해 진심으로 축하했다. 신지 선생이 ‘또 하나의 신지 선생’을 추구해 온 지 32년 만에 마침내 목적을 향한 막이 올랐다. 이후에는 처남을 통하지 않고 원 투 스리와 신포가 신지 선생에게 직접 소식을 전하게 되었다.",
    "notes": "",
