    "title": "처남을 통해 나타난 아인슈타인의 영",
    "origTitle": "「高橋信次師物語」 真のメシヤの記録 45　八起正法先生編",
    "contentType": "",
    "summary": "그 뒤 처남에게는 원자폭탄의 이론적 바탕이 된 아인슈타인 박사의 영이 나타났다. 신지 선생은 그에게서 극미(極微)의 세계와 극대(極大)의 세계에 관한 설명을 들었으며, “자연의 법칙이야말로 인간이 어떻게 살아야 하는지를 가르쳐 준다”는 가르침도 받았다...",
    "body": "그 뒤 처남에게는 원자폭탄의 이론적 바탕이 된 아인슈타인 박사의 영이 나타났다. 신지 선생은 그에게서 극미(極微)의 세계와 극대(極大)의 세계에 관한 설명을 들었으며, “자연의 법칙이야말로 인간이 어떻게 살아야 하는지를 가르쳐 준다”는 가르침도 받았다고 강연에서 말했다. 지도령 원 투 스리는 올바른 인생의 모습과 신의 자녀라는 증거에 관한 책을 쓰라고 신지 선생에게 제안하고, 자신도 협력하겠다고 전했다. 8월에 들어서는 마음이라는 문제를 한층 자세히 설명했다고 한다. 한 달 전만 해도 신지 선생은 엉뚱한 방향으로 탐구를 이어 가고 있었다. 그러나 이제 마음은 완전히 맑아졌고, 줄곧 찾아 헤매던 ‘또 하나의 신지 선생’이 무엇인지도 분명한 윤곽을 잡은 듯했다. 원문은 신지 선생이 깨달음을 얻은 날을 쇼와 43년(1968년) 7월 12일로 기록한다. 신지 선생은 제자인 무라카미 유카이에게 다음과 같이 말했다고 한다.\n\n“스님, 나는 깨달음을 얻었어. 7월 12일의 일이야. 현생의 일도 전생의 일도 무엇이든 전부 알 수 있어. 깨달음은 참으로 훌륭한 것이야.” 또 다른 제자 와타나베 야스오는 자신의 책에 다음과 같이 썼다.\n\n“선생님은 그때 절의 산문에서 생각에 잠기셨습니다. 이치카와 지부의 지구좌(地区座) 모임은 그 산문에서 100미터도 떨어지지 않은 곳에서 열렸지요. 아주 최근까지도, 지금 생각하면 거짓말처럼 느껴지는 일이지만, 불과 30~40명이 모인 자리에 일부러 말씀하러 와 주셨습니다.” 아인슈타인의 이론은 잘못되었는가? 앞서 처남에게 아인슈타인 박사의 영이 나타났다고 서술했는데, 원문은 여기에 다음 이야기를 덧붙인다. 어느 날 신지 선생이 아인슈타인의 영을 불러내자 그 영은 머리를 숙이며 말했다고 한다.\n\n“나의 상대성이론은 잘못되어 있었습니다.”\n\n그리고 다음과 같이 정정했다는 것이다.\n\n“진공은 완전한 공(空), 곧 아무것도 없는 공간이 아니라 에너지로 가득한 공간입니다.” 원문은 최근 이를 우주 에너지 또는 영성 에너지라고 부르기도 하고, 상대성이론에 맞서 절대성이론이라고도 하지만, 어쨌든 아인슈타인의 영이 자신의 이론을 정정한 것이라고 설명한다. 와타나베의 책에는 “그때의 테이프에는 독일어와 영어가 뒤섞여 있었기 때문에 아직도 해명하거나 정리하지 못했다”고 적혀 있다고 한다.",
    "notes": "",
