    "title": "신지 선생이 밝혔다고 하는 니치렌의 윤회",
    "origTitle": "「高橋信次師物語」 真のメシヤの記録 47　八起正法先生編",
    "contentType": "",
    "summary": "다시 간단히 되짚어 보자. 가란다 장자는 기원전 500년 인도에서 태어난 뒤, 5세기 중국에서 중장(中録)으로 태어났다고 한다. 5세기의 중장에게는 두 자녀, 곧 누나 임장(林録)과 남동생 오장(吾録)이 있었다. 남동생 오장이 훗날 일본에서 니치렌으로...",
    "body": "다시 간단히 되짚어 보자. 가란다 장자는 기원전 500년 인도에서 태어난 뒤, 5세기 중국에서 중장(中録)으로 태어났다고 한다. 5세기의 중장에게는 두 자녀, 곧 누나 임장(林録)과 남동생 오장(吾録)이 있었다. 남동생 오장이 훗날 일본에서 니치렌으로 다시 태어났다는 것이다. 원문은 니치렌의 생명 계보를 따라가면 구카이에 이른다고 설명한다. 니치렌은 가마쿠라 시대에 구카이가 설한 진언밀교를 ‘진언망국(真言亡国)’, 곧 진언밀교가 나라를 망친다며 거세게 비판했다. 하지만 그 뒤 빛의 사자라고도 할 수 있는 종교인들이 승병이 되어 권력에 복속되고 그 체제 속으로 편입되어 갔다. 그러한 모습은 보살계의 빛의 천사인 니치렌으로서는 마음 깊은 곳에서 도저히 참을 수 없는 일이었으리라고 저자는 풀이한다. 신지 선생은 강연에서 니치렌에 관해 다음과 같이 말했다고 한다.\n\n“니치렌은 성격이 거칠어 다른 종파들을 마구 베어 내듯 비판했다. ‘진언망국’, ‘선천마(録天魔, 선을 닦으면 마에 침범당한다는 뜻)’ 같은 거리 설법을 펼쳤다. 그는 그러한 일을 반성하며 600년 동안 고계(苦界)에 몸을 담갔다.” 또 다른 강연에서는 다음과 같이 말했다고 한다.\n\n“니치렌은 그 책임을 지고 고계, 곧 지옥계에 몸을 담갔지만 겸허한 분이어서 저세상에서 모르는 사람이 없습니다. 창가학회에서 하는 것과 같은 것이 아닙니다.” 니치렌의 영혼 계보가 중국 시대의 누나 임장에게까지 이어진다는 것이 불가사의하지만, 원문은 다음으로 신지 선생의 여동생이자 과거에 임장이었다는 호시 ○코의 글을 소개한다.",
    "notes": "",
