    "title": "「자비와 사랑에 관하여」",
    "origTitle": "「高橋信次師物語」 真のメシヤの記録 48　八起正法先生編",
    "contentType": "",
    "summary": "호시 ○코의 글이다. “독자 여러분은 ‘사랑’이라는 말을 자주 듣고 또 실천하고 계시리라 생각합니다. 먼저 남녀의 사랑에 관해 이야기해 보고자 합니다. 인간이 이 세상에 태어날 때, 사람은 실재계에서 생활하고 있었습니다.…… 이하 생략.…… 날마다의 ...",
    "body": "호시 ○코의 글이다.\n\n“독자 여러분은 ‘사랑’이라는 말을 자주 듣고 또 실천하고 계시리라 생각합니다. 먼저 남녀의 사랑에 관해 이야기해 보고자 합니다. 인간이 이 세상에 태어날 때, 사람은 실재계에서 생활하고 있었습니다.…… 이하 생략.…… 날마다의 생활에 힘써 주신다면 여러분의 수호령을 통해 생활 그 자체에 대혁명이 일어날 것입니다.” 9월 23일신지 선생의 중학교 시절 친구 사토는 자신의 친한 친구 K를 신지 선생에게 소개했다. 사토는 앞서 신지 선생 곁에 태어나게 하기로 했다고 서술된 영혼의 친구이다. 그런데 두 사람의 뒤에 금빛으로 둘러싸인 인도풍 수호령이 뚜렷하게 나타났다고 한다. 신지 선생에게는 두 수호령이 서로 이야기하는 모습이 보였다.\n\n그러나 지도령 원 투 스리는 “과거세의 이름을 알려 주어서는 안 된다”고 신지 선생에게 주의를 주었다. 신지 선생이 “왜 내 주변에서만 이런 현상이 일어나는 것일까?”라는 의문을 품기 시작하자, 원 투 스리는 다음과 같이 말했다고 한다.\n\n“핵이라는 중심이 없으면 형태는 이루어지지 않는다.”\n\n또한 모세의 십계명이 성립한 과정과 우상숭배의 잘못, 고타마와 예수 시대의 신리(神理)로 돌아가는 것이 사람들을 구할 유일한 길이라는 설명도 했다. 이렇게 신지 선생은 낮에는 회사 일을 하고 밤에는 원고를 쓰며 바쁜 나날을 보냈다. 이때 집필한 것은 마음에 관한 가르침이었다.",
    "notes": "",
