    "title": "토요회",
    "origTitle": "「高橋信次師物語」 真のメシヤの記録 49　八起正法先生編",
    "contentType": "",
    "summary": "이 무렵부터 신지 선생은 모여든 동지들에게 신리(神理)의 언령(言魂)을 설하는 모임을 ‘토요회’라고 불렀다. 동지들은 토요일 밤을 기다리며 많이 모여들었다. 모임이 자주 한밤중까지 이어지자 종료 시간을 앞당겨 오후 7시부터 10시까지 열게 되었다. 이...",
    "body": "이 무렵부터 신지 선생은 모여든 동지들에게 신리(神理)의 언령(言魂)을 설하는 모임을 ‘토요회’라고 불렀다. 동지들은 토요일 밤을 기다리며 많이 모여들었다. 모임이 자주 한밤중까지 이어지자 종료 시간을 앞당겨 오후 7시부터 10시까지 열게 되었다. 이 모임은 누가 먼저 제안한 것도 없이 자연스럽게 생겨났다고 한다. 9월 무렵부터 신지 선생 앞에 자주 모습을 보이던, 불상처럼 아름다운 여성이 다시 나타났다.\n\n“저는 미로쿠(미륵)라고 합니다. 오랜만입니다.”\n\n그녀는 자신을 신지 선생의 아내 가즈에의 수호령이라고 소개했다. 가즈에는 20여 년 동안 신앙에 별다른 관심이 없었다. 그러나 신지 선생이 인도 시대의 경문을 낭랑하게 소리 내어 외우자, 가즈에의 마음이 신리의 빛을 받아 커다란 눈물이 끊임없이 흘렀다고 한다. 신지 선생은 가즈에에게 다음과 같이 일렀다.\n\n“오늘부터 일주일 동안 새벽 1시부터 2시까지 옥상에 나가, 지금까지의 인생을 잘 반성하고 마음의 조화를 이루도록 하세요.” 10월 23일 밤신지 선생이 아내에게 조화의 빛을 주자 마침내 수호령이 아내를 직접 지배하여 말하기 시작했다고 한다.\n\n“저는 미로쿠 보살이라 불리는 존재입니다. 본체의 마음의 눈이 열렸으므로 제가 수호령을 맡도록 하겠습니다.” 원문은 이를 놀라운 고지였다고 표현한다. 아내 가즈에의 윤회원문은 가즈에의 영혼 계보를 다음과 같이 전한다.",
    "notes": "• 기원전 7000년, 지금으로부터 9천 년 전: 아틀란티스 제국의 나다리야\n\n• 기원전 500년: 인도의 마이트레야, 사후에는 미로쿠라고 불림\n\n• 15세기: 중국의 가란\n\n• 현대: 신지 선생의 아내 다카하시 가즈에이어서 원문은 가즈에의 글을 소개한다.\n\n「행하는 것의 참뜻」 - 다카하시 가즈에\n\n“제가 영도(録道)를 연 것은 재작년 11월, 곧 쇼와 43년(1968년)이었습니다. 이번 정월로 꼭 1년하고 조금이 됩니다. 그동안 여러 가지 체험을했습니다만, 지난해 8월 무렵이었던 것으로 생각합니다. 저는 불교에서 말하는 고집멸도 가운데 고(苦)를 없애려면…… 이하 생략.…… 자신을 조용히 바라보고 조용히 행동해 나가는 것 또한 깨달음에 이르는 하나의 방법이라고 생각합니다.”",
