    "summary": "에 맞춰 본문에서는 포아이 신 포아이 신포로 통일했다.",
    "body": "에 맞춰 본문에서는 포아이 신 포아이 신포로 통일했다.",
    "notes": "• 043번의 中山寺는 기준 원문과 강연록에 모두 확인되므로 나카야마사(中山寺)로 옮겼다. 어떤 사찰을 가리키는지 번역자가 임의로 다른 절 이름으로 바꾸지 않았다.\n\n• 045번의 아인슈타인 영 및 상대성이론에 관한 내용, 046~050번의 전생·수호령·지도령에 관한 내용은 원문 저자와 인용된 발언의 종교적 주장이다. 역사적·과학적 사실로 확정하지 않도록 문장 주체를 살렸다.\n\n• 046번은 첫날 한 여성만 묘사한 뒤 다음 날 갑자기 두 사람 가운데 한 사람이라고 적는다. 원문에서 다른 한 사람을 설명하지 않으므로 내용을 보충하지 않았다.\n\n• 046·047번의 林縁·中縁·吾縁은 실재 인명 여부와 독음이 명확하지 않다. 한자를 보존하고 각각 임장·중장·오장으로 음독했다.\n\n• 048·049번의 인용문은 원문 자체가 云々으로 중간 내용을 생략한다. 번역문에서도 없는 내용을 복원하지 않고 이하 생략으로 표시했다.\n\n• 050번 웹 원문은 책 제목을 大自然と生命이라고 적지만, 겹치는 강연록에는 大自然の波動と生命이라고 나온다. 본문은 웹 원문대로 『대자연과 생명』으로 보존했으며 강연록의 제목으로 고치지 않았다.\n\n• 강연록에서는 7월 12일의 결심, 고야산·간에이지·나카야마사 방문, 원 투 스리·포아이 신 포아이 신포, 원 투 스리가 모세였다는 발언이 겹치는 것을 확인했다. 강연록에만 있는 더 긴 설명은 번역문에 추가하지 않았다.",
