    "summary": "신지 선생은 쇼와 44년(1969년) 2월 도쿄 강연회에서 다음과 같이 예고했다. “머지않아 우리 동료들이 간사이에서 하나의 집단을 이루어 나타날 것입니다.” 또한 다음과 같이 말했다고 한다. “천상계에 가면 전체를 내려다볼 수있습니다. 그러면 우리 ...",
    "body": "신지 선생은 쇼와 44년(1969년) 2월 도쿄 강연회에서 다음과 같이 예고했다.\n\n“머지않아 우리 동료들이 간사이에서 하나의 집단을 이루어 나타날 것입니다.”\n\n또한 다음과 같이 말했다고 한다.\n\n“천상계에 가면 전체를 내려다볼 수있습니다. 그러면 우리 무리가 어디에 나와 있는지 전부 알 수 있어요. 저세상에서 약속하고 태어난 것이니까요.” 원문은 이 시기 신지 선생 주변의 일을 보여 주기 위해 A·치카의 수기를 소개한다. 3월\n\n“지인의 권유로 선생님 댁을 찾아갔을 때의 일입니다. 큰아들을 데리고 2층 응접실로 들어가니 선생님은 두꺼운 스웨터를 입고 계셨고, 바지도 값비싼 물건이라고는 할 수 없었습니다. 선생님은 빛을 넣고 무언가를 외우시더니 ‘이제 걱정하지 않아도 됩니다. 무척 힘드셨겠군요’라고 말씀하셨습니다. 그리하여 저는 17년 동안 겪었던 병고에서 벗어났습니다. 그로부터 1년이 되었지만 회사도 쉬지 않고 있습니다. 저 역시 영도(録道)를 열어 주셨는데, 카필라성, 곧 석가모니가 자란 왕궁에서 배식 담당이었다고 합니다.” 4월아사쿠사에서 건설 중이던 빌딩도 거의 완성되었다. 토요일마다 열리는 공부 모임에는 약 100명이 모였고 신지 선생의 집에는 다 들어갈 수 없을 듯했다. 그래서 우선 빌딩 3층을 개방하여 정신 부활 운동에 제공하게 되었다. 그곳에는 300~400명이 들어갈 수 있었을 것이다. 신지 선생은 처음에 1층과 지하층을 음식점으로, 2층과 3층을 사우나와 초음파 목욕 시설로 만들 생각이었던 듯하다. 그러나 지도령이 다음과 같이 타일렀다고 한다.\n\n“몸의 때를 벗기는 곳은 어디에나 있다. 사명을 잊어서는 안 된다. 네가 출판한 책을 통해 많은 사람이 모여들 것이다.” 이에 계획을 180도 바꾸어, 마음의 때를 벗기는 장소로 삼았다는 것이다. 이 건물은 아사쿠사 지하철 출입구 위에 있어 매우 편리했으며, 야오키(八起) 빌딩이라 불렸다. 신지 선생은 예수의 조언에 따라 십자 모양의 보강재를 넣었으므로 지진에도 강하다고 강연에서 말했다. 원문은 지도령의 충고로 계획을 바꾸었다고 앞서 언급했다며, 다음 항목에서 당시의 일을 이어 간다.",
