    "title": "계획 중단과 노숙인의 인연",
    "origTitle": "「高橋信次師物語」 真のメシヤの記録 54　八起正法先生編",
    "contentType": "",
    "summary": "계획 중단신지 선생이 망설이자 모세의 영은 강한 어조와 자신감에 찬 태도로 말했다. “강행하겠다면 그래도 좋다. 손님이 단 한 명도 들어가지 못하게 해 보이겠다. 거짓말이라고 생각한다면 내일 지켜보아라.” 다음 날 신지 선생이 지켜보니, 그 앞을 지나...",
    "body": "계획 중단신지 선생이 망설이자 모세의 영은 강한 어조와 자신감에 찬 태도로 말했다.\n\n“강행하겠다면 그래도 좋다. 손님이 단 한 명도 들어가지 못하게 해 보이겠다. 거짓말이라고 생각한다면 내일 지켜보아라.” 다음 날 신지 선생이 지켜보니, 그 앞을 지나가야 할 사람들이 빌딩 가까이 오기만 하면 모두 고개를 돌리고 빌딩 반대편으로 걸어갔다고 한다. 신지 선생은 이래서는 정말 손님이 한 명도 오지 않겠다고 생각하여 포기할 수밖에 없었던 듯하다. 원문 저자는 참으로 난처했을 것이라고 헤아린다. 노숙인에 관한 이야기그 일이 있고 나서 빌딩의 철골이 거의 다 올라갔을 무렵, 예순 살쯤 된 한 노숙인이 3층 부분에 눌러앉았다고 한다. 신지 선생은 그가 동료들에게 “나는 저곳의 관리인이 될 거야”라고 떠벌리는 말을 들었다. 어느 날 갑자기 온천 여관에서 전화가 왔다.\n\n“댁의 사장님께서 돈을 가져오라고 하시는데요.” 신지 선생이 수상하게 여기면서도 돈을 가지고 가 보니, 그 노숙인은 동료 다섯 명을 데리고 호화롭게 놀고 있었다는 것이다. 신지 선생은 어째서 이런 일이 생기는지 알아보려고 선정·명상에 들어가 과거의 의식을 풀어 살펴보았다고 한다.\n\n그러자 석가모니 시대에 그 노숙인 노인은 옷을 파는 행상인이었으며, 죽림정사 앞을 지날 때마다 늘 의류를 보시하곤 했다는 것이다. 그래서 신지 선생은 웃으며 즐거운 듯 말했다고 한다.\n\n“뭐, 신세를 졌으니 이것도 어쩔 수 없지.” 그 뒤 그 사람은 정말로 관리인이 되었다. 원문은 이야기가 하나 더 있다며 다음 항목으로 이어 간다.",
