    "title": "구두쇠에게 바르는 묘약",
    "origTitle": "「高橋信次師物語」 真のメシヤの記録 55　八起正法先生編",
    "contentType": "",
    "summary": "야오키 빌딩 2층에는 Ś의원이 세 들어 있었고, 어느 일류 기업의 부사장이 그곳에서 진료를 받았다. “우리 아내는 낭비벽이 심해서 곤란합니다. 거기에 듣는 약은 없을까요?” 그가 Ś의사에게 이렇게 상담했다고 한다. 그의 아내는 유명 기업가의 딸로, 매...",
    "body": "야오키 빌딩 2층에는 Ś의원이 세 들어 있었고, 어느 일류 기업의 부사장이 그곳에서 진료를 받았다.\n\n“우리 아내는 낭비벽이 심해서 곤란합니다. 거기에 듣는 약은 없을까요?” 그가 Ś의사에게 이렇게 상담했다고 한다. 그의 아내는 유명 기업가의 딸로, 매달 청구되는 돈이 200만~300만 엔에 달했다. Ś의사는 다음과 같이 말했다.\n\n“그렇지! 좋은 약이 있습니다. 이 위층에 다카하시라는 선생이 계십니다. 그분의 말씀을 들어 보세요.” 얼마 뒤 머리부터 발끝까지 화려하게 차려입은 여성이 신지 선생을 찾아왔다고 한다.\n\n“우리 남편은 너무 구두쇠라서 못살겠어요. 구두쇠에게 바르는 약은없습니까?” 그 여성은 연신 손가락을 움직였고, 그때마다 훌륭한 반지가 반짝였다. 신지 선생은 자기 반지를 알아봐 주기를 바라는 것이라고 생각했다.\n\n“훌륭한 반지군요.” 신지 선생이 칭찬하자 여성은 말했다.\n\n“이게 ○캐럿이나 된답니다. 드릴까요?”\n\n“받아도 스미다강에 버릴 뿐입니다.”\n\n“어머, 아까워라.” 그 뒤 신지 선생은 만족할 줄 알아야 한다는 것, 부자의 사명은 어려움에 처한 이들에게 도움의 손길을 내미는 것이라는 점 등을 차근차근 타일렀다고 한다. 신지 선생은 강연에서 다음과 같은 말도 했다고 원문은 전한다.\n\n“여성은 기껏해야 보살계까지입니다. 여성은 목걸이를 하고 싶어 하고 귀걸이를 하는 등 본질적으로 몸을 꾸미려 합니다. 아기를 낳아 기르므로 여성은 아무래도 자신을 지키려 하고 보수적입니다. 그에 비해 여래는 몸치장을 개의치 않으며 어떤 옷차림도 신경 쓰지 않습니다. 그러므로 여성은 기껏해야 보살계까지입니다. 그러나 보살이 되는 것조차 좀처럼 어렵습니다.”",
    "notes": "",
