    "contentType": "",
    "summary": "5월 - N·T코에 관한 이야기 N·T코는 신지 선생의 힘으로 영도(録道)를 열었다. 원문은 그가 1만 2천 년 전 아틀란티스 시대 이후 때로는 남자로, 때로는 여자로 태어나 불교와 기독교에 인연을 맺은 사람이라고 서술한다. 이 무렵 그는 신지 선생의...",
    "body": "5월 - N·T코에 관한 이야기 N·T코는 신지 선생의 힘으로 영도(録道)를 열었다. 원문은 그가 1만 2천 년 전 아틀란티스 시대 이후 때로는 남자로, 때로는 여자로 태어나 불교와 기독교에 인연을 맺은 사람이라고 서술한다. 이 무렵 그는 신지 선생의 강연회와 연수회 무대에 화려하게 등장하곤 했다. 원문은 다음과 같은 그의 후일담을 소개한다.\n\n“저는 다카하시 선생님의 힘으로 영도를 열어 주셨고, 윤회전생의 증명자로서 과거세의 ‘말’을 여러분 앞에서했습니다. 그런데 어느새 저는 선생이라 불리게 되었고 전국에서 편지를 받게 되었습니다. 저는 그저 한 사람의 주부일 뿐입니다. 이런 일로 여러분을 그릇되게 해서는 안 된다고 생각하여 물러났습니다.” 원문 저자는 신지 선생의 힘으로 마음의 창을 열고도 영도를 과시하며 증상만(録上慢)에 빠진 사람이 많은 가운데, 이 일은 영적 단계의 차이를 똑똑히 보여 준 사례였다고 평가한다. 동시에 이 사례를 든 까닭은 사람이 어떤 생에서는 남자로, 다른 생에서는 여자로 태어날 수도 있음을 보여 주기 위해서라고 설명한다. 남자와 여자원문은 인간 가운데 석가모니나 예수처럼 언제나 남자로 태어나는 사람, 마리아나 마야처럼 언제나 여자로 태어나는 사람, N·T코의 사례처럼 남자와 여자로 번갈아 태어나는 사람이 있다고 설명한다.\n\n또한 영원한 생명으로서 남성과 여성 가운데 어느 쪽을 더 많이 체험했는지에 따라 다음과 같은 사람이 있다고 한다.",
    "notes": "• 남자다운 여자\n\n• 남자다운 남자\n\n• 여자다운 남자\n\n• 여자다운 여자그러나 이 생에서 남자로 태어났다면 남자로서의 사명이 있고 여자로 태어났다면 여자로서의 사명이 있으므로, 남자로 태어나고도 여자처럼 나약하게 굴어 실패한 사람은 다음 생에도 다시 남자로 태어나 수행을 처음부터 다시 하게 된다는 것이다. 여성도 마찬가지라고 한다. 원문은 남자는 남자답고 여자는 여자다운 것이 신리(神理)에 맞는다고 설명한다.",
