    "contentType": "",
    "summary": "8월 - 식물의 정령과 나눈 대화고향 사쿠 고원에서 신지 선생이 글라디올러스와 달리아를 바라보고 있을 때의 일이었다. 어른인지 아이인지 분간하기 어려운 사랑스러운 소녀가 꽃 속에서 나왔다. 소녀는 활짝 웃으며 고개를 숙이고는 인간을 조금 비판한 뒤 사...",
    "body": "8월 - 식물의 정령과 나눈 대화고향 사쿠 고원에서 신지 선생이 글라디올러스와 달리아를 바라보고 있을 때의 일이었다. 어른인지 아이인지 분간하기 어려운 사랑스러운 소녀가 꽃 속에서 나왔다. 소녀는 활짝 웃으며 고개를 숙이고는 인간을 조금 비판한 뒤 사라졌다고 한다. 이 밖에도 신지 선생에게는 등나무와 소나무 정령에 관한 기록이 있으며, 소나무의 정령은 노인처럼 늙은 모습이었다고 한다. 그린 섬세상에는 ‘그린 섬(green thumb)’, 곧 식물을 잘 기르는 마법 같은 손을 지닌 사람이라고 하여 나무와 식물에 다정하게 말을 건네며 키우는 이들에 관한 이야기가 있다. 저자는 식물에 정령이 있다면 그런 말을 귀담아들으리라는 것도 수긍할 만하다고 말한다.\n\n또한 이 이야기가 그렇게 다정한 사람들에게 힘이 되고 기쁜 말이 될 것이 틀림없다고 덧붙인다. 원문은 식물과 관련된 이야기가 하나 더 있다며 ‘인격 측정기’를 소개한다. 인격 측정기\n\n‘인간성 측정기’라고 표현해도 좋을 이 기구 또는 기계 앞에 지원자를 앉히고, 측정 자료를 보면서 채용 여부를 결정하는 꿈같은 면접이 가능해진다는 것이다. 신지 선생에 따르면 이 장치에는 식물 세포를 응용하게 된다고 한다. 먼저 정치인을 세워 전쟁을 계획할 만한 사람을 즉시 걸러 내는 꿈의 판정도 할 수 있다는 것이다. 저자는 고요하고 온화한 식물이라면 틀림없이 적절한 판단을 내려 주리라고 말한다.",
    "notes": "",
