    "num": "060",
    "chapter": 2,
    "chapterMeta": {
      "id": 2,
      "name": "제2장",
      "title": "영혼의 세계와 정법의 실천",
      "fullTitle": "제2장 · 영혼의 세계와 정법의 실천",
      "range": "051–100",
      "badgeColor": "blue",
      "flow": "영혼·수호령·지도령 → 윤회 → 빙의·영적 현상 → 마음과 생활의 조화"
    },
    "title": "신체 투시와 「생명과 물질」 강연",
    "origTitle": "「高橋信次師物語」 真のメシヤの記録 60　八起正法先生編",
    "contentType": "",
    "summary": "10월 - 신체 투시신지 선생이 마음의 눈으로 자세히 보면 내장이 구조도처럼 선명하게 나타났고, 유착된 부위도 입체도처럼 보였다고 한다. “당신은 내년 2월 안에 지금까지의 고통에서 벗어날 것입니다.” 그 예고대로 되었다는 것이다. 같은 해 10월 -...",
    "body": "10월 - 신체 투시신지 선생이 마음의 눈으로 자세히 보면 내장이 구조도처럼 선명하게 나타났고, 유착된 부위도 입체도처럼 보였다고 한다.\n\n“당신은 내년 2월 안에 지금까지의 고통에서 벗어날 것입니다.” 그 예고대로 되었다는 것이다. 같은 해 10월 - 도쿄 다카다노바바 간논지 강연강연 제목은 「생명과 물질 - 모든 것의 중심은 마음」이었다. 원문은 강연의 요지를 다음과 같이 정리한다.",
    "notes": "• 지상에서의 목적은 조화에 있다.\n\n• 신불은 에너지 그 자체이다.\n\n• 인간은 핵을 중심으로 한 다섯 분신(五分身)으로 이루어진다.\n\n• 인도 시대의 현상이 나타난다.\n\n• 육체를 태우면 세 홉의 재가 된다고 하지만 영혼은 죽지 않는다.\n\n• 생명은 윤회전생을 계속한다. 이날 강연은 다음과 같이 시작했다고 한다.\n\n“이 세상에 생명을 받아 태어난 우리가 먼저 의문을 품는 것은, 무엇을 위해 육체를 지니고 이 세상에 태어났는가 하는 점입니다. 그러나 그 본론을 말하기 전에 어째서…… 중략.…… 대우주 그 자체라는 사실을 잊어서는 안 됩니다.” 11월마이트레야, 곧 신지 선생의 아내 다카하시 가즈에의 사촌 오빠였던 핑갸가 일본인으로 태어나 있다는 사실이 밝혀졌다고 원문은 서술한다. 원문·용어 주의\n\n• 051~060번은 FC2 원문의 11·12번 묶음에서 항목 경계와 순서를 확인하고, 하테나 합본의 겹치는 본문과 대조했다. 이 파일의 번호는 웹 원문의 표기 번호 51~60과 일치한다.\n\n• 051번 웹 원문은 천상계 강연 시각을 1968년 11월 24일 오전 1시로 적는다. 그러나 동일 일화를 직접 언급한 1976년 6월 5일 「태양계의 천사들」 강연록에는 『심행』을 11월 22일 완성하고 23일 밤 오전 1시에 강연했다고 되어 있다. 본문은 웹 원문의 날짜를 보존하고 차이만 여기에서 밝혔다.\n\n• 052번 첫 문장은 기준 원문과 하테나 합본에 똑같이 두 번 실려 있다. 편집상 중복일 가능성이 있지만, 번역 원칙에 따라 두 문장을 모두 보존했다.\n\n• 052번의 『심행』 인용은 웹 원문에서 我正法に目覚め와 境涯に到着せん으로 적혀 있으나, 겹치는 강연록에는 각각 我正道に目覚め와 境涯に到達せん으로 나온다. 번역 본문은 웹 원문을 따랐다.\n\n• 054번의 六十位の乞食는 문맥상 예순 명가량이 아니라 예순 살쯤 된 한 노숙인을 뜻하는 것으로 읽힌다. 뒤에서 한 사람을 가리키는 その乞食·その人이 이어지는 점을 반영했다. 시대적 멸칭인 乞食는 한국어 본문에서 노숙인으로 옮겼다.\n\n• 055번 보석의 캐럿 수는 원문부터 〇カラット로 가려져 있으므로 ○캐럿으로 보존했다. 같은 항목과 057·058번에 실린 성별 역할 및 여성의 영적 단계에 관한 내용은 인용된 신지 선생의 발언과 원문 저자의 종교적 견해이며, 보편적 사실로 확정하지 않도록 발언 주체를 분명히 했다.\n\n• 056번은 신지 선생이 알리의 수호령에게 약점을 물어 ‘알리 킥’을 전수했다고 먼저 설명하지만, 이어지는 이노키 자서전 인용은 어깨 치료와 펀치를 피하라는 조언만 전한다. 두 서술을 임의로 합치거나 보충하지 않았다.\n\n• 056번의 権大僧正는 인명이나 사찰명이 아니라 니치렌종 승려의 직함으로 보이며, 정확한 한국식 대응 직함을 임의로 만들지 않고 곤다이소조(権大僧正)로 음역·병기했다.\n\n• 057번은 최초의 외부 강연 장소를 와타나베 야스오의 기록에서는 야마나시현 시모베 온천, 소노가시라 히로치카의 기록에서는 이와테현 모리오카라고 전한다. 원문 자체가 이 차이를 ‘수수께끼’로 다루므로 어느 한쪽으로 바로잡지 않았다.\n\n• 058번의 네 가지 유형은 FC2·하테나 본문에서 줄바꿈으로 구분된 남자다운 여자·남자다운 남자·여자다운 남자· 여자다운 여자를 기준으로 복원했다. 기준 텍스트 일부에는 줄바꿈이 사라져 단어가 이어 붙은 흔적이 있다.\n\n• 060번의 간논지는 원문 표기 東京・高田馬場観音寺를 따라 도쿄 다카다노바바 간논지로 옮겼다. 강연 첫머리 인용은 원문 자체가 云々。……으로 중간을 생략하므로 없는 내용을 강연록에서 끌어와 채우지 않았다.\n\n• 첨부 강연록에서는 051~052번의 『심행』 완성, 천상계의 「물질과 생명」 강연, 모세의 사회, 미카엘의 선행 강연, 진도 3의 지진, 아내도 강연을 들었다는 회고가 직접 겹치는 것을 확인했다. 강연록에만 이어지는 더 긴 설명은 번역문에 추가하지 않았다.",
    "image": "https://raw.githubusercontent.com/concario17-max/shinji/33f81d5266c36192c933d734494bd922df4702d8/images/stories/060.webp",
