    "title": "S씨의 수기 「믿기 어려운 사실」",
    "origTitle": "「高橋信次師物語」 真のメシヤの記録 61　八起正法先生編",
    "contentType": "",
    "summary": "12월 - S씨(공학박사)의 수기이 놀라운 사실을 요약해 보자. Ś씨는 쇼와 42년(1967년) 8월부터 9월까지 자바섬에서 금광을 조사했다. 지프 여러 대에 장비를 싣고 스물다섯 곳에서 시료를 채취한 결과, 평균 함유량은 톤당 6그램이었다. 쇼와 4...",
    "body": "12월 - S씨(공학박사)의 수기이 놀라운 사실을 요약해 보자. Ś씨는 쇼와 42년(1967년) 8월부터 9월까지 자바섬에서 금광을 조사했다. 지프 여러 대에 장비를 싣고 스물다섯 곳에서 시료를 채취한 결과, 평균 함유량은 톤당 6그램이었다. 쇼와 43년(1968년) 12월, Ś씨는 지인과 함께 신지 선생을 찾아가 산의 사진과 간단한 지도를 보여 주었다. 이야기를 모두 들은 신지 선생은 1~2분 동안 눈을 감았다. 그러고는 합장한 손이 머리 높이까지 올라갔을 때 광석 세 개가 또르르 떨어져 나왔다고 한다. 신지 선생은 곧바로 다음과 같이 조언했다는 것이다.\n\n“일본 돈으로 1억 엔, 일본인 기술자 열 명, 현지인 쉰 명, 그 밖에 발전기와 채굴용 트레일러·셔블 등을 준비하면 가능합니다.” Ś씨는 증거를 남기기 위해 세 광석을 실물 크기의 컬러 사진으로 찍고, 일부러 도쿄 통상산업국까지 가져가 분석을 의뢰했다고 한다. 분석 결과 하나에서는 톤당 27.5그램, 다른 하나에서는 톤당 0.3그램이 나왔다. 마지막 하나는 증거품으로 자신의 수중에 보관하고 있으므로 보여 주겠다고 Ś씨는 수기에 적었다. 원문은 이때 광석의 물질화 현상이 일어나 세 개의 광석이 눈앞으로 또르르 굴러 나왔다고 서술한다. 또한 신지 선생의 기적으로 나타난 광석은 실제 현장의 광석 그대로였으며, 금 성분까지 분석할 수 있을 만큼 진짜였다고 주장한다.\n\n한편 동물령이나 어두운 인간령이 협력하는 물질화 현상은 구리나 아연을 주성분으로 하며, 그 상태를 오래 유지하는 일은 불가능하다고 한다. 원문은 화려한 옷을 입고 재를 만들어 내거나 손바닥 위에 올라갈 만한 금빛의 작은 다층탑을 꺼내 보이는 사람이 외국에 있는 듯하다며, 이처럼 영능력자라 불리는 사람들을 올바로 분별해 주기를 바란다고 덧붙인다. 그런데 Ś씨의 이야기에는 후일담이 있었다. 신지 선생은 소노가시라 히로치카 회장에게 다음과 같이 말했다고 한다.\n\n“나는 배신당했습니다. 소중히 보관하던 광석이 악용되면 곤란하므로, 내 영력으로 없애 버렸습니다.” Ś씨는 신지 선생이 생존해 있을 때 GLA를 떠나 다른 교단으로 옮긴 듯하다. 그에게서 권유 편지를 받은 소노가시라 회장은 씁쓸해했다고 원문은 전한다.",
    "notes": "",
