    "contentType": "",
    "summary": "쇼와 45년(1970년), 신지 선생 마흔세 살 때의 일이다. 5월 - 가와고에시 오노 ○코의 집에서 일어났다는 실화원문은 오노 ○코가 예수의 제자 바울의 어머니였던 생명을 지닌 사람이라고 설명한다. 이 일은 고(故) 나가타 슌스이 화백의 장례식이 열...",
    "body": "쇼와 45년(1970년), 신지 선생 마흔세 살 때의 일이다. 5월 - 가와고에시 오노 ○코의 집에서 일어났다는 실화원문은 오노 ○코가 예수의 제자 바울의 어머니였던 생명을 지닌 사람이라고 설명한다. 이 일은 고(故) 나가타 슌스이 화백의 장례식이 열린 4일에 일어났다고 한다. 그날 관 옆에는 화백이 정성을 다해 그린 공작 족자가 걸려 있었다. 오노 ○코의 이웃집 부인은 다음과 같이 말했다.\n\n“신기한 일도 다있습니다. 4일 아침 공작 일곱여덟 마리가 우리 집 정원에 내려앉더니, 곧 선생님 댁 정원으로 날아 들어갔습니다. 벚꽃 사이를 천천히 세 바퀴 돌고 현관 앞에서 한동안 울다가 어디론가 날아가 버렸습니다.” 더욱이 그날 저녁, 이바라키에 있는 오노 씨 남동생의 집으로 비둘기 한 마리가 날아들었다. 비둘기는 가족들의 손과 어깨에 올라앉고 볼을 쪼기까지 하면서 좀처럼 떠나지 않았다. 사람들은 저마다 “할아버지다, 할아버지다”라고 말하며 반가워했다고 한다. 이 일을 두고 원문 저자는 명인이 그린 그림 속에서 새나 동물이 빠져나왔다는 이야기가 사실일지도 모르며, 장인의 손으로 만든 것에는 이와 같은 불가사의한 일이 생기는 것인지도 모르겠다고 추측한다.",
    "notes": "",
