    "title": "내장 투시와 기관지 『히카리』",
    "origTitle": "「高橋信次師物語」 真のメシヤの記録 63　八起正法先生編",
    "contentType": "",
    "summary": "5월 - 내장 투시한 청년이 창백한 얼굴로 신지 선생을 찾아왔다. 그러나 청년은 신지 선생 앞에 앉은 채 한마디도 하지 않고, 그저 선생의 얼굴만 빤히 바라보았다고 한다. 그때 청년의 위장이 다음과 같이 말하기 시작했다는 것이다. “저는 위장입니다. ...",
    "body": "5월 - 내장 투시한 청년이 창백한 얼굴로 신지 선생을 찾아왔다.\n\n그러나 청년은 신지 선생 앞에 앉은 채 한마디도 하지 않고, 그저 선생의 얼굴만 빤히 바라보았다고 한다.\n\n그때 청년의 위장이 다음과 같이 말하기 시작했다는 것이다.\n\n“저는 위장입니다. 이분은 폭음과 폭식을 하고 시간도 가리지 않은 채 끊임없이 음식을 밀어 넣으므로 저희는 몹시 곤란합니다. 저희도 쉬면서 상태를 가다듬지 않으면 큰일이 납니다. 죄송하지만 이분에게 배를 80퍼센트만 채워 먹는 법을 가르쳐 주십시오.” 이에 신지 선생은 청년에게 차근차근 타이르며 주의를 주었다. 원문 저자는 위장의 의식이 직접 말을 꺼냈다고 할 정도라면 사정이 여간 심각한 것이 아니었을 것이라고 말한다. 신지 선생도 “이와 같은 일은 드물다”라고 기록했다고 한다. 또 신지 선생은 강연에서 다음과 같이 말했다.\n\n“심장 나리께서(웃음) 내게 말씀하셨습니다. 당신의 과거세 체험을 풀어 보면, 코카서스 시대에는 배를 60퍼센트만 채워 먹었습니다.\n\n그때 당신은 185세까지 살았습니다. 당시 사람들은 200년, 300년씩 장수했고, 그보다 더 전에는 500세, 1,000세가 당연한 일이었습니다.” 500년이나 1,000년이라는 말에 놀랄 독자도 있을 것이다. 그러나 원문은 양식 있는 현대의 의사들이 풍요로운 음식 때문에 오히려 수명이 짧아지므로 한 끼 정도는 거르라고 말한다고 서술한다. 전쟁 때 제대로 먹지 못한 일이 지금 일본이 세계적인 장수국이 된 까닭 아니냐고 말하는 사람도 있다고 한다. 요즘 아이들 세대는 어떻게 될지 모르지만, 어떤 사람은 하루 150킬로칼로리만 있어도 살 수 있다고 말한다는 것이다. 원문은 이것이 현대인이 섭취하는 열량의 약 10분의 1이라고 덧붙인다. 8월앞서도 나왔듯이 열 쪽가량의 기관지 『히카리』가 발행되었다. 원문은 그 일부를 다음과 같이 인용한다.\n\n“노아의 방주 현상은 지구상에 인류가 살기 시작한 뒤 여러 차례 되풀이되어 왔습니다. ……\n\n그러나 인류가 독점욕과 지배욕 쪽으로 마음을 기울여 간다면, 그 반작용으로 그야말로 갑작스러운 천재지변이 닥칠 것임을 예언해 둡니다.”",
    "notes": "",
