    "title": "초기 강연 기록과 사토 씨의 첫 방문",
    "origTitle": "「高橋信次師物語」 真のメシヤの記録 64　八起正法先生編",
    "contentType": "",
    "summary": "8월, 날짜 불명 - 도쿄 강연 「성장 과정에서 GLA 발족까지」 이 강연의 날짜는 알려져 있지 않으나, 남아 있는 녹음테이프 가운데 가장 오래된 것으로 여겨진다고 한다. 8월 15~17일시즈오카현 후지에다시에서 제1회 연수회가 열렸다. 이 연수회에서...",
    "body": "8월, 날짜 불명 - 도쿄 강연 「성장 과정에서 GLA 발족까지」 이 강연의 날짜는 알려져 있지 않으나, 남아 있는 녹음테이프 가운데 가장 오래된 것으로 여겨진다고 한다. 8월 15~17일시즈오카현 후지에다시에서 제1회 연수회가 열렸다. 이 연수회에서 열세 살 중학생 두 명이 ‘마음의 창’을 열었다고 한다. 신지 선생은 이날 다음과 같이 강연했다.\n\n“영도(録道)가 열린 것이 깨달음은 아닙니다. 그것은 정법(正法)으로 나아가는 한 페이지에 지나지 않습니다. 그리고 영원한 생명을 깨닫기 위한 실증일 것입니다.” 10월 9일도쿄에서 「정법과 과학」 강연이 열렸다. 12월 2일창립 당시의 명칭인 ‘대우주신광회’를 GLA(GOD LIGHT AŚŚOCIATION)로 바꾸었다. 또 신지 선생은 1970년 한 해 동안 약 일흔 명이 영도(録道)를 열어 생활에 활용하고 있다고 보고했다. 이 무렵 신지 선생 주변의 이야기사토 ○○ 씨가 신지 선생을 알게 된 것은 쇼와 45년(1970년)이었다.\n\n그는 도쿄유카타 사장 가와이의 소개로 신지 선생을 찾아가, 진짜인지 가짜인지 자기 눈으로 확인하려 했다. 사무실 입구에는 ‘신광회’라는 간판이 걸려 있었다. 신지 선생은 사토 씨에게 다음과 같이 말했다.\n\n“사토 씨, 나를 시험해 보려고 오셨지요. 그래도 좋습니다. 마음껏 의문을 품으십시오.” 더욱이 신지 선생은 사토 씨가 선거에서 차점으로 낙선하고 선거법 위반으로 아키타형무소에 있었던 때의 일을 세세히 짚어 냈다고 한다. 사토 씨는 아연실색했다. 그것은 자신밖에 모르는 일이었다는 것이다.",
    "notes": "",
