    "contentType": "",
    "summary": "야시카에 관한 이야기사토 씨는 한 사람과 함께 신지 선생의 강연장을 찾았다. 당시 세상을 떠들썩하게 했던 야시카의 7억 엔 행방불명 사건 때문에, 야시카 창업자인 ○시마 요시마사(〇島善政) 사장과 함께 온 것이었다. 신지 선생은 과장 이상 간부들의 이...",
    "body": "야시카에 관한 이야기사토 씨는 한 사람과 함께 신지 선생의 강연장을 찾았다. 당시 세상을 떠들썩하게 했던 야시카의 7억 엔 행방불명 사건 때문에, 야시카 창업자인 ○시마 요시마사(〇島善政) 사장과 함께 온 것이었다. 신지 선생은 과장 이상 간부들의 이름을 적으라고 지시한 뒤, 한 사람을 가리키며 “이 사람입니다”라고 말했다고 한다. ○시마 사장은 “그 사람만은 아닙니다”라고 반박했지만, 원문에 따르면 실제로 바로 그 사람이었다. 게이오 플라자에 관한 이야기신주쿠에 게이오 플라자가 개업하기 전, 사토 씨는 I 사장을 신지 선생에게 소개했다.\n\n그러자 신지 선생은 다음과 같이 세세히 지도했다고 한다.\n\n“전망대를 만드십시오. …… 해외 농협의 손님을 유치하도록 하십시오. ……” 그 지침에 따라 방침을 세워 성공했다는 것이다. 또 사토 씨가 예고 없이 신지 선생의 사무실을 찾아갔을 때, 신지 선생은 “아버님을 만나고 싶지 않습니까?”라고 물었다. 그래서 신지 선생의 여동생을 영매로 삼아 실험하기로 했다. 그때 사토 씨의 아버지는 다음과 같이 말했다고 한다.\n\n“○○야! 고생시켜서 미안하구나. ……” 사토 씨는 자신의 수기에 이렇게 썼다.\n\n“아버지와 이야기하고 있다고밖에는 생각할 수 없었다. 실제로 아버지의 목소리였다. 충격적인 체험이었다.”",
    "notes": "",
