    "title": "다이코쿠텐의 의미와 마쓰시타 고노스케",
    "origTitle": "「高橋信次師物語」 真のメシヤの記録 68　八起正法先生編",
    "contentType": "",
    "summary": "다이코쿠텐에 관하여 신지 선생은 “정법을 위해 경제적으로 협력할 사명을 지닌 사람을 다이코쿠텐(大録天)이라 하며, 세상에서 말하듯 돈벌이의 신을 뜻하는 것이 아니다”라는 말을 남겼다고 한다. 따라서 신지 선생은 마쓰시타 씨를 정법을 위해 일하는 ‘다이...",
    "body": "다이코쿠텐에 관하여\n\n신지 선생은 “정법을 위해 경제적으로 협력할 사명을 지닌 사람을 다이코쿠텐(大録天)이라 하며, 세상에서 말하듯 돈벌이의 신을 뜻하는 것이 아니다”라는 말을 남겼다고 한다. 따라서 신지 선생은 마쓰시타 씨를 정법을 위해 일하는 ‘다이코쿠텐’, 곧 재정을 맡은 천사라고 불렀다는 것이 원문의 설명이다.\n\n그러나 신지 선생이 세상을 떠난 뒤 그가 이끌던 GLA에는 전례를 찾기 어려울 만큼 큰 혼란이 일어났다고 한다. 저자는 마쓰시타 씨의 경제적 협력을 얻지 못한 일이 아무리 생각해도 아쉽지만, 결과적으로는 오히려 잘된 일일지 모르며 이 또한 천상계의 뜻이었을지도 모른다고 생각한다.\n\n한편 원문은 신지 선생이 사토 씨에 관해 다음과 같이 기록했다고 전한다. 주식회사 게이자이카이(経済界)의 사토 주간(主幹)의 수호령, 곧 과거세의 영혼 형제는 명랑한 사람이었다. 그는 당시 일을 이야기하고, 지금 육체를 지닌 사람들을 비판하기도 했다는 것이다. 마쓰시타 고노스케는 아흔네 살로 생을 마쳤다. 원문에 따르면 만년의 그는 보청기에 의지해야 겨우 말을 들을 수 있었고, 목소리를 내지 못하게 되었으며 어디를 가든 휠체어를 이용한 듯하다.\n\n그러나 남몰래 쌓은 음덕도 많아 수십억, 수백억에 이르는 돈을 사회에 기부하고 교단과 신사·사찰에도 큰돈을 내놓았다고 한다. 또한 사재 70억 엔을 선뜻 들여 지가사키에 마쓰시타정경숙을 세웠다. 그럼에도 이번 생에서는 고노스케와 신지 선생 사이에 인연이 없었던 듯하다고 원문은 말한다. 저자는 여기에 조금 덧붙이겠다고 한다. 책을 여러 권 낸 어떤 발명가이자 영능력자는 자신의 책에서 마쓰시타 씨와 신지 선생이 실제로 만난 듯이 썼으며, 자신과 신지 선생은 한 영혼이 둘로 갈라진 관계인 듯 서술했다고 한다. 저자는 자신의 취재 노트를 보면 이처럼 신지 선생의 위대성에 주목하거나 그를 화제로 삼은 사람이 수십 명에 이른다고 말한다. 이 항목을 마지막으로 다듬고 있을 때 흰옷을 입은 집단이 언론을 떠들썩하게 하고 있었다. 웹마스터 주변에서는 그 일을 곧바로 홈페이지에 올리라고 권하는 사람도 있었다. 원고만 완성되면 한 시간도 지나지 않아 전 세계에 공개할 수 있었기 때문이다. 그러나 웹마스터는 센○ 씨(千〇氏)가 병을 앓는 듯해 아픈 사람을 몰아붙이고 싶지 않으므로 조금만 언급하겠다면서도, 보도를 보고 “아, 또인가” 하고 놀랐다고 한다. 원문은 그 여성이 일본이 지진으로 붕괴한다는 이유를 들어 과거에 이십여 명과 수수께끼 같은 미국행에 나서 신문을 떠들썩하게 했다고 서술한다. 저자는 다음으로 다나카 가쿠에이에 관해 말하겠다고 하며 항목을 맺는다.",
