    "title": "다나카 가쿠에이·다구치 리하치와 사토 씨의 기록",
    "origTitle": "「高橋信次師物語」 真のメシヤの記録 68　八起正法先生編",
    "contentType": "",
    "summary": "다나카 가쿠에이에 관한 이야기다나카 전 총리가 록히드 문제로 혼란을 겪던 때, 니가타 후원회 대표와 제1비서가 오사카 강연회에서 소노가시라 회장과 이야기하고 있던 신지 선생을 찾아왔다고 한다. 더욱이 신지 선생의 지시에 따라 소노가시라 회장이 그 대화...",
    "body": "다나카 가쿠에이에 관한 이야기다나카 전 총리가 록히드 문제로 혼란을 겪던 때, 니가타 후원회 대표와 제1비서가 오사카 강연회에서 소노가시라 회장과 이야기하고 있던 신지 선생을 찾아왔다고 한다. 더욱이 신지 선생의 지시에 따라 소노가시라 회장이 그 대화를 녹음해 남겼다는 것이다. 신지 선생은 다음과 같이 말했다고 한다.\n\n“다나카 씨, 재산을 모두 내놓고 빈몸이 되십시오. 그러면 국민은 다시 한번 당신을 총리로 세우자고 할 것입니다. 그것만으로는 부족합니다. 이어 Ś당의 N군, Ś평의 ○군에게 ‘당신들은 노동귀족이다. 나도 빈몸이 되었으니 당신들도 나처럼 빈몸이 되라. 모두 빈몸이 된 자리에서 일본에 관해 충분히 이야기해 보지 않겠는가’라고 말하십시오. 그래도 이러쿵저러쿵 불평한다면 ‘○○군, 당신은 △△라는 맨션 몇 호실에 이런 여성이 있지 않은가’라고 하십시오. 그래도 아니라고 한다면 이름과 얼굴, 키까지 가르쳐 주십시오. 빈몸이 되라고 하십시오.” 또 쇼와 49년(1974년) 2월 간사이 본부 강연회에서 신지 선생은 다음과 같이 말했다.\n\n“다나카 가쿠에이 씨 자신도 도쿄도 안에 있는 재산을 전부 내놓고, 자민당이 지금 쓰는 자금도 모두 공개하여 ‘이 돈을 모두 대중을 위해 쓰자’고 한다면 Ś당이나 K당 같은 것은 별것 아닙니다. 그렇게 하지 않고 물러날 때를 모르고 미련을 부리니 이런 일이 생긴 것입니다.” 또 신지 선생은 다나카 가쿠에이가 사이토 도산의 환생이라는 말을 남겼다고 한다. 세이노운수 창업자 다구치 리하치에 관한 이야기앞서 등장한 사토 씨는 자신의 기록에서 다음과 같은 일들을 전했다.\n\n그는 ‘대우주신광회’라는 이름을 영어 첫 글자를 딴 GLA로 바꾸자고 권했다고 한다. 또 『연생의 배(録生の舟)』, 곧 뒤에 『마음의 발견』으로 제목이 바뀐 책은 처음에 사토 씨의 회사에서 출판되었다. 신지 선생은 “『연생의 배』는 70만 부가 팔립니다”라고 예언했으며, 실제로 그대로 되었다는 것이다. 신지 선생은 인세를 손에 들고도 다음과 같이 말했다고 한다.\n\n“이렇게 많이 받아도 괜찮습니까?”\n\n“소중하게 사용하겠습니다. ……” 또 사토 씨가 바나 클럽으로 안내하면 신지 선생은 술을 마시지 않고 호스티스의 이야기에 조용히 귀 기울이기만 했던 듯하다. 세이노운수 창업 사장 다구치 리하치는 중국 시대에 마차 운송업의 사장과 같은 일을 했으며, 그때에도 사토 씨와 형제처럼 가까운 사이였다고 신지 선생이 밝혔다고 한다. 또 당시 마흔 살 남짓이던 사토 씨가 신일철(新日鉄)의 나가노 시게오와 후지이 헤이고 사이의 냉전을 끝내고 화해를 이루어 낸 것은 신지 선생의 다음과 같은 권유 덕분이었다고 한다.\n\n“사토 씨! 당신이 하면 반드시 성공합니다.” 사토 씨가 “반야심경을 쉽게 해설해 주십시오”라고 부탁하자, 신지 선생은 『원설 반야심경』 한 권을 완성했다. 신지 선생은 다음과 같이 말하며 웃었다고 한다.\n\n“나는 불교 책 같은 것은 한 권도 읽은 적이 없습니다. 말도 안 되지요. ……”\n\n그러나 책을 내자 폭풍 같은 반향이 일어나 베스트셀러가 되어 갔다고 기록되어……. 원문은 여기서 문장이 완결되지 않은 채 다음 항목으로 넘어간다.",
    "notes": "",
