    "contentType": "",
    "summary": "7월쇼와 46년(1971년) 7월 7일, 도쿄에서 「심행 낭독, 심행 해설, 지옥계의 모습, 불교 전래에 관하여」 강연이 열렸다. 7월 24일에는 도쿄에서 「조화와 과학」 강연이 열렸다. 8월지난 항목에 나온 두 사람은 8월 도치기현 이즈루산에서 열린...",
    "body": "7월쇼와 46년(1971년) 7월 7일, 도쿄에서 「심행 낭독, 심행 해설, 지옥계의 모습, 불교 전래에 관하여」 강연이 열렸다. 7월 24일에는 도쿄에서 「조화와 과학」 강연이 열렸다. 8월지난 항목에 나온 두 사람은 8월 도치기현 이즈루산에서 열린 연수회에도 찾아왔다. 신지 선생은 다음과 같이 말했다.\n\n“이 두 분 선생님은 아무 말도 하지 않습니다. 하지만 나는 그분들의 수호령·지도령과 이야기하므로 모두 알 수있습니다. 인도 시대와 중국 시대에 함께했던 동료라고 해도 좋을 분들입니다. 나는 두 분의 수호령에게 들은 그대로를 전했습니다.” 두 사람은 신지 선생이 진짜인지 가짜인지 확인하고, 진짜라면 그 지도 방법을 활용하여 신자들을 행복하게 하려는 생각이었던 듯하다. 신지 선생이 다음과 같이 말하자 두 사람은 속마음을 정확히 들킨 듯 쓴웃음을 지었다.\n\n“연수 결과를 전해 주면 되겠지요.” 그러고는 이렇게 물었다.\n\n“이 일을 녹음해도 되겠습니까?” 신지 선생은 교단의 회장이 『법화경』에 입각한 선조 공양으로 신자들을 이끄는 일에 자신이 없다고 말한다는 내용 등을 모두 녹음하게 했다.\n\n그때 회장은 이미 『마음의 발견·신리편』과 『마음의 발견·과학편』을 읽었다고 한다. 두 사람은 이 테이프를 가지고 오사카로 돌아갔다.\n\n한편 신지 선생은 도쿄에 앉아서도 영시(録視)와 투시를 통해 그 교단의 내막을 모두 알게 되면 회장이 자신을 다시 찾아올 것이라고 생각했다. 신지 선생의 수호령도 상당히 자신에 찬 어조로 그렇게 말했다고 한다. 원문은 이처럼 신지 선생이 그 자리에 가만히 있으면서도 모든 일을 텔레비전 화면처럼 알아보고, 무엇이든 꿰뚫어 보았다고 주장한다. 이와 관련해 여러 이야기가 남아 있다. 그중 하나는 고제 가운데 한 사람인 무라카미 유카이가 제자가 운전하는 차에 함께 탔다가 큰 사고를 당할 뻔한 일이다. 무라카미가 도쿄로 돌아와 신지 선생에게 보고하려 하자, 선생은 그보다 한순간 먼저 다음과 같이 말했다고 한다.\n\n“다행이군요. 목숨을 건졌습니다.” 원문은 신지 선생이 이미 모든 일을 알고 있었다고 전한다. 쇼와 46년(1971년) 8월 7일에는 오사카 즈이호카이에서 「다카하시 선생, 첫 만남 강좌」가 열렸다.",
