    "contentType": "",
    "summary": "11월강연회는 도쿄에서 지방으로 퍼져 나갔다. 신지 선생은 간사이 지방으로 출장을 가는 일도 많아져, 24일에는 오사카, 25일에는 시코쿠로 움직이는 일정이 마치 선거 유세와 같았다고 한다. 지도령에게서 이것이 평생의 일이라는 말을 들었기 때문에 신지...",
    "body": "11월강연회는 도쿄에서 지방으로 퍼져 나갔다. 신지 선생은 간사이 지방으로 출장을 가는 일도 많아져, 24일에는 오사카, 25일에는 시코쿠로 움직이는 일정이 마치 선거 유세와 같았다고 한다. 지도령에게서 이것이 평생의 일이라는 말을 들었기 때문에 신지 선생 자신은 그리 힘들다고 여기지 않은 듯하다. 그러나 이틀 동안 그는 하루에 여덟 시간씩 이어지는 강연과 질의응답, 현증(現証)을 진행했다. 청중은 수천 명이었고, 개인 상담을 받은 환자도 일흔여섯 명에 달했다. 원문에 따르면 그 가운데 15년 동안 걷지 못한 사람과 10년 동안 반신불수로 지낸 사람들에게 기적이 일어났다. 신지 선생은 그것이 자신에게 협력하는 대지도령의 힘이었다고 말했다고 한다. 웹 편집자는 신지 선생이 자신의 힘이 아니라 대지도령의 힘이었다고 말했다는 점을 두고 참으로 겸허하다고 평가한다. 또 기적은 저세상 영들의 협력으로 일어나며, 신지 선생의 경우에는 모세와 예수 같은 빛의 대천사가 협력하므로 그 힘이 절대적이었으리라고 추측한다. 신지 선생은 다음과 같이 말하기도 했다.\n\n“동물령도 기적을 일으키고 병을 고치는 정도는 합니다.” 원문은 그러므로 영능력자라고 불리는 사람을 올바로 분별하는 일이 중요하며, 동물령이나 인간의 지옥령이라면 언젠가는 반드시 본성을 드러낸다고 설명한다. 신지 선생은 밤낮없이 강행군을 계속하면서도 정신적인 피로는 느끼지 않았다고 한다. 그러나 지도령에게서는 늘 ‘몸도 자기 자신의 일부이니 충분히 조심하라’는 주의를 들었다는 것이다.",
    "notes": "",
    "image": "https://raw.githubusercontent.com/concario17-max/shinji/33f81d5266c36192c933d734494bd922df4702d8/images/stories/074.webp",
