    "notes": "• 쇼와 47년(1972년) 1월 3일: 「빛은 곧 행위」, 도쿄\n\n• 1월 8일: 「종교는 과학이다」, 간사이\n\n• 1월 9일: 「신리와 과학, 질의응답」, 간사이\n\n• 1월 22일: 「정법과 마(魔), 질의응답」, 간사이\n\n• 1월 23일: 「반야심경 해설」, 간사이 2월\n\n• 쇼와 47년(1972년) 2월 10일: 「마음의 본질」, 간사이\n\n• 2월 12일: 「반야심경 해설」, 간사이\n\n• 2월 13일: 「반야심경과 심행 해설」, 간사이 3월모리오카시 국민건강보험회관에서 「인도 불교와 현대 불교」라는 제목의 강연이 열렸다. 원문은 강연 일부를 다음과 같이 생략된 형태로 인용한다.\n\n“이 자리에는 직업 승려 여러분도 몇 분 와 계십니다. 그런 분들 앞에서 인도 불교가 어떻고 하는 이야기를……. ……‘손을 댄다’는 것은 그렇게 하는 일입니다.” 쇼와 47년(1972년) 3월 13일에는 간사이에서 「심행 해설, 현증, 질의응답」이 열렸다. 봄",
