    "notes": "• 쇼와 47년(1972년) 5월 21일: 「신과 인간」, 간사이 6월\n\n• 쇼와 47년(1972년) 6월 6~8일: 고야산 연수회\n\n• 「빛을 넣는 법, 법화경, 반야심경 해설, 중도 반성의 척도」\n\n• 6월 10일: 「자력과 타력에 관하여, 질의응답」, 간사이\n\n• 6월 11일: 「중도의 실천이야말로 정법, 신리 이야기와 질의응답」, 간사이 7월\n\n• 쇼와 47년(1972년) 7월 6일: 「요시노산 연수회」, 요시노\n\n• 7월 10일: 「모리오카 강연회」, 이와테\n\n• 7월 22일: 「빛이란 무엇인가」, 도쿄 간논지\n\n• 7월 27일: 「연수회」, 나라 후루미네 신사 8월\n\n• 쇼와 47년(1972년) 8월 20일: 「신앙과 생활」, 가시하라 9월\n\n• 쇼와 47년(1972년) 9월 1일: 「체험 발표, 질의응답」, 간사이\n\n• 9월 9일: 「실재계와 현상계」, 간사이\n\n• 9월 11일: 「질의응답」, 도쿄\n\n• 9월 16일: 「반야심경 해설」, 간사이 10월모리오카시 국민건강보험회관에서 「색심불이(色心不二)」라는 제목의 강연이 열렸다. 원문은 강연 일부를 다음과 같이 중간이 생략된 형태로 인용한다.\n\n“‘색심불이’라는 말을 여러분은 알고 계시겠지요. 이 ‘색심불이’라는 말이 몹시 철학화되어……. ……할 때 자기 자신의 마음의 평화를 되찾는 것입니다.” 이어지는 일정은 다음과 같다.\n\n• 쇼와 47년(1972년) 10월 7일: 「마음과 공해에 관하여, 질의응답」, 간사이\n\n• 10월 8일: 「윤회전생, 질의응답」, 간사이\n\n• 10월 15일: 「법등(法灯)에 관하여」, 도쿄 간논지",
