    "title": "「마(魔)에 지지 말라」와 소노가시라 회장의 영도 체험",
    "origTitle": "「高橋信次師物語」 真のメシヤの記録 88　八起正法先生編",
    "contentType": "",
    "summary": "4월 1일 「마에 지지 말라」 4월 1일, 히가시오사카의 시노부가오카 중학교 강당에서 「마(魔)에 지지 말라」라는 제목의 강연이 열렸다. 원문은 강연 일부를 다음과 같이 생략해 인용한다. “쇼와 43년(1968년) 3월 우리 집에 영적 현상이 일어난 ...",
    "body": "4월 1일 「마에 지지 말라」 4월 1일, 히가시오사카의 시노부가오카 중학교 강당에서 「마(魔)에 지지 말라」라는 제목의 강연이 열렸다. 원문은 강연 일부를 다음과 같이 생략해 인용한다.\n\n“쇼와 43년(1968년) 3월 우리 집에 영적 현상이 일어난 뒤 벌써 4년이 되었습니다. 인간이 신의 자녀로서 목적과 사명을 지니고 이 지상계에 태어났다는 사실은 누구의 마음에도 내재해 있습니다. 비록 조화롭지 못한 현대사회에…….” 이어 신지 선생은 다음과 같이 설했다.\n\n“누구든 사랑하는 마음을 강하게 지니면 됩니다. 그렇게 하면 누구에게나 힘이 나옵니다.”\n\n“빛을 넣기 전에 자기 마음을 사랑으로 가득 채우는 일이 중요합니다.”\n\n“선정(録定)을 할 때에는 마음과 육체의 파동을 맞추십시오. 서로 일치시키십시오.” 4월 8~10일 GLA 간사이 본부 강습회 4월 9일 오후, 신지 선생은 소노가시라 회장에게 말했다.\n\n“어젯밤 당신의 수호령이 인사하러 왔습니다. 머지않아 당신도 과거세를 기억하게 될 것입니다.” 4월 10일 강연이 끝난 뒤, 신지 선생은 다시 권했다.\n\n“소노가시라 씨, 오늘 밤은 함께 묵으십시오. 같이 오신 두 분도 함께 말입니다. 나는 개인 지도가 있으니 먼저 숙소인 이코마의 미쓰루 산장으로 가 계십시오.” 두 사람은 소노가시라 회장이 ‘생장의 집(生長の家)’에 있던 시절의 친구들이었다고 한다. 오후 6시 무렵 신지 선생이 숙소로 돌아왔다. “선생님이 돌아오셨다”는 말을 듣고 소노가시라 회장이 현관으로 마중 나가자, 신지 선생은 그를 배려하며 말했다.\n\n“왜 먼저 목욕하고 편히 쉬지 않았습니까?” 소노가시라 회장은 스승을 맞을 때 옷깃을 여미고 예를 다해야 한다고 생각했다. 또한 자신이 지금까지 알았던 교조 가운데 이토록 세심하게 마음을 쓰는 사람이 있었던가 싶어 감동했다고 한다. 저녁 식사가 끝난 뒤 신지 선생이 명했다.\n\n“소노가시라 씨, 정신을 통일해 보십시오.” 키가 큰 소노가시라 회장은 길이가 짧은 유카타의 앞섶을 여미고 정좌했다.\n\n그러자 신지 선생이 말했다.\n\n“그렇게 불편한 자세로 어떻게 정신을 통일하겠습니까. 몸을 좀 더 편히 하십시오. 다리가 저리면 오래 앉을 수 없고 마음에도 집중할 수없습니다.” 소노가시라 회장은 그 말이 옳다고 생각했다. 그동안의 종교 체험 때문에 양반다리로 앉는 데 조금 거부감이 있었지만, 쇼와 15년(1940년)에 우주즉아를 체험했을 때에도 선종에서 가르치는 자세로 앉았던 것은 아니었다는 사실을 떠올렸다고 한다. 소노가시라 회장이 마음을 통일하고 있을 때, 신지 선생은 오른손을 들어 올려 알아들을 수 없는 말로 말을 걸었다. 소노가시라 회장은 신지 선생이 무슨 말을 하는지 전혀 알아듣지 못했다. 그런데 뜻은 알 수 없어도 무엇인가가 뱃속 깊은 곳에서 치밀어 올라, 입을 열기만 하면 그대로 말이 되어 나올 듯한 느낌이 들었다고 회고했다. 신지 선생이 말을 이었다.\n\n“육체를 지닌 사람이여, 그대로 소리를 내십시오.” 소노가시라 회장은 ‘육체를 지닌 사람이여’와 같은 권위 있는 말을 이제껏 들어 본 적이 없었다. 그대로 따르지 않을 수 없게 하는 권위가 깃든 말이었다는 것이다. 그가 입을 크게 벌리고 “아―” 하고 소리를 내자, 그 소리는 곧바로 말로 바뀌었다. 배운 적 없는 말이 차례차례 입에서 쏟아져 나왔다고 한다.",
