    "title": "소노가시라 회장의 과거세 회상",
    "origTitle": "「高橋信次師物語」 真のメシヤの記録 89　八起正法先生編",
    "contentType": "",
    "summary": "소노가시라 회장은 자신이 최면술에 걸린 것은 아닐까 생각했다. 그러나 최면술이나 암시라면 당사자가 깨어난 뒤 그 상태에서 어떤 일이 있었는지 기억하지 못할 것이라고 여겼다. 그런데 자신의 의식은 또렷했고 일어난 일을 모두 알고 있었다. 배운 적도 알지...",
    "body": "소노가시라 회장은 자신이 최면술에 걸린 것은 아닐까 생각했다. 그러나 최면술이나 암시라면 당사자가 깨어난 뒤 그 상태에서 어떤 일이 있었는지 기억하지 못할 것이라고 여겼다. 그런데 자신의 의식은 또렷했고 일어난 일을 모두 알고 있었다. 배운 적도 알지도 못하는 말이 계속 입에서 흘러나왔고, 감동의 눈물이 넘쳐 눈과 코가 엉망이 되도록 울었다고 한다. 신지 선생이 다시 말을 건넸다.\n\n“당신은 헤이마카라는 사람을 알고 있을 것입니다. 과거세에 어떤 관계였는지, 이번에는 일본어로 대답하십시오.” 소노가시라 회장은 순간 당황했다. 그러나 지금까지 자신을 감동시킨 가슴속, 또는 뱃속 깊은 곳에 가만히 잠재해 있던 자기 마음에 조용히 물어보자 대답이 돌아왔다.\n\n그는 그 대답을 부정했다. 그 말을 선뜻 입 밖에 낼 수 없었던 듯하다.\n\n“마음속에 떠오른 그 말을 그대로 하십시오.” 신지 선생이 다시 재촉했다. 신지 선생은 소노가시라 회장의 마음속을 알고 있었다는 것이다. 말하라는 재촉을 받고도 망설이던 소노가시라 회장은 잠시 뒤 결심하고 대답했다.\n\n“그 사람은 제 시종이었습니다.” 시종(侍録)은 천황의 측근을 뜻한다. 소노가시라 회장은 민간인인 자신이 입에 올릴 말이 아니라는 사실도 잘 알고 있었지만, 그 말밖에는 떠오르지 않아 어쩔 수 없었다고 한다. 신지 선생이 말했다.\n\n“그렇습니다. 맞습니다. 그 사람은 지금 교토에 다시 태어났습니다. 앞으로 석 달 뒤면 그 사람도 나를 찾아올 것입니다.” 원문에 따르면 그 사람은 정말 석 달째 되는 때 오사카 강습회에 오게 되었다. 그 말과 동시에 소노가시라 회장의 눈에는 신지 선생의 모습 위에 겹쳐 보이는 석가의 모습이 나타났다고 한다.\n\n“붓다, 그리웠습니다. 위대한 관자재자 붓다.” 소노가시라 회장은 그렇게 말하고 엎드려 울었다.",
