    "summary": "『인간·석가』는 일본인 아내를 둔 미국인 대학교수의 손으로 영어로 번역되었다고 한다. 완역된 때는 신지 선생이 살아 있을 때였지만, 번역문이 일본에 도착한 것은 그가 승천한 뒤였다는 것이다. 웹 편집자는 그 뒤 GLA가 혼란에 빠지는 바람에 번역본이 ...",
    "body": "『인간·석가』는 일본인 아내를 둔 미국인 대학교수의 손으로 영어로 번역되었다고 한다. 완역된 때는 신지 선생이 살아 있을 때였지만, 번역문이 일본에 도착한 것은 그가 승천한 뒤였다는 것이다. 웹 편집자는 그 뒤 GLA가 혼란에 빠지는 바람에 번역본이 빛을 보지 못한 일을 몹시 안타까워한다. 또 쇼와 51년(1976년) 3월 22일 오키나와 강연회에서 신지 선생은 다음과 같이 말했다고 한다.\n\n“내 책은 미국 스탠퍼드대학교에서 번역되고 있습니다. 올해 5월(주: 1976년)에 완성되면 미국 태평양 연안으로 크게 퍼져 나갈 것입니다. 그리고 우리가 설하고 있는 것은 유럽으로도 퍼져 나갈 것입니다…….”",
