    "contentType": "",
    "summary": "5월신지 선생은 다음과 같이 말했다고 한다. “상대가 내게 아무리 싫은 말을 해도 나는 내 마음을 우주만큼 크게 만듭니다. 그러면 상대는 내 손바닥 위에 올라와 있는 셈이므로 무슨 말을 해도 화가 나지 않습니다.” 5월 9일 - 뉴욕의 친구에게 보낸 ...",
    "body": "5월신지 선생은 다음과 같이 말했다고 한다.\n\n“상대가 내게 아무리 싫은 말을 해도 나는 내 마음을 우주만큼 크게 만듭니다. 그러면 상대는 내 손바닥 위에 올라와 있는 셈이므로 무슨 말을 해도 화가 나지 않습니다.” 5월 9일 - 뉴욕의 친구에게 보낸 편지앞에서 신지 선생이 유체이탈하여 미국으로 가서 영적 통신을 했다는 이야기가 나왔다. 웹 편집자는 신지 선생이 대목련의 과거세를 지녔다고 하는 오타니 ○輝 씨에게 보낸 편지를 소개한다.\n\n“그리운 벗이여. 머나먼 옛 인도의 땅에서 마음에 법등을 밝혔듯이, 이번 생에서도 다시 인연으로 만난 일을 신께 감사드립니다. 나는 5년 전부터 그리운 벗이 뉴욕에서 동양철학을 가르치고 있다고 많은 사람에게 예언해 왔습니다.\n\n마침내 28일, 나는 뉴욕으로 가서 마음의 통신에 성공했습니다. 이를 기쁘게 생각합니다. 그리운 벗이여, 마음과 행위를 법에 비추어 자기완성을 위해 노력하십시오. 거짓된 나를 버리고 선아(善我)의 마음을 기르십시오. 언제나 팔정도를 마음과 행위의 척도로 삼아 반성하고, 거짓된 나를 신께 사죄한 뒤 명상하십시오.\n\n그때 실재계를 통하여 우리는 자유롭게 교신할 수있습니다. 자신을 믿으십시오, 위대한 벗이여. 마음속에 법등을 밝히십시오. 매 순간의 마음과 행위 속에서 모든 집착은 괴로움을 만들어 냅니다. 모든 것을 법에 귀의했을 때, 모든 것이…… 운운. 그리운 벗이여, 용기와 지혜와 노력으로 실천하십시오. 광명은 가까이 있습니다. 광명은 가까이 있습니다. 고뇌는 머지않아 평안의 경지에 이를 것입니다. 자기완성, 가정의 조화, 부모와 자녀의 대화. 벗이여, 한 걸음 한 걸음 조급해하지 말고 살아갑시다.\n\n그리고 중심이 될 핵을 만들고 사람들의 마음에 법등을 밝혀 갑시다. 법등은 종족을 초월하고 국경도 넘어 사람들의 마음에 조화를 만들어 낼 것입니다. 머지않아 인류는 물질문명의 노예 상태에서 스스로를 해방하고 인생의 목적과 사명을 깨달아 갈 것입니다. 벗이여, 우리는 그날을 위해 모든 지위와 명예와 욕망을 버리고 사람들을 위해 살아갑시다. 그 길 말고는 인류를 구할 수 없기 때문입니다. 예수의 사랑으로 살아갑시다. 붓다의 자비로 살아갑시다. 길은 오직 하나, 법에 귀의합시다. 친애하는 벗의 영광을 기원합니다. 다시 영적 통신을 하겠습니다. 쇼와 48년(1973년) 5월 9일 오타니 님께 다카하시 신지”",
    "notes": "",
