    "contentType": "",
    "summary": "신지 선생의 유체이탈웹 원문은 영혼이나 의식으로 목적지에 가는 일을 유체이탈이라고 설명한다. 또는 ‘또 한 사람의 신지 선생’, 곧 ‘광자체 (光子体)의 신지 선생’이 되어 그곳으로 가는 일이라고도 한다. 신지 선생은 육체가 이곳에 있는 동안에도 의식...",
    "body": "신지 선생의 유체이탈웹 원문은 영혼이나 의식으로 목적지에 가는 일을 유체이탈이라고 설명한다. 또는 ‘또 한 사람의 신지 선생’, 곧 ‘광자체 (光子体)의 신지 선생’이 되어 그곳으로 가는 일이라고도 한다. 신지 선생은 육체가 이곳에 있는 동안에도 의식은 뉴욕으로 날아가 영적 통신을 했다는 것이다. 그 밖에도 이집트 카이로에 가거나, 실크로드의 벽화를 보거나, 영화관에 들어가 영화를 본 일이 있었던 듯하다고 원문은 전한다. 신지 선생은 한 제자에게 다음과 같이 말했다고 한다.\n\n“내가 와타나베 씨가 있는 곳으로 의식만으로 갔을 때, 마침 불확정성 원리에 관한 책을 읽고 있었습니다.” 웹 편집자는 이처럼 신지 선생이 자유자재였다고 서술한다. 달 뒤편에 또 하나의 별이 있다는 이야기별들의 운행은 수백 년에 1초밖에 어긋나지 않을 정도로 정확히 제어된다고 한다. 그렇다면 달 건너편에 숨어 움직이는 별이 있다면 어떻게 될까. 신지 선생은 지구에서는 달에 가려 보이지 않는 별이 있다고 말했다고 한다. 오모토교의 데구치 오니사부로도 그와 비슷한 말을 했다고 한다. 신지 선생은 오니사부로가 보살계의 사람이며 일본 종교의 잘못을 일깨울 사명을 지녔던 사람이라는 말도 남겼다고 원문은 전한다. 웹 편집자는 현재 알려진 아홉 행성이 아니라 열 행성이라는 일이 사실일지도 모른다고 추측한다. 그 별은 지구보다 더 크고 태양에 가장 가까우며, 태양 위에 비쳐 보여 큰 센세이션을 일으킬 듯하다는 것이다. 웹 편집자는 신지 선생이 우주 전체를 내다볼 수 있었던 듯하다고 덧붙인다.",
    "notes": "",
