    "contentType": "",
    "summary": "웹 편집자는 쇼와 48년(1973년) 7월 1일 발행 월간 『GLA』에서 당시 상황을 전재하고 요약한다. 원문부터 여러 곳이 운운과 말줄임표로 생략되어 있다. “우리 인간은 모두 신의 자녀이며…… 운운. ……위대한 과거세를 떠올린 사람이 나왔다. 그 ...",
    "body": "웹 편집자는 쇼와 48년(1973년) 7월 1일 발행 월간 『GLA』에서 당시 상황을 전재하고 요약한다. 원문부터 여러 곳이 운운과 말줄임표로 생략되어 있다.\n\n“우리 인간은 모두 신의 자녀이며…… 운운. ……위대한 과거세를 떠올린 사람이 나왔다. 그 Ś 씨, 소노가시라 회장의 정진에 깊은 경의를…… 운운. 석가가 출가했을 때 다섯 무사가 부왕의 명을 받아 그를 지켰습니다. 그 가운데 아사지라는 사람이 있었습니다. 아사지의 과거세를 지닌 기타하라 씨와 선생님의 대화가 이어집니다.\n\n‘우리는 인도 시대에 고타마 싯다르타의 최초 제자가 되어 마음의 창을…… 운운. ……그 인도 시대에 내가 알던 분이 오늘 이 자리에 와 계십니다. 그분의 이름은 우파텟사, 개명한 뒤에는 샤리푸트라였습니다.’ 다카하시 선생님은 규슈에서 온 Ś 씨를 가리키며 말씀하셨습니다.\n\n‘당신이라고 합니다…… 잠시 이리 와 주십시오.’\n\n그때의 여러 일을 떠올리며 눈물을 글썽인 채 대화가 이어졌습니다…… 운운. ……잠시 뒤 선생님은 Ś 씨에게 말씀하셨습니다.\n\n‘당신은 저 부인을 알고 있을 것입니다.’ 도쿄에서 온…… 운운. Ś 씨는 그 부인을 보는 순간 외쳤습니다.\n\n‘오—, 마이트레야, 다카하시 가즈에 씨!’ 가즈에 선생님의 얼굴도 눈물에 젖었습니다…… 운운.…… 이분은 ‘우파텟사’라고 불렸던 사람입니다. 이분은 인도 시대에 나란다라는 곳에서 태어났습니다.\n\n그리고 붓다에게 귀의한 뒤에는 고타마 싯다르타, 석가모니불의 오른팔이라 불린 사람입니다.\n\n그는 인도에서…… 운운.…….” 기록은 우파텟사라는 사람이 뒤에 샤리푸트라라고 불리게 된 경위와, 반야심경에 나오는 ‘사리자’는 이 사람의 이름을 제자들의 대명사로 사용한 것이라는 설명으로 감동적인 현증(現証)을 마쳤다고 적는다.",
    "notes": "",
