    "id": 99,
    "number": "#099",
    "num": "099",
    "chapter": 2,
    "chapterMeta": {
      "id": 2,
      "name": "제2장",
      "title": "영혼의 세계와 정법의 실천",
      "fullTitle": "제2장 · 영혼의 세계와 정법의 실천",
      "range": "051–100",
      "badgeColor": "blue",
      "flow": "영혼·수호령·지도령 → 윤회 → 빙의·영적 현상 → 마음과 생활의 조화"
    },
    "title": "간사이 대강연회 뒤의 발언과 소노가시라 회장의 회상",
    "origTitle": "「高橋信次師物語」 真のメシヤの記録 99　八起正法先生編",
    "contentType": "",
    "summary": "간사이 대강연회가 끝난 뒤어느 날 간사이 대강연회가 끝난 뒤 신지 선생은 다음과 같이 말했다고 한다. “인도에 있을 때에는 모두에게 저세상의 극락과 지옥이 어떤 모습인지 보여 준 적이 있습니다. 그러니 머지않아 언젠가 다시 해 보겠습니다. 인도에 있을...",
    "body": "간사이 대강연회가 끝난 뒤어느 날 간사이 대강연회가 끝난 뒤 신지 선생은 다음과 같이 말했다고 한다.\n\n“인도에 있을 때에는 모두에게 저세상의 극락과 지옥이 어떤 모습인지 보여 준 적이 있습니다. 그러니 머지않아 언젠가 다시 해 보겠습니다. 인도에 있을 때 나는 석 달 동안 천상계로 돌아가 모습을 감춘 적도 있습니다. 이번에도 그런 일이 생길지 모릅니다.”\n\n그러나 신지 선생은 이 말을 실현하지 못한 채 세상을 떠났다고 원문은 적는다. 쇼와 48년(1973년)의 어느 때어느 때 신지 선생은 다음과 같이 말했다고 한다.\n\n“간토대지진을 일으킬 만큼의 지하 에너지는 이미 가득 차있습니다. 그 에너지를 방출하기 위해 사쿠라지마는 분화를 되풀이하고 있는 것입니다. 천상계에서 지구의 기상을 조작하고 있습니다.” 웹 편집자는 이 항목을 최종적으로 정리하던 헤이세이 15년(2003년) 골든위크에 홋카이도 남부에서 사흘을 보냈다고 회고한다. 도야호 근처의 쇼와신잔과 우스산을 오랫동안 바라보며 짧은 기간에 여러 차례 분화한 역사를 보았다. 규슈 최남단과 홋카이도에서 활동하는 활화산을 둘러보는 동안, 신지 선생의 위 발언이 홋카이도를 떠날 때까지 줄곧 마음을 떠나지 않았다는 것이다. 신지 선생은 또 다음과 같이 말했다고 한다.\n\n“지금부터 1만 년 전 아틀란티스 대륙의 문명을 이룩한 고도의 지식과 지혜를 지닌 영혼들이 앞으로 태어납니다. 이미 조금은 태어나있습니다.” 5월 23일소노가시라 회장은 GLA 도쿄 본부 회의에 처음 참석했다. 회의가 끝난 뒤 신지 선생은 소노가시라 회장을 비롯한 몇 사람을 방으로 불러들였다. 그 자리에서 이치카와의 K 씨에게 말했다.\n\n“잠시 정신을 통일해 보십시오.”\n\n그러자 2~3분 뒤 K 씨는 갑자기 소노가시라 회장 앞에 몸을 던지듯 엎드려 오체투지의 예를 올리고 말했다고 한다.\n\n“과거세에 여러모로 친절히 지도해 주셔서 감사합니다.” 이어 신지 선생은 소노가시라 회장을 다른 방으로 불러 느닷없이 말했다.\n\n“당신은 인도 다음에는 어떻게 했는지 떠올려 보십시오.” 아무것도 떠오르지 않자 소노가시라 회장은 가슴 깊은 곳, 또는 뱃속 깊은 곳에서 곰곰이 생각하며 자기 마음에 물어보았다고 한다.\n\n그러자 다음과 같은 말이 나왔다.\n\n“인도 다음에는 이스라엘에서, 그리스도 시대에 가브리엘이라는 이름으로 천상계에서 여러 역할을 수행했습니다.” 말을 마친 소노가시라 회장은 그리움에 북받쳐 눈물을 흘렸다고 한다. 소노가시라 회장은 성경을 읽어 가브리엘이라는 이름을 알고 있었다. 하지만 그 이름이 자기 마음속에서 갑자기 튀어나온 듯 나타난 일이 스스로도 신기하여 놀랐다는 것이다. 이렇게 4월에는 2,500년 전 석가 시대에 사리불로서 석가를 섬겼고, 5월에는 2,000년 전 예수 시대에 천상계에서 그리스도의 전도를 도왔던 일을 떠올렸다는 것이 원문의 설명이다. 소노가시라 회장은 이러한 과거세를 떠올림으로써 자신의 우주즉아 체험이 지금까지의 과거세에서 습득한 것이었다고 확신했다. 또 반야심경의 ‘사리자’는 “비구와 비구니들이여, 여러분이여”라고 부르는 호칭이었다는 것이다.",
