    "title": "석가·사리불·대목련의 인연과 신리·도덕",
    "origTitle": "「高橋信次師物語」 真のメシヤの記録 101　八起正法先生編",
    "contentType": "",
    "summary": "석가와 사리불과 대목련의 인연그러면 석가였다는 기도 다카요시와 사이고 다카모리, 사카모토 료마의 관계는 어떠했을까. 사카모토 료마의 중개로 사이고·오쿠보와 기도 다카요시 사이에 삿초 동맹이 맺어졌다. 이상하게도 석가였다는 정치가 기도는 정한론과 타이완...",
    "body": "석가와 사리불과 대목련의 인연그러면 석가였다는 기도 다카요시와 사이고 다카모리, 사카모토 료마의 관계는 어떠했을까. 사카모토 료마의 중개로 사이고·오쿠보와 기도 다카요시 사이에 삿초 동맹이 맺어졌다. 이상하게도 석가였다는 정치가 기도는 정한론과 타이완 출병에도 반대했다. 알려진 대로 사카모토는 칼에 쓰러졌고 사이고는 자결했으며, 기도만 다다미 위에서 생을 마쳤다. 웹 편집자는 이를 보면 과연 평화주의자 석가다운 영통(録統)과 부합한다고 말한다. 한 가지 더 덧붙이면, 사카모토였다는 대목련은 고대 인도 석가 시대에는 어릴 적 이름이 코리타였다고 한다. 석가 교단에서 활약한 뒤 폭한에게 습격당해 목숨을 잃었으며, 료마도 알려진 바와 같이 죽었다는 것이다. 그래서 신지 선생은 강연에서 코리타라는 이름을 이용해 다음과 같이 농담했다고 한다.\n\n“어떻게든 하게나. 몇 번이나 ‘코리’해도 소용없으니까.” (폭소) 또 이 무렵 신지 선생은 다음과 같이 밝혔다고 한다.\n\n“도덕으로는 사람을 구할 수없습니다.” 신리와 도덕신지 선생은 도덕으로는 사람을 구할 수 없다는 말을 남겼다. 그러나 많은 사람은 도덕적으로 훌륭한 사람을 인격자라 부르며, 그런 사람은 높은 영계로 간다고 설명한다는 것이다. 하지만 신지 선생이 설한 정법(正法)은 마음의 상태를 문제로 삼는다. 예를 들어 겉으로는 훌륭한 인격자라 하더라도, 마음속에 마음의 삼독이라는 불평·분노·불만이 소용돌이치는 사람은 낮은 영계나 어두운 세계로 간다는 것이다. 정법은 마음의 상태를 문제로 삼으므로, 웹 편집자는 여기에 좋은 예가 있다며 다음 항목을 제시한다.",
    "notes": "",
