    "summary": "문제여기에 다음과 같은 사람이 있다. 11. “실제로 자기 몸을 움직여 사람을 죽인 사람” 또 여기에 다음과 같은 사람이 있다. 12. “말로 사람을 속여 불행하게 만든 사람” 그리고 또 여기에 다음과 같은 사람이 있다. 13. “실로 성실한 사람이어...",
    "body": "문제여기에 다음과 같은 사람이 있다. 11. “실제로 자기 몸을 움직여 사람을 죽인 사람” 또 여기에 다음과 같은 사람이 있다. 12. “말로 사람을 속여 불행하게 만든 사람”\n\n그리고 또 여기에 다음과 같은 사람이 있다. 13. “실로 성실한 사람이어서 마음속으로 여러 생각을 하지만, 그런 일을 해서는 안 된다는 사실을 알기 때문에 절대로 행하지 않는 성실한 사람” 이 세 사람 가운데 누구의 죄가 가장 깊을까? 해답\n\n“단연 ①번 살인자”라는 답이 돌아오리라 생각하지만, 정답은 세 번째인 다음 사람이라고 원문은 말한다.\n\n“여러 생각을 하지만 성실하게 사는 사람.”\n\n“그럴 수가!” 그렇게 생각하겠지만, 정법은 마음의 문제를 설하므로 이 뜻을 알지 못한다면 신리(神理)를 알았다고 할 수 없다는 것이다. 종교가라고 불리는 사람에게 시험해 보면 재미있을 것이라고 웹 편집자는 덧붙인다.",
