    "title": "정법 전파 방안·전쟁으로 늦어진 깨달음·세계 평화",
    "origTitle": "「高橋信次師物語」 真のメシヤの記録 103　八起正法先生編",
    "contentType": "",
    "summary": "같은 5월 - 도쿄 이사회신지 선생은 다음 의제를 내놓고 모두의 의견을 물었다. “앞으로 어떻게 정법을 발전시킬 것인가.” 그러나 “다카하시 선생님의 가르침을 올바르게 전해 가면 된다”는 말뿐이었고, 그 밖의 구체적인 의견은 없었던 듯하다. 정법에 귀...",
    "body": "같은 5월 - 도쿄 이사회신지 선생은 다음 의제를 내놓고 모두의 의견을 물었다.\n\n“앞으로 어떻게 정법을 발전시킬 것인가.”\n\n그러나 “다카하시 선생님의 가르침을 올바르게 전해 가면 된다”는 말뿐이었고, 그 밖의 구체적인 의견은 없었던 듯하다. 정법에 귀의한 지 얼마 되지 않았던 소노가시라 회장은 다음과 같이 건의했다고 한다.\n\n“앞으로 각 종교단체 사람들이 정법을 찾아올 것입니다. 예를 들어 창가학회 사람들에게는 학회의 교의와 정법이 어떻게 다른지, ‘생장의 집’ 사람들에게는 무엇이 다른지를 강사라면 설명할 수 있어야 합니다.\n\n그러나 다른 교단의 교의를 곧바로 알 수 없다면, 그 교단의 옛 신자에게 정법을 철저히 교육하여 각 교단을 담당할 역할에 맞는 전문 강사를 만들면 됩니다.” 전쟁이 신지 선생의 깨달음을 10년 늦추다또 이 무렵 신지 선생은 다음과 같이 말했다고 한다.\n\n“소노가시라 씨, 당신이 가고시마를 택한 까닭은 가고시마가 일본에서 남존여비의 경향이 가장 강한 곳이기 때문입니다. 그곳에서 당신은 대동아전쟁이 일어나지 않았다면 스물네 살까지 가고시마에 하나의 교단을 만들고, 남존여비의 폐단을 타파한 뒤 나와 합류하게 되어 있었습니다. 그런데 대동아전쟁이 일어나는 바람에 나도 깨닫는 일이 10년 늦어졌고, 당신들도 그만큼 먼 길을 돌아오게 되었습니다.” 세계 평화신지 선생은 다음과 같은 말도 했다고 한다.\n\n“죽으면 한평생이 파노라마 영화처럼 전부 눈앞에 나타납니다. 그리고 그곳에서 반드시 반성하게 됩니다.” 또 다음과 같이 말했다.\n\n“마음이 어두워지는 반성은 진정한 반성이 아닙니다.”\n\n그리고 어느 때에는 다음과 같이 말했다고 한다.\n\n“세계 평화를 이루는 길은 멀리 돌아가는 듯하지만, 한 사람 한 사람이 정법을 알고 마음을 평안하게 하며 조화를 이루는 것밖에는 없습니다.”",
    "notes": "",
