    "title": "기독교와 불교·제법무아·1973년 5월 강연 기록",
    "origTitle": "「高橋信次師物語」 真のメシヤの記録 104　八起正法先生編",
    "contentType": "",
    "summary": "기독교와 불교는 왜 같은가신지 선생은 자주 다음과 같이 말했다고 한다. “석가가 육체를 지녔을 때에는 그리스도가 천상계에서 지도하도록 되어 있습니다. 그리스도가 육체를 지녔을 때에는 석가가 천상계에서 지도합니다. 석가의 가르침과 그리스도의 가르침이 같...",
    "body": "기독교와 불교는 왜 같은가신지 선생은 자주 다음과 같이 말했다고 한다.\n\n“석가가 육체를 지녔을 때에는 그리스도가 천상계에서 지도하도록 되어 있습니다. 그리스도가 육체를 지녔을 때에는 석가가 천상계에서 지도합니다. 석가의 가르침과 그리스도의 가르침이 같은 원인은 여기에 있습니다.” 같은 5월 - 강연 제목 「붓다와 모여드는 제자들」\n\n“제법무아라는 불교 용어가 있습니다. 거의 대부분의 사람은 제법무아라고 하니 자기 자신도 무아의 상태가 되어야 한다는 잘못된 생각을 하고 있습니다. 제법무아에서 ‘제법’은 우주의 신리입니다. 우주의 신리라는 것은 우리가 사는 이 지구상의 기상 현상과 그 밖의 온갖 현상을 통해 보더라도 우리 인간의 힘으로 바꿀 수 없는 것입니다. 이것을 제법무아라고 하는 것입니다. 운운.” 쇼와 48년(1973년) 5월 일정",
    "notes": "• 5월 4일: 「마음의 원점(정법의 원점), 맹세의 말」, 시가고원\n\n• 5월 6일: 「심행 해설」, 도쿄\n\n• 5월 12일: 「질의응답」, 간사이 청년부\n\n• 5월 13일: 「제법무아」, 간사이\n\n• 5월 25일: 「불교의 원점」, 야오\n\n• 5월 26일: 「정법이란 무엇인가」, 간사이\n\n• 5월 26일: 「특별 강화」, 마쓰사카시",
