    "summary": "또 이 무렵 신지 선생의 제자 한 사람이 친구에게 다음과 같이 물었다고 한다. “전철 안에 흩어진 종잇조각을 줍는 데에는 용기가 필요합니다. 주워야 할까요, 말아야 할까요?” 질문을 받은 친구는 다음과 같이 답했다. “청소를 맡은 사람이 있으니 너무 ...",
    "body": "또 이 무렵 신지 선생의 제자 한 사람이 친구에게 다음과 같이 물었다고 한다.\n\n“전철 안에 흩어진 종잇조각을 줍는 데에는 용기가 필요합니다. 주워야 할까요, 말아야 할까요?” 질문을 받은 친구는 다음과 같이 답했다.\n\n“청소를 맡은 사람이 있으니 너무 깨끗이 치우면 그 사람의 일거리를 빼앗게 됩니다. 그냥 두는 편이 좋겠지요.” 그런데 다음 강연회에서 신지 선생은 “이렇게 말하는 사람이 있습니다”라고 하며 그 사람이 했던 말을 그대로 이야기했다. 그 사람은 자기 마음을 전부 들여다보였다고 생각하여 깜짝 놀랐다. 곧바로 신지 선생은 다음과 같이 강연했다고 한다.\n\n“이렇게 하면 다른 사람이 어떻게 생각할까 하는 마음을 버리고 종잇조각을 줍는 것입니다.” 그 사람은 식은땀을 닦으며 이 일을 소노가시라 회장에게 이야기했다고 한다. 또 이때 신지 선생은 다음과 같이 말했다.\n\n“자기 자신이 운명의 주인공입니다. 운명은 마음으로 만듭니다.”",
    "notes": "",
