    "contentType": "",
    "summary": "어떤 사람에 관하여 어느 때 신지 선생은 “간사이에서 청년이 나올 것입니다”라고 예고했지만, 그 뒤 그 말을 정정했다고 한다. 그 정정 사실을 아는 사람은 GLA 간사이 본부의 이사 몇 명과 소노가시라 히로치카 회장이었다고 한다. 월간 『정법』 제11...",
    "body": "어떤 사람에 관하여\n\n어느 때 신지 선생은 “간사이에서 청년이 나올 것입니다”라고 예고했지만, 그 뒤 그 말을 정정했다고 한다. 그 정정 사실을 아는 사람은 GLA 간사이 본부의 이사 몇 명과 소노가시라 히로치카 회장이었다고 한다. 월간 『정법』 제117호에 실린 소노가시라 히로치카의 글에서 전하는 내용이다. 어떤 사람은 간사이·시코쿠 사람이다. 어떤 사람의 아버지는 신지 선생의 강연을 자주 들었던 사람이며, 그 사람은 아버지의 감화를 받은 듯하다. 어떤 사람은 “간사이에서 나올 사람은 나다”라고.\n\n그러나 신지 선생이 정정한 내용을 보면, 간사이에서 혼란을 일으킬 사람이 나온다는 뜻이었던 모양이라고 웹 편집자는 해석한다. 살아 있을 때부터 신지 선생은 이미 모든 것을 내다보고 있었을지도 모른다고 웹 편집자는 말한다. 어떤 사람에게는 ‘다카하시 신지물’이라고 불리는 저서가 수십 권이나 있고. 다른 사람의 영언은 거의 한두 권에 그치는데 그 수가 단연 압도적이었다. 그런데 소노가시라 회장이 『어떤 사람은 붓다가 아니다』를 비롯한 여러 저서로 경고를 내놓자, 그 때문인지는 모르지만 그 책들은 감쪽같이 자취를 감춘 듯하다. 이 책들은 다카하시 신지 선생이 어떤 사람에게 영언을 전했다는 내용인 듯하다. 그러나 웹 편집자는 자신이 가지고 있는 그 사람의 책과 신지 선생의 저서·강연 테이프를 비교해 들으면 파동이 완전히 다른 듯하다고 평한다. 신지 선생은 「고모로 마고오이우타(小諸馬子追い唄)」를 잘 불렀고, 웹 편집자도 그 테이프를 가지고 있다고 한다. 목소리는 맑고 아름다웠으며 나가노 억양이 섞인 도쿄말이었다. 신지 선생이 나타난다고 하는 사람은 전국에 많이 있는 듯하지만, 이상하게도 어째서인지 간사이 사람이 많다고 한다. 웹 편집자는 그들 모두에게 신지 선생을 나오게 하여 「고모로 마고우타(小諸馬子唄)」를 불러 달라고 한 다음, 생전의 테이프와 비교해 보자고 제안한다. 나가노 억양의 특징이 있는 「고모로 마고오이우타(小諸馬子追い唄)」를 제대로 연습해 달라는 것이다. 정말로 신지 선생이 내려온다면 노래의 곡조·말투·악센트 등이 완전히 같아야 한다고 웹 편집자는 말한다. 얼굴과 분위기도 똑같이 닮아 모두 신지 선생이어야 한다는 것이다.\n\n또한 모습이 보이지 않는 만큼 서양에서 하듯 엄밀하게 영을 심사하고, 생전에 소노가시라 회장에게서 전해 들은 신지 선생 영언의 첫마디를 확인하고 싶다고 말한다. 어떤 말부터 시작하기로 약속되어 있다는 것이다. 보이지 않는 만큼 거듭 신중해야 한다고 강조한다. 어느 때 웹 편집자는 그 어떤 사람의 강연회에 참석했다. 마지막에 다음과 같은 안내가 나왔다.\n\n“오늘 강연은 다카하시 신지의 영시(録示)에 따라 이루어졌습니다.”\n\n그러나 웹 편집자는 그것이 완전히 이질적인 것이라고 생각했다. 쇼와 48년(1973년) 6월 일정",
    "notes": "• 6월 2일: 「집착을 버리기, 자주 연수」, 교토부 다나베시 주신 산장\n\n• 6월 3일: 「빛을 넣는 법, 전생의 비밀, 질의응답, 체험담」, 교토부 다나베시 주신 산장\n\n• 6월 4일: 「현증, 전생윤회, 질의응답」, 교토부 다나베시 주신 산장\n\n• 6월 10일: 「심행 해설, 질의응답」, 간사이\n\n• 6월 10일: 「석가의 성도」, 우라와시\n\n• 6월 23일: 「마음의 원점, 질의응답」, 아키타현 오마가리시\n\n• 6월 날짜 미상: 「청년부 연수회」, 간사이",
    "image": "https://raw.githubusercontent.com/concario17-max/shinji/33f81d5266c36192c933d734494bd922df4702d8/images/stories/107.webp",
