    "title": "신리 유포의 본질과 소노가시라 회장에 관한 발언",
    "origTitle": "「高橋信次師物語」 真のメシヤの記録 108　八起正法先生編",
    "contentType": "",
    "summary": "7월 - 강사·간부 연수회, 야오키 빌딩 “우리가 신리(神理)를 널리 전하는 데 가장 중요한 것은 운운.…… 어느 전기회사 사장의 아들이 6월 17일 교통사고를 일으켰습니다. 벌써 한 달째 의식을 찾지 못하고 있습니다. 고등학교 3학년입니다. 영시로 ...",
    "body": "7월 - 강사·간부 연수회, 야오키 빌딩\n\n“우리가 신리(神理)를 널리 전하는 데 가장 중요한 것은 운운.…… 어느 전기회사 사장의 아들이 6월 17일 교통사고를 일으켰습니다. 벌써 한 달째 의식을 찾지 못하고 있습니다. 고등학교 3학년입니다. 영시로 보면 본인의 영은 새빨간 불길 속에서 자기 육체로 돌아가고 싶다고 말합니다. 하지만 돌아갈 수없습니다. 머리를 다쳤기 때문에 머리를 제어…… 운운. 부모가 지나치게 응석을 받아 주었습니다. 인간은 본래 질병이나 경제적·가정적 고통을 통해 길을 찾습니다. 운운.” 신리 유포의 본질신지 선생의 강연은 계속된다.\n\n“그러나 정법이라는 것은 그런 사람들만 상대해서는 안 됩니다. 병이 있는 것도 아니고 경제적으로 곤란한 것도 아닌, 제일선에서 활기차게 일하는 사람들이야말로 본래 이 사실을 알았으면 하는 사람들입니다.” 웹 편집자는 신지 선생이 종교의 진수라고도 할 만한 말을 했다고 평한다. 교조와 그 주위 사람들에게는 이 말이 괴롭겠지만, 많은 신흥종교가 불행하다고 불리는 사람들 위에서 성립하고 있다고 말할 수 있다는 것이 웹 편집자의 견해다. 신지 선생의 말은 계속된다. 신지 선생이 소노가시라 회장을 칭찬하다\n\n“고통을 인연으로 삼아 길을 찾는 일도 좋습니다. 하지만 어째서 그렇게 되었는지 원인을 반성하려 하지 않고 결과만 얻으려는 생각은 곤란합니다. 고통이 없는 사람에게도 신리를 알리는 일이 중요하다고 생각합니다. 대개의 종교는 ‘당신은 몇 년 전부터 입교했습니까?’라는 것을 문제 삼습니다. 그러나 마음의 상태에는 시간적으로 오래되고 새롭다는 구분이 없습니다. 알게 되면 그 즉시 아는 것입니다. 현실에서 그러했던 사람이 소노가시라라는 분이었습니다.\n\n‘생장의 집’의 대간부였던 사람이지만 신리에 닿자 곧바로 현상이 나타났습니다.\n\n이처럼 내게 온 때가 오래되었느냐 새로우냐는 문제가 아닙니다. 그러므로 정법을 따르게 되었다면 자신이 직접 실천해 보는 일이 중요하다고 생각합니다. 사람은 아무래도 자신에게 너그러워지기 쉽지만, 자신에게 엄격하기를 바랍니다. 그런 뜻에서도 소노가시라 씨처럼, 거칠기는 해도 자신을 바라보며 불도저로 자기 인생 항로의 울퉁불퉁한 곳을 고치면서 그 사람은 여기까지 왔습니다. 그 정도의 열의를 여러분에게 바랍니다. 그렇게 하여 그 사람은 위대성을 발견했습니다. 아니룻다……(중략)…….”",
    "notes": "",
