    "contentType": "",
    "summary": "“어제 하야시야 기쿠조라는 사람이 왔습니다. 마침 야마가타에서 온 젊은 여성이 있었는데 약간 후광이 나오고 있었습니다. 그래서 빛을 넣었더니 처음에는 중국어로, 뒤에는 인도 말로 이야기하기 시작했습니다. 기쿠조 씨는 잠시 그 모습을 지켜보았습니다. 그...",
    "body": "“어제 하야시야 기쿠조라는 사람이 왔습니다. 마침 야마가타에서 온 젊은 여성이 있었는데 약간 후광이 나오고 있었습니다. 그래서 빛을 넣었더니 처음에는 중국어로, 뒤에는 인도 말로 이야기하기 시작했습니다. 기쿠조 씨는 잠시 그 모습을 지켜보았습니다.\n\n그는 삿포로 공항에서 기다리는 동안 매점에서 『연생의 배』, 개제 뒤의 『마음의 발견·현증편』을 사서 읽었다고 합니다. 여러 책을 사서 읽었지만 마음이 이토록 감격한 책은 없었다고 합니다. 자기가 지금까지 생각해 온 것과 같다는 것입니다. 정법을 알게 된 이상 사람들에게도 전하고 싶다고 합니다. 무엇보다 책에 적힌 것과 똑같은 일을 지금 눈앞에서 보았기 때문에 더욱 깊이 감명받은 것입니다. 우선 가까운 사람부터 시작하겠다고했습니다.\n\n‘제 스승인 하야시야 ○○라는 사람은 지금 마침 텔레비전에서 유령 역할을 하고 있습니다. 유령 이야기를 할 때 스승의 집에 가면 오싹해집니다. 스승이 유령처럼 보입니다. 아, 스승에게는 언제나 유령이 붙어 있구나. 그래서 안색이 나쁘고 조금 이상하구나 하고 생각합니다. 하야시야 ○○라는 또 한 사람의 스승은 열심히 이나리 신앙을 믿습니다. 아침저녁으로 촛불을 켜고 기도한다고 합니다. 책에 쓰인 그대로입니다. 그래서 먼저 사모님께 책을 읽힌 뒤 스승 쪽에 손을 써 볼 생각입니다.’” 웹 편집자는 기쿠조 씨 이야기가 나온 김에 그도 책을 출간했다고 말한다. 그 책에 신지 선생에 관한 내용이 있으므로 다음 항목에서 인용해 요약하겠다고 한다.",
    "notes": "",
