    "contentType": "",
    "summary": "『기쿠조의 심령교실』 “지금은 이미 세상을 떠났지만, 운운. 여러 가르침을 얻고자 약속을 잡은 뒤, 어느 날 어슬렁어슬렁 아사쿠사 가미나리몬의 스미다강 변에 있는 야오키 빌딩의 GLA 본부로 찾아갔다. 나는 다카하시 씨를 찾아가는 길에 인사 삼아 무언...",
    "body": "『기쿠조의 심령교실』\n\n“지금은 이미 세상을 떠났지만, 운운. 여러 가르침을 얻고자 약속을 잡은 뒤, 어느 날 어슬렁어슬렁 아사쿠사 가미나리몬의 스미다강 변에 있는 야오키 빌딩의 GLA 본부로 찾아갔다. 나는 다카하시 씨를 찾아가는 길에 인사 삼아 무언가 선물이라도 가져가야겠다고 생각했다. 당시 살던 무사시노의 미타카에서 주오선을 타고 간다까지 간 뒤 간다역 주위를 이리저리 돌아다녔지만 마땅한 선물을 좀처럼 찾지 못했다. 어쩔 수 없이 지하철 긴자선으로 갈아타고 종점 아사쿠사역의 계단을 올라 시계를 보니 약속한 오후 1시가 코앞이었다. 서둘러 과일가게로 뛰어 들어가 오렌지 한 상자를 포장해 달라고 하여 들고 갔다. 야오키 빌딩 엘리베이터를 타고 다카하시 신지 씨의 방이 있는 위층으로 올라가자 담당 여직원이 응접실로 안내했다. ……과연 나타난 다카하시 씨에게서는 교조의 그림자를 조금도 찾아볼 수 없었다. 점퍼를 걸치고 감색 바지를 입은, 체격 좋은 중년의 동네 공장장 같은 인상이었다.\n\n‘잘 오셨습니다…….’\n\n‘편지로 뻔뻔스럽게 면담을 신청하여 송구합니다…….’\n\n‘아닙니다. 책을 읽고 곧바로 만나러 오는 분은 그리 많지 않습니다. 일 처리가 빠르시군요……. 여기까지 오면서 여러 곳에 들르셨습니다. 간다역 주변이라든가 가미나리몬이라든가, 길을 헤매셨지요…….’\n\n‘네? 예!’\n\n‘뭔가를 가져가야 한다고 생각하고, 내게 인사할 물건을 사느라 마음이 급해져서 안절부절못하지 않으셨습니까…….’\n\n‘아, 예, 예. 아, 이건 오렌지입니다……. 그, 헤매다가 산 것입니다. 인사 대신으로…….’\n\n‘하하하, 정확히 맞혔지요?’\n\n‘하하하하하.’” 기쿠조 씨도 부끄러워 멋쩍은 웃음을 터뜨렸지만 속으로는 놀랐다고 한다. 신지 선생의 말에 따르면 기쿠조 씨의 직업이 라쿠고가라는 사실에 흥미를 느껴, 그가 도착하기 한 시간 전부터 생각을 집중하고 영시로 보고 있었다는 것이다. 마치 텔레비전 화면을 보듯 그의 행동을 지켜보았다고 한다. 이 일을 계기로 기쿠조 씨는 신지 선생에게 완전히 흥미를 느꼈으며, 기회가 있을 때마다 찾아갔던 듯하다. 어느 날 기쿠조 씨가 야오키 빌딩에 훌쩍 들렀다.\n\n그러자 히피풍의 젊은이 몇 명이 신지 선생을 붙들고 시비를 걸고 있었다.\n\n“신을 꺼내 보여 봐.”\n\n“이봐, 해 보라고.”\n\n“전생윤회라고?”\n\n그러자 신지 선생은 다음과 같이 말했다.\n\n“이 사람에게 붙어 있는 악마여, 이 사람에게서 떠나라!” 그런 대화가 오간 뒤 젊은이들은 일행과 함께 돌아갔다. 기쿠조 씨는 당시의 모습을 글로 기록했다고 한다. 쇼와 48년(1973년) 7월 일정",
    "notes": "• 7월 7일: 「마음의 법」, 간사이\n\n• 7월 8일: 「실재계와 현상계의 물리적 고찰」, 간사이원문·용어 참고\n\n• 101~105번은 FC2 원문의 21번 묶음, 106~110번은 22번 묶음을 기준으로 번역했으며 하테나 합본의 해당 본문과 대조했다.\n\n• 101번의 코리타(コリータ) 농담은 이름과 일본어 懲りる, 곧 혼이 나서 질리거나 잘못을 깨닫는다는 말의 소리를 겹친 말장난이다. 번역문에서는 원문의 코리 소리를 남겼다.\n\n• 102번의 해답에 있는 ①은 정밀검수 원문에 수록된 글자를 그대로 사용했다.\n\n• 105번의 동화(同和)는 일본에서 부라쿠 차별 문제와 그 해소 정책을 가리키는 역사적 용어다. 원문의 표현에 따라 동화 문제·동화 해방으로 옮겼다.\n\n• 107번의 어떤 사람과 두 명의 하야시야 ○○는 원문이 이름을 밝히지 않았으므로 그대로 익명 처리했다.\n\n• 108번 인용문의 현상(現象)은 원문 표기대로 옮겼으며 이를 현증(現証)으로 바꾸지 않았다.\n\n• 101번의 환생 계보와 사후 세계, 102번의 죄에 관한 해답, 104번의 석가·그리스도 관계, 105번의 동화 해방, 107 번의 영언 검증, 108~110번의 영시·영언·빙의 관련 내용은 신지 선생의 발언, 제삼자의 기록 또는 웹 편집자의 종교적 주장과 판단으로 귀속해 옮겼다.\n\n• 첨부 강연록에서는 코리타의 말장난, 1973년 5월 13일 「제법무아」, 1973년 7월 13일 강사·간부 연수회의 사고 사례와 소노가시라 회장에 관한 발언, 하야시야 기쿠조의 방문담이 직접 겹치는 것을 확인했다. 웹 원문과 겹치는 범위에서만 용어를 검증하고 강연록에만 있는 문장은 추가하지 않았다.",
    "image": "https://raw.githubusercontent.com/concario17-max/shinji/33f81d5266c36192c933d734494bd922df4702d8/images/stories/110.webp",
