    "title": "8월의 예고와 도쿄 본부 지도",
    "origTitle": "「高橋信次師物語」 真のメシヤの記録 111　八起正法先生編",
    "contentType": "",
    "summary": "8월신지 선생은 소노가시라 회장에게 다음과 같이 말했다고 한다. “현재 ‘생장의 집’ 회원 가운데에는 인도 시대에 당신의 제자였던 사람들이 많이 다시 태어나있습니다. 어느 시점이 되면 모여들 것입니다.” 또 다음과 같이 예고했다. “한 번 몰락한 미국...",
    "body": "8월신지 선생은 소노가시라 회장에게 다음과 같이 말했다고 한다.\n\n“현재 ‘생장의 집’ 회원 가운데에는 인도 시대에 당신의 제자였던 사람들이 많이 다시 태어나있습니다. 어느 시점이 되면 모여들 것입니다.” 또 다음과 같이 예고했다.\n\n“한 번 몰락한 미국은 다시 부흥합니다. 미국 부흥의 원천은 정법(正法)입니다.” 그 뜻은 이렇다고 원문은 설명한다. 엘 란티가 예수에게 여호와로서 설한 정법은 긴 세월 동안 왜곡되고 곡해된다. 그러나 지금부터 150년쯤 뒤 시카고에 태어나는 본체 예수가 이를 바로잡으면, 그것이 미국이 몰락한 뒤 부흥하는 원천이 된다는 것이다. 헤이세이 15년(2003년) 봄, 미국 주도로 시작된 이라크 전쟁은 대국주의를 여실히 보여 주었다. 미국에서 짧게 여러 차례 유학한 경험도 있는 저자는, 다카하시 신지 선생이 예고한 것처럼 그 전쟁이 미 제국의 황혼을 고하는 사자가 되지는 않을까 매우 걱정한다. 신지 선생은 더 나아가 다음과 같이 말했다고 한다.\n\n“빛을 이용해 행성 사이를 여행하게 되고, 지구인이 다른 천체에 인간이 있다는 사실을 발견하는 것은 100년 뒤입니다.” 8월 12일 - 간사이 본부 강습회 8월 16일 - 도쿄 본부 지도이때 신지 선생은 도쿄 본부의 강사·간부들을 엄격하게 지도했다. 그 이유는 도쿄 본부의 강사·간부들이 너무나 공부하지 않았기 때문이었다. 신지 선생은 시험을 보겠다고 미리 알렸지만, 이에 반대하는 강사가 있었다. 그러므로 그에 대한 엄한 질책과 주의가 그날 지도의 내용이었다. 신지 선생은 그 가운데서 다음과 같이 말했다.\n\n“내 눈은 옹이구멍이 아닙니다. 설령 시험을 치지 못했더라도 그 노력은 내게 보입니다. 나는 석가모니여래로서 말하고 있는 겁니다. 내가 하는 일은 모두 천상계에서 결정된 일입니다. 따라오지 않겠다면 따라오지 않아도 됩니다. 따라오는 사람이 한 명만 있어도 그걸로 됩니다.” 평소와 달리 엄격한 어조였다고 한다. 질책이 끝난 뒤 신지 선생이 말했다.\n\n“내 이야기는 끝입니다.”\n\n그러자 모두가 답했다.\n\n“고맙습니다.”\n\n그리고 이후부터 신지 선생은 다음과 같은 고총스러운 심정을 자주 토로하게 되었다고 한다.\n\n“이런 의도로 GLA를 만든 것이 아니었습니다.”",
    "notes": "",
