    "contentType": "",
    "summary": "선정의 극의신지 선생은 선정과 명상을 지도할 때 다음과 같이 가르쳤다. “몸 둘레에 황금빛의 테를 그리십시오.” 또 어느 때 신지 선생은 기원정사를 기증한 수닷타(수달다)의 과거세를 지니고 있다는 강사 K씨에게 명했다. “공(空)에 관한 이야기를 하십...",
    "body": "선정의 극의신지 선생은 선정과 명상을 지도할 때 다음과 같이 가르쳤다.\n\n“몸 둘레에 황금빛의 테를 그리십시오.” 또 어느 때 신지 선생은 기원정사를 기증한 수닷타(수달다)의 과거세를 지니고 있다는 강사 K씨에게 명했다.\n\n“공(空)에 관한 이야기를 하십시오.” 그 명을 받은 K씨는 앞자리에 나서 말했다. 단에서 내려온 K씨는 신지 선생에게 다음과 같이 물었다고 한다.\n\n“방금 이야기는 어떠했습니까?” 신지 선생은 웃으며 고개를 끄덕이고 있었지만, 사랑이 깊은 신지 선생은 사람들 앞에서 결점을 지적하는 사람이 아니었으며, 다음과 같이 말하는 사람이었던 듯하다.\n\n“좋았습니다.” 유마에 대하여\n\n또 이 무렵 신지 선생은 다음과 같이 설명했다.\n\n“유마는 실재한 인물이 아니었습니다.”",
