    "title": "쿠마노유 연수회의 금가루·예언·치유 발언",
    "origTitle": "「高橋信次師物語」 真のメシヤの記録 113　八起正法先生編",
    "contentType": "",
    "summary": "여름 - 나가노현 쿠마노유에서 열린 자주 연수회신지 선생은 다음과 같이 말했다. “여러분, 저세상 같은 것을 말하면 ‘그런 말도 안 되는 소리를’이라고 하겠지만…… 운운. 어느 날의 강연에서 금가루가 나왔습니다. 땀이 모두 금이 되고, 말하는 단어가 ...",
    "body": "여름 - 나가노현 쿠마노유에서 열린 자주 연수회신지 선생은 다음과 같이 말했다.\n\n“여러분, 저세상 같은 것을 말하면 ‘그런 말도 안 되는 소리를’이라고 하겠지만…… 운운. 어느 날의 강연에서 금가루가 나왔습니다. 땀이 모두 금이 되고, 말하는 단어가 모두 금이 되어 입에서 튀어나옵니다. 그 금을 모두 모아 사면 엄청난 금액이 될 겁니다.” (폭소)\n\n“나는 과학자이니까요. 처음에는 이런 일이 있을 수 있는가 하고 깜짝 놀랐기에 가져가면 안 된다고 말했습니다. 그런데 가져간 사람이 있었습니다. 내 손에서도 얼굴에서도 금가루가 나오고, 입안에서도 가득 나옵니다.\n\n‘아, 빛난다.’ 누군가가 그렇게 말하자마자 그 금을 주워 가져가려고 몇 사람이 단상으로 몰려들었습니다.\n\n결국 그 금은 사라졌지요.…… 운운. 네가 설하는 신리(神理)는 태평양 연안을 따라 계속 뻗어 나갈 것이라는 말을 천상계로부터 들었습니다. 그래서 현재는 모두 태평양 연안입니다. 이와테, 센다이, 미토, 그리고 치바, 도쿄, 가나가와가 모두 태평양 연안이지요. 내 책이 나온 뒤에는 동해 연안에서도 오기 시작했습니다. 이번에도 아난(아난)이라는 사람이 어디서 나올지, 그리고 규슈에서 샤리푸트라(사리불)가 나올지를 모두 알고 있었기 때문입니다. 내가 교토에 나가면…… 일본만이 아닙니다. 외국에도 나가고 있습니다. 그것이 어느 시점이 되면 불길을 올리는 겁니다. 운운. 나는 가짜 예언을 하지 않습니다. 가짜 예언까지 하며 먹고살지 않아도, 먹고살 직업은 갖고 있으니까요. 돈을 벌려고 한다면 얼마든지 벌 수있습니다. 이 사람이 돈을 얼마나 가지고 있는지 모두 아니까, 부자가 있는 곳에 가서 병에 걸리게 하고…….” (웃음)\n\n“‘의사로는 못 고칩니다’ 같은 말을 하고 확 고쳐 주면 되지 않겠습니까.…… 물질화 현상을 일으키거나 마술사를 흉내 낸 듯한 짓을 해 봤자, 그런 흉내 같은 일은 해도 소용없습니다.\n\n그러나 믿으시겠습니까? 내가 처음 간사이에 갔을 때 만만치 않은 것이 있었습니다.\n\n‘이 사람, 나을까요?’ 돈파아(ドンパア)라는 사람 말입니다. 확 하자 나왔습니다. 젊은 여자아이인데, 눈이 멀어 우물에 빠져 자살한 여자입니다. 그 여자가 귀할멈가 되어 입이 귀밑까지 찢어져 있는 것이 보입니다. 그것의 눈을 확 뜨게 해 주었습니다. 그 순간 으스대기 시작했습니다.\n\n‘네 힘이 아니야.’\n\n‘아, 그래? 그럼 다시 눈을 멀게 해 봐.’ 나는 자유자재니까요. 춥게 하든 어떻게 하든, 눈을 멀게 하는 것도 자유자재입니다. 저세상에서 말입니다. 우리는 그만한 권한을 부여받았습니다. 마지막에는 ‘나가겠습니다’라고 했고, 지금은 나아 버렸습니다. 앉은뱅이로 이렇게 걸어 다니던 사람이 확 나은 일도 있습니다. 머리가 미쳤다고 불리는 사람은 거의 모두 빙의된 사람입니다. 뇌가 부서진 사람은 보지 못하고, 듣지 못하고, 말하지 못하는 것과 같아서 식물인간 같은 것입니다.”",
