    "title": "겸허한 신지 선생과 사건 해결 일화",
    "origTitle": "「高橋信次師物語」 真のメシヤの記録 114　八起正法先生編",
    "contentType": "",
    "summary": "겸허한 신지 선생다음 말은 영능력자나 교조라고 불리는 사람들이 새겨들어야 할 ‘말’이다. “나는 가르침을 받고 있습니다. 그래서 빛을 넣는 것도 내가 하는 일이 아니라고 말하는 겁니다. 그렇다면 어떻게 증상만(增上慢)에 빠질 수 있겠습니까? 내가 하는...",
    "body": "겸허한 신지 선생다음 말은 영능력자나 교조라고 불리는 사람들이 새겨들어야 할 ‘말’이다.\n\n“나는 가르침을 받고 있습니다. 그래서 빛을 넣는 것도 내가 하는 일이 아니라고 말하는 겁니다. 그렇다면 어떻게 증상만(增上慢)에 빠질 수 있겠습니까? 내가 하는 일이라면 으스댈 수도 있겠지만, 나는 아무런 힘도 없으니까요. 하느님에 관한 일이라면 나는 아마추어입니다. 그것을 가르쳐 주는 것이니, 그래서 나는 이것이 나 혼자의 힘이 아니라 차원이 다른 세계의 협력자들에 의해 움직이고 있는 것이라고 합니다. 그러므로, 그러므로 자기 힘이 아니니까, 무언가를 하려면 그런 것을 받을 수 있는 자기 자신을 만드는 일이 중요합니다. 눈먼 채 무엇을 하고 있는지는 모르겠습니다만, A씨를 조사하려고 한다면 간단합니다. 위에서 들여다보면 모두 알 수있습니다. 생각하는 것도, 하고 있는 것도 모두 말입니다.” 사건 해결사가 된 신지 선생\n\n“미야지마 ○○라고 해도 전국에 몇 명이나 있으니까요. 주소, 성명, 생년월일, 이것만 묻습니다. 그리고 나는 말했습니다.\n\n‘미야지마라는 사람이 간 경로를 알려 주십시오.’ 그것이 텔레비전처럼 비칩니다. 어디로 갔고, 어디에 들어갔는지 말입니다. 아, 바카스라는 술집에 갔군. 여기서 이런 남자를 만나 이런 일을 교섭하고 있습니다. 그런 뒤 끌려 나가…… 산의 농업용 저수지의…… 끌(ノミ)로……. 그리고 아내에게 알려 경찰에게, 사흘째에 붙잡혔습니다. 긴테츠 폭발 사고가 있었지요. 그건 RG라는 그룹입니다. 간사이를 조사해도 소용없습니다. 주오대학 학생입니다.\n\n그때 현경찰본부장이 고마움을 표하러 왔습니다.” 천상계의 꾸짖음을 들은 신지 선생\n\n“그런데 천상계에서 화를 냈습니다.\n\n‘네가 그런 범죄 수사의 앞잡이 노릇 같은 일을 하다가, 도시에 나쁜 놈이 있으면 그들에게 살해당한다.’ 그래서 그 ○억 엔 사건의 범인도 나는 알고 있습니다만…….\n\n‘너는 신리(神理)만 설하면 된다.’ 그런 주의를 받았기 때문에 지금은 일절 거절하고 있습니다. 뭐, 그렇게 차원을 넘은 세계로부터 가르침을 받으니 알 수 있는 겁니다.” 원문은 이런 일을 알 수 있는 이유를 다음과 같이 설명한다. 영원한 영혼에는 경험한 모든 일이 기록되어 있다. 그러므로 물어보면 알 수 있으며, 극히 간단한 일이라는 것이다. 신지 선생은 그 능력을 지니고 있었다고 한다.",
    "notes": "",
