    "contentType": "",
    "summary": "“오니시라는 교조가 있었습니다. ‘다카하시 신지 군’이라고 하면서요. 나는 6층에 있는데 그가 접수처로 왔습니다. 상대는 신흥종교의 부자였고, 나처럼 초라하게 입지 않았습니다. 그를 3층의 내가 있는 곳으로 안내했습니다. ‘다카하시 신지 씨는 어디에있...",
    "body": "“오니시라는 교조가 있었습니다. ‘다카하시 신지 군’이라고 하면서요. 나는 6층에 있는데 그가 접수처로 왔습니다. 상대는 신흥종교의 부자였고, 나처럼 초라하게 입지 않았습니다. 그를 3층의 내가 있는 곳으로 안내했습니다.\n\n‘다카하시 신지 씨는 어디에있습니까?’ 내가 바로 앞에 있는데도 나를 사환 같은 사람으로 생각한 거지요. 본인을 눈앞에 두고 그런 말을 한 겁니다.\n\n‘앉으십시오.’ 다카하시 신지라는 사람은 나이가 꽤 많고, 멋지게 생겼으며, 수염도 기른 남자일 것으로 생각했겠지요. 그런데 어느 회사의 과장에도 못 미치고 계장 같은 차림의 사람이 나오니까 말입니다. 그 사람은 내게 왔습니다. 나는 그런 때 가만히있습니다. 상대편이 먼저 말하게 두는 편이 빠르기 때문입니다. 그랬더니 다음과 같은 대화가 오갔습니다. 오니시: 당신은 자신이 석가라고 칭하지만, 석가가 태어날 리없습니다. 다카하시: 아, 석가 말입니까? 나는 내 입으로 석가라고 말한 적이 없습니다. 하지만 사람의 입에는 문을 달 수 없으니까요. 그것이 진실인지 아닌지 당신이 알 수 있다면 입증할 수 있어야 합니다. 당신은 교조라며 많은 사람을 미혹하고 있습니다. 오니시: 미혹하고 있지 않습니다. 다카하시: 그 증거로 당신은 내가 누구인지 모릅니다. 모른다는 것은 다른 사람에게도 알게 할 수 없다는 뜻입니다. 뜻을 알겠습니까? 대체 당신이 사는 곳이 바뀐 건 무슨 까닭입니까? 당신은 본처를 시코쿠에 두고, 지금 여기에 있는 사람은 대체 무엇입니까? 하느님을 설하는 사람이 이게 뭔가요? 그런 일은 없다는 말은 못 하게 할 겁니다. 오니시: 그런 것까지 알 수있습니까? 다카하시: 그런 음탕한 종교인이있습니까? 처음부터 다시 시작하고 오십시오. 당신은 마음에 관해서는 아무것도 모릅니다. 머리로 알아도 실천하는 것은 하나도 없습니다. 처음부터 다시 시작하십시오.”\n\n“그런 사람이 교조이고 신학박사라니. 그런 사람에게 속아 ‘돈을 가져오라, 무엇을 가져오라’는 말을 듣습니다. 당신, 그렇게 많은 돈을 대체 무엇에 쓰려는 겁니까? 수상한 짓을 하고, 그런 것은 신앙적인 것도 무엇도 아닙니다. ‘당신은 나를 모릅니다’라고 딱 일침을 놓은 겁니다. 개중에는 도발하러 오는 사람도 있어요.”\n\n“대개는 안 됩니다. 한꺼번에 뒤집혀져 버립니다. 나에게는 그만한 힘이 있습니다. 인간에게는 근본적으로 올바른 길을 실행하게 하는 일이 중요합니다. 우리는 다투는 일을 목적으로 삼고 있지 않으며, 다투어야 할 필요도 없습니다. 그래서 그런 사람들은 모두 두 손을 들고 안 되게 되지요. 나는 여러분에게 믿으라고 말한 적이 없습니다. 어째서일까, 왜일까 하고 의문을 품으라고 합니다. 의문을 추구해 가면 마지막에는 신리(神理)에 도달하기 때문입니다. 그러므로 나는 계속 강연해 왔지만, 처음부터 순순히 믿지 말고 의문을 품으며, 의문이 생기면 다시 질문하라고했습니다. 그렇게 해야 마지막에 도달하기 때문입니다. 그러니 다 알았다는 표정을 지을 필요는 없습니다.”",
    "notes": "",
