    "contentType": "",
    "summary": "의문과 기적 “예수님이 말씀하셨습니다. 네가 의문을 품으라고 하니 안 된다고, 왜 ‘믿으라’고 말하지 않느냐고 말입니다. 예수님과 나는 생각이 조금 다릅니다. 그러자 예수님은 그러면 곤란하다, 중간에서 어정쩡하게 되니 믿으라고 말하라고했습니다. 병의 ...",
    "body": "의문과 기적\n\n“예수님이 말씀하셨습니다. 네가 의문을 품으라고 하니 안 된다고, 왜 ‘믿으라’고 말하지 않느냐고 말입니다. 예수님과 나는 생각이 조금 다릅니다.\n\n그러자 예수님은 그러면 곤란하다, 중간에서 어정쩡하게 되니 믿으라고 말하라고했습니다. 병의 경우에는 말입니다, 사실은 믿게 하는 편이 기적이 일어나기 쉽습니다. 빠릅니다. 믿는 마음이 있으면 기적이 빨리 일어납니다. 내가 의문을 품으라고 말하는 것은 어떤 의문에도 답할 수 있는 힘이 내게 있기 때문입니다.” 마음에도 모양이 있다\n\n“지금까지 입으로 마음을 말한 사람은 있었지만, 마음에도 모양이 있다고 말한 사람은 내가 처음입니다. 막 태어난 아이의 마음은 실로 깨끗하고 동그랗습니다. 그것이 자라면서 왜곡되기 시작합니다.” 하트 모양의 마음\n\n“마음이 하트 모양으로 보이는 사람이 있습니다. 이 사람은 유난히 분홍색으로 빛나는군. 예전부터 마음을 하트 모양으로 그려 왔는데, 대체 이건 무엇일까?\n\n‘당신은 몇 살입니까?’\n\n그러자 그 사람의 수호령(과거세, 영혼의 형제)이 알려 줍니다.\n\n‘이 사람은 연애 중입니다.’ 어떤 사람인지 물으면 그 모습을 보여 줍니다.\n\n‘어라, 당신은 연애하고 있군요. 이런 여자지요?’ 모든 것을 알게 됩니다. 연애하는 사람의 마음은 실제로 하트 모양이 됩니다. 사랑에 빠진 사람에게는 분홍색 후광이 나옵니다.”",
    "notes": "",
