    "title": "오쿠보 히코자에몬·니치렌·미래 전망",
    "origTitle": "「高橋信次師物語」 真のメシヤの記録 119　八起正法先生編",
    "contentType": "",
    "summary": "오쿠보 히코자에몬에 대하여 “지위가 높은 사람일수록 지옥에 있습니다. 욕망으로 한평생을 보내기 때문입니다. ‘저런 물만 먹고사는 빈농이’라고 할 만한 사람이 천상계에 가 있으니까요. 오쿠보 히코자에몬 말입니다. 깜짝 놀랐습니다. 보살계에서 아름다운 빛...",
    "body": "오쿠보 히코자에몬에 대하여\n\n“지위가 높은 사람일수록 지옥에 있습니다. 욕망으로 한평생을 보내기 때문입니다. ‘저런 물만 먹고사는 빈농이’라고 할 만한 사람이 천상계에 가 있으니까요. 오쿠보 히코자에몬 말입니다. 깜짝 놀랐습니다. 보살계에서 아름다운 빛을 내고 있었습니다. 내게 와서 다음과 같이 말했습니다.\n\n‘이 오쿠보 히코자에몬이옵니다.’” 니치렌에 대하여\n\n“일본에서 유명한 승려 가운데 보살계에 가 있는 사람은 적습니다. 니치렌도 오랜 기간 자발적으로 지옥계에 있었던 사람입니다. 보살계에 들어가지 않았습니다. 자신이 뿌린 씨앗이 그후 많은 대중을 미치게 했다는 책임을 지고 말입니다. 저세상에서 그 사람을 모르는 사람은 없습니다. 너무나 유명하고 겸허합니다. 지금 창가학회가 하고 있는 것과 같은 건 아닙니다. 마음이 깨끗한 사람들 가운데는 가난하더라도 훌륭한 사람이 많이 있습니다. 그러므로 금액의 크기나 지위가 인간의 가치를 결정하는 것은 아닙니다.” 앞으로의 미래 전망질문자: 이번 세상에서 안 되면 다음 세상에서, 다음 세상에서도 안 되면 또 그다음 세상에서라는 마음이군요. 다카하시: 하지만 이 지상에 나올 수 있을지는 의문입니다. 많은 영이 지상에 나와 영을 공부하고 싶다며 기다리고 있으니까요. 나는 780년 뒤에 한 번 더 지구상에 나옵니다. 그런 뒤 또 다른 천체에도 태어납니다. 그 천체가 어디인지도 알고 있습니다. 이 지구는 지금부터 700년쯤 뒤에 조화를 이룰 것이기 때문입니다. 유토피아가 될 것이기 때문입니다.\n\n그때에는 지금과 같은 공해가 하나도 없어집니다. 그리고 현재의 일본은 기후가 바뀝니다. 현재의 아프리카, 남아메리카, 그리고 인도 지역은 현재의 일본과 마찬가지로 봄·여름·가을·겨울이 가장 조화를 이룬 나라가 됩니다.",
    "notes": "",
