    "summary": "아프리카에 우주 정거장 “그리고 아프리카의 대서양 연안에 큰 우주 정거장이 생깁니다. 다른 천체와 자유롭게 교통하게 됩니다. 우리는 그런 상태가 된 유토피아에 태어납니다. 780년 뒤입니다. 그 중간에(쇼와 48년인 1973년 현재, 180년) 예전에...",
    "body": "아프리카에 우주 정거장\n\n“그리고 아프리카의 대서양 연안에 큰 우주 정거장이 생깁니다. 다른 천체와 자유롭게 교통하게 됩니다. 우리는 그런 상태가 된 유토피아에 태어납니다. 780년 뒤입니다. 그 중간에(쇼와 48년인 1973년 현재, 180년) 예전에 예수 그리스도라고 불린 분이 미국에 태어납니다. 시카고라는 곳에 태어납니다.\n\n그때 여러분은 천상계에서 협력하는 겁니다. 천상계에서 이 지상계를 보며 ‘또 저런 짓을 하고 있군’하는 것입니다.” 질문자: 시카고에는 본체가 나타나는 겁니까? 다카하시: 본체입니다. 분신은 필리핀에 나타나있습니다.\n\n“과학에는 주기율이라는 것이 있지요. 이 물질의 주기율과 마찬가지로 영의 주기율도 있습니다. 우리의 생명도 어느 시점이 되면 저세상으로 돌아갑니다.” 참된 십자가\n\n“예수님이 십자가에 못 박혔을 때, 그분의 영은 자신의 육체가 십자가에 못 박힌 것을 보고 계셨습니다. 당시에는 예수 그리스도라고 부르지 않았습니다. 이마니엘이라고 불렀습니다. 나는 이분의 지도령을 맡고 있었습니다. 그러므로 그때의 일도 내게는 모두 보입니다. 내가 육체를 가질 때는 예수님이 지도합니다. 예수님이 육체를 가질 때는 내가 천상계에서 지도령을 맡습니다. 예수님은 엄격하다고 해도 서양적인 면이 있어 매우 친절합니다.\n\n그러나 내가 예수님의 지도령을 맡을 때는 엄격합니다. 그래서 나는 이런 말을 들었습니다.\n\n‘너는 자신에게는 무르고 나에게는 엄격하다.’ 예수님이 어떤 남동생의 병을 고쳐 주었습니다. 그 남동생의 누나를 좋아하게 되었습니다.\n\n‘예수, 그런 일을 하면 안 된다.’ 그랬더니 ‘너는 나에게 연애도 못 하게 하지 않았느냐. 그러면서 너는 무르지 않느냐’라고 말한 일이 있습니다. 지금까지 예수와 모세들이 내게 예언한 일은 하나도 틀리지 않았습니다. 나는 컴퓨터를 만드는 사람이니까요. 되는대로 한 말은 믿지 않습니다.” 원문·용어 참고",
    "notes": "• 111~115번은 FC2 원문의 23번 묶음, 116~120번은 24번 묶음을 기준으로 번역했으며 하테나 합본의 해당 본문과 대조했다.\n\n• 113번의 돈파아(ドンパア)는 원문의 뜻이 분명하지 않아 소리를 옮겼고, 114번의 산의 농업용 저수지의…… 끌 (ノミ)로……는 웹 원문의 불완전한 표현을 채우지 않았다.\n\n• 117번의 블랑크 상수는 원문의 ブランク常縁를 그대로 옮겼으며, 현대 과학 용어로 교정하지 않았다. 또 아인슈타인의 일본인 대상 메시지는 원문이 제시한 인용으로서 그대로 번역했다.\n\n• 118번의 슈바이처가 이집트에서 치료에 종사했다는 서술, ○田○ 총리대신, 114번의 ○억 엔 사건은 원문의 표기와 익명 처리를 그대로 유지했다.\n\n• 111·120번에서 시카고에 예수의 본체가 태어난다고 한 시점은 각각 150년쯤 뒤와 쇼와 48년(1973년) 현재, 180년로 적혀 있으며, 원문 그대로 옮겼다.\n\n• 113번의 금가루·빙의·치유, 114번의 영시와 범죄 수사, 116번의 기적·수호령·마음의 모양, 117번의 아인슈타인 관련 발언, 118~120번의 사후 세계·환생·예수에 관한 내용은 신지 선생의 발언 또는 웹 편집자의 종교적 주장으로 귀속해 옮겼다.\n\n• 첨부 강연록에서는 114번의 미야지마 사건과 긴테츠 폭발 사고, 115번의 오니시와의 대화, 117번의 블랑크 상수, 118번의 헬렌 켈러·슈바이처, 119번의 오쿠보 히코자에몬, 120번의 우주 정거장·이마니엘 대목이 직접 겹치는 것을 확인했다. 웹 원문과 겹치는 범위에서만 용어를 검증했고 강연록에만 있는 문장은 추가하지 않았다.",
    "image": "https://raw.githubusercontent.com/concario17-max/shinji/33f81d5266c36192c933d734494bd922df4702d8/images/stories/120.webp",
