    "chapterMeta": {
      "id": 3,
      "name": "제3장",
      "title": "마음의 본질과 인간의 목적·사명",
      "fullTitle": "제3장 · 마음의 본질과 인간의 목적·사명",
      "range": "101–150",
      "badgeColor": "purple",
      "flow": "마음의 구조 → 신리와 과학 → 인간의 목적 → 윤회와 사명 → 사후세계와 현증"
    },
    "title": "쿠마노유 연수회의 배경과 하쓰요 씨의 일화",
    "origTitle": "「高橋信次師物語」 真のメシヤの記録 121　八起正法先生編",
    "contentType": "",
    "summary": "쿠마노유 연수회의 배경지금까지 서술한 쿠마노유 연수회의 참가자는 700명이었고, 그 가운데 300명이 ‘생장의 집’ 관계자였다. 그중 한 사람이 다음과 같은 희망을 밝혔다. “‘생장의 집’ 가르침과 어떻게 다른지 알려 주십시오.” 그래서 연수 둘째 날...",
    "body": "쿠마노유 연수회의 배경지금까지 서술한 쿠마노유 연수회의 참가자는 700명이었고, 그 가운데 300명이 ‘생장의 집’ 관계자였다. 그중 한 사람이 다음과 같은 희망을 밝혔다.\n\n“‘생장의 집’ 가르침과 어떻게 다른지 알려 주십시오.” 그래서 연수 둘째 날, 아침 식사를 마친 뒤의 휴식 시간을 이용해 그 차이를 설명했다고 한다. 이때의 자주 연수는 한 반을 100명으로 나누어 일곱 반을 편성하고, 각 반에 담당 강사를 두었으며, 신지 선생이 각 반을 돌아다니며 전체적으로 지도하는 방식이었다. 지금까지 서술한 내용은 이와테현 T씨가 속한 반에서 녹음한 테이프를 글로 옮긴 것이다. 원문은 석가 시대에는 기억력이 뛰어난 사람이 “이때 석가는 이렇게 말씀하셨다”라고 구전한 내용이 후세에 남게 되었지만, 과연 그것이 얼마나 정확했겠느냐고 묻는다.\n\n그러나 현대에는 테이프레코더가 있고, 음성뿐 아니라 영상까지 담는 비디오도 있으므로 비할 데 없이 정확하다는 것이다. 원문은 어느 시점이 되면 인터넷을 이용한 신지 선생 강연 동영상을 통해 정법(正法)이 각 가정에 성큼성큼 들어갈 것이라고 예상한다. 8월 29일신지 선생은 회사 일로 신슈의 공장에 갔다. 컴퓨터 단말 장치와 카세트를 대량 생산하는 것이 신지 선생의 사업이었다. 작업장은 활기가 넘쳤다. 신지 선생이 플라스틱 공장을 둘러보다가 다카하시 하쓰요 씨(38세)가 보이지 않아 묻자, 그녀가 거의 2주 동안 쉬고 있다는 답이 돌아왔다. 가벼운 작업인데도 허리를 펴지 못한다는 것은 생각하기 어려웠다.\n\n“안녕하세요!” 신지 선생이 뒷문에서 소리를 건네자 “네”라는 대답이 돌아왔지만, 그녀는 몸을 자유롭게 움직일 수 없는 듯했다.\n\n“바쁘신데 회사를 쉬어서 죄송합니다.”\n\n그녀는 고통스러운 듯 말했다. 신지 선생이 하쓰요 씨의 몸을 보자 이상한 일이 있었다. 누워 있는 사람은 틀림없이 하쓰요 씨인데도, 82~83세쯤으로 보이는 다듬지 않은 수염의 노인이 눈앞에 누워 있었다고 한다. 신지 선생이 몇 번이나 확인해도 목소리는 하쓰요 씨의 것이었다. 신지 선생은 결심하고 물었다.\n\n“언제쯤부터 몸이 좋지 않았습니까?”\n\n“아마 8월 13일 밤이었던 것 같습니다. 오봉 맞이불을 피운 뒤로 온몸이 오슬오슬 떨렸습니다. 맞이불을 피우기 전까지는 별일이 없었습니다. 올해 오봉은 새로 상을 치른 뒤 맞는 첫 오봉이었고, 돌아가신 삼촌에게도 처음 맞는 오봉이었기 때문에 불단도 기후 등롱으로 꾸며 놓았습니다.” 하쓰요 씨는 틀림없이 세상을 떠난 삼촌을 불러들인 것이었다. 하쓰요 씨는 무언가가 생각난 듯 다음과 같이 말했다.\n\n“8월 1일에 무덤의 잡초를 뽑으며 속으로 ‘삼촌, 오봉이 머지않았어요. 오봉에는 꼭 와 주세요’라고 부탁했습니다.” 신지 선생은 하쓰요 씨에게 말했다.\n\n“당신이 불렀을 때 그 삼촌은 정말로 왔습니다.”\n\n“설마…….”\n\n그러자 신지 선생은 노인의 영에게 엄하게 말했다.\n\n“당신은 하쓰요 씨에게서 떠나십시오.”\n\n그러자 그 영은 다음과 같이 말하며 매달렸다고 한다.\n\n“나는 갈 곳이 없다. 여기에 머물게 해 다오.” 신지 선생이 차근차근 타일러 설명하자, 그 영은 지금까지의 인생을 반성하기 시작했고 하쓰요 씨의 몸에서 떠나갔다고 한다. 쇼와 48년(1973년) 8월 강연 일정",
    "notes": "• 8월 4일: 「전생윤회·현증」, 시가고원\n\n• 8월 11일: 「마음의 공해」, 간사이\n\n• 8월 12일: 「반야심경의 해설·질의응답」, 간사이\n\n• 8월 16일: 「도쿄 본부 직원을 꾸짖다·반야심경·공양」",
