    "title": "소노가시라 회장이 보았다는 신의 빛",
    "origTitle": "「高橋信次師物語」 真のメシヤの記録 123　八起正法先生編",
    "contentType": "",
    "summary": "회장은 이마를 바닥에 대고 있었으므로 신지 선생의 모습을 볼 수는 없었다. 보이지는 않았지만 느낄 수는 있었다고 한다. 신지 선생은 석가의 상을 나타냈고, 그러자 그 석가의 상 위에 큰 빛이 있었다고 한다. 그것은 석가의 권위를 초월한 또 하나의 큰 ...",
    "body": "회장은 이마를 바닥에 대고 있었으므로 신지 선생의 모습을 볼 수는 없었다. 보이지는 않았지만 느낄 수는 있었다고 한다. 신지 선생은 석가의 상을 나타냈고, 그러자 그 석가의 상 위에 큰 빛이 있었다고 한다. 그것은 석가의 권위를 초월한 또 하나의 큰 권위였다고 한다. 회장은 무릎을 꾸은 채 그 감격과 고마움에 울음을 터뜨렸다. 회장의 머리는 그 권위 앞에서 저절로 숙여졌다. 머리를 들고 있을 수 없을 만큼 전혀 자연스러운 일이었고, 들어 올리려 해도 들 수 있는 성질의 것이 아닌 영의 권위와 영의 중압이었던 듯하다. 신지 선생의 말이 끝나 회장이 머리를 들어 올리려 한 순간, 이번에는 회장의 머리가 누르듯 아래로 밀려 이마가 다다미에 문질러졌다. 그리고 말이 가슴 깊은 곳에서 터져 나왔다고 한다. 머리는 다다미에 문질러져 있었지만, 회장의 심안은 신지 선생과 그 배후에 있는 석가와 그리스도를 통해 아득히 먼 곳이라고 해야 할지, 아득히 높은 곳이라고 해야 할지, 눈이 멀 듯한 신의 빛을 보고 있었다고 한다.\n\n“신이시여, 이 위대한 분을 지금 이 세상에 내려 보내시고 저희 마음의 빛이 되게 하여 주신 것에 감사드립니다.” 육체를 지닌 회장은 신지 선생 앞에 무릎을 꾸고 있었지만, 회장의 마음은 신지 선생의 마음과 신의 빛(신의 마음)이 하나임을, 신의 빛이 육체를 지닌 모습으로 이 현상의 세계에 나타났음을, 그것이 신이 전 인류를 구원하기 위한 위대한 사랑임을 알게 되었다고 한다. 더 나아가 큰 권위, 빛, 석가, 예수, 다카하시 신지 선생, 그곳에서 흘러나오는 “불법·정법(正法)”이야말로 신의 마음이 흘러나온 것이었다고 소노가시라 히로치카 회장은 가르쳐 준다. 원문은 이 항목의 일부가 앞의 내용과 겹치지만 굳이 다시 서술한다고 밝힌다.",
    "notes": "",
