    "title": "꿈의 조작과 여성이 유혹하는 꿈 시험",
    "origTitle": "「高橋信次師物語」 真のメシヤの記録 127　八起正法先生編",
    "contentType": "",
    "summary": "꿈의 조작이와 같은 이야기는 더 있다. 돈에 인색한 사람이 있으면 꿈을 조작해 돈이 떨어져 있는 꿈을 보여 준다고 한다. 그 사람이 손을 내밀면 다음 날 전화가 와서 다음과 같이 말한다. “실패했군요.” 여성에게 약한 사람에게는 절세의 미녀가 나타난다...",
    "body": "꿈의 조작이와 같은 이야기는 더 있다. 돈에 인색한 사람이 있으면 꿈을 조작해 돈이 떨어져 있는 꿈을 보여 준다고 한다. 그 사람이 손을 내밀면 다음 날 전화가 와서 다음과 같이 말한다.\n\n“실패했군요.” 여성에게 약한 사람에게는 절세의 미녀가 나타난다. 제자들에게는 고달픈 일이었던 듯하다. 여성이 유혹하는 꿈 시험의 한 예당시 20대였던 제자 Ś原 씨는 다음과 같이 글을 남겼다.\n\n그는 언제 꿈 시험이 있을까 기다렸지만, 이제 그 일을 잊을 무렵이었다고 한다.\n\n그는 태국의 사원 안에서 여성 세 명의 춤을 보고 있었다. 두 명은 버마인이었고, 한 명은 녹빛을 띠는 짙은 갈색 피부의 크메르인 여성이었다. 코 모양이나 입매, 커다란 검은 눈동자의 눈 등 모든 면에서 이상적인 얼굴이었다고 한다. 가슴의 탄력도 이상적이었고, 그 크메르인 여성은 그를 옆방으로 유인했다. 두 버마인 여성은 Ś原 씨를 붙잡고 가지 말라고 했지만, 그는 캐노피가 달린 침대에서 그녀와 서로 꿀어안았다. 그녀의 옷을 천천히 벗기고, 그 크메르인 여성의 몸 안으로 천천히 들어가 계속 환희를 느꼈다고 한다. Ś原 씨가 “아, 꿈 시험이다”라고 생각했을 때는 이미 늦은 뒤였다. 후일 그는 머리를 긁적이며 신지 선생 앞으로 나아가 말했다.\n\n“실패했습니다.”\n\n“왜요?”\n\n“그녀와 해 버렸습니다.”\n\n“당신은 젊으니까 음경이 서는 것은 당연하지요. 왜 실패입니까? 그만큼 유혹받았다면 무리하게 억눌렀을 때 오히려 부자연스럽습니다.”\n\n“그럼 그렇게 해도 괜찮았던 겁니까?”\n\n“아니요, 안 됩니다.”\n\n“그 여성과 섹스하기 전에 현재의 소중한 여성을 생각하지 않았습니까?” 현재 사귀고 있는 여성에 관한 생각이 머릿속에서 사라져 버리는, 말도 안 되는 이성의 결여를 드러내고 말았다고 한다.",
    "notes": "",
