    "contentType": "",
    "summary": "가을 - 「부동명왕에 대하여」 와카야마시 노동회관에서 열린 강연이었다. 신지 선생은 다음과 같이 강연했다. “부동명왕은 올바른 마음을 지닌 사람들을 악령으로부터 수호하는 빛의 천사입니다. 천국의 경찰관이라고 생각하면 됩니다. 실재계의 질서를 바로잡는 ...",
    "body": "가을 - 「부동명왕에 대하여」 와카야마시 노동회관에서 열린 강연이었다. 신지 선생은 다음과 같이 강연했다.\n\n“부동명왕은 올바른 마음을 지닌 사람들을 악령으로부터 수호하는 빛의 천사입니다. 천국의 경찰관이라고 생각하면 됩니다. 실재계의 질서를 바로잡는 역할을 합니다. 부동명왕은 본래 마음의 세계에서 활동하는 존재라고 할 수있습니다. 예배할 대상은 아닙니다.” 11월 - 오사카 강연 「윤회전생」\n\n“오늘은 윤회전생에 관해 말씀드리겠습니다. 태양은 동쪽에서 서쪽으로 져 갑니다. 그리고 내일 다시…… 운운.” 강연은 이와 같이 시작되었다. 마르크스에 대하여\n\n“카를 마르크스도 또한 ‘빛의 천사’로 나타난 겁니다.” 신지 선생은 마르크스도 빛의 천사였다고 가르쳤다. 그러나 무신론적 입장을 취한 공산주의자 마르크스도 경제에 대한 고찰이 벽에 부딪혀 모스크바에 신학교를 세웠다고 신지 선생은 말했다.",
    "notes": "",
