    "contentType": "",
    "summary": "아틀란티스와 아가샤 “나는 1만 2천 년 전, 아틀란티스 제국에 ‘아가샤’로 태어났습니다.” 피라미드 “나일강 가의 피라미드 가운데 하나가 어느 시점이 되면 우리 동지들의 손으로 발견될 것입니다.” 이때 아가샤 대왕은 악한 사람들이 천사들을 모조리 죽...",
    "body": "아틀란티스와 아가샤\n\n“나는 1만 2천 년 전, 아틀란티스 제국에 ‘아가샤’로 태어났습니다.” 피라미드\n\n“나일강 가의 피라미드 가운데 하나가 어느 시점이 되면 우리 동지들의 손으로 발견될 것입니다.” 이때 아가샤 대왕은 악한 사람들이 천사들을 모조리 죽였기 때문에, 아틀란티스 대륙에서 육로를 따라 아프리카 대륙으로 피난했다는 강연 내용도 있다. 그후 아틀란티스 대륙은 황폐해질 대로 황폐해진 사람들과 함께 하루 밤낮 사이에 함몰되었다고 한다. 아가샤 대왕은 피난한 이집트의 나일강 가에 아틀란티스 제국과 관련된 피라미드를 지어 남겼으며, 자신들이 남긴 자료로 두 대륙의 관계가 밝혀질 것이라고 신지 선생은 말했다. 다카하시 신지의 『마음의 지침』이 출간되었다. 머리말\n\n“현대 불교와 기독교의 신리(神理)는 오랜 역사적 과정 속에 매몰되었다고 해도 좋을 것입니다. 물론 그에는 그만한 이유가 있습니다. 인간은 한편으로 오관이나 육근에 좌우되도록 되어 있기 때문입니다. 이 책을 손에 든 독자가 본서의 참뜻을 파악하고, 조화로운 생활과 평화로운 사회를 건설하는 데 마음의 양식으로 삼기를 간절히 바랍니다.” 쇼와 48년(1973년) 11월 길일　다카하시 신지쇼와 48년(1973년) 11월 강연 일정",
    "notes": "• 11월 10일: 「마음을 씻다」, 간사이\n\n• 11월 11일: 「전생과 사명·번뇌즉보리」, 간사이\n\n• 11월 12일: 「정도 실천」, 간사이\n\n• 11월 23일: 「물질과 생명·현증」, 도쿄 요미우리홀",
