    "title": "관동 지진·리니어 모터카·새로운 에너지",
    "origTitle": "「高橋信次師物語」 真のメシヤの記録 137　八起正法先生編",
    "contentType": "",
    "summary": "관동 지진에 대하여 “얼마 전 천상계에서 도쿄에 대지진을 일으키겠다고 알려 왔습니다. 12월 1~5일이라고했습니다. 그런 일을 하면 300~400만 명이 죽는다고 말했습니다. 그런 일을 하게 둘 수는 없으므로, 우리는 그에 대비해 사쿠라지마를 비롯한 ...",
    "body": "관동 지진에 대하여\n\n“얼마 전 천상계에서 도쿄에 대지진을 일으키겠다고 알려 왔습니다. 12월 1~5일이라고했습니다. 그런 일을 하면 300~400만 명이 죽는다고 말했습니다. 그런 일을 하게 둘 수는 없으므로, 우리는 그에 대비해 사쿠라지마를 비롯한 태평양 연안의 화산 지대와 후지 화산 지대로 에너지를 분산시켜 달라고 부탁해 두었습니다. 도쿄나 오사카 같은 인구 밀집 지역에 지진을 일으키면 견딜 수가 없습니다.” 리니어 모터카에 대하여\n\n“도쿄와 오사카 사이도 시속 500킬로미터의 리니어 모터카가 다니게 되며, 비행기보다 안정된 교통수단이 될 것입니다.” 새로운 에너지\n\n“앞으로 일본의 태평양 연안에서 새로운 에너지가 크게 분출할 것입니다. 그 결과 일본의 연료 관계는 매우 조화롭게 되고 가솔린은 사양화할 것입니다. 지금처럼 투쟁과 파괴를 거듭하고 신의 아들로서의 자각을 잃어 가면, 신의 아들임을 자각할 때까지 천변지이도 일어날 것입니다. 아직 그 장소는 정해지지 않았습니다.” 원문은 일본인의 반성과 자각을 촉구하기 위해 천상계에서 대지진을 일으키려 한다는 것이라고 설명한다. 원문은 인간의 영혼이 계속 살아 있는 것이므로, 그 사람의 업(카르마, 마음의 경향성)의 원인과 결과에 따라 천변지이에 휘말리는 사람이 있더라도 그것은 그것대로 어쩔 수 없는 일이라고 말한다. 또 일본인이 돈에 빠지고 버블에 취하며, 자력을 잊은 타력신앙에 빠져 투쟁과 파괴를 거듭하는 등 인간으로서의 자각을 잃고, 이러한 악한 상념이 집단적으로 된다면 그것을 정화하기 위해 천변지이가 일어나게 된다고 원문은 서술한다.",
