    "title": "미야자키 연수회의 T·Y 씨",
    "origTitle": "「高橋信次師物語」 真のメシヤの記録 142　八起正法先生編",
    "contentType": "",
    "summary": "같은 1월, 규슈 미야자키 교외의 국민숙사에서 약 300명의 희망자가 참가한 2박 3일 연수회가 열렸다. 원문은 참가자의 80퍼센트가 조화롭지 못한 지옥령과 관계를 맺고 있던 안타까운 사람들이었다고 서술한다. 60세인 T·Y 씨는 남편과 자녀를 데리고...",
    "body": "같은 1월, 규슈 미야자키 교외의 국민숙사에서 약 300명의 희망자가 참가한 2박 3일 연수회가 열렸다. 원문은 참가자의 80퍼센트가 조화롭지 못한 지옥령과 관계를 맺고 있던 안타까운 사람들이었다고 서술한다. 60세인 T·Y 씨는 남편과 자녀를 데리고 고베에서 왔다.\n\n그는 20여 년의 신앙 경력을 지니고 있었으며, 그 밑에는 절복을 받아 입회한 많은 회원이 있었다고 한다.\n\n그러나 그가 이제까지의 신앙을 버리기로 결심한 계기는 육체의 이상이었다. 증오·분노·질투의 생각이 마음속에서 부풀어 오르면 입원해 있을 때에도 어김없이 관절 통증이 심해졌다는 것이다. Y 씨는 남편의 부축을 받아 연수회에 참가했다고 신지 선생에게 인사했다. 원문에 따르면 신지 선생이 영시(録視)해 보니, 잘못된 신앙 때문에 몸은 만신창이가 되어 있었고 등에서 허리와 다리 관절에 걸쳐 지옥령이 붙어 있는 모습이 보였다고 한다. 원문은 신지 선생이 자신을 절대적으로 신뢰하게 하려고 관절에 붙어 있던 동물령을 즉시 떼어 냈다고 서술한다.\n\n“여보, 안 아파요. 걸을 수 있어요. 신기하네.” 남편도 눈을 크게 뜨고 아내에게 일어난 기적을 바라보았다고 한다. 이렇게 하여 Y 씨는 처음으로 신지 선생이 설하는 법에 마음을 기울이게 되었다. 신지 선생이 말했다.\n\n“Y 씨, 당신이 조화롭지 못한 마음을 품으면 또 다른 지옥령이 빙의합니다. 마음가짐을 바로잡는 일이 중요합니다.” Y 씨가 물었다.\n\n“조화롭지 못한 마음이란 어떤 마음입니까?”\n\n“분노·푸념·시기·원한의 마음입니다.”\n\n“우리는 감정을 고스란히 드러내며 살았어요. 이래서는 안 되겠네요. 하지만 푸념은 왜 나쁩니까? 마음속 응어리를 푸는 데는 제일…….”\n\n“푸념은 자기 욕망이 채워지지 않을 때 나오는 것입니다. 그것은 마음속에 때를 만들고 다른 사람의 마음에도 독을 먹입니다…….” 신지 선생은 다음과 같이 설했다고 한다.\n\n“대자연을 보십시오. 대자연은 우리에게 이렇게 살아가라고 가르칩니다. 감사하는 마음은 보은이라는 행위를 통해 올바르게 윤회합니다.”",
    "notes": "",
