    "body": "「영춘(迎春)」 - 다카하시 신지돌아온 새봄, 즐거운 아침 꿈속에빛나고 있는 벗의 모습이정도의 빛으로 가득 차 깨어났도다해가 다시 돌아온 설날 아침의 꿈세월 흘러 마음의 길에서 헤매거든법을 의지하여 정도를 걸어라따스한 햇살처럼 차별하지 말고자신의 자애를 벗에게 베풀어라괴로움의 원인을 끊어 내어 어둠에서빛으로 빛나는 자신의 마음으로쇼와 49년(1974년) 1월 강연 일정",
    "notes": "• 1월 6일: 「마음의 혁명」\n\n• 1월 12일: 「전진을 위한 기초 만들기」, 간사이\n\n• 1월 13일: 「법등을 밝혀라」, 간사이\n\n• 1월 20일: 「노이로제·용기를 가지고 실천·현증」, 도쿄 야오키 빌딩 정례 강연회\n\n• 1월 27일: 「특별 강연회」, 가고시마",
