    "contentType": "",
    "summary": "2월 - 히가시오사카시 간사이 본부 강연강연 제목은 「경전에 대하여」였다. “오늘은 경전이라는 것에 관해 이야기해 보고자 합니다. 우리는 오랜 역사 속에서 경전을…… 운운.” 강연은 이렇게 시작되었다. “경전이라는 것은 지금으로부터 2,500년 전, ...",
    "body": "2월 - 히가시오사카시 간사이 본부 강연강연 제목은 「경전에 대하여」였다.\n\n“오늘은 경전이라는 것에 관해 이야기해 보고자 합니다. 우리는 오랜 역사 속에서 경전을…… 운운.” 강연은 이렇게 시작되었다.\n\n“경전이라는 것은 지금으로부터 2,500년 전, 고타마 싯다르다가 45년 동안 여러 사로몬(비구)과 사마나(비구니), 중생들에게 설한 하나하나의 말이며 신리(神理)입니다. 그것이 나중에 경전이 되어 버렸고, 후대의 승려들이 경전은 외우는 것이라고 말해 버렸기 때문에 지금과 같은 모습이 된 것입니다. 경전을 보면 처음에 반드시 ‘여시아문(如是我聞)’이라고 적혀있습니다. 이는 ‘나는 이와 같이 들었습니다’라는 뜻입니다. 중요한 것은 경전의 내용을 잘 알고 자기 마음과 행위의 지침으로 삼는 일입니다. 그것이 참된 신심이며, 매일 아침저녁으로 경전을 외우는 일은 크게 잘못된 것입니다. 고보대사는 『반야심경비건(般若心経秘鍵)』이라는 경전에서 ‘나는 영취산에서 예전에 붓다에게 법을 들었다. 그 때문에 반야심경을 설할 수 있다’고 말했습니다.” 반야심경에 대하여\n\n“현장 삼장은 어떻게든 그 진실을 알고자 머나먼 인도의 날란다라는 곳까지 17년이나 걸려 경전을 가지러 갔습니다.\n\n그때 대반야경을 가지고 왔습니다. 그 대반야경의 내용을 압축하여 정수만 뽑은 것이 반야심경입니다.\n\n한편 금강지 삼장이라 불리는 사람이 있었는데, 그는 밀교라는 것을 공부하고 사람들에게 길을 설했습니다.\n\n그러나 현장 삼장조차 ‘마하반야바라밀다심경(摩訶般若波羅密多心経)’이라는 음역 한자를 쓰지 않을 수 없었습니다. 그 안에 담긴 위대한 신리(神理)를 중국말로는 간단히 표현할 수 없었기 때문입니다.\n\n‘마하’라는 말은 ‘마하불가사의’라고 할 때에도 쓰지요. ‘마하’는 ‘크다·크게·위대하다’라는 뜻이고, ‘이것은 매우 불가사의하다’라는 말을 ‘마하불가사의’라고 하는 것입니다. 또 마하 브라만은 대브라만이라는 뜻이며, 이때에도 마하를 씁니다.”",
    "notes": "",
