    "title": "기도사를 바르게 보라",
    "origTitle": "「高橋信次師物語」 真のメシヤの記録 146　八起正法先生編",
    "contentType": "",
    "summary": "신지 선생은 다음과 같이 말했다. “영매나 기도사 같은 사람들도 연기가 능숙해졌습니다. 도호쿠 지방에서 자라 도호쿠 사투리밖에 모르는 어머니의 영을 불러내 달라고 했더니, 그 영이 영매를 통해 간사이 사투리로 말합니다. 그런데 듣는 사람은 그것이 연기...",
    "body": "신지 선생은 다음과 같이 말했다.\n\n“영매나 기도사 같은 사람들도 연기가 능숙해졌습니다. 도호쿠 지방에서 자라 도호쿠 사투리밖에 모르는 어머니의 영을 불러내 달라고 했더니, 그 영이 영매를 통해 간사이 사투리로 말합니다. 그런데 듣는 사람은 그것이 연기라는 사실을 알아차리지 못합니다. 이상한 일인데도 듣는 사람은 진지하게 받아들입니다. 사물을 올바르게 보려면 우선 영감자·영능력자라고 불리는 사람들의 생활과 행위를 살펴보아야 합니다. 하나하나 올바르게 말하는지, 올바른 생활과 행위를 하고 있는지 확인하지 않은 채 이렇게 말합니다.\n\n‘그 사람은 영감이 있어요.’ 심한 경우에는 다음과 같은 말까지 합니다.\n\n‘우리 교조님은 오늘 기분이 좋지 않대요.’\n\n‘새전으로 들어온 돈이 적어서 그렇다나 봐요.’ 그런 노파에게 신자가 10만 명이나 있으니 일본인은 어지간히 얼빠졌습니다. 그런 곳에서 또 구원받을 수 있다고 생각하니 이상한 일입니다.”",
    "notes": "",
