    "body": "쇼와 49년(1974년) 2월 강연 일정",
    "notes": "• 2월 2일: 「강연·현증」, 도쿄 야오키 빌딩\n\n• 2월 6일: 「인생이란·마음이란 무엇인가·빙의령·질의응답」, 도쿄 간논지\n\n• 2월 9일: 「유령 세 가지 이야기」, 간사이\n\n• 2월 10일: 「경전 설명」, 간사이\n\n• 2월 11일: 「마음의 원점」, 교토 3월 강연 일정\n\n• 3월 9일: 「질의응답」, 간사이\n\n• 3월 10일: 「마음의 병·노이로제에 대하여」, 간사이\n\n• 3월 23일: 「마음의 원점」, 간사이 4월 6일 - 간다 교리쓰강당 GLA 창립 5주년 기념 강연회강연 제목은 「자력에서 타력으로 가는 길」이었다.\n\n“바로 쇼와 43년(1968년) 7월, 믿을 수 없을 듯한 영적 현상, 본래 나는 영적 현상이라는…… 운운.” 강연은 이렇게 시작되었다.\n\n“밤 10시 무렵부터 우리는 육체에서 빠져나가 저편의 동료들에게 그 길을 설하고 있습니다. 한편으로는 이미 뉴욕에서도 우리 동료가 첫울음을 터뜨리려 하고 있습니다.\n\n그리고 앞으로는 오히려 일본보다 미국에서 내가 설하는 신리(神理)가 퍼져 갈 것입니다. 그러나 어디까지나 내가 직접 설하는 것은 아닙니다. 나는 대변자입니다. 서두르지 않아도 우리는 인간의 보편적인 신리(神理)를 점차 마음의 척도로 삼고, 마음속에 법등을 밝혀 가게 될 것입니다. 그 일을 위해 대만 방면에서도 이미 우리 동료가 첫울음을 터뜨렸습니다. 우리는 서로 일면식도 없습니다.”",
