    "title": "아오시마 연수회의 두 사례",
    "origTitle": "「高橋信次師物語」 真のメシヤの記録 148　八起正法先生編",
    "contentType": "",
    "summary": "쇼와 49년(1974년) 4월 10~12일, 미야자키 아오시마 국민숙사에서 연수회가 열렸다. 어느 교단 회장의 사례국철 파업 때문에 참가자가 줄어들까 걱정했지만 숙소 전체를 빌릴 만큼 만원이 되었다. 고베에는 레이유카이(録友会)에서 갈라져 나온 레이○...",
    "body": "쇼와 49년(1974년) 4월 10~12일, 미야자키 아오시마 국민숙사에서 연수회가 열렸다. 어느 교단 회장의 사례국철 파업 때문에 참가자가 줄어들까 걱정했지만 숙소 전체를 빌릴 만큼 만원이 되었다. 고베에는 레이유카이(録友会)에서 갈라져 나온 레이○카이(録○会)라는 교단이 있었고, 그 교단에서 20명이 참가했다. 원문에 따르면 신지 선생은 그 교단에서 회장 다음가는 사람에게 교단 회장에게 붙어 있던 존재를 들여보냈다고 한다.\n\n“나는 늙은 여우이니라. 여자를 품고 돈을 모으지. 돈이라는 것은 좋은 물건이야.” 원문은 그 사람의 얼굴이 완전히 여우처럼 변하여 무서운 형상이 되었다고 서술한다. 그 교단의 신자 20명은 그 모습을 보고 어안이 벙벙하여 넋을 잃었다고 한다. 연수회 이틀 뒤인 4월 14일 간사이 본부 강연회에는 그 레이○카이 회장도 왔지만, 금전에 대한 집착이 강해 이야기를 듣는 데 그친 듯하다고 원문은 말한다. 후쿠오카 남성의 사례쇼와 48년(1973년) 7월에 정법(正法)에 귀의하고 이 연수회에 참석한 후쿠오카의 I 씨는 다음과 같이 말했다고 한다. 여섯 명가량이 신지 선생의 방을 찾아갔다. I 씨의 차례가 되자 신지 선생은 눈을 반쯤 감고 그의 상념대(想念録)를 보고 있는 듯했다. I 씨는 사고 후유증으로 요통에 시달리고 있었는데, 아무 말도 하지 않았음에도 신지 선생은 다음과 같이 말했다고 한다.\n\n“쇼와 36년(1961년)에 있었군요. ‘일일일생(一日一生)’의 의미를 잘 생각해 보십시오.” 사업을 하던 I 씨는 책상 위에 산더미 같은 일을 남겨 둔 채 연수회에 참석한 듯했다. 신지 선생은 더 나아가 다음과 같이 말했다.\n\n“많은 일을 남겨 두고도 ‘일일일생’입니다. 사고가 난 날에는 초조해하고 있었군요. 팔정도에서 벗어나면 또 나빠질 테니까요.” 신지 선생은 이렇게 말하고 빛을 넣었다. 빛을 다 넣은 뒤에는 다음과 같이 웃으며 말했다고 한다.\n\n“필리핀의 토니라면 40만 엔 아래로는 안 되겠지만요.” 원문·용어 참고",
    "notes": "• 141~145번은 FC2 원문의 29번 묶음, 146~150번은 30번 묶음을 기준으로 번역했으며 하테나 합본의 해당 본문과 대조했다.\n\n• 정리 번호 148번은 FC2 원문 제목에서 147번으로 중복 표기되어 있고, 정리 번호 150번은 FC2 원문 제목에서 148번으로 표기되어 있다. 번역문에서는 전체 배열 순서에 따라 148·150으로 정리하되 원제에는 원문의 숫자를 그대로 남겼다.\n\n• 143번의 「영춘」은 원문의 행 구분과 미완결감을 유지하면서 뜻을 옮겼다.\n\n• 144·145번의 사로몬, 사마나, 파니야, 마하 파니야 파라미타는 원문의 가나 표기를 기준으로 옮겼으며, 통상적인 불교 용어로 임의 교정하지 않았다.\n\n• 141번 웹 원문은 1월 13일 간사이 본부 신년 강연회 다음에 「마음의 본질·우주즉아」를 배치하지만, 143번의 일정에는 1월 13일 강연이 「법등을 밝혀라」로 적혀 있다. 첨부 강연록은 「마음의 본질·우주즉아」를 1974년 1월 12일 강연으로 싣는다. 서로 다른 날짜·제목은 어느 한쪽으로 고치지 않고 각 원문 표기를 그대로 남겼다.\n\n• 첨부 강연록에서는 141번과 144~148번의 발언이 직접 겹치는 것을 확인했다. 웹 원문과 겹치는 범위에서만 인명\n\n·전문용어를 검증했고 강연록에만 있는 문장은 추가하지 않았다.\n\n• 142번의 관절 통증과 빙의, 145~148번의 지옥령·사후세계·질병·자살에 관한 설명, 150번의 동물령·영시·빛에 관한 내용은 신지 선생의 발언, 제삼자의 회고 또는 웹 편집자의 종교적 주장으로 귀속해 옮겼다.",
    "image": "https://raw.githubusercontent.com/concario17-max/shinji/33f81d5266c36192c933d734494bd922df4702d8/images/stories/150.webp",
