    "title": "4·5월 강연 일정과 후쓰카이치 강연",
    "origTitle": "「高橋信次師物語」 真のメシヤの記録 151　八起正法先生編",
    "contentType": "",
    "summary": "쇼와 49년(1974년) 4월 강연 일정",
    "body": "쇼와 49년(1974년) 4월 강연 일정",
    "notes": "• 4월 6일: 「자력에서 타력으로 가는 길」, 간다\n\n• 4월 10일: 「연수회·초보자를 대상으로 한 정법 이야기」, 규슈 제2회\n\n• 4월 11일: 「연수회·규슈 제2회\n\n• 4월 13일: 「마음의 혁명」, 산케이홀\n\n• 4월 14일: 「불교의 변천·현증」, 간사이\n\n• 4월 20일: 「다카하시 신지 선생과 중국 Ś 씨 대담\n\n• 4월 28일: 「조화로 가는 길」, 도쿄 간논지\n\n• 4월 29일: 「마음과 생활·질의응답」, 소아이학원 5월 23일 - 후쿠오카현 후쓰카이치 강연회\n\n“이렇게 규슈에서 하는 강연도 사가현에서는 거의 세 차례에 이르렀고 이곳에서는 처음입니다. 대체로 신앙이라고 하면 비과학적인 무언가를 숭배하게 하려는 것이 아닌가, 또는 경전을 외워 조상을 공양하거나 우상을 모시고 절하는 일이 신앙이 아닌가 하고 아마 많은 사람이 느끼고 있을…… 운운.” 강연은 이렇게 시작되었다. 신지 선생은 더 나아가 다음과 같이 말했다.\n\n“믿든 믿지 않든 인간은 진실한 인간의 마음의 소리를 외면할 수없습니다. 영원한 생명으로서 인간은 누구나 모두 신의 자녀입니다. 인간의 가치는 돈이 많거나 지위가 높다고 해서 결정되는 것이 아닙니다. 인간답게 살아가는 사람들이야말로 참된 신의 자녀입니다. 만족할 줄 모르고 자기만 좋으면 된다는 식으로 살아가는 사람은 머지않아 자기 손으로 자기 목을 조르게 됩니다. 몇 사람을 통해 실험해 봅시다.” 그 뒤 전생윤회의 증명으로 들어갔다. 5월 강연 일정\n\n• 5월 3일: 「예수·모세·석가의 메시지」, 시가고원\n\n• 5월 4일: 「올바른 자기 확립」, 시가고원\n\n• 5월 5일: 「연수회」, 시가고원\n\n• 5월 6일: 「연수회」, 시가고원\n\n• 5월 11일: 「마음의 스모그」, 간사이\n\n• 5월 12일: 「인과의 법칙」, 간사이\n\n• 5월 19일: 「마음의 원점·현증」, 요코하마\n\n• 5월 21일: 「반야바라밀다로 가는 길」, 사가\n\n• 5월 22일: 「인생의 목적과 사명·질의응답」, 간사이\n\n• 5월 23일: 「위대한 깨달음」, 후쿠오카 후쓰카이치\n\n• 5월 26일: 「마음의 발견·질의응답」, 와카야마\n\n• 5월 27일: 「특별 담화·예언서」, 와카야마",
