    "title": "중심산장 연수회와 수행자의 영",
    "origTitle": "「高橋信次師物語」 真のメシヤの記録 152　八起正法先生編",
    "contentType": "",
    "summary": "6월 - 교토 중심산장 연수회 60대 부인이 말했다. “저는 거의 20년 동안 냉증으로 고생하고 있습니다.” 원문은 신지 선생이 그 부인 뒤에 흰옷을 입은 수행자가 서 있는 모습을 알아보았다고 서술한다. 신지 선생이 말했다. “당신은 약 20년 전부터...",
    "body": "6월 - 교토 중심산장 연수회 60대 부인이 말했다.\n\n“저는 거의 20년 동안 냉증으로 고생하고 있습니다.” 원문은 신지 선생이 그 부인 뒤에 흰옷을 입은 수행자가 서 있는 모습을 알아보았다고 서술한다. 신지 선생이 말했다.\n\n“당신은 약 20년 전부터 혹독한 육체 수행을 했군요.” 부인은 다음과 같이 답했다.\n\n“그렇습니다. 폭포 수행도 했기 때문에 냉증이 생겼습니다.” 원문에 따르면 지옥령은 신지 선생의 목소리가 부인에게 들리지 않도록 하고 있었다. 신지 선생은 빙의해 있던 수행자에게 말했다.\n\n“이 여성에게서 떨어져라.”\n\n그러자 수행자는 대들듯이 말했다.\n\n“폭포 수행을 하는 모습을 보고 힘을 빌려 협력한 것이 어째서 나쁘단 말이냐?” 신지 선생은 다음과 같이 말했다.\n\n“너 자신이 지옥에 떨어져 있으니 이 여성을 구할 수는 없다.”\n\n“너는 생전에 가족을 내버리고 가족들을 길거리에 나앉게 했으며, 수행 중 골짜기 아래로 떨어져 죽었지?” 신지 선생의 입에서 엄한 말이 잇달아 나왔다. 원문은 이것이 신지 선생의 수호령이 한 말이었다고 서술한다.\n\n“빛이 너무 강해서 그대를 볼 수가 없구나.” 원문에 따르면 지옥령은 이렇게 말하며 엎드렸다. 신지 선생이 말했다.\n\n“구해 주고 싶다고 말하지만, 사실은 네가 갈 곳이 없어서 붙어 있는 것이지?” 지옥령이 말했다.\n\n“나도 구원받고 싶소. 이 추운 곳에서 구해 주시오. 이렇게 부탁하오.” 신지 선생은 다시 엄하게 말했다.\n\n“너는 일하기 싫어 가족의 생활을 보고도 못 본 척했다. 가족에게 따뜻한 말 한마디 건넨 적도 없지 않으냐?”\n\n“요시코야, 용서해 다오. 아빠는 나쁜 아빠였다.” 원문은 수행자의 마음에 불심이 되살아나 그가 부인의 몸을 통해 엉엉 큰 소리로 울었다고 서술한다. 신지 선생이 물었다.\n\n“지금 육체를 빌리고 있는 이 여성을 여태껏 미치게 만든 죄에 대해서는 어떻게 할 것이냐?”\n\n“용서해 주시오. 신이니 용신이니 말하며 이 여성을 미혹해 왔소. 지금까지의 죄를 용서해 주시오.” 부인이 혼자 두 역할을 연기하는 듯한 모습을 회장 사람들은 의아하게 바라보았다고 한다. 이렇게 수행자는 부인의 몸에서 나갔다. 부인의 얼굴에는 붉은 기운이 돌았고, 그는 다음과 같이 말했다고 한다.\n\n“몸속에 손난로를 넣은 것처럼 따뜻합니다.” 신지 선생이 말했다.\n\n“지옥에 떨어진 수행자였습니다.” 부인은 “어머, 무서워라”라고 말하고 신지 선생에게 머리를 숙인 뒤 단상에서 내려갔다.",
    "notes": "",
