    "contentType": "",
    "summary": "10월 13일 - 오사카 강연회신지 선생은 다음과 같이 말했다. “영도(録道)를 여는 일을 목적으로 팔정도를 하는 것이 아닙니다. 일상생활에서 실천하는 일이 귀중합니다.” 그리고 강사들을 향해 말했다. “여러분은 내가 설하는 내용을 세밀하게 일상생활과...",
    "body": "10월 13일 - 오사카 강연회신지 선생은 다음과 같이 말했다.\n\n“영도(録道)를 여는 일을 목적으로 팔정도를 하는 것이 아닙니다. 일상생활에서 실천하는 일이 귀중합니다.”\n\n그리고 강사들을 향해 말했다.\n\n“여러분은 내가 설하는 내용을 세밀하게 일상생활과 밀착하도록 이야기하십시오.” 같은 10월 - 「자브도바」 신지 선생의 고제 가운데 한 명인 소노가시라 회장은 “어째서 석가모니는 2,500년 뒤 일본에 태어날 것을 예언한 것입니까?”라고 신지 선생에게 질문했다. 그에 대한 답이 다음의 「자브도바」이다.\n\n「자브도바」 - 다카하시 신지어느 분에게 다음과 같은 질문이 왔으므로 이번에는 그 질문에 답하고자 한다. 질문의 요지는 고타마 붓다가 왜 일본을 재생의 땅으로 삼았고, 어째서 미국이나 다른 나라를 선택하지 않았느냐는 것이다. 한마디로 말하면 불교와 정법(正法)이 전해지기 쉬웠기 때문이다. 2,500여 년 전 석가는 자브도바, 곧 동방의 나라에 있는 켄토마티라는 도시에서 다시 정법을 유포하겠다고 제자들에게 선언했다. 어째서 이와 같은 선언을 했느냐 하면, 오늘날 세계 정세가 어떻게 움직이고 인류의 의식이 어떻게 변해 갈지 붓다는 이해하고 있었기 때문이다. 이것이 첫 번째 요점이다. 두 번째 요점은 정법을 재흥할 때의 지리적 조건도 고려되었다는 것이다. 세계의 교류가 시작된 것은 기껏해야 최근 100년가량이다. 그전에는 극히 일부의 요인과 상인을 제외하면 다른 나라와 거의 교류하지 않았으며, 교류할 수도 없었다. 정법이 유포되려면 언어와 지리적 조건이 당연히 고려된다. 세 번째 요점은 정법을 이해하려면 그것을 받아들일 기초적인 토양이 필요하다는 것이다. 전통과 풍습이 다르고 사고방식에 큰 간격이 있다면 정법을 갑자기 들여와도 이를 소화하는 데 상당한 시간이 필요하다.",
