    "contentType": "",
    "summary": "그러나 일본 불교의 역사는 오래되었고, 전교대사가 중국에서 법화경을 들여옴으로써 불교가 정착했다. 그 뒤 오늘에 이르기까지 현상계의 상황이 끊임없이 지켜보아졌고 실재계에서 계획되어 왔다. 그러므로 붓다의 약속은 필연적인 형태를 취하여 현재에 이른 것이...",
    "body": "그러나 일본 불교의 역사는 오래되었고, 전교대사가 중국에서 법화경을 들여옴으로써 불교가 정착했다. 그 뒤 오늘에 이르기까지 현상계의 상황이 끊임없이 지켜보아졌고 실재계에서 계획되어 왔다. 그러므로 붓다의 약속은 필연적인 형태를 취하여 현재에 이른 것이다. 제삼자가 보면 미국이나 유럽이어도 되지 않느냐고 생각하겠지만, 앞의 사정을 참작하면 자연히 이해하게 될 것이다. 정법 유포는 이와 같은 계획 아래 진행되어 왔다고 신지 선생은 말했다. 같은 10월 - 소노가시라 히로치카 회장의 편지원문은 소노가시라 히로치카 회장이 어느 사람에게 보낸 쇼와 49년(1974년) 10월 15일 자 편지를 요약하면 당시 상황을 잘 알 수 있다며 다음 내용을 전한다.\n\n“합장. 19일부터 나가노현 오쿠시가고원에서 열리는 특별 연수에 참석하려고 18일 도쿄로 올라갑니다. 내년 1월 다카하시 선생님이 미국에 가신다는 이야기는 연기될 것이라고 합니다. 다카하시 선생님은 지도자를 서둘러 양성해야 한다고 자주 말씀하시게 되었습니다. 또 강사 가운데에는 ‘수호령에게 물어보겠습니다’ 또는 ‘당신의 수호령이 이렇게 말합니다’라고 하면서, 실제로는 수호령이 보이지 않는데도 마치 보이는 듯 꾸미고 자기 영능력을 과시하듯 지도하는 사람이 있습니다. 이는 사실이 아닙니다.” 원문은 이 편지가 가나가와현 회원이 늘어나면서 그곳의 돌봄 역할을 맡은 ‘어느 사람’에게 개인 지도를 부탁하는 사람도 많아진 일과 관련해 쓰였다고 설명한다. 그 때문에 GLA 본부 사무국장 명의로 다음과 같은 통지가 나왔다.\n\n“영도(録道)를 열지 않은 사람은 개인 지도를 해서는 안 된다.” 이 편지는 그 통지에 관해 쓴 것이었다. 원문은 이를 통해 당시 GLA의 모습을 엿볼 수 있다고 말한다.",
