    "contentType": "",
    "summary": "10월 19일 - 나가노현 오쿠시가고원이때 신지 선생은 다음과 같은 말을 남겼다고 한다. “소크라테스는 마오쩌둥으로 다시 태어났습니다.” 더 나아가 다음과 같이 말했다. “소노가시라 씨, 나는 지금의 GLA를 없애도 상관없다고 생각합니다. 도쿄 본부의...",
    "body": "10월 19일 - 나가노현 오쿠시가고원이때 신지 선생은 다음과 같은 말을 남겼다고 한다.\n\n“소크라테스는 마오쩌둥으로 다시 태어났습니다.” 더 나아가 다음과 같이 말했다.\n\n“소노가시라 씨, 나는 지금의 GLA를 없애도 상관없다고 생각합니다. 도쿄 본부의 강사들은 조금도 공부하지 않습니다.” 이 특별 연수에서 신지 선생은 실재계와 저세상에 관해 다음과 같이 말했다.\n\n“붓다는 주로 인도에서 생활했으므로 붓다가 천상계에 사는 곳은 인도 상공에 있습니다. 또 예수님이 사는 곳은 지금의 이스라엘 상공에 있습니다. 인도 상공에는 석가의 궁전이 있습니다. 소노가시라 씨, 그 궁전의 문지기를 맡았던 사람이 바로 당신이었습니다. 이 사람은 엄격해서 나도 때때로 꾸지람을 들었습니다. 법의 파수꾼, 그것이 당신의 사명입니다.” 원문은 소노가시라 회장이 법의 파수꾼이었다고 서술한다. 법률은 인간이 만든 것이므로 시대와 장소에 따라 바뀔 수 있다. 하지만 여기서 말하는 법은 인간이 바꿀 수 없는 신리(神理)이다. 원문은 소노가시라 회장이 예수 시대의 가브리엘이며 종교개혁 시대의 칼뱅이었다고 전해진다면서, 그렇기 때문에 법을 왜곡하는 사람에게 특히 엄격했을지도 모른다고 풀이한다. 이 특별 연수 도중 신지 선생은 차를 세우게 하고 갓 딴 사과를 사서 제자들에게 나누어 주었다고 한다. 신지 선생은 더 나아가 다음과 같이 말했다.\n\n“소련은 악마가 움직이는 나라이니까요.” 또 다음과 같이 말했다.\n\n“여래나 보살, 빛의 지도령은 자신이 누구인지 스스로 말하지 않습니다. 다른 사람이 자연스럽게 말해 주는 것입니다. 자기 입으로 말하는 사람은 가짜가 많습니다.” 원문·용어 참고",
    "notes": "• 151~155번은 FC2 원문의 31번 묶음, 156~160번은 32번 묶음을 기준으로 번역했으며 하테나 합본의 해당 본문과 대조했다.\n\n• 정리 번호 155번은 FC2 원문 제목에서 154번으로 중복 표기되어 있다. 번역문에서는 전체 배열 순서에 따라 155 로 정리하되 원제에는 원문의 숫자 154를 그대로 남겼다.\n\n• 151번의 4월 11일·4월 20일 강연 제목은 원문에서 닫는 괄호가 없으며, 5월 3~4일과 5월 26~27일 일정은 서로 붙어 있다. 번역문에서는 일정만 개별 항목으로 나누고 불완전한 제목은 보충하지 않았다.\n\n• 153번의 気違い는 현재 모욕적으로 여겨지는 옛 표현이지만, 역사적 강연 제목을 임의로 순화하지 않고 미치광이로 옮겼다.\n\n• 156번의 오국풍요(五国豊饒)와 쓰카이히메(使い姫)는 원문 표기를 그대로 옮겼으며, 통상적인 오곡풍양(五穀 豊縁)이나 다른 이나리 신앙 용어로 교정하지 않았다.\n\n• 158·159번의 자브도바와 켄토마티는 원문의 ジャブドーバー, ケントマティー를 음역했다. 첨부 강연록에서 같은 용어와 이나리 대명신에 관한 유사 설명을 확인했지만, 웹 원문과 겹치지 않는 문장은 추가하지 않았다.\n\n• 152~156번의 수행자·지옥령·백여우·이나리 신앙, 157번의 과거세와 미래 사건 예고, 158~160번의 붓다 재생· 실재계의 계획·소크라테스와 마오쩌둥·가브리엘과 칼뱅·소련에 관한 내용은 신지 선생의 발언, 제삼자의 회고 또는 웹 편집자의 종교적·역사적 주장으로 귀속해 옮겼다.",
