    "title": "도쿄 나카노의 T 씨 부부와 여래·보살에 관한 발언",
    "origTitle": "「高橋信次師物語」 真のメシヤの記録 161　八起正法先生編",
    "contentType": "",
    "summary": "도쿄 나카노의 T 씨 부부 이야기어느 날 T 씨가 신지 선생의 개인 지도를 받았다고 한다. 신지 선생은 다음과 같이 말했다. “당신은 금세 화를 내는군요. 그리고 이상한 것을 모시고 있네요. 당신의 몸을 커다란 뱀이 휘감고 있습니다. 이런 이상한 신앙...",
    "body": "도쿄 나카노의 T 씨 부부 이야기어느 날 T 씨가 신지 선생의 개인 지도를 받았다고 한다. 신지 선생은 다음과 같이 말했다.\n\n“당신은 금세 화를 내는군요. 그리고 이상한 것을 모시고 있네요. 당신의 몸을 커다란 뱀이 휘감고 있습니다. 이런 이상한 신앙을 해서는 안 됩니다.” 그런 일이 있고 몇 년 뒤, T 씨의 아내가 뇌졸중으로 입원했다. T 씨가 밤에 앉아 있을 때 다음과 같은 목소리가 들렸다고 한다.\n\n“2주일.” T 씨는 2주일 뒤에 회복한다는 뜻인지, 아니면 목숨이 그때까지라는 뜻인지 생각했다고 한다.\n\n그는 정법의 삶의 방식을 따르며 정법을 염하는 것밖에는 달리 길이 없다고 생각하고 조용히 반성했다. 그러자 2주일 뒤 아내가 말끔히 나았다고 한다. 같은 10월 - 간사이 본부 대기실 GLA 간사이 본부의 강연이 시작되기 전, 대기실에 들어온 신지 선생은 다음과 같이 말했다.\n\n“소노가시라 씨, 여래는 가르침의 대강을 설합니다. 보살은 여래가 설한 가르침을 일상생활에서 어떻게 살릴 것인지를 설합니다. 그러나 여래가 없어지면 보살도 가르침의 대강을 설해야 합니다.” 또 다음과 같이 말했다.\n\n“여래는 미래의 일도 모두 내다보는 힘을 지니고 있습니다. 일본에 태어날 것을 예언한 까닭은 2,500년이 지났을 때 일본이 세계에 큰 영향력을 지니고 정법을 설하기에 알맞은 나라가 되리라는 것을 알고 있었기 때문입니다.”",
    "notes": "",
