    "title": "미쓰루 산장에서 나눈 천상계와 인도 시대의 회고",
    "origTitle": "「高橋信次師物語」 真のメシヤの記録 162　八起正法先生編",
    "contentType": "",
    "summary": "10월 어느 날 - 이코마 미쓰루 산장이코마의 미쓰루 산장(三鶴山録)에 묵은 신지 선생과 소노가시라 회장이 한가위 보름달 아래 노천탕에 있을 때, 신지 선생은 다음과 같이 말했다. “소노가시라 씨, 호오, 이번에도 인도 때와 마찬가지로 아홉 살 차이입...",
    "body": "10월 어느 날 - 이코마 미쓰루 산장이코마의 미쓰루 산장(三鶴山録)에 묵은 신지 선생과 소노가시라 회장이 한가위 보름달 아래 노천탕에 있을 때, 신지 선생은 다음과 같이 말했다.\n\n“소노가시라 씨, 호오, 이번에도 인도 때와 마찬가지로 아홉 살 차이입니까. 우리가 천상계에서 이번에는 누가 어디에 태어날지를 정한 때가 간에이 2년(1625년)이었지요. 홋카이도로 하려고 했지만 너무 멀었습니다. 그래서 인도의 카필라와 닮은 나가노를 골랐고, 그다음에는 아버지와 어머니를 골랐습니다. 먼저 그 부모가 되어 주실 분들이 앞서 태어나기로 한 것이지요.” 신지 선생은 더 나아가 다음과 같이 말했다.\n\n“도쿠가와 막부 체제 그대로는 정법을 설할 수없습니다. 그래서 도쿠가와 막부를 무너뜨리고 천황제로 되돌리기 위해 기타바타케 지카후사에게 『신황정통기』를 쓰게 하여 근왕 사상을 드높이고, 메이지 유신을 이루게했습니다. 나의 분신은 기도 다카요시로 나타났고, 소노가시라 씨, 당신의 분신은 사이고 다카모리로서 가고시마에 나타났습니다.” 한동안 침묵이 이어진 뒤 신지 선생은 다시 말했다.\n\n“죽림정사의 그곳에 온천이 있었지요. 전도에서 돌아오는 길에 갑자기 비가 내리기 시작했습니다. 붉은 흙먼지가 몽글몽글 일던 곳에 굵은 빗방울이 떨어지면 작게 푹 하고 흙먼지가 솟았고, 발은 먼지투성이가 되었습니다. 우리는 그 온천에서 먼지를 씻어 냈지요. 한 번 인도에 가 보고 싶군요.” 다시 침묵이 이어졌다. 원문은 두 사람이 이처럼 인도에서의 일을 함께 회상했다고 서술한다. 또 죽림정사 남쪽에는 지금도 온천이 있고, 힌두교도와 이슬람교도가 들어가는 탕이 따로 나뉘어 있는 듯하다고 덧붙인다. 이후 강연 일정",
    "notes": "• 10월 12일: 「노이로제」\n\n• 10월 13일: 「건드리지 않는 신에게 재앙 없다·질의응답」, 간사이\n\n• 10월 21일: 「특별 선정」, 도쿄\n\n• 10월 22일: 「시가고원에서의 담화」, 나가노\n\n• 10월 26일: 도쿄 강연회",
