    "contentType": "",
    "summary": "11월 - 오사카 강연 11월 오사카 강연에서 신지 선생은 다음과 같이 말했다. “소노가시라 씨, 오늘 강연은 인도 때와 같은 방식으로 내게 대표 질문을 해 주십시오. 내가 거기에 답하는 형태로 오늘 강연을 진행해 볼까요?” 이에 소노가시라 회장이 물...",
    "body": "11월 - 오사카 강연 11월 오사카 강연에서 신지 선생은 다음과 같이 말했다.\n\n“소노가시라 씨, 오늘 강연은 인도 때와 같은 방식으로 내게 대표 질문을 해 주십시오. 내가 거기에 답하는 형태로 오늘 강연을 진행해 볼까요?” 이에 소노가시라 회장이 물었다.\n\n“『미륵보살하생경』에 따르면 미륵보살이 다시 태어나 세상에 나온다고 전해지는데, 실제로는 어떻게 전해졌던 것입니까?” 신지 선생은 다음과 같이 말했다고 한다.\n\n“석가님은 동방의 나라 일본에 태어나 법을 설하겠다고 예언하고 세상을 떠났습니다. 이를 글로 남길 역할을 지닌 미륵보살은 올바르게 기록했지만, 후세 사람들이 석가님은 다시 태어나지 않을 것이라고 해석하여 그 부분을 삭제했습니다. 그 때문에 미륵보살만 태어난다고 전해지게 된 것입니다.” 11월 16일 - 미야자키 강연회참가자는 600명이었다. 11월 17일 - 후쿠오카시 도코중학교 강연회참가자는 1,000명이었다. 홍보 차량에서 내보낸 방송문의 한 예는 다음과 같았다.\n\n“거리의 여러분, 이곳은 GLA 서일본 본부 홍보반입니다. 계속해서 베스트셀러가 되고 있는 『마음의 원점』, 『연생의 배』(개제 『마음의 발견』), 『원설 반야심경』의 저자 다카하시 신지 선생의 대강연회가 11월 17일 오후 1시부터 도코중학교 체육관에서 열립니다. 사람들이 ‘마음의 원점’을 잃어버린 때부터 인생을 밝고 풍요로운 것으로 만들기 위해, 11월 17일 오후 1시부터 도코중학교에서 열리는 강연회에 꼭 와 주십시오.” 포스터 300장, 입간판 50개, 전단 3만 장, 엽서 500장이 배포되었고 약 1,000명이 모였다. 원문은 강연회의 한 장면을 다음과 같이 전한다. 마히카리문명교단의 ‘손을 갖다 대는 행위(手かざし)’로 눈이 보이지 않게 된 아이의 눈에는 동물령이 빙의해 있었다고 한다. 신지 선생이 빙의한 뱀의 영을 제거하자 아이가 다시 볼 수 있게 되었고, 청중은 조화롭지 못한 신앙을 엄중히 삼가야 한다는 생각을 품고 돌아갔다고 원문은 서술한다.",
    "notes": "",
