    "title": "나카마루 가오루와 오만의 보석 이야기",
    "origTitle": "「高橋信次師物語」 真のメシヤの記録 165　八起正法先生編",
    "contentType": "",
    "summary": "쇼와 49년(1974년) 어느 날 - 나카마루 가오루원문은 나카마루 가오루를 메이지 천황의 숨겨진 자식의 딸이라고 소개하면서, 그가 오사카 강연회에서 신지 선생을 찾아왔다고 서술한다. 나카마루 씨는 개인 외교관으로서 여러 나라의 왕·대통령·수상을 직접...",
    "body": "쇼와 49년(1974년) 어느 날 - 나카마루 가오루원문은 나카마루 가오루를 메이지 천황의 숨겨진 자식의 딸이라고 소개하면서, 그가 오사카 강연회에서 신지 선생을 찾아왔다고 서술한다. 나카마루 씨는 개인 외교관으로서 여러 나라의 왕·대통령·수상을 직접 만날 수 있는 사람이라고 한다. 나카마루 씨가 중동 오만의 사막을 달리던 중 갑자기 하늘에서 다음과 같은 목소리가 들렸다고 한다.\n\n“기도하라.” 차에서 내려 모래 위에 무릎을 꿇었을 때 다시 목소리가 들렸다고 한다.\n\n“몸에 지닌 보석과 귀금속을 모두 벗어라.”\n\n그는 목소리가 시키는 대로 한동안 기도한 뒤 눈을 떴고, 수백만이나 하는 보석과 귀금속이 모두 사라졌다고 한다. 그가 이곳저곳을 찾아보았지만 발견하지 못했다고 원문은 전한다. 일본에 돌아온 뒤 신지 선생을 알게 된 나카마루 씨는 야오키 빌딩을 방문했다고 한다. 그러자 아무것도 알 리 없는 신지 선생이 대뜸 다음과 같이 지적했다고 한다.\n\n“오만에서는 큰일이었군요.” 원문은 그러한 일을 겪은 나카마루 씨가 정법에 귀의했다고 서술한다. 그가 이 강연회의 신지 선생을 찾아오기 직전, 소노가시라 회장은 신지 선생에게 다음과 같이 질문하고 있었다.\n\n“세계가 평화로워지려면 유대의 프리메이슨 문제를 해결해 두어야 한다고 생각합니다만……” 신지 선생은 다음과 같이 말했다.\n\n“지금은 아직 말할 때가 아닙니다.”\n\n그러자 나카마루 씨도 말했다.\n\n“지금은 말하지 않는 편이 좋습니다.” 그날 강연에서 신지 선생은 다음과 같이 말했다고 한다.\n\n“앞으로 공산권에 기근이 일어납니다. 일본을 망치려고 계획한 나라는 그 내부에서부터 붕괴하게 됩니다.”",
    "notes": "",
