    "summary": "원문은 나카마루 씨가 자신의 저서에 이 일을 어떻게 썼는지 살펴보자며 다음 일화를 전한다. 나카마루 씨의 불가사의한 체험나카마루 씨가 신지 선생을 만난 것은 『마음의 원점』을 읽고 감명을 받은 뒤였다고 한다. 신지 선생은 나카마루 씨에게 말했다. “카...",
    "body": "원문은 나카마루 씨가 자신의 저서에 이 일을 어떻게 썼는지 살펴보자며 다음 일화를 전한다. 나카마루 씨의 불가사의한 체험나카마루 씨가 신지 선생을 만난 것은 『마음의 원점』을 읽고 감명을 받은 뒤였다고 한다. 신지 선생은 나카마루 씨에게 말했다.\n\n“카이저수염을 기른 고귀한 노인이 당신 곁에 붙어 있는 모습이 보입니다만.”\n\n“아! 그분은 제 아버지 호리카와 다쓰키치로입니다.” 그런 일이 있은 뒤인 1976년(쇼와 51년) 3월, 나카마루 씨는 아랍에미리트를 방문했다고 한다.\n\n“사이드 국왕을 알현한 날 밤, 기도하고 싶은 마음이 들어 비서와 둘이 차를 타고 해안으로 갔습니다. 바닷가에 앉아 깊이 생각하며 묵상하고 있는데 갑자기 번개가 번쩍였습니다. 정신을 차려 보니 굵은 비에 온몸이 흠뻑 젖어 있었습니다. 황급히 일어나 벗어 두었던 다이아몬드 세 개를 가방에 넣고 기다리던 차로 달려갔습니다. 차가 움직이기 시작하자 거센 뇌우는 거짓말처럼 그쳤습니다. 분명히 넣었을 다이아몬드는 사라져 있었고 다음과 같은 목소리가 울렸습니다.\n\n‘당신에게는 다이아몬드 같은 것은 필요하지 않다…… 마음속에서 빛나고 있다.’”",
    "notes": "",
