    "title": "유리 겔러와 1975년 경영연구회의 출범",
    "origTitle": "「高橋信次師物語」 真のメシヤの記録 167　八起正法先生編",
    "contentType": "",
    "summary": "유리 겔러에 관하여 쇼와 49년(1974년)은 유리 겔러의 숟가락 구부리기에서 시작된 초능력 열풍의 해였다. 신지 선생은 다음과 같이 말했다고 한다. “유리 겔러는 동물령의 지배를 받고 있습니다. 올바르게 보아야 합니다.” 당시 주간지에는 그에 관해 ...",
    "body": "유리 겔러에 관하여\n\n쇼와 49년(1974년)은 유리 겔러의 숟가락 구부리기에서 시작된 초능력 열풍의 해였다. 신지 선생은 다음과 같이 말했다고 한다.\n\n“유리 겔러는 동물령의 지배를 받고 있습니다. 올바르게 보아야 합니다.” 당시 주간지에는 그에 관해 “기분이 수시로 바뀌고 까다로운 사람이라 몹시 곤란했다”는 등의 내용이 실렸다고 한다. 원문은 초능력이 저세상 영들의 협력으로 이루어지며 유리 겔러가 동물령의 협력으로 초능력을 발휘했다고 해석한다. 이어 초능력자라는 사람을 올바르게 보고 초능력을 동경해서는 안 된다고 말한다. 쇼와 49년(1974년) 12월 강연 일정",
    "notes": "• 12월 7일: 「한 해의 반성과 참된 법등」, 간사이\n\n• 12월 8일: 「쇼와 49년을 돌아보며·질의응답」 쇼와 49년(1974년) 날짜 미상의 강연\n\n• 「대자연과 인간의 관계」, 도쿄 야오키 빌딩\n\n• 「신리 입문·브라질의 벗에게」, 도쿄\n\n• 「시가고원 담화·각 선생과 신지 선생의 대화」, 장소 미상\n\n• 「개인 지도」, 장소 미상\n\n• 「불멸의 생명」, 장소 미상쇼와 50년(1975년) - 신지 선생 48세 1월 21일 - 경영연구회 발회식신지 선생은 종교를 어떻게 경제 속에 받아들일 것인지, 앞으로는 정법에 따른 사원 교육도 필요하다는 취지에서 경영연구회를 만들었다고 한다. 원문은 신지 선생이 경영 속의 인간 교육에 정법이 들어가야 한다는 생각 아래 ‘인간도과학연구소 소장’이라는 직함으로 강연했다고 서술한다. 종교라는 말을 떼어 내고 ‘인간도과학연구소 소장 다카하시 신지’라고 내세운 셈이었다.",
    "image": "https://raw.githubusercontent.com/concario17-max/shinji/33f81d5266c36192c933d734494bd922df4702d8/images/stories/167.webp",
