    "title": "정법과 경제, 그리고 참된 경영자의 길",
    "origTitle": "「高橋信次師物語」 真のメシヤの記録 168　八起正法先生編",
    "contentType": "",
    "summary": "원문은 『월간 GLA』에 ‘정법과 경제’에 관한 글이 많이 실려 있다고 말하며 다음 글을 소개한다. 「정법과 경제, 그 목적과 바람직한 모습」 1973년(쇼와 48년) 11월호 “이 글에서는 여러 모습으로 변하며 목적을 잃어 가는 현대 경제에 메스를 ...",
    "body": "원문은 『월간 GLA』에 ‘정법과 경제’에 관한 글이 많이 실려 있다고 말하며 다음 글을 소개한다.\n\n「정법과 경제, 그 목적과 바람직한 모습」 1973년(쇼와 48년) 11월호\n\n“이 글에서는 여러 모습으로 변하며 목적을 잃어 가는 현대 경제에 메스를 대는 한편, 정법에 비추어 본 경제의 바람직한 모습과 경제란 도대체 무엇인지, 인간은 경제에 봉사하는 존재인지 아니면 경제가 인간의 생활을 풍요롭게 하기 위해 존재하는지, 미래 사회의 전망 등에 걸쳐 논의를 전개해 보고자 한다. 먼저 경제의 개념을 생각해 보자. 사전에 따르면 경제란 돈을 벌거나 쓰는 여러 행위 또는 상태를 말한다고 되어 있다. 경제학은 인간의 욕망을 충족하기 위한 수단으로 경제를 바라보고, 여기에 초점을 맞추어 학문으로서의 논리를 전개한다. 현실의 경제 행위는 사전과 경제학의 관점을 뒷받침하기라도 하듯 격렬하고 냉혹하게 움직이고 있다. 정치도 교육도 과학도 노동도 문화도 현실 경제의 움직임 앞에서는 손발을 쓰지 못한 채, 거기에 휘둘리면서도 겨우 명맥을 유지하고 있다고 말할 수 있을 듯하다. 무엇을 하든 돈이고 살아가는 데도 돈이 든다. 말하자면 현실에는 경제의 신세를 지지 않는 것이 하나도 없다…… 운운.” 이 글은 1976년 1월까지 연재되었다고 한다. 또 1975년 1월 21일부터 9월 19일까지 여섯 차례에 걸쳐 설한 「참된 경영자의 길」은 정법에 따른 이상 세계를 건설하기 위해 정업(正業), 곧 바르게 일하는 데서 출발한 경제 혁명과 경영 혁명이 이루어져야 한다는 목적에서 설해졌다고 원문은 설명한다.",
    "notes": "",
