    "num": "170",
    "chapter": 4,
    "chapterMeta": {
      "id": 4,
      "name": "제4장",
      "title": "정법의 전개와 삶에서 드러나는 현증",
      "fullTitle": "제4장 · 정법의 전개와 삶에서 드러나는 현증",
      "range": "151–200",
      "badgeColor": "amber",
      "flow": "정법의 유전 → 사회·종교 비판 → 다양한 체험·현증 → 인생의 의미와 실천"
    },
    "title": "빙의되었다고 서술된 뇌내출혈 환자의 사례",
    "origTitle": "「高橋信次師物語」 真のメシヤの記録 170　八起正法先生編",
    "contentType": "",
    "summary": "한 사람이 다음과 같이 말했다. “저는 가나가와의 K라고 합니다. 제 동생은 많은 사람에게 신의 길을 설하고 있는데, 갑자기 병이 들어 시나가와의 병원에 입원했습니다. 의사는 뇌내출혈이라고 하며 내일이라도 수술해야 한다고 합니다. 어떻게 하면 좋겠습니...",
    "body": "한 사람이 다음과 같이 말했다.\n\n“저는 가나가와의 K라고 합니다. 제 동생은 많은 사람에게 신의 길을 설하고 있는데, 갑자기 병이 들어 시나가와의 병원에 입원했습니다. 의사는 뇌내출혈이라고 하며 내일이라도 수술해야 한다고 합니다. 어떻게 하면 좋겠습니까?” K 씨가 가져온 사진을 신지 선생에게 보여 주자 사진 속에 마왕과 동물령의 모습이 뚜렷이 찍혀 있어 모두가 놀랐다고 원문은 서술한다. 신지 선생은 다음과 같이 답하고 이튿날 병원으로 급히 갔다고 한다.\n\n“수술은 잠시 기다려 주십시오. 내일 병원에 가 보겠습니다.” 병실에는 ‘면회 사절’이라고 적혀 있었지만, 신지 선생이 병실에 들어가 보니 머리에서 허리까지 동물령이 완전히 빙의한 모습이 보였다고 원문은 전한다. K 씨의 동생이 때때로 경련을 일으키자 신지 선생과 동행한 승려 무라카미 씨가 땀을 흘리며 동물령을 제거했다고 한다. 신지 선생이 마음속으로 환자 곁에 있는 마왕에게 신의 자녀로서 살아갈 길을 설하자, 약 30분 뒤 의식을 되찾아 스스로 화장실에 갔다고 한다. 원문은 K 씨의 동생이 날마다 회복되어 수술하지 않고도 나았으며, 의사도 신지 선생 일행의 조치를 이상하게 여겼다고 서술한다. K 씨의 동생은 퇴원한 뒤 신지 선생의 사무실을 찾아왔다. 신지 선생은 다시 다음과 같이 말했다.\n\n“당신은 자신이 신을 섬기는 사람이라고 생각하지만, 자기 자신의 본성을 알지 못한 채 다른 사람을 이끄는 것은 더할 나위 없이 위험합니다.” K 씨의 동생이 말했다.\n\n“저는 집에 모셔 둔 신을 믿고 그 신이 내리는 계시를 가르쳐 왔습니다.” 신지 선생이 물었다.\n\n“그 신이라는 존재를 당신 눈으로 보았습니까? 이야기를 나누었습니까?”\n\n“보지는 못했지만 가슴께에서 목소리가 들려옵니다.”\n\n“초조하고 짜증스러웠던 적은없습니까?”\n\n“네. 내가 나 자신이 아닌 것처럼 자주 초조하고 짜증스러웠습니다.” 신지 선생이 물었다.\n\n“물을 뒤집어쓰면 몸은 분명 깨끗해지지만 마음은 어떻습니까?”\n\n“마음을 깨끗이 하려면 어떻게 해야 합니까?”\n\n“당신이 평소 생각하는 것과 행동하는 것을 올바른 기준에 비추어 생활을 고쳐 나가야 합니다.” 신지 선생이 이렇게 말하자 K 씨의 동생은 고개를 숙이고 들었다고 한다. 원문·용어 참고",
    "notes": "• 161~165번은 FC2 원문의 33번 묶음, 166~170번은 34번 묶음을 기준으로 번역했으며 하테나 합본의 해당 본문과 대조했다.\n\n• 162번의 三鶴山縁은 원문에 독음이 없어 한자 표기를 함께 남겼다. 寛永二年은 서기 1625년에 해당한다.\n\n• 163번 홍보문의 『録生の舟』는 원문이 괄호 안에 改題『心の発見』이라고 덧붙인 구조를 그대로 살렸다.\n\n• 164번의 “GLA 본부에도 강사가 있는데, 왜 규슈의……”와 169번의 “그러니 그렇게 하는 것도 좋습니다만……”은 원문 자체가 완결되지 않았으므로 뒷말을 추정해 보충하지 않았다.\n\n• 165번의 메이지 천황 혈통·유대의 프리메이슨·공산권 기근에 관한 내용은 사실로 단정하지 않고 웹 원문의 소개와 신지 선생 등의 발언으로 귀속해 옮겼다.\n\n• 166번의 국왕 이름은 웹 원문의 サイド国王을 따라 사이드 국왕으로 옮겼으며 다른 이름으로 교정하지 않았다.\n\n• 167번의 유리 겔러와 동물령, 169번의 염과 반작용, 170번의 빙의·뇌내출혈·회복 이야기는 원문의 종교적·의학적 주장과 회고로 구분해 서술했다. 특히 170번은 역사적 원문을 번역한 것이며 현대 의학적 사실이나 치료 지침으로 제시한 내용이 아니다.\n\n• 첨부 강연록에서 1974년 12월 7일 「한 해의 반성과 참된 법등」의 날짜와 제목을 확인했다. 그 밖의 회고·대화에는 강연록의 다른 내용을 덧붙이지 않았다.",
