    "title": "술·상념·돈과 문명에 관한 강연",
    "origTitle": "「高橋信次師物語」 真のメシヤの記録 172　八起正法先生編",
    "contentType": "",
    "summary": "술꾼·주정뱅이·취광신지 선생은 다음과 같이 말했다. “또 술을 마시는 경우가 있습니다. 술을 마시지 않았을 때와 마셨을 때 마음이 극단적으로 돌변하여 인격이 달라지는 사람들이 있지 않습니까. 이런 사람들도 마찬가지로 조화롭지 못한 세계의 주민들에게 빙...",
    "body": "술꾼·주정뱅이·취광신지 선생은 다음과 같이 말했다.\n\n“또 술을 마시는 경우가 있습니다. 술을 마시지 않았을 때와 마셨을 때 마음이 극단적으로 돌변하여 인격이 달라지는 사람들이 있지 않습니까. 이런 사람들도 마찬가지로 조화롭지 못한 세계의 주민들에게 빙의되어 선장이 바뀌어 버린 것입니다.” 마음과 상념은 에너지이다\n\n“우리가 품는 상념은 에너지입니다. 우리 마음에 상대를 원망하는 마음을 품으면 그 원망하는 마음과 에너지와 진동은 상대의 마음에 통합니다. 상대의 마음이 아름다우면 그것은 반작용이 되어 자기에게 돌아옵니다. 눈에 보이지 않기 때문에 우리는 이를 소홀히 여기고 있습니다.” 돈과 물질\n\n“돈이나 물질은 우리가 살아가는 데 필요한 만큼만 있으면 됩니다. 그런데 우리의 욕망은 끝없이 커지고 무한히 바깥으로 향합니다. 노사 간의 투쟁과 상층·하층 계급의 투쟁 속에서 문명이 발전한다고 설하는 사상이 있습니다.” 인류를 위한 문명\n\n“그렇다면 인류가 문명을 위해 존재하는 것입니까? 그렇지 않습니다. 문명이 인류를 위해 존재하는 것입니다. 이런 착각을 일으켜 마음을 언제나 투쟁 속에 두고 잘못된 방향으로 나아가는 사람들도 있습니다. 또 잘못된 종교를 사람들에게 가르쳐 자기 자신의 욕망을 채우려는 사람들도 있습니다.\n\n그러나 머지않아 그들은 자신의 죄를 스스로 갚을 때를 맞게 됩니다.”",
    "notes": "",
