    "title": "미야자키 연수회와 히미코에 관한 발언",
    "origTitle": "「高橋信次師物語」 真のメシヤの記録 173　八起正法先生編",
    "contentType": "",
    "summary": "3월 22~24일 - 미야자키 연수회참가자는 460명이었고 강연 제목은 「정법과 현대 종교」였다. 신지 선생은 다음과 같이 말했다. “올해도 이 아름다운 자연 속에서 연수회를 열 수 있게 되어 진심으로 기쁩니다. 지금부터 「현대 종교와 정법」이라는 제...",
    "body": "3월 22~24일 - 미야자키 연수회참가자는 460명이었고 강연 제목은 「정법과 현대 종교」였다. 신지 선생은 다음과 같이 말했다.\n\n“올해도 이 아름다운 자연 속에서 연수회를 열 수 있게 되어 진심으로 기쁩니다. 지금부터 「현대 종교와 정법」이라는 제목으로 설명해 보고자 합니다. 이 가운데에도 신을 열심히 모시고, 신이라고 불리는 존재가 여러분의 육체를 통해 나타나는 사람이 있을 것입니다. 또 현대의 종교를 열심히 믿으면서 GLA 연수회가 어떤 곳인지 한번 살펴보러 온 사람도 몇 분 있을 것입니다. 그런 분들은 느긋하게 지켜봐 주십시오. 먼저 여러분에게 신이란 무엇인지…… 운운.” 히미코에 관하여\n\n신지 선생은 다음과 같이 말했다고 한다.\n\n“이 사람, 곧 다카하시 게이코 씨는 과거세에 히미코였다는 사실을 기억해 냈습니다. 아마미오시마에서 온 두 부인은 히미코의 시녀였습니다. 도쿄에서 디자이너로 일하는 ○마도 씨와 영화배우 ○마루 다다오 씨의 부인 나카마루 가오루 씨는 모두 히미코의 대신이었던 사람들입니다.” 대일여래는 아마테라스 오미카미신지 선생은 더 나아가 다음과 같이 말했다.\n\n“히미코는 야마타이국에 살던 때 과거세를 기억해 내고, 인도에서 대일여래를 그리워하며 모셨습니다. 그 대일여래가 뒤에 아마테라스 오미카미로 모셔지게 되었습니다.” 3월 26일 - 기타큐슈 고쿠라 강연회기타큐슈시 고쿠라의 마이니치회관 홀에서 강연회가 열렸다. 마이니치신문과 고쿠라상공회의소 기관지에 광고가 실렸다고 한다.",
    "notes": "",
