    "title": "와타나베 야스오와 GLA 창립 6주년 강연회",
    "origTitle": "「高橋信次師物語」 真のメシヤの記録 174　八起正法先生編",
    "contentType": "",
    "summary": "같은 3월 - 와타나베 야스오의 회고쇼와 50년(1975년) 3월, 앞서 나온 와타나베 야스오 씨가 GLA 본부 사무실에 들렀다. 그때 신지 선생의 막냇동생 고와 씨가 물었다고 한다. “와타나베 씨, 언제쯤부터 도와주실 수있습니까?” 와타나베 씨는 놀...",
    "body": "같은 3월 - 와타나베 야스오의 회고쇼와 50년(1975년) 3월, 앞서 나온 와타나베 야스오 씨가 GLA 본부 사무실에 들렀다.\n\n그때 신지 선생의 막냇동생 고와 씨가 물었다고 한다.\n\n“와타나베 씨, 언제쯤부터 도와주실 수있습니까?” 와타나베 씨는 놀라 적당히 대답하고 그 자리에서 돌아갔다. 마침 그 이야기가 나온 3월에 미야자키현 아오시마에서 연수회가 열렸다. 와타나베 씨는 마음을 굳히고 신지 선생의 방을 찾아갔다.\n\n그는 고와 씨에게서 들은 이야기와 자신에게 도울 마음의 준비가 되어 있다는 점 등을 말했다. 신지 선생은 잠시 생각한 뒤 다음과 같이 답했다고 한다.\n\n“지금은 이릅니다. 2년 뒤입니다.〔주: 쇼와 52년(1977년)〕” 당시 신지 선생은 『GLA』 8월호에 실을 「석가전」을 집필하고 있었다고 한다. 이 글은 뒤에 『인간 석가』로 출판되었다. 와타나베 씨가 바쁜 가운데에도 연수회의 짧은 틈을 이용해 글을 쓰는 신지 선생의 모습에 감탄하자, 신지 선생은 웃으며 말했다고 한다.\n\n“와타나베 씨, 45년 치나 쓸 것이 있으니 얼마든지 미리 써 둘 수있습니다.” 쇼와 50년(1975년) 3월 강연 일정",
    "notes": "• 3월 8일: 「마음의 정리·실지 지도·참된 자신이란·반성 선정·반성의 실수(實修)」, 간사이 청년부\n\n• 3월 10일: 「간사이 본부 조직홍보부에 한 이야기」, 간사이\n\n• 3월 15일: 오다와라 강연회\n\n• 3월 22~24일: 「정법과 현대 종교·현증·질의응답」, 아오시마·미야자키 연수회\n\n• 3월 26일: 「기타큐슈 강연회」, 고쿠라 4월 5일 - 히비야공회당 GLA 창립 6주년 기념 강연회강연 제목은 「인간이란」이었다.\n\n“방금 소개받은 다카하시 신지입니다. 오늘의 제목은 「인간이란 무엇인가」입니다. 우리는 자칫하면 육체를 지닌 자기 자신조차도…… 운운. 우리는 드넓은 하늘을 바라봅니다. 밤에는 별이 가득합니다. 우리 눈에 보이는 세계는 은하계 우주입니다. 이 우주 안에서, 더구나 작은 지구라는 우주선 안에서 40억여 명〔현재는 60억 명〕의 만물의 영장인 인간이 빽빽이 모여 살면서, 어떤 사람들은 여전히 투쟁과 파괴를 거듭하고 있습니다. 어떤 사람들은 종파 간의 다툼을 벌입니다. 어리석은 일입니다. 해님은 하나뿐입니다. 우리는 지구라는 신의 몸 가운데 한 부분인 환경 속에서 생활하고 있습니다. 여러분은 이 지구 위에서 선조 대대로 전해져 온 육체라는 배에 올라타고, 오관을 통해 온갖 체험을 하고 있습니다…… 운운.”",
