    "origTitle": "「高橋信次師物語」 真のメシヤの記録 176　八起正法先生編",
    "contentType": "",
    "summary": "4월 무렵 - 교토 중심산장 연수회원문은 쇼와 49년(1974년)에 신지 선생이 고대 인도 시대의 가섭이라고 불리던 사람이 대만에 다시 태어났다는 이야기를 자주 했다고 전한다. 그 사람이 일본에 와서 여러 일이 일어났으므로 참고로 소개하겠다며, 원문은...",
    "body": "4월 무렵 - 교토 중심산장 연수회원문은 쇼와 49년(1974년)에 신지 선생이 고대 인도 시대의 가섭이라고 불리던 사람이 대만에 다시 태어났다는 이야기를 자주 했다고 전한다. 그 사람이 일본에 와서 여러 일이 일어났으므로 참고로 소개하겠다며, 원문은 와타나베 야스오 씨의 회고를 인용한다.\n\n“봄에 대만에서 Ś라는 사람이 왔습니다. 그분은 젊을 때부터 법화경을 공부했고 일본에 오기 전해에 『아귀도』, 나중에 『사랑은 증오를 넘어서』로 제목을 바꾼 책을 읽었습니다. 다카하시 선생님은 이 책을 내기 전부터 ‘이 책을 읽으면 반드시 울기 시작할 것입니다’라고 말씀하셨습니다. 책을 다 읽은 Ś 씨는 곧바로 다카하시 선생님에게 편지를 보냈습니다. 선생님이 기회가 있을 때마다 그 이야기를 하셨기 때문에 잘 기억하고 있습니다. 선생님은 편지를 주고받으면서 의식으로 타이베이까지 가 여러 차례 지도하셨습니다. 그러므로 선생님은 실제로 타이베이에 가지 않고도 Ś 씨를 잘 알고 계셨습니다. 그러는 사이 Ś 씨는 2,500년 전에 선생님에게 가르침을 받고 있던 자신의 모습을 보게 되었습니다. 선생님이 측근에게 ‘지금 그 사람이 자기 자신을 알게 되었습니다’라고 말한 지 일주일 뒤, 당시의 감격을 전하는 Ś 씨의 편지가 왔다고 합니다. 한동안 타이베이에서는 그 이야기로 떠들썩했습니다. 그런 일이 있은 뒤, 아마 주쿄와 간사이의 합동 연수회였던 것으로 기억합니다. Ś 씨는 열흘간의 관광 여행을 마치고 교토 중심산장에서 열린 연수회에 합류했습니다.\n\n그때 저도 Ś 씨를 만났습니다. 그런데 대만에서 독자적으로 활동해 온 만큼 이쪽과는 방식이 상당히 달랐고, 여러 파문이 일어난 듯합니다.”",
    "notes": "",
