    "contentType": "",
    "summary": "와타나베 야스오 씨의 회고는 계속된다. “그런 사정으로 연수회가 시작되기 전날, 다카하시 선생님은 교토의 한 호텔 객실로 Ś 씨와 간부 세 명을 불러 말씀을 내리셨습니다. ‘법을 의지할 곳으로 삼으십시오.’ 그 자리에 함께 있던 세 사람 가운데 한 명...",
    "body": "와타나베 야스오 씨의 회고는 계속된다.\n\n“그런 사정으로 연수회가 시작되기 전날, 다카하시 선생님은 교토의 한 호텔 객실로 Ś 씨와 간부 세 명을 불러 말씀을 내리셨습니다.\n\n‘법을 의지할 곳으로 삼으십시오.’ 그 자리에 함께 있던 세 사람 가운데 한 명인 호소노 선생에게 이 말씀을 이튿날 들었고, 며칠 뒤에는 선생님에게도 직접 들었습니다. 저도 대만에 가 본 적이 있어서 Ś 씨와 금세 가까워졌습니다. 연수회가 끝난 뒤 도쿄로 가는 신칸센에서도 함께 앉았습니다. 주로 저와 Ś 씨 둘만 이야기를 나누게 되었습니다. 대만은 중공과의 관계 때문에 사상 통제가 대단히 엄격한 곳입니다. 마음의 가르침을 일본 본토에서 하듯 그대로 설하면 하나의 사상으로 간주되므로, 철학의 하나, 곧 의식과학으로 설명하느라 애써야 한다고했습니다. 다카하시 선생님이 자주 인용하는 아인슈타인의 E=mc²도 그렇고, 30년 전에 배운 그보다 앞선 로런츠 변환식도 그렇습니다. 식 자체가 아인슈타인의 식보다 복잡하기 때문에 나름대로 억지로 끼워 맞출 수 있다는 이야기였습니다. 며칠 뒤 Ś 씨가 대만으로 돌아간다고 하여 하네다공항까지 배웅하러 갔습니다. 그랬더니 다카하시 선생님과 가즈에 선생님도 와 계셨습니다. 한 번 돌아가려던 다카하시 선생님이 다시 이쪽으로 되돌아오셨습니다. 선생님은 제게 성큼성큼 다가와 말씀하셨습니다.\n\n‘지난번 그 식은 잘못되었으니 조심하십시오.’ 신칸센에서 선생님은 저보다 세 자리쯤 앞에 앉아 계셨지만, 우리가 나눈 대화의 처음부터 끝까지 잘 알고 계셨습니다.\n\n‘네, 알고 있습니다. 그것은 로런츠 변환이지요.’\n\n‘잘 알아차리셨습니다. 그렇습니다. 신칸센 안이었고 사람들 앞에서 지적할 수도 없어서 정말 곤란했습니다. 타친 마라라는 마(魔)가 있는데, 아주 교묘하게 정법을 설합니다. 특히 과학적인 수법을 구사하므로 과학에 강한 사람일수록 표적이 됩니다.’\n\n‘문답을 허용하지 않고 무조건 밀어붙이는 태도였습니다.’\n\n‘그렇습니다. 그것이 특징입니다. 간사이에서도 여러 일이 있었습니다.’ 선생님은 제게 여러 사건을 이야기해 주셨습니다.” 원문은 이어 같은 사정을 다른 관점에서 살펴보자고 말한다.",
    "notes": "",
