    "origTitle": "「高橋信次師物語」 真のメシヤの記録 179　八起正法先生編",
    "contentType": "",
    "summary": "원문은 이 Ś 씨가 인도 석가 시대에는 석가가 세상을 떠난 뒤 석가 교단의 통괄자가 되었다고 전해지는 사람인데도 이처럼 되었다고 말한다. 이어 정법이 나타나면 마가 다투어 일어난다고 하면서 다음과 같이 해석한다. 정법이 널리 퍼져 세계가 광명으로 가득...",
    "body": "원문은 이 Ś 씨가 인도 석가 시대에는 석가가 세상을 떠난 뒤 석가 교단의 통괄자가 되었다고 전해지는 사람인데도 이처럼 되었다고 말한다. 이어 정법이 나타나면 마가 다투어 일어난다고 하면서 다음과 같이 해석한다. 정법이 널리 퍼져 세계가 광명으로 가득 차면 마가 발붙일 곳이 무너지므로, 마도 필사적으로 저항할 것이라는 설명이다. 영능력만 추구하고 마음이 욕망으로 가득 차면 마는 그 사람을 지배하려고 접근한다고 한다. 마가 사람을 지배하려 할 때에는 먼저 정법을 설하고 그럴듯한 말을 한다고 한다. 그런 다음 서서히 자기 쪽으로 끌어들인다. 열 가지 가운데 아홉 가지 옳은 말로 신뢰하게 한 뒤, 남은 한 가지로 사람을 미치게 만든다는 것이다. 쇼와 50년(1975년) 4월 일정",
    "notes": "• 4월 5일: 「GLA 창립 6주년 기념 강연회·인간이란」, 히비야공회당\n\n• 4월 6일: 「강연회」, 간다 교리쓰강당\n\n• 4월 10~12일: 「미야자키·아오시마 연수회」, 아오시마 국민숙사\n\n• 4월 날짜 미상: 「연수회」, 교토 중심산장\n\n• 4월 29일: 「강연회」, 오키나와 나하 5월 - 『다카하시 신지 강연집』 발간 GLA 간사이 본부에서 『다카하시 신지 강연집』이 한정 비매품으로 발간되었다. 쇼와 50년(1975년) 5월 일정\n\n• 5월 5일: 「인생이란 무엇인가」, 나가노 시라카바호\n\n• 5월 10일: 「이 세상과 저세상」, 간사이\n\n• 5월 22일: 「강연회」, 사가\n\n• 5월 23일: 「강연회」, 후쿠오카현 후쓰카이치\n\n• 5월 25일: 「석가의 성도·정법과 현대 종교」, 후쿠오카\n\n• 5월 25일: 「서일본 본부 설립 기념 축하회」",
