    "title": "1975년 6·7월 일정과 가나자와 「마음의 원점」 강연",
    "origTitle": "「高橋信次師物語」 真のメシヤの記録 180　八起正法先生編",
    "contentType": "",
    "summary": "했으며 현대 의학적 설명이나 치료 지침이 아니다.",
    "body": "했으며 현대 의학적 설명이나 치료 지침이 아니다.",
    "notes": "• 173번의 히미코·대일여래·아마테라스 오미카미와 176~179번의 가섭 재생·의식에 의한 지도·마와 과거세에 관한 내용은 신지 선생의 발언, 제삼자의 회고 또는 웹 편집자의 종교적 주장으로 구분해 옮겼다.\n\n• 174번의 40억여 명(현재는 60억 명)은 웹 원문에 들어 있는 당시의 편집자 주석을 그대로 살린 것이다. 현재 세계 인구로 고쳐 쓰지 않았다.\n\n• 177번의 ターチンマラー는 원문의 독자적인 명칭이므로 타친 마라로 음역했다. E=mc2는 뜻을 바꾸지 않는 범위에서 E=mc²로 표기했다.\n\n• 178번 제목은 Ś 씨 이야기 2부이지만 인용문 안에서는 그 인물을 葵さん이라고 적고 있다. 인물 관계를 추정해 고치지 않고 아오이 씨로 옮겼다. 정신병원 입원과 이후 행적도 원문이 전하는 미확인 정보로 귀속해 서술했다.\n\n• 첨부된 『다카하시 신지 강연집』의 머리말에서 1975년 5월 발간 사실을 확인했다. 웹 원문의 한정 비매품 표기는 그대로 유지했다.\n\n• 180번 가나자와 「마음의 원점」 발언은 첨부 강연록의 1975년 7월 6일 본문과 대조했다. 강연록에 이어지는 문장은 웹 원문에 인용되지 않았으므로 추가하지 않았다.",
