    "title": "1976년 1월 - 「자기의 확립」과 때를 기다리는 일",
    "origTitle": "「高橋信次師物語」 真のメシヤの記録 189　八起正法先生編",
    "contentType": "",
    "summary": "번호 주: 정리상 이 글은 190번이지만, FC2 원문 제목에는 앞 글과 마찬가지로 189번이라고 적혀 있다. 원문의 번호 중복을 그대로 남겼다. 『GLA』 신년호쇼와 51년(1976년) 1월, 『GLA』 신년호에는 다음과 같은 글이 실렸다. “하나부...",
    "body": "번호 주: 정리상 이 글은 190번이지만, FC2 원문 제목에는 앞 글과 마찬가지로 189번이라고 적혀 있다. 원문의 번호 중복을 그대로 남겼다.\n\n『GLA』 신년호쇼와 51년(1976년) 1월, 『GLA』 신년호에는 다음과 같은 글이 실렸다.\n\n“하나부터 열까지 모두 성공하는 것만이 정법이라고 생각해서는 안 됩니다. 실패 또한 정법 안에 있습니다.”\n\n「자기의 확립」 - 다카하시 신지\n\n“우리가 사는 세계는 틀림없이 경쟁사회이며 힘의 사회입니다. 그곳에서는 언제나 젊음과 활동이 존중받고, 더 많은 일을 하는 데 늘 목표를 둡니다. 무엇이든 세계 제일이 되는 것을 목표로 삼고 그것을 자랑합니다. 현대는 그러한 일에 지나친 찬사를 보내고 있습니다.\n\n‘마음의 평안이란 무엇인가’라는 질문에서 출발하여 그 물음을 통해 자신을 알게 될 때 비로소 마음의 평안을 얻을 수있습니다. 오직 일만 좇는 인생에는 평안도 조화도 주어지지 않는다는 것을 알아야 합니다.” 이 무렵에는 장차 단체가 크게 발전할 때에 대비하여 컴퓨터 도입 위원회가 만들어졌다. 같은 1월 - 때를 기다리는 일원문은 ‘정법을 실천하는 모든 분에게’라는 말과 함께 신지 선생의 다음 발언을 전한다.\n\n“처음에는 실천하면 좋은 결과가 주어집니다. 그다음에는 본인의 마음을 시험하기 위해 혼란을 일으키는 작은 사건이 생기거나, 여러 욕망이 신기할 만큼 솟아나기도 합니다. 업의 활동은 시간이 지나면 잦아듭니다. 그러므로 올바르게 생활하면서 그때까지 묵묵히 기다릴 수밖에 없습니다.” 원문·용어 참고",
    "notes": "• 181번의 1975년 8월 17일 고베국제회관 강연 제목과 인용문의 첫머리는 별도 강연록의 「인생의 의의·올바른 마음의 자세」와 대조해 같은 강연임을 확인했다. 번역에는 웹 원문에 제시된 범위만 반영했다.\n\n• 綱張縁은 원문의 표기를 유지해 쓰나하리소(綱張縁)로 옮겼다.\n\n• 縁長慢은 불교 용어의 뜻을 살려 증상만(增上慢)으로 표기했다.\n\n• 182~183번의 ‘마음의 창’, 방언, 수호신·수호령, 의식체 관련 내용은 기쿠치 씨의 체험담과 원문의 종교적 설명으로 제시된 것이며, 객관적으로 입증된 사실이라는 뜻으로 보충하지 않았다.\n\n• 189번의 미래 예측, 탕산 대지진 예고, 특정 강사와 회사에 관한 내용은 원문이 전하는 발언·주장·소문 및 웹 편집자의 해석으로 구분해 번역했다.\n\n• 190번 원제의 189는 원문에 존재하는 번호 중복이다.",
    "image": "https://raw.githubusercontent.com/concario17-max/shinji/33f81d5266c36192c933d734494bd922df4702d8/images/stories/190.webp",
