    "contentType": "",
    "summary": "1976년 1월 - 간사이본부 강연 전강연이 시작되기 전, 대기실로 들어온 신지 선생은 털썩 책상다리를 하고 앉아 긴 한숨을 내쉬며 말했다고 한다. “소노가시라 씨, 나는 실패했습니다.” 2월 22일 - 오키나와 강연회신지 선생은 강연을 다음과 같이 ...",
    "body": "1976년 1월 - 간사이본부 강연 전강연이 시작되기 전, 대기실로 들어온 신지 선생은 털썩 책상다리를 하고 앉아 긴 한숨을 내쉬며 말했다고 한다.\n\n“소노가시라 씨, 나는 실패했습니다.” 2월 22일 - 오키나와 강연회신지 선생은 강연을 다음과 같이 시작했다.\n\n“소개받은 다카하시 신지입니다. 오키나와는 섬이어서 좁을 것이라고 생각하고 왔는데, 예상보다 넓어서 놀랐습니다.\n\n그리고 바다가 매우 깨끗하고 하늘은 아름다우며 공기도 맑습니다. 우리가 사는 도쿄에서는 좀처럼 누릴 수 없는 듯한…… 운운.” 원문에 실린 강연의 마지막 부분은 다음과 같다.\n\n“그것을 믿는 것입니다. 거짓말을 할 수 없는 선아(善我)의 마음을 믿는 것입니다. 오랫동안 경청해 주셔서 대단히 감사합니다.” 같은 2월 - 간사이본부장과 서일본본부장에게 한 말원문에 따르면 신지 선생은 두 본부장 앞에서 다음과 같이 말했다.\n\n“육체를 지니면 육체의 제약을 받아 활동이 제한됩니다. 이것은 어쩔 수없습니다. 의식만 남으면 육체에 얽매이지 않으므로 자유자재로 활동할 수있습니다. 나는 어쩌면 빨리 저세상으로 돌아가야 할지도 모릅니다. 내가 해야 할 일이 아주 많습니다. 소련은 원자폭탄을 사용하려 하고 있습니다. 원자폭탄을 사용하면 지구는 끝입니다. 지구가 끝나면 다른 천체에 사는 인간들과의 균형이 무너집니다. 그러므로 절대로 원자폭탄을 사용하게 해서는 안 됩니다. 육체를 지니고 있으면 육체의 제약을 받으니, 소련의 지도자를 천상계에서 직접 지도하는 수밖에 없습니다.” 이어 웹 원문의 편집자는 ‘다른 천체에 사는 인간들과의 균형이 무너진다’는 말은 과연 참된 메시아다운 발언이라고 평한다. 또 원문은 신지 선생이 대우주에는 일곱 영권이 있으며 일곱 인간이 존재한다고 예고했다고 전한다. 그 모습과 형태는 모두 같고, 인간은 인간이며 원숭이는 원숭이이므로 진화론은 잘못되었다고도 말했다고 한다.",
    "notes": "",
