    "summary": "다카하시 고와 씨와 T·도시오 씨는 소노가시라 회장에게 다음과 같이 말했다고 한다. “다카하시 신지 선생은 가짜입니다. 석가의 환생도 무엇도 아닙니다. 이 연수회가 끝나면 우리는 GLA를 그만둘 것입니다. 선생님도 어떠십니까?” 두 사람은 소노가시라 ...",
    "body": "다카하시 고와 씨와 T·도시오 씨는 소노가시라 회장에게 다음과 같이 말했다고 한다.\n\n“다카하시 신지 선생은 가짜입니다. 석가의 환생도 무엇도 아닙니다. 이 연수회가 끝나면 우리는 GLA를 그만둘 것입니다. 선생님도 어떠십니까?” 두 사람은 소노가시라 회장에게 동의해 달라고 요구했다. 소노가시라 회장은 자신의 신념이 있었으므로 ‘그만두고 싶다면 그만두면 된다’고 생각하고 아무 말 없이 방을 나왔다고 한다. 이어 소노가시라 회장의 회고에는 다음과 같은 말이 나온다.\n\n“여성 조수 가운데 반역의 마음을 일으킨 사람은 G·世○子라는 사람이었습니다.” 연수회 셋째 날 아침신지 선생은 소노가시라 회장의 방으로 들어오자마자 다음과 같이 말했다고 한다.\n\n“어젯밤 파피아스 마라가 내 심장에 화살을 쏘았습니다. 아직도 가슴이 아픕니다.” 식사를 마친 뒤 신지 선생과 엇갈려 고와 씨가 방으로 들어왔다. 그는 다시 소노가시라 회장에게 다음과 같이 권했다고 한다.\n\n“다카하시 선생은 마(魔)입니다. 이 연수회가 끝나면 나는 GLA를 그만둘 것입니다. 선생님도 그만두지 않겠습니까?” 소노가시라 회장은 당시 상황을 다음과 같이 회고했다.\n\n“사탄이 나타났다는 사실은 저도 그전에 통지를 받아 알고 있었습니다. 사탄은 먼저 가까운 가족부터 갈라서게 하기 시작한 것입니다. 이것은 큰일이 되겠다고 생각했습니다. 하지만 다카하시 선생님은 이 사실을 모두 알고 계셨습니다. 3월 22일 오전 강화를 취소하고 강사와 조수들에게 집합을 명하셨습니다. 그런데 G·世○子 씨만 반발하며 모이지 않았습니다. 그 사람을 찾아 데려온 뒤 시작된 것이 3월 22일 영상의 장면입니다.”",
    "notes": "",
