    "title": "3월 22일 영상과 GLA 창립 7주년 강연",
    "origTitle": "「高橋信次師物語」 真のメシヤの記録 194　八起正法先生編",
    "contentType": "",
    "summary": "영상 속 한 장면신지 선생은 고제자들의 어깨에 한 사람씩 손을 얹으며 눈물을 흘린 채 다음과 같이 말했다고 한다. “그대는 ○○에서 나를 참으로 잘 도와주었습니다.” 원문은 이를 감사의 말로도, 작별의 말로도 받아들일 수 있는 장면이었다고 평한다. 또...",
    "body": "영상 속 한 장면신지 선생은 고제자들의 어깨에 한 사람씩 손을 얹으며 눈물을 흘린 채 다음과 같이 말했다고 한다.\n\n“그대는 ○○에서 나를 참으로 잘 도와주었습니다.” 원문은 이를 감사의 말로도, 작별의 말로도 받아들일 수 있는 장면이었다고 평한다. 또 이때로부터 석 달 뒤 신지 선생이 세상을 떠날 것이라고 누가 상상할 수 있었겠느냐고 회고한다. 이때 신지 선생은 “지도자는 실천을 통해 부동심을 지니십시오”라고 말했다고 한다. 그 뒤 자기 귀의와 법 귀의의 중요성을 설명하고 주요 강사들을 한 사람씩 타일렀다. 소노가시라 회장은 영상에 나온 대로 신지 선생이 자신에게 다음과 같이 말했다고 전한다.\n\n“소노가시라 씨, 당신은 인도 시대〔사리불·사리자로 살았을 때〕의 지혜를 전부 발휘하지 않고 있습니다. 이제부터는 사양하지 말고 드러내십시오.” 1976년 3월 일정",
    "notes": "• 3월: 간사이본부 정기 강연회\n\n• 3월 19일: 「신지 선생과 이치노미야 교조의 대담」, 도쿄\n\n• 3월 20~22일: 「엘 란티와 미카엘의 깨달음」, 와카야마 난키 시라하마 연수회 4월 11일 - GLA 창립 7주년 기념 강연회\n\n• 장소: 니혼대학 강당\n\n• 강연 제목: 「마음속에 내재한 영지(英智)」 신지 선생은 다음과 같이 말했다.\n\n“차가운 북풍도 멎고 따뜻한 남풍과 함께 검은 흙 위로 아지랑이가 피어오릅니다. 땅속에서는 새싹이 돋아나고 벚꽃은 지금 한창입니다. 버찌는 머지않아 열매를 맺고, 벚나무에는 꽃 대신 잎이 무성해질 것입니다. 우리의 인생도 마찬가지입니다. 청춘은 한때뿐이며 우리의 인생은 무정한 것입니다. 우리가 물질에 빠져 살면서 설령 인생이 70년이라 해도, 길고 긴 전생윤회의 관점에서 보면 한순간 타오르는 선향 불꽃과 같은…… 운운.”",
