    "title": "소노가시라 회장에 대한 평가와 「정법의 유전」 연수회",
    "origTitle": "「高橋信次師物語」 真のメシヤの記録 195　八起正法先生編",
    "contentType": "",
    "summary": "수제자에 대한 칭찬 4월 간사이본부 정기 강연회 때 신지 선생은 나카타니 간사이본부장의 집에 묵었다. 이튿날 아침 식사 도중 신지 선생은 문득 다음과 같이 말했다고 한다. “내가 설한 것을 하나부터 열까지 이해하고 있는 사람은 소노가시라 씨입니다.” ...",
    "body": "수제자에 대한 칭찬 4월 간사이본부 정기 강연회 때 신지 선생은 나카타니 간사이본부장의 집에 묵었다. 이튿날 아침 식사 도중 신지 선생은 문득 다음과 같이 말했다고 한다.\n\n“내가 설한 것을 하나부터 열까지 이해하고 있는 사람은 소노가시라 씨입니다.” 강연이 시작되기 전 나카타니 씨도 소노가시라 회장에게 “당신, 참 대단하구먼”이라고 말했다고 한다. 이어 웹 원문의 편집자는 신지 선생의 마음속에 소노가시라 회장이 자신의 후계자로 깊이 새겨져 있었던 것은 아닐까 하고 추측한다. 5월 2~5일 - 후지 미도리노 휴가촌 청년부 연수회강연 제목은 「정법의 유전(流転)」이었다.\n\n“지난해에 이어 이곳에서 여러분과 함께 신리(神理)를 공부할 수 있게 된 것을 기쁘게 생각합니다. 오늘 강연의 제목은 「정법의 유전」이라고 할까요…… 운운. 이때 길이 열립니다. 지금 이러한 사실을 다시 한번, 내가 아니라 천상계의 사람이 말하도록 하겠습니다.” 신지 선생은 “라위아스포로테이야소보로티아……”라고 말한 뒤 ‘현증(現証)’의 시간으로 들어갔다고 한다. 와타나베 씨가 회고한 연수회의 한 장면둘째 날 모두가 함께 점심을 먹었다. 와타나베 씨는 운 좋게 신지 선생의 바로 맞은편에 앉았고, 오른쪽 옆자리에는 신지 선생의 장녀 게이코 씨가 앉았다. 점심은 카레라이스였다. 와타나베 씨가 한 그릇을 다 먹고 문득 신지 선생 쪽을 바라보니, 그는 아직 3분의 1도 먹지 못한 상태였다고 한다. 와타나베 씨도 식사가 빠른 편이었지만, 그전까지는 신지 선생보다 먼저 수저를 놓은 적이 없을 정도로 신지 선생의 식사 속도가 빨랐다고 한다. 와타나베 씨는 ‘몹시 피곤하신 모양이구나’라고 생각했다. 마지막 날 전날 밤, 자정이 되자 신지 선생은 갑자기 참가한 강사와 도우미 전원에게 모이라고 명했다.\n\n“지금 이런 통신이 들어왔습니다.” 신지 선생이 그렇게 말하며 읽어 준 것은 ‘사탄에게서 온 통신’이었다고 한다. 그 뒤 신지 선생은 앞으로 정법을 널리 펴는 길이 험난하리라는 점을 설명하고, 마지막으로 다음과 같이 당부하며 말을 맺었다.\n\n“이제부터는 조급한 마음과 두려운 마음, 특히 이 두 가지를 조심하십시오.”",
