    "contentType": "",
    "summary": "사탄에게서 온 편지원문에는 신지 선생이 읽었다는 편지의 일부가 다음과 같이 실려 있다. “황금빛 날개를 지닌 천사여. 나는 실재하는 마계의 제왕이니라. 나는 너희의 정법에 가로막히지 않으며, 내가 생각하는 곳에 내가 있고, 나의 앞길을…… 운운. 모든...",
    "body": "사탄에게서 온 편지원문에는 신지 선생이 읽었다는 편지의 일부가 다음과 같이 실려 있다.\n\n“황금빛 날개를 지닌 천사여. 나는 실재하는 마계의 제왕이니라. 나는 너희의 정법에 가로막히지 않으며, 내가 생각하는 곳에 내가 있고, 나의 앞길을…… 운운. 모든 자는 나의 명령에 복종하리라. 나는 신성한 마왕이며 암국의 제왕, 위대한 사탄이니라…… 운운. 우리의 올바름이 언젠가 실증될 때, 너희의 놀란 얼굴이 떠오르…… 그때는 반드시 오리라.” 마지막 문장은 원문 자체가 불완전한 형태로 끊겨 있다. 5월 8일 - 간논지 주지 무라카미 씨의 방문간논지(観音寺)의 주지 무라카미 씨는 신지 선생에게 직접 전화를 건 뒤 야오키빌딩을 찾아갔다. 5층에 있는 신지 선생의 방을 열었을 때, 그는 소파에서 곧바로 일어설 수 없을 정도로 몸 상태가 좋지 않았으며 안색도 나빴다고 한다. 건강한 몸으로 동분서주하던 옛 모습은 찾아볼 수 없었다고 원문은 전한다. 신지 선생은 약한 목소리로 말했다.\n\n“내 몸에 빛을 넣어 주시지 않겠습니까?” 무라카미 씨는 빛을 넣기 쉽도록 신지 선생의 몸을 안아 일으킨 뒤 예수의 내림을 기원했다. 약 세 시간이 지났을 무렵 신지 선생의 얼굴에 붉은 기가 돌았고, 그는 스스로 몸을 일으켜 서서 무라카미 씨에게 받아 적을 준비를 하라고 지시했다고 한다.\n\n그때 신지 선생의 목소리는 부드러우면서도 힘이 있었고, 조용히 명상한 그의 입에서 나오는 말은 느린 어조 속에 억양이 실려 있었다고 한다.",
    "notes": "",
