    "contentType": "",
    "summary": "앞 항목에서 이어지는 「신부활」 강연이다. “그러나 여러분의 마음속에는 누구나 위대한 지혜가 존재합니다. 태어나서 지금에 이르는 동안 생각하고 행동하는 올바른 기준을 잃었기 때문에 마음이 스모그에 덮였고, 스스로 신의 빛을 가려 그 지혜를 알지 못할 ...",
    "body": "앞 항목에서 이어지는 「신부활」 강연이다.\n\n“그러나 여러분의 마음속에는 누구나 위대한 지혜가 존재합니다. 태어나서 지금에 이르는 동안 생각하고 행동하는 올바른 기준을 잃었기 때문에 마음이 스모그에 덮였고, 스스로 신의 빛을 가려 그 지혜를 알지 못할 뿐입니다. 그러므로 우리가 물리학에서 말하는 시간과 공간은 불확정적입니다. 또 마음의 차원에서는 과거·현재·미래라는 시간이 현재의 한 점에 모여 있습니다. 여러분의 마음속에는 그처럼 분명하고 위대한 지혜가 존재합니다. 그것을 조사해 가면, 3억 수천만 년 전 인류가 이 지상계에 나와 제2제대가 이주했을 때 에덴동산의 일부 사람들이 물질욕에 이끌려 길을 잘못 들었다는 사실에 이릅니다. 엘 란티를 비롯한 일곱 대천사는 이 지상계를 떠났습니다. 그들은 많은 유산을 지상계에 남기고, 후대 사람들이 그 위대한 유산을 어떻게 활용하는지 천상의 세계에서 따뜻하게 지켜보았습니다. 하지만 물질과 육체와 정욕에 빠져 에덴동산을 떠난 일부 사람을 구하기 위해, 천상의 세계에서 루시펠이라는 천사를 보냈습니다.\n\n그러나 천사라 해도 불안정한 지상의 육체를 지니면 손발을 잃은 것과 같은 상태가 됩니다. 태어난 환경·교육·사상·습관 속에서 자신의 본성을 잊고, 마침내 루시펠은 사탄이라는 이름으로 불리게 되었습니다.\n\n그는 그 환경에서 사는 동안 자신의 지위와 명예에 사로잡혔고, 마침내 천상의 세계와 교신을 끊었습니다. 지상계를 떠날 때에도 천상의 세계로 돌아가지 않고 지옥의 세계로 가 버렸습니다. 그 사탄은 지금 지옥의 제왕이 되어 있습니다. 이것이 최초 지옥계의 실상입니다. 이렇게 많은 천사는 천상의 세계에서 지상계의 움직임을 지켜보며 사람들을 신의 자녀로 되돌리기 위해 많은 빛의 천사를 지상계로 보냈습니다. 엘 란티 자신은 자신의 빛의 분령인 아가샤라는 분을 보냅니다. 또 칸타레라는 분을 보냅니다. 그가 뒤의 고다마 붓다입니다. 천상계에서는 칸타레라고 부릅니다. 석가님이라고 부르지 않습니다. 고다마 붓다입니다. 아가샤는 뒤의 임마누엘 예수 그리스도이며, 모세는 모세입니다.”",
    "notes": "",
