    "title": "유대교·종교개혁과 아미타교의 유래에 관한 설명",
    "origTitle": "「高橋信次師物語」 真のメシヤの記録 204　八起正法先生編",
    "contentType": "",
    "summary": "“잘못된 유대교를 바로잡고 인간의 사랑을 설하게 하려고 예수를 이 지상계로 보낸 것입니다. 야베는 ‘엿새 동안 일하고 하루를 성일로 삼아 한 주 동안의 잘못된 과거를 돌아보고, 마음을 바로잡아 두 번 다시 같은 잘못을 저지르지 말라’는 성일을 마련했습...",
    "body": "“잘못된 유대교를 바로잡고 인간의 사랑을 설하게 하려고 예수를 이 지상계로 보낸 것입니다. 야베는 ‘엿새 동안 일하고 하루를 성일로 삼아 한 주 동안의 잘못된 과거를 돌아보고, 마음을 바로잡아 두 번 다시 같은 잘못을 저지르지 말라’는 성일을 마련했습니다. 그런데 뒤의 사제들은 ‘일곱째 날에는 일해서는 안 된다. 사람을 만나서도 안 되고 동물에게 먹이를 주어서도 안 된다’는 식으로 바꾸어 버렸습니다. 이렇게 유대교는 크게 일그러졌습니다. 그것을 바로잡기 위해 보낸 이가 임마누엘 예수 그리스도입니다. 하지만 그도 이윽고 사탄의 먹이가 되어 십자가에 못 박혔습니다. 또 가르침이 바뀌어 버렸으므로 미카엘의 분신인 천사, 영혼의 형제를 지상계로 보냈습니다. 그가 마르틴 루터입니다.\n\n그리고 프랑스에서는 가브리엘인 칼뱅을 보내 종교개혁에 나서게했습니다.\n\n한편 불교에서는 고다마 붓다가 깨달음을 열고 길을 설해 가는 과정에서, 미카엘이 과거세인 3,500년 전 그리스에서 설했던 아폴로의 가르침을 이어받았습니다. 그 아폴로의 가르침은 이윽고 동쪽 나라 인도로 전해질 것이었습니다. 인도로 전해지는 그 신리(神理)를 메시아인 고다마 붓다가 태어나 깨닫고 길을 설하게 됩니다. 이렇게 동쪽에는 칸타레를 보냈습니다. 이것이 뒤의 불교입니다. 그런데 어느새 불교도 화석처럼 굳어, 경전을 외우기만 하면 구원받는다는 식이 되었습니다. ‘나무아미타불’, ‘나무묘법연화경’을 외워 구원받은 사람은 한 명도 없습니다.\n\n‘나무아미타불’의 유래도 이러합니다. 고다마 붓다가 라자그리하라는 도시 외곽의 벨베나〔죽림정사〕에 있을 때 빈비사라라는 왕이 있었습니다. 그의 아내가 유폐됩니다. 그 여성은 코살라라고 불리는 이다케다였습니다. 아자스타라는 아들에게 갇혔습니다. 부모는 자기 자녀가 어떻게든 불교를 알게 되기를 바랐지만, 고다마 붓다의 사촌이자 같은 왕자 신분으로 출가한 사람이 있었습니다. 아자스타는 그 사람의 꾐에 넘어가 아버지와 어머니를 감금했고, 아버지는 죽고 말았습니다. 어머니는 마지막 소원으로 ‘부처님에게서 무엇이든 한 가지 말씀을 듣고 싶습니다. 아무것도 필요하지 않으니 부처님에게 참된 이야기를 듣고 싶습니다. 어머니의 평생소원이니 들어주십시오’라고 말했습니다. 감옥에 갇혀 있었지만 어머니의 그 소원만은 받아들여져 부처님의 말씀을 듣게 되었습니다. 그것이 아미타교입니다.”",
    "notes": "",
