    "title": "형식화된 독송 비판과 마음속의 신",
    "origTitle": "「高橋信次師物語」 真のメシヤの記録 206　八起正法先生編",
    "contentType": "",
    "summary": "“그 뜻을 알지 못한 채 ‘법화경에 귀의합니다, 법화경에 귀의합니다……’, ‘나무묘법연화경, 나무묘법연화경……’ 하고 외웁니다. 요즘은 더 빠르게 외우면 좋다고 생각하여 ‘나묘호렌게쿄, 나묘호렌게쿄……’라고 합니다. 터무니없는 이야기입니다. 미친 짓입...",
    "body": "“그 뜻을 알지 못한 채 ‘법화경에 귀의합니다, 법화경에 귀의합니다……’, ‘나무묘법연화경, 나무묘법연화경……’ 하고 외웁니다. 요즘은 더 빠르게 외우면 좋다고 생각하여 ‘나묘호렌게쿄, 나묘호렌게쿄……’라고 합니다. 터무니없는 이야기입니다. 미친 짓입니다. 더구나 ‘그대는 우상을 모시고 기도하지 말라’고했습니다. 사람이 인쇄한 것을 아무리 숭배해도 구원받을 길은 없습니다. 우리는 오래된 악습을 깨뜨려야 합니다. 신이 필요했다면 여러분이 지상계에 태어날 때 지니고 오게 했을 것입니다. 모두 만다라를 매달고 태어나게 했을 것입니다. 남성들이 달고 태어난 것은 그것과 다르지 않습니까? 이렇게 불교조차 알 수 없는 것으로 변해 버렸습니다. 태양계 영단은 빛의 직계로서 엘 란티를 중심으로 합니다. 엘 란티는 시대에 따라 어느 때에는 야베, 어느 때에는 여호와, 어느 때에는 범천, 또 마호메트 시대에는 알라라는 이름을 사용했습니다. 인류는 모두 형제이며 같은 하나의 태양 아래에서 살아갑니다. 종교는 하나입니다. 갠지스강의 흐름도 요르단강의 흐름도 지금껏 방향을 바꾸지 않았습니다. 시대가 옛날이냐 지금이냐에 따라 길이 달라지는 것은 아닙니다. 지금 우리는 모세·예수·마호메트·고다마가 설한 것을 하나로 합치기 위해 육체를 지니고 있습니다. 여러분은 그 선택받은 사람들입니다. 자신의 마음을 열면 여러 나라에서 거듭 태어난 체험과 그 신리가 모두 마음속에 기록되어 있음을 알게 됩니다. 그것을 되살릴 때 지금 내가 하는 말을 이해할 수있습니다. 신은 자신의 마음속에 있습니다. 자신이 결코 속일 수 없는 선아(善我)의 마음이야말로 ‘신’입니다. 신은 사람이 형상으로 만든 것 안에 있지 않습니다. 여러분의 마음속에 있습니다. 그곳은 차원이 다른 세계입니다. 여러분은 그곳에서 와서 지금 육체를 지니고 살아갑니다. 육체를 지니면 눈과 귀와 입, 마음속에 떠오르는 여러 상념으로 인해 참된 것을 보지 못하게 됩니다. 여러분은 참된 자신의 모습을 볼 수없습니다. 거울을 통해 볼 수 있는 것은 육체의 모습뿐입니다. 그러나 누구에게나 참된 자기가 있습니다. 나는 참된 자기를 보라고 가르칩니다. 그것은 마음이고 영혼이며, 여러분이 생각하는 작용의 근원입니다. 그것은 변하지 않습니다. 지금 자신의 것이라고 여기는 육체도 사실은 착각에 지나지 않습니다.”",
    "notes": "",
