    "contentType": "",
    "summary": "“육체는 언젠가 썩어 없어져 지구의 먼지로 바뀝니다. 그러나 육체를 지배하는 여러분의 영혼은 영원합니다. 우리가 살아가는 데 최소한 필요한 형태로 오관을 받았을 뿐입니다. 하지만 참된 오관은 여러분의 마음속에 있습니다. 마음의 눈과 마음의 귀입니다. ...",
    "body": "“육체는 언젠가 썩어 없어져 지구의 먼지로 바뀝니다. 그러나 육체를 지배하는 여러분의 영혼은 영원합니다. 우리가 살아가는 데 최소한 필요한 형태로 오관을 받았을 뿐입니다. 하지만 참된 오관은 여러분의 마음속에 있습니다. 마음의 눈과 마음의 귀입니다. 마음의 모든 기능을 여러분은 이미 지니고 있습니다. 그것을 스스로 계발할 때 참으로 영원한 자기 자신을 알 수있습니다. 우리는 이 지상계가 전부라고 생각해서는 안 됩니다. 50년이나 100년의 인생은 환상과 같고 선향불꽃처럼 한순간에 지나지 않습니다. 우리 눈앞에 나타나는 물질과 여러 현상 또한 환상입니다. 그것들은 영원하지 않고 썩어 사라지며 형태를 바꿉니다. 그러나 여러분의 마음속에 체험으로 쌓인 위대한 지혜는 변하지 않습니다. 지상계를 떠날 때 여러분은 아무것도 가지고 돌아갈 수없습니다. 태어날 때 무엇인가를 가지고 온 사람도 없습니다. 우리는 이처럼 오관에 현혹되고 물질적인 광경 속에서 물질에 빠져 스스로 고뇌를 만들어 냅니다. 그 눈먼 상태에서 인간의 가치가 무엇인지 알아가는 것입니다. 더듬어 나아가며 스스로 마음의 평안을 얻고, 올바르고 보편적인 신리를 자기 마음과 행위의 척도로 삼아 생활할 때 참된 자기를 알 수있습니다. 이것이 깨달음입니다. 깨달음은 자기 자신의 마음을 아는 것입니다. 자신의 마음을 알 때 비로소 인생의 목적과 사명을 알 수있습니다. 그것은 타력이 아니라 자력입니다. 신은 모든 것을 여러분을 위해 준비하여 주었습니다. 태양을 비롯해 생활에 필요한 모든 동물·식물·광물을 여러분에게 주었습니다. 여러분이 그것을 취하지 않을 뿐이고, 취하는 방법을 모를 뿐입니다. 무엇을 더 바라겠습니까? 물질과 경제는 무상한 것입니다.”",
    "notes": "",
