    "title": "그릇된 종교와 ‘최종 유토피아’에 관한 발언",
    "origTitle": "「高橋信次師物語」 真のメシヤの記録 210　八起正法先生編",
    "contentType": "",
    "summary": "번호 주: 정리상 이 글은 209번이지만 FC2 원문 제목에는 210이라고 적혀 있다. 다음 210번과 원제 번호가 겹치며, 원문의 번호 오기를 그대로 남겼다. “그릇된 종교인들은 나에 의해 무너질 것입니다. 어떤 종교인이든 그릇된 종교인은 우리의 영...",
    "body": "번호 주: 정리상 이 글은 209번이지만 FC2 원문 제목에는 210이라고 적혀 있다. 다음 210번과 원제 번호가 겹치며, 원문의 번호 오기를 그대로 남겼다.\n\n“그릇된 종교인들은 나에 의해 무너질 것입니다. 어떤 종교인이든 그릇된 종교인은 우리의 영적인 힘에 의해 그 실상이 현상으로 드러납니다. 믿든 믿지 않든 이것은 사실입니다. 여러분은 지켜보십시오. 지진도 벼락도 자유자재로 일으킬 수있습니다. 그러므로 우리는 지금 그것을 받아들일 태세를 갖추어야 합니다. 일본만의 일이 아닙니다. 나는 이윽고 중근동으로 갑니다. 그러면 그들도 참된 길을 알게 될 것입니다. 우리가 지금 육체를 지닌 것은 지구의 최종 유토피아를 이루기 위해서입니다. 그러므로 이번의 빛의 천사들은 모두 자신의 생활 터전에서 사업을 하며 나왔습니다. 종교로 밥을 먹지 않습니다. 그것이 참된 모습입니다. 신은 인간에게서 단 한 푼의 돈도 필요로 하지 않습니다. 태양은 무료입니다. 그것이 신의 마음이며 신리입니다. 나는 실업가로서 그 방면에서도 세계에서 모르는 사람이 없게 될 것입니다. 당연한 일입니다. 그것이 길입니다. 예수나 고다마의 시대에는 그런 방식으로도 괜찮았습니다. 하지만 현대에는 그래서는 안 됩니다. 교조와 그 주변 사람들이 호화롭게 생활하기 위해 종교가 존재하는 것이 아닙니다. 참된 종교는 우주의 참된 인간으로 살아가는 길을 가르치며, 인간에게 살아가는 기쁨을 주는 길입니다. 이것이 신리입니다. 신은 인간이 만든 물건을 원하지 않습니다. 중요한 것은 한 사람의 아름다운 마음입니다. 길은 이윽고 열리고 우리의 앞날은 빛으로 가득 찰 것입니다. 그리고 그 사람들은 구원받습니다. 지상계 사람들의 마음이 한 사람씩 조화를 이루게 되면 육체의 선조들은 그 모습을 보고 ‘우리 시대와는 다르다. 우리는 왜 이 가혹한 환경에 있는가?’ 하고 생각할 것입니다. 어려운 경전이 아니라, 여러분이 일상생활에서 품는 하나하나의 상념과 행위가 내는 빛이 이윽고 지옥의 세계를 구합니다. 최종 유토피아는 지옥이 사라지는 때입니다. 내가 지금 「신부활」이라는 책을 온 힘을 다해 쓰고 있고 모세의 십계명을 비롯한 그릇된 종교를 바로잡고 있기 때문에, 사탄은 필사적으로 나를 공격합니다.\n\n그러나 루시펠 사탄이라 해도 나의 옛 제자입니다.\n\n그는 이윽고 내 군문에 굴복할 것입니다. 알지 못하기 때문에 지옥에 떨어져 있는 것입니다. 그들도 구원받을 것입니다. 나는 목숨을 걸고 있습니다. 여러분 한 사람 한 사람이 자각할 때, 여러분 주변에서 육체를 지녔던 선조들도 구원받습니다. 승려가 외우는 어려운 경전으로 구원받는 것이 아닙니다.”",
    "notes": "",
