    "title": "살아 있는 동안 자신을 만드는 길",
    "origTitle": "「高橋信次師物語」 真のメシヤの記録 210　八起正法先生編",
    "contentType": "",
    "summary": "“경전의 뜻을 이해하고 그대로 생활하는 사람이라면 천상계로 갑니다. 고다마 붓다는 죽은 사람을 성불시키기 위해 승려를 만든 것이 결코 아닙니다. 살아 있는 사람을 어떻게 이끌 것인가, 인간의 마음을 어떻게 지도할 것인가를 위해 이 지상계에 나온 것입니...",
    "body": "“경전의 뜻을 이해하고 그대로 생활하는 사람이라면 천상계로 갑니다. 고다마 붓다는 죽은 사람을 성불시키기 위해 승려를 만든 것이 결코 아닙니다. 살아 있는 사람을 어떻게 이끌 것인가, 인간의 마음을 어떻게 지도할 것인가를 위해 이 지상계에 나온 것입니다. 지옥에 떨어지는 것은 다른 사람의 탓이 아닙니다. 자신의 잘못된 사념과 행위가 행동으로 나타난 결과, 스스로 지옥에 떨어지는 것입니다. 천상의 세계가 피라미드처럼 위로 높이 존재한다면, 지옥의 세계는 거꾸로 선 피라미드처럼 존재합니다. 지구는 그 중간 환경에 있습니다. 그러므로 여러분이 선을 생각하고 선한 행동을 하면 천상의 세계로 가고, 악한 행동을 하면 지옥의 세계로 갑니다. 그들은 언제나 기다리고 있습니다. 그만큼 올바른 마음과 올바른 법의 길을 자신의 것으로 삼아 생활하지 않으면 인간은 구원받지 못합니다.\n\n그러나 누구나 마음속에 신의 자녀로서 참된 사랑의 마음을 지니고 있습니다. 여러분 모두가 천상의 세계에서 약속을 하고 이 지상계에 나왔기 때문입니다. 돌아갈 때를 생각하며 이것도 하고 저것도 하겠다고 미룰 것이 아니라, 지금의 1초 1초와 하루를 일생처럼 사는 자기 완성이 여러분을 더욱 크고 풍요롭게 합니다. 지금 혹독한 경제 환경에 놓여 있어도 비관할 필요는 없습니다. 그 혹독한 환경에서 여러분은 자기 영혼을 배우기 위해 지금 그 체험을 하고 있습니다. 경제적으로 넉넉하더라도 그 환경에 안주해서는 안 됩니다. 혜택을 받았다면 그것을 소중히 여기고, 어려운 사람들에게 아무런 대가를 바라지 않는 참된 사랑의 행동을 해야 합니다. 이것이 길입니다. 여러분은 모두 형제입니다. 태어난 환경이 다르더라도 모두 신의 자녀이며 태양 아래의 형제입니다. 남이 아닙니다. 옷깃만 스쳐도 전생의 인연이라고 합니다. 참으로 그 말과 같습니다. 여러분이 눈을 뜨고 자신을 자각할 때 신의 자녀로서의 길을 스스로 실천하게 됩니다. 지금 내가 말하는 이 모든 말은 여러분의 마음속에 전부 기록됩니다. 지상계를 떠났을 때 이것이 진실인지 아닌지를 스스로 알게 됩니다.\n\n그때 구원받습니다. 살아 있는 동안 자기 자신을 만드는 것입니다. 길은 영원히 계속됩니다. 이번 세상으로 끝나는 것이 아닙니다. 이윽고 우리는 저세상으로 돌아갑니다.\n\n그리고 언젠가 다시 지상계나 다른 천체에 태어납니다. 여러분은 자기 자신에게 눈뜨십시오! 자신의 마음을 여십시오! 작은 자기를 버리십시오! 위대한 신의 빛에 눈뜨십시오! 그것은 사랑입니다. 그 밖에는 없습니다. 이 연수회를 통해 마음을 벌거벗기고, 신의 자녀인 자기 본성에 눈뜨십시오. 오랜 시간 진심으로 감사드립니다.”",
    "notes": "원문·자료 대조 참고\n\n• 201~210번은 강연 PDF의 1976년 6월 4일 「신부활」과 문장 순서까지 직접 겹치는 연속 구간이다. 번역에는 웹 원문에 포함된 범위만 반영했다.\n\n• 202번에 덧붙은 십계명 목록에는 ‘간음하지 말라’에 해당하는 일본어 표현이 중복되어 있다. 의미를 옮기되 원문의 중복 사실을 별도로 밝혔다.\n\n• 204~206번의 유대교·불교·염불·법화경 관련 역사 설명과 가치 판단은 강연자의 독자적인 종교적 주장이다. 원문에 포함된 비하 표현도 발언의 성격을 흐리지 않는 범위에서 옮겼다.\n\n• 208번의 소련·북한·중국·아프리카·파라과이·중근동 및 재난에 관한 내용과 209번의 지진·벼락에 관한 내용은 강연자가 천상계의 보고 또는 자신의 능력으로 제시한 주장이다.\n\n• 209번 원제의 210은 원문에 존재하는 번호 오기이며, 실제 210번과 번호가 중복된다.",
    "image": "https://raw.githubusercontent.com/concario17-max/shinji/33f81d5266c36192c933d734494bd922df4702d8/images/stories/210.webp",
    "thumb": "https://raw.githubusercontent.com/concario17-max/shinji/33f81d5266c36192c933d734494bd922df4702d8/images/stories/thumbs/210.webp",
