    "contentType": "",
    "summary": "1976년 6월 5일 - 「태양계의 천사들」 “좋은 아침입니다. 방금 여러분에게 드린 『심행(心行)』은 쇼와 43년(1968년) 11월 22일에 완성되었습니다. 그리고 23일 밤 오전 1시, 천상계에서 처음으로 「물질과 생명」이라는 강연을했습니다. 그...",
    "body": "1976년 6월 5일 - 「태양계의 천사들」\n\n“좋은 아침입니다. 방금 여러분에게 드린 『심행(心行)』은 쇼와 43년(1968년) 11월 22일에 완성되었습니다.\n\n그리고 23일 밤 오전 1시, 천상계에서 처음으로 「물질과 생명」이라는 강연을했습니다. 그때 사회를 맡은 이는 모세였습니다. 그보다 앞서 미카엘이 약 한 시간 반 동안 강연했고, 23일 오전 2시 30분에는 지구에서 진도 3의 지진이 있었습니다. 나는 선정에 든 채 천상계에 갔기 때문에 곁에서 자던 아내가 ‘방금 아버지의 강연을 듣고 있었어요’라고 말했습니다. 얼마 전에도 천상계에서, 내가 70년 전 이 지상계에 나올 때의 상황과 『심행』이 만들어진 경위 등이 담긴 책을 보았습니다. 지금은 미카엘 대천사가 그 책을 가지고 있는데, 책장을 넘겨 보다가 나 자신도 놀랐습니다.\n\n‘나는 보고 들으며 정법에 귀의할 수 있었노라’라는 첫머리는, 그 책에 적힌 ‘나는 정도에 눈떠 정법을 널리 펴기 위해 목숨을 던지리라’라는 시작부터 마지막의 ‘선정삼매의 경지에 이르리라’까지 거의 완전히 같았습니다. 내가 쓴 것은 지구적인 표현이었고 천상계의 것은 우주적인 표현이었지만, 아주 조금밖에 다르지 않았습니다. 역시 누군가에 의해 쓰게 된 것이겠지요. 지금도 미카엘이라는 대천사는 이 정도로 두꺼운 책에, 내가 세상에 나오기 전의 모든 계획과 현재 쓰는 책, 앞으로 낼 책까지 기록해 두고 있습니다.” 원문에는 신지 선생이 영상에서 가로세로 약 20~30cm인 입방체 모양의 책을 손으로 나타냈다고 적혀 있다.\n\n“사실 그것은 나만의 이야기가 아닙니다. 여러분도 자신의 마음을 풀어 살펴보면 아마 계획서가 있을 것입니다. 단지 그것을 알아차리지 못할 뿐입니다. 우리는 여러 인생의 고통을 겪으며 그 계획을 잊어버렸습니다. 그러므로 먼저 마음속에서 생각하는 것과 날마다 생활하며 행하는 것을 판단할 올바른 자와 필터를 확실히 지녀야 합니다. 이것이 정법입니다.”",
    "notes": "",
