    "title": "갓난아기의 웃음과 천상계의 ‘조종’에 관한 설명",
    "origTitle": "「高橋信次師物語」 真のメシヤの記録 212　八起正法先生編",
    "contentType": "",
    "summary": "“생각하고 행동하는 하나하나를 이 필터에 걸러 올바른 것만 자신의 것으로 만들어 가십시오. 그것을 알게 될 때 여러분은 참된 자기를 알 수있습니다. 인생은 단 한 번뿐이 아닙니다. 여러분이 지상계에 나와 갓 태어난 아기는 부모가 가르치지 않아도 어머니...",
    "body": "“생각하고 행동하는 하나하나를 이 필터에 걸러 올바른 것만 자신의 것으로 만들어 가십시오. 그것을 알게 될 때 여러분은 참된 자기를 알 수있습니다. 인생은 단 한 번뿐이 아닙니다. 여러분이 지상계에 나와 갓 태어난 아기는 부모가 가르치지 않아도 어머니의 젖을 빨기 시작합니다. 사람들은 이를 본능이라고 부르지만, 이것은 전에 살았다는 증거입니다. 아기는 태어난 지 불과 2~3주 만에 혼자 웃습니다. 그런데 마음의 눈으로 보면 아기의 영혼의 형제나 수호령·지도령들이 다음과 같이 이야기하며 웃고 있습니다.\n\n‘잘됐구나. 단단히 마음먹고 살아가거라. 이번에 태어난 곳은 네게 가혹할지도 모른다. 괜찮겠니?’\n\n‘제게 맡겨 주세요. 약속대로 제대로 해낼게요.’\n\n그러나 성장하면서 환경·사상·습관 속에서 그런 일은 오래전에 잊어버립니다. 그 모습을 천상의 세계에서 지켜보는 영혼의 형제와 지도령·수호령은 어떻게 생각하겠습니까? 여러분은 마치 자기 혼자의 의지로 살아가는 듯 착각하지만, 모든 것은 천상의 세계에서 조종되고 있습니다. 조종받고 있는데도 육체를 지닌 개성은 어느 정도 제멋대로 행동합니다. 마치 꼭두각시와 같습니다. 천상의 세계에서 조종하는 쪽은 처음에는 ‘잘하고 있군’ 하고 바라봅니다. 그러다가 자신의 의지가 움직이기 시작하면 ‘아, 또 파친코 가게에 들어갔군. 또 36번이 나오지 않는다고 고함치고 있군. 또 이상한 곳으로 가기 시작했군’ 하고 걱정합니다. 천상의 세계에서 걱정하는 대상은 지상계에 나온 영혼의 형제나 친구들입니다. 다섯 살이나 여섯 살 무렵까지는 그리 걱정하지 않습니다. 철이 들기 시작하는 열 살·열다섯 살 무렵, 특히 중학교 때부터 대학 시절까지, 어떤 사람은 사회에 나온 뒤부터 이상한 행동을 하기 시작합니다. 독을 먹기 시작하는 것입니다. 그 전에 이미 잔뜩 먹어 버리는 사람도 있지만, 요즘은 빠르면 초등학교 3~4학년부터 이상해지는 아이도 있습니다. 이른바 ‘열쇠 아동’입니다. 부모와 자녀의 대화가 사라집니다.”",
    "notes": "",
