    "title": "부모와의 단절·빙의 및 인간 감각에 관한 발언",
    "origTitle": "「高橋信次師物語」 真のメシヤの記録 213　八起正法先生編",
    "contentType": "",
    "summary": "의학적 맥락 주의: 아래의 노이로제·대인공포증·반항기·빙의에 관한 설명은 1976년 종교 강연의 발언이다. 현대 정신의학적 진단이나 원인 설명으로 받아들여서는 안 된다. “자녀는 부모와 대화하지 않으므로 자기 나름의 판단으로 생활하기 시작합니다. 노이...",
    "body": "의학적 맥락 주의: 아래의 노이로제·대인공포증·반항기·빙의에 관한 설명은 1976년 종교 강연의 발언이다. 현대 정신의학적 진단이나 원인 설명으로 받아들여서는 안 된다.\n\n“자녀는 부모와 대화하지 않으므로 자기 나름의 판단으로 생활하기 시작합니다. 노이로제입니다. 그렇게 되면 그런 아이의 곁에도 조화롭지 못한 영이 찾아옵니다. 그 존재의 의식에 지배되므로 살아 있는 사람과 말하는 것조차 싫어지고 대인공포증에 빠집니다. 둥글고 풍요롭던 마음은 점점 작고 어두워지며 외로워집니다. 그 무렵부터 부모는 ‘우리 아이가 좀 이상하다. 요즘 부모 말을 듣지 않는다’며 다시 거칠게 부딪칩니다. 아이의 마음은 더 작아집니다. ‘누가 나를 이런 아이로 만들었느냐’고 말하면서, 자기가 만들어 낸 일로 자기가 괴로워하면서도 남의 탓으로 돌립니다. 그러다가 부모에게 불효하게 됩니다. 물론 가정 안에는 인간이 성장하는 과정에서 성격이 달라지는 반항기가 있습니다. 그러나 그것이 빙의 현상으로 나타나는 경우가 많습니다. 마음이 어두운 사람에게는 그 어둠에 비례하는 악령이 마음의 어두운 영역으로 다가옵니다. 지구는 피라미드와 거꾸로 선 피라미드의 한가운데에 있습니다. 곧 천상의 세계와 지옥의 세계 사이에 있는 물질세계입니다. 그래서 매우 민감한 곳입니다. 하지만 여러분이 육체를 지니면 둔감해져 알지 못하게 됩니다. 여러분의 눈에 보이는 세계는 아주 작습니다. 일곱 색 무지개의 세계, 약 4,000~7,000옹스트롬의 주파수 영역만 볼 수있습니다. 무지개의 양 끝은 보라색과 붉은색입니다. 붉은색 너머에는 적외선이 있고 적외선 너머에는 전파가 있습니다. 이것들은 보이지 않습니다. 보라색 너머에는 자외선이 있고 자외선 너머에는 열선이 있습니다. 이것도 보이지 않습니다. 그러므로 사람의 눈이 아무리 좋다 해도 극히 일부의 세계밖에 볼 수없습니다. 후각도 마찬가지이고 청각도 대단하지 않습니다.” 원문은 파장 단위를 オングストロング이라고 적었으나, 번역에서는 통용 표기인 옹스트롬으로 옮겼다. 가시광선의 범위와 전자기파 배열에 대한 설명 역시 현대 과학의 정확한 설명과는 차이가 있다.",
