    "title": "반성과 후광·마음의 형태에 관한 설명",
    "origTitle": "「高橋信次師物語」 真のメシヤの記録 214　八起正法先生編",
    "contentType": "",
    "summary": "“하지만 나는 들을 수있습니다. 저세상의 일까지 볼 수있습니다. 마음의 귀·마음의 눈·마음의 코와 같은 참된 마음의 기능을 지니면 자유자재, 곧 관자재(観自在)가 됩니다. 남의 이야기가 아닙니다. 여러분도 그 힘을 지니고 있지만 조금 둔감해졌을 뿐입니...",
    "body": "“하지만 나는 들을 수있습니다. 저세상의 일까지 볼 수있습니다. 마음의 귀·마음의 눈·마음의 코와 같은 참된 마음의 기능을 지니면 자유자재, 곧 관자재(観自在)가 됩니다. 남의 이야기가 아닙니다. 여러분도 그 힘을 지니고 있지만 조금 둔감해졌을 뿐입니다. 둔감해진 까닭은 일상생활에서 남을 원망하고 질투하고 헐뜯고 불평하며, 마음이 원만하지 못한 채 초조해하기 때문입니다. 그것이 모두 스모그가 됩니다. 어젯밤에는 바람을 꽤 많이 불게했습니다. 되도록 오늘 비가 오지 않기를 바랐기 때문입니다. 그처럼 스모그를 걷어 내려면 그에 맞는 작용을 일으켜야 합니다. 여러분에게는 반성이 그 작용입니다. 반성이란 올바른 필터를 가지고 자신이 생각하고 행동한 일을 하나씩 돌아보는 것입니다. 인간이므로 잘못을 저지르기도 합니다. 잘못 또한 자기 마음을 풍요롭게 하는 하나의 보리(菩提)가 됩니다. 잘못했다고 해서 ‘나는 안 된다’며 자신을 작게 만들어서는 안 됩니다. 현재의 환경이 영혼을 더욱 풍요롭게 하는 배움의 장이라면 사소한 일에 집착할 필요가 없습니다. 실패는 성공의 어머니이기도 합니다.\n\n‘잘못을 고치는 일을 주저하지 말라’는 속담이 있습니다. 참으로 그대로입니다. 그 일을 바탕으로 자신을 더욱 풍요롭게 만들고 같은 잘못을 되풀이하지 않는 것이 중요합니다.” 신지 선생은 그림을 가리키며 설명을 이어 갔다. 원문은 두 번째 그림이 선정에 들어앉은 사람과 그 주위의 오라를 그린 것이라고 설명한다.\n\n“지금 여러분은 원자 육체를 지니고 있지만 또 하나의 육체도 지니고 있습니다. 누구나 그렇습니다. 이 가운데 후광이 나오는 사람도 있습니다. 머리카락이 없어서 전등 빛에 머리가 빛나는 사람도 있습니다. 이것은 후광이 아니라 오해입니다.” 원문은 청중이 이 말에 웃었다고 적고 있다.\n\n“본래 머리카락이 있든 없든, 마음이 깨끗하고 태양처럼 아름답고 둥글며 자비로운 사람이 있습니다. 자신만 있는 것이 아니라 상대도 존재한다는 사실을 생각하고 늘 조화를 이루며 정법을 실천하는 사람에게는 아름다운 후광이 나옵니다. 이 후광이 여러분이 저세상에서 되살아날 때의 육체입니다. 서툰 그림이지만 그려 보겠습니다. 이렇게 선정에 든 사람을 생각해 봅시다. 마음은 가슴 부근에 있습니다. 가슴 부근에서 깨끗하고 둥근 형태인 사람, 하트 모양인 사람, 일그러진 형태를 만든 사람이 있습니다. 둥근 마음 안에는 지성·본능·감정·이성·상념의 기능이 있습니다. 크게 나누면 이와 같으며 풍선처럼 둥글게 자리합니다. 마음의 기능이 반듯하게 자리한 것입니다. 이것은 사람마다 하나씩있습니다.”",
