    "contentType": "",
    "summary": "“앞쪽을 보면 아름다운 분홍빛을 내는 사람이 있습니다. 그것은 현재 연애 중이라는 뜻입니다. 어느 정도 나이가 지난 뒤에도 분홍빛을 띠는 사람이 있는데, 그런 경우는 곤란합니다. 마음이 둥근 사람의 몸에서는 아름다운 후광이 나옵니다. 달마처럼 아름답고...",
    "body": "“앞쪽을 보면 아름다운 분홍빛을 내는 사람이 있습니다. 그것은 현재 연애 중이라는 뜻입니다. 어느 정도 나이가 지난 뒤에도 분홍빛을 띠는 사람이 있는데, 그런 경우는 곤란합니다. 마음이 둥근 사람의 몸에서는 아름다운 후광이 나옵니다. 달마처럼 아름답고 부드러운 금빛이 나옵니다. 이런 빛이 나오는 사람은 우선 마음이 100퍼센트 깨끗하여 밤에 잠들어도 지옥에 가지 않는 사람입니다. 잠든 뒤 누군가에게 쫓기거나 무서운 곳에 가서 벌벌 떠는 사람은 대개 전날 잠들기 전에 그다지 좋은 일을 하지 않은 사람입니다. 감정·지성·이성·상념을 비롯한 마음 전체가 둥글고 풍요로우면 지옥의 세계에 가지 않습니다. 어젯밤 무서운 꿈을 꾸었다면 마음이 그리 둥글지 않았다는 증거입니다. 걱정거리가 있거나 무언가가 있는 경우입니다. 그동안 사람들은 마음에 형태가 없다고 생각했지만 그렇지 않습니다.” 신지 선생은 규슈에서 강연했을 때 만난 유명한 의사와의 대화를 소개했다.\n\n“그 의사는 ‘마음 같은 것이 어디 있는가. 인간은 모든 것을 머리로 판단한다. 그러므로 마음은 머리에 있다’고했습니다. 일류대학의 유명한 의사이며 정신의학계에서 일본 최고라는 사람이었습니다. 그는 내 앞에서 ‘사람의 머리가 이상해진 것이므로 치료하려면 대뇌를 이렇게 해야 한다’는 말을 장황하게했습니다. 그래서 내가 ‘선생님, 마음은 어디에있습니까?’라고 묻자 ‘그야 머리에 있지’라고 답했습니다. 나는 ‘그렇습니까’ 하고 다음과 같이 물었습니다.\n\n‘그렇다면 기쁘거나 슬플 때 북받쳐 오르는 감정도 머리에서 올라옵니까?’\n\n‘그건 여기에서 올라오지.’\n\n‘그렇다면 이쪽에서 북받쳐 오르는 것은 무엇입니까?’\n\n‘그걸 알면 노벨상을 받지.’” 원문은 청중이 웃었다고 적고 있다.",
