    "contentType": "",
    "summary": "“빛으로 된 육체는 보이지 않는 신의 빛으로 가득 차있습니다. 마음에 스모그가 없으므로 후광이 나오며, 사실 이것이 참된 육체입니다. 여러분이 저세상으로 돌아갈 때 타는 배입니다. 그쪽에도 대뇌를 비롯한 모든 것이 갖추어져있습니다. 그러므로 지금 여러...",
    "body": "“빛으로 된 육체는 보이지 않는 신의 빛으로 가득 차있습니다. 마음에 스모그가 없으므로 후광이 나오며, 사실 이것이 참된 육체입니다. 여러분이 저세상으로 돌아갈 때 타는 배입니다. 그쪽에도 대뇌를 비롯한 모든 것이 갖추어져있습니다. 그러므로 지금 여러분의 뇌세포는 수신하고 송신하는 기능에 지나지 않습니다. 귀로 소리를 들으면 청각신경은 뇌세포의 청각 기능으로 신호를 보내고, 그 신호를 다른 차원으로 전달하는 장치에 지나지 않습니다. 이번에는 물건을 봅니다. ‘빨강’이라고 본 것은 청각신경의 ‘빨강’밖에 볼 수없습니다. 그 ‘빨강’을 판독하는 쪽에서는 영어·독일어·프랑스어·일본어처럼 말이 다를 뿐 빨강이라는 사실은 바뀌지 않습니다.\n\n‘빨강’은 영어로 레드라고 해도 빨강입니다. 뇌세포는 250억 개입니다. 이 250억 개의 각 영역에서 신경섬유 하나하나는 일방통행하며 그것이 기억합니다. 그러므로 어느 나라에서나 빨강은 빨강이고 말만 다릅니다. 실제로 기억하는 것은 빛으로 된 육체입니다. 여러분이 밤에 꿈을 꿀 때 자기 육체를 바라본 적이 있을 것입니다. 자신의 육체는 누워 자고 있습니다. 잠든 육체에서 나온 또 하나의 육체가 활동하는 모습을 자신이 다시 바라봅니다. 그런 경험이 있는 사람은 손을 들어 보십시오. 그 모습을 보는 존재는 여러분의 광자체라는 배를 모는 진정한 선장입니다. 그것이 여러분의 참된 진아인 자기 자신입니다. 그러므로 이 세상을 떠날 때에는 ‘용케 이런 배를 타고 있었구나’ 하고 지금의 육체를 돌아보게 됩니다. 무엇보다 우리는 천상계에서 자주 회의를 합니다.” 웹 원문은 물체를 볼 때에도 청각신경이라고 적지만, 동일 강연 PDF에는 시각신경이라고 되어 있다. 본문에는 기준 원문의 표현을 유지하고 이 차이를 별도로 밝혔다. 뇌세포 수와 기억 기능에 관한 설명 또한 현대 신경과학의 설명과는 다르다.",
    "notes": "",
