    "title": "천상계의 외모와 ‘아스테리아’ 체험담",
    "origTitle": "「高橋信次師物語」 真のメシヤの記録 217　八起正法先生編",
    "contentType": "",
    "summary": "“천상계 회의에서 육체를 지닌 존재는 나뿐이므로 우선 내 모습이 추합니다. 게다가 내가 가장 나이가 많습니다. 스스로는 젊다고 생각하지만 상대는 모두 스물여섯이나 스물일곱쯤이고, 미카엘은 스물여덟·스물아홉에서 서른쯤, 예수님은 서른여섯·서른일곱에서 마...",
    "body": "“천상계 회의에서 육체를 지닌 존재는 나뿐이므로 우선 내 모습이 추합니다. 게다가 내가 가장 나이가 많습니다. 스스로는 젊다고 생각하지만 상대는 모두 스물여섯이나 스물일곱쯤이고, 미카엘은 스물여덟·스물아홉에서 서른쯤, 예수님은 서른여섯·서른일곱에서 마흔쯤이므로 피부색부터 다릅니다. 악수하면 내 손은 돌처럼 느껴지는 반면 상대의 손은 로열젤리 같은, 말로 표현하기 어려운 감촉입니다. 보살계에 있는 여성들은 미스 유니버스처럼 모두 아름답습니다. 그래서 눈을 뜨면 실망합니다. 지상계의 여러분도 외모가 조금 못생겼다고 실망할 필요는 없습니다. 언젠가 천상계로 돌아가면 모두 아름다워지기 때문입니다. 광자체의 육체에는 나처럼 여드름이 솟았던 흔적도 하나없습니다. 여성들은 거의 모두 아름답습니다. 하지만 지옥계는 다릅니다. 마왕 주변에 있는 존재는 아름다운 얼굴처럼 보여도 마음이 갑자기 바뀌는 순간 입이 찢어지고 똑바로 보기 어려운 모습으로 변합니다. 무서운 노파라는 말조차 귀엽게 느껴질 만큼 끔찍한 얼굴이며 해골 같은 모습이 됩니다. 지옥계는 별개의 세계입니다.\n\n‘미스 추녀’ 정도가 아닙니다. 겉모습이 아름답다고 생각했다가는 큰일입니다.” 신지 선생은 이어 자신이 겪었다는 아스테리아의 이야기를 했다.\n\n“얼마 전 우리 집에 마왕 사탄의 조카인 아스테리아가 찾아왔습니다. 내가 가진 법륜을 힘껏 던지자 거기에 걸려 왔습니다. 모두에게 ‘바로 이런 모습이다’ 하고 보여 주었더니 내 손 안에서 춤을 추었습니다. 그것을 휙 던져 놓고 잠들었는데, 밤중에 성장하여 내 이불 안으로 들어왔습니다.\n\n‘이 여자가 왜 내 이불 속에 들어오는 거지?’ 하고 생각했습니다. 마침 안마를 받고 있던 중이라 나는 ‘너는 왜 이런 곳에 들어오느냐. 나가라!’고 말했습니다. 하지만 시각장애가 있는 안마사는 그 존재를 볼 수 없었으므로 ‘저는 아무것도 하지 않았습니다’라고했습니다. 당연히 본인은 깜짝 놀랐습니다. 나는 볼 수 있지만 상대는 볼 수 없기 때문입니다. 그래서 ‘당신에게 한 말이 아닙니다. 지금 굉장히 아름다운 외국인 여성이 문병을 왔다면서 내 옆에 나타났습니다. 문병을 왔는데 왜 이불 속으로 들어오느냐고 나가라고 한 것입니다’라고 설명했습니다. 안마사는 ‘그렇습니까? 저는 그럴 생각이 없었고, 다만 무언가 좋지 않은 기운을 느꼈습니다’라고했습니다. 나는 ‘그것과는 다릅니다’라고 답했습니다. 그 존재는 외국 영화배우처럼 대단히 아름다운 여성을 닮았습니다.\n\n그러나 마음을 갑자기 바꾸자 악당이자 무서운 노파의 모습으로 변했고, 입가가 찢어져 똑바로 바라볼 수 없었습니다. 이것이 지옥계의 실상입니다.” 원문에는 시각장애인을 가리키는 오늘날의 비하 표현이 사용되어 있으나, 번역에서는 맥락을 보존하면서 중립적인 표현으로 옮겼다.",
