    "title": "파워트론과 ‘빛의 분령’에 관한 설명",
    "origTitle": "「高橋信次師物語」 真のメシヤの記録 218　八起正法先生編",
    "contentType": "",
    "summary": "“천상계에는 그런 일이 없고 분노도 없습니다. 천상의 세계에서 마음이 조화를 이룬 엘 란티라는 분에게는 이곳에 파워트론이라는 것이 있습니다.” 원문은 이때부터 신지 선생이 그림을 그리며 설명했다고 적는다. “머리에 파워트론을 달고 있습니다. 신의 빛을...",
    "body": "“천상계에는 그런 일이 없고 분노도 없습니다. 천상의 세계에서 마음이 조화를 이룬 엘 란티라는 분에게는 이곳에 파워트론이라는 것이 있습니다.” 원문은 이때부터 신지 선생이 그림을 그리며 설명했다고 적는다.\n\n“머리에 파워트론을 달고 있습니다. 신의 빛을 곧바로 받는 장치이며, 이 파워트론에서 빛이 쭉 뻗어 나옵니다. 머리와 몸에서 모두 빛이 나오므로 빛의 화신이라고 생각하면 됩니다. 파워트론과 엘 란티의 마음이 자리한 곳을 기준으로 같은 축의 약 70~80cm 지점에 구슬이 있습니다. 이것이 돔입니다. 돔에서도 부드러운 금빛이 나옵니다. 매우 큰 빛입니다. 파워트론에서 빛이 발사되는 동시에 그곳에는 영혼의 분령, 곧 빛의 분령인 예수님·모세님·칸타레의 의식이 들어 있습니다. 머리 위로 약 70cm 되는 곳입니다. 예를 들어 내가 예수님 시대의 이야기를 하면, 예수님의 의식이 든 것이 빙글빙글 돌다가 내 몸속으로 들어옵니다. 그러면 내 얼굴이 예수님의 얼굴로 바뀝니다. 석가님 이야기를 하면 앞의 의식이 나가고 석가님의 의식이 들어옵니다. 당시의 의식이 몸속에 들어오므로 이번에는 석가님의 얼굴로 바뀝니다. 그래서 내가 전국을 돌며 강연하면 ‘저분은 석가님의 환생이다’라고 말하는 사람이 나옵니다. 그들에게는 그렇게 보이기 때문입니다. 평소에는 이렇게 작은 귓불이 인도 시대의 모습으로 바뀌고, 눈은 가늘어집니다. 사람들은 그 모습을 보고 놀라며 석가님으로 보게 됩니다. 이것을 빛의 분령이라고 합니다. 엘 란티의 빛의 분령은 각각 개성을 지니므로 그런 방식으로 나타납니다.”",
