    "title": "문제의 뿌리와 계명(戒名)에 관한 비판",
    "origTitle": "「高橋信次師物語」 真のメシヤの記録 222　八起正法先生編",
    "contentType": "",
    "summary": "“집안에서 여러 좋지 않은 문제가 일어날 때에는 ‘우리의 사고방식이나 생활 방식에 무언가 잘못이 있다. 올바른 법칙에서 벗어났다’고 생각해야 합니다. 조상이 어떻다는 이야기가 아닙니다. 괴로워하는 사람은 바로 우리 자신입니다. 그 뿌리를 생각하고 바로...",
    "body": "“집안에서 여러 좋지 않은 문제가 일어날 때에는 ‘우리의 사고방식이나 생활 방식에 무언가 잘못이 있다. 올바른 법칙에서 벗어났다’고 생각해야 합니다. 조상이 어떻다는 이야기가 아닙니다. 괴로워하는 사람은 바로 우리 자신입니다. 그 뿌리를 생각하고 바로잡으십시오. 그러면 나아집니다. 여기에도 그렇게 해서 온 사람이 여러 명있습니다.\n\n그때는 무엇을 향해 비는 것이 아니라 우리의 사고방식·생활 방식·사물을 보는 방식을 고칠 기회를 받은 것입니다. 그 뿌리는 어디에 있는가, 원인은 어디에 있는가를 살펴야 합니다. 나쁜 면을 없애지 않는 한 안 됩니다. 그런데 그저 조상 탓으로 돌리고 조상을 섬기면 낫는다며 ‘그렇다면 조상에게 좋은 계명을 올리자’고 합니다. 그러면 거기에서 입을 딱 벌리고 기다리는 장사꾼이 있습니다. 좋은 계명을 올리면 구원받는다는 것은 어리석은 말입니다. 여러분, 아무리 좋은 계명을 붙여도 지옥은 지옥입니다. 몇 해 전 ‘○○원전(院殿) ○○대거사(大居士)’라는 계명을 지닌 사람이 죽었습니다. 그 사람은 도큐 사장을 지냈는데\n\n‘내 두목을 불러내 달라’고 해서, 나는 그 두목이 틀림없이 고토 게이타라고 생각했습니다. 그런데 아니었습니다. 전직 총리였습니다. ‘나다’ 하고 나타났지만 목에서 목소리가 나오지 않았습니다. 암 수술을 받고 죽은 총리였기 때문입니다. 그가 지옥에 있으니 어쩔 도리가 없지 않습니까? 이름을 보니 ‘원전대거사’였습니다.\n\n그러자 그는 ‘그런 이름은 남들이 멋대로 붙인 것이니 나와는 관계없다. 고야산에 가서 물어보라’고했습니다. 그런 것입니다. 중요한 것은 이름이 아닙니다. ‘저승 일도 돈에 달렸다’는 말은 터무니없습니다. 돈이 한 푼 없어도 천상계에 갈 수있습니다. 이것을 알아 두십시오. 아무리 훌륭한 계명을 붙여도 지옥에 떨어질 사람은 지옥에 떨어집니다. 이름 따위는 아무래도 좋습니다. 지옥에 가서 계명을 대는 사람은 한 명도 없습니다. 여기에는 일본인의 여러 사정이 얽혀있습니다. 계명은 본래 살아 있을 때 붙이는 것입니다. 옛 승려들은 사람을 절의 서당 같은 곳으로 데려와 정법과 불교를 잘 가르친 뒤 이렇게 말했습니다.\n\n‘아, 많이 공부했고 생활도 달라졌군요. 그럼 이제까지의 이름을 바꾸고 이쯤에서 거사라는 이름을 드리지요.’\n\n‘고맙습니다. 덕분에 제 마음도 온화해졌습니다.’ 본래는 그렇게 받는 것이었습니다.” 원문의 パックリ屋는 입을 크게 벌리고 돈을 기다리는 사람을 빗댄 듯한 속어·말장난으로, 문맥에 맞추어 ‘입을 딱 벌리고 기다리는 장사꾼’으로 옮겼다. 전직 총리와 사후세계에 관한 이야기는 강연자의 체험 주장으로 기록된 것이며, 인물의 실명은 원문도 밝히지 않는다.",
