    "title": "살아 있을 때 받는 계명과 불제자들의 이름",
    "origTitle": "「高橋信次師物語」 真のメシヤの記録 223　八起正法先生編",
    "contentType": "",
    "summary": "“그런데 일본에서는 사람이 죽고 얼마가 지난 뒤 돈을 가져가서 계명을 붙입니다. 죽은 사람이 그것을 알 리가 없지 않습니까? ‘당신은 누구입니까?’ 하고 물으면 자기 본명을 말합니다. ‘○○원전 ○○대거사 같은 이름은 모른다’는 것입니다. 마찬가지로 ...",
    "body": "“그런데 일본에서는 사람이 죽고 얼마가 지난 뒤 돈을 가져가서 계명을 붙입니다. 죽은 사람이 그것을 알 리가 없지 않습니까?\n\n‘당신은 누구입니까?’ 하고 물으면 자기 본명을 말합니다. ‘○○원전 ○○대거사 같은 이름은 모른다’는 것입니다. 마찬가지로 저승 일이 돈에 달린 것은 아닙니다. 사정이 좋지 않은 누군가가 그렇게 말했을 뿐입니다. 그러므로 여러분에게 계명은 사실 필요하지 않습니다. 살아 있을 때 자기 마음과 행동을 바로잡고 ‘좋아’ 하며 예전 이름을 버린 뒤, 새로 태어난 마음으로 인생을 다시 시작하겠다는 뜻에서 이름을 바꾸는 것이라면 얼마든지 하십시오. 죽은 뒤에 받는 것이라면 필요없습니다. 살아 있을 때 자기 마음을 개조하고 생활을 고친 뒤 이름을 받는 것이 참된 계명입니다. 계명과 관련하여 인도 당시 붓다의 제자 가운데 샤리 푸트라〔사리불·사리자〕라는 사람이 있었습니다. 그의 이름은 우파텟사였습니다. 그런데 ‘우파텟사라는 이름으로는 도무지 앞날이 트이지 않겠다’는 이야기가 나왔습니다.” 원문은 여기에서 일본어의 ‘우파텟사’와 ‘우다쓰가 아가라나이〔출세하지 못하다〕’의 비슷한 소리를 이용한 농담 뒤 청중이 웃었다고 적는다.\n\n“‘너는 아주 잘하고 있으니 어머니 이름인 샤리를 받아 보는 것이 어떠냐. 네 어머니는 남모르게 덕을 쌓은 훌륭한 분이다. 마음과 몸가짐을 새롭게 하여 샤리 푸트라라는 이름으로 바꾸면 좋겠다’고 해서 계명을 바꾸었습니다. 또 코리타라는 이름을 가진 사람도 있었습니다. 몇 번이나 ‘코리테〔懲りて, 데이고 깨닫다〕’도 곤란하니까 말입니다.” 이 대목도 ‘코리타’와 일본어 懲りて의 소리를 겹친 말장난이며, 원문에는 웃음 표시가 있다. 웹 원문의 편집자는 괄호 안에 “고대 인도 석가 시대에 코리타는 폭한에게 살해되었고, 훗날 유명한 사카모토 료마로 다시 태어났으나 메이지유신 때에도 마찬가지로 암살된 것으로 알려졌다. ‘몇 번이나 코리테’라는 말은 이를 받은 것이다”라는 주기를 덧붙였다. 이는 편집자의 윤회 주장으로, 강연록 PDF 본문에는 없는 설명이다.\n\n“어쨌든 이제 마음도 깨끗해졌으니 이 기회에 네 이름을 몬가라나로 하자고 하여, 마하 몬가라나라는 이름으로 바꾸었습니다. 곧 대목련입니다. 이것도 살아 있을 때의 일입니다. 죽고 난 뒤 아무리 좋은 이름을 받아도 어찌할 수 없지 않습니까? 요즘 일본인은 그런 것을 좋아하게 되어 죽은 뒤에 하나 받는 것이 좋다고 여깁니다. 최근에는 결혼에까지 영향을 미쳐, 묘지에 가서 계명을 보고 ‘이 집 조상의 계명은 별로 좋지 않으니 안 된다’는 말을 합니다.\n\n‘원전대거사라는 계명이 없으니 결혼 상대가 될 수 없다’고까지 말한다면 이미 악령과 다름없습니다. 여러분, 그런 것이 아닙니다.”",
