    "title": "살아 있는 사람을 구해야 할 승려에 관한 발언",
    "origTitle": "「高橋信次師物語」 真のメシヤの記録 224　八起正法先生編",
    "contentType": "",
    "summary": "“그 점에서 그리스도교 신자들은 살아 있을 때 자기 마음을 바꾸고, 마리아에 가까운 마음과 마리아님 같은 마음을 지니고 싶다며 마리아를 비롯한 여러 사람의 이름을 붙이기도 합니다. 그리스도교 신자 쪽이 훨씬 훌륭합니다. 살아 있을 때 사고방식을 바꾸기...",
    "body": "“그 점에서 그리스도교 신자들은 살아 있을 때 자기 마음을 바꾸고, 마리아에 가까운 마음과 마리아님 같은 마음을 지니고 싶다며 마리아를 비롯한 여러 사람의 이름을 붙이기도 합니다. 그리스도교 신자 쪽이 훨씬 훌륭합니다. 살아 있을 때 사고방식을 바꾸기 때문입니다. 그런데 불교에서는 죽은 뒤 이름을 바꿉니다. 죽은 다음에 달라질 수는 없지 않습니까? 그러므로 여러분은 그런 것에 마음을 빼앗겨서는 안 됩니다. GLA의 승려는 그런 일을 하지 않습니다. ‘인덴(院殿) 계명을 주세요’ 하고 와도 ‘뭐, 인(院) 정도면 되지 않습니까’ 하는 식입니다.” 원문은 계명의 높은 등급인 院殿과 더 짧은 院을 이용한 농담 뒤 청중이 웃었다고 적는다.\n\n“그러니 장사가 번창하고 일이 바빠집니다. ‘그곳에 가면 천상계에 갈 수 있다’며 장례가 많아지는 것입니다. 하지만 본래 승려가 장례만 전문으로 해서는 곤란합니다. 살아 있는 사람을 구해야 합니다. 죽은 사람은 이제 어찌할 수없습니다. 그런데 일본에서는 승려가 살아 있는 사람과 관계없는 존재가 되어 버렸습니다. 절의 승려가 입원 환자를 문병하러 가면 ‘재수가 없다’고 합니다. 그럴 것이 아니라 병원에 입원해 죽느냐 사느냐 하는 사람에게 ‘저승이 있다. 언제까지나 집착하지 말고 모두 버려라. 자녀들에게 전부 나누어 주어라’라고 가르쳐 주어야 합니다. 본래는 그래야 합니다. 그런데 승려가 오면 ‘재수가 없다. 저 사람은 죽는 것 아닐까’라고 합니다. 얼마 전 내가 마침 승려 같은 머리로 배를 탔더니 ‘스님과 함께라 물고기 한 마리도 못 잡겠군’이라고했습니다.” 원문은 이 대목에서 청중이 웃었다고 적는다.\n\n“이렇게 승려는 재수가 나쁜 존재가 되어 버렸습니다. 나도 일단 마음을 고쳐먹고 머리 모양부터 바꾸어 보려고 여러모로 검토한 끝에 머리를 3푼 길이로 짧게 깎았습니다. 그랬더니 ‘스님과 함께라 물고기도 못 잡겠군’이라고했습니다. 참 이상한 일입니다.” 三分刈り는 당시 일본식 길이 표현으로, 머리카락을 약 9mm 안팎으로 짧게 깎는 형태를 가리킨다.",
