    "title": "붓다의 유언과 갑작스러운 죽음에 관한 체험담",
    "origTitle": "「高橋信次師物語」 真のメシヤの記録 225　八起正法先生編",
    "contentType": "",
    "summary": "“본래 승려는 살아 있는 사람을 구하는 존재입니다. 인도에서 석가모니가 실제로 가르친 내용을 보십시오. 붓다가 세상을 떠날 때 제자 아난이 곁에서 울며 물었습니다. ‘붓다께서 돌아가시면 저희는 어떻게 해야 합니까? 이제 저희에게는 의지할 곳이 없습니다...",
    "body": "“본래 승려는 살아 있는 사람을 구하는 존재입니다. 인도에서 석가모니가 실제로 가르친 내용을 보십시오. 붓다가 세상을 떠날 때 제자 아난이 곁에서 울며 물었습니다.\n\n‘붓다께서 돌아가시면 저희는 어떻게 해야 합니까? 이제 저희에게는 의지할 곳이 없습니다.’\n\n그러자 붓다는 ‘무슨 말을 하는가. 내가 45년 동안 설한 법이 너희 마음속에 있지 않으냐. 너희는 그 법을 의지해 사람들을 구해야 한다’고 가르쳤습니다. 그런데 어째서인지 승려는 죽은 사람을 가르치는 존재처럼 바뀌었습니다. 이래서는 정말 안 됩니다. 그 승려가 보며 듣고 말할 수 있다면 그나마 좋겠지만, 보이지도 않고 들리지도 않으며 말하지도 못하는 사람이 망자에게 인도(引導)를 내린다고 하니 어찌할 도리가 없습니다.” 웹 원문은 이 대목을 見えて聞えて話せない이라고 잘못 적은 뒤, 괄호 주기에서 見えず、聞えず、話せない이라는 뜻이라고 바로잡았다. 번역은 그 주기의 뜻을 따랐다.\n\n“어떻게 된 일입니까? 우리라면 사람이 죽을 때 ‘아, 이 사람은 지옥에 가겠구나. 이봐, 잠깐 기다리게’ 하고 붙잡습니다. 얼마 전 어떤 사람이 죽어서 충격을 받았습니다. 내가 가 보니 그는 무의식계에 있었습니다. 내가 사업을 하고 있던 중이라 곧장 그곳으로 갔습니다.\n\n‘당신, 어떻게 된 것입니까?’ 하고 묻자 그는 ‘화장실에 있을 때 이렇게 되어 버렸습니다’라고했습니다. 화장실에 있다가 그대로 털썩 세상을 떠난 것입니다. 아무런 예고도 없었습니다. 대개는 언제쯤 죽을 것이라는 보고가 오지만, 그가 건강했으므로 나도 건강한 줄 알았습니다. 아침에 사망했다는 전화가 와서 내가 곧장 가 보니, 그는 무의식계에서 자기 육체를 떠난 채 스스로 의식하지 못하고 있었습니다.\n\n‘당신, 어떻게 되었습니까?’\n\n‘화장실에 있을 때까지는 알았지만 그 뒤는 알 수 없게 되었습니다.’\n\n‘정신 차리십시오. 당신이 이렇게 일찍 갈 줄은 생각하지 못했습니다.’ 그래서 ‘예수님, 예수 그리스도여. 즉시 가서 도와주십시오’라고 했고, 곧 그의 혼을 흔들어 깨웠습니다. 그는 지금 수양소에 있습니다.” 이 항목의 무의식계·혼·예수의 협력·수양소에 관한 내용은 강연자의 영적 체험 주장이다.",
