    "contentType": "",
    "summary": "“그는 노동조합에서 집중적으로 비판받고 가정에서도 반발을 받았습니다. 정신적으로 의지할 곳 없이 마음고생을 하던 때 그런 죽음을 맞았습니다. 그러니 무서운 일입니다. 모든 것은 무상합니다. 인간이 언제 이 세상을 떠날지는 알 수없습니다. 따라서 여러분...",
    "body": "“그는 노동조합에서 집중적으로 비판받고 가정에서도 반발을 받았습니다. 정신적으로 의지할 곳 없이 마음고생을 하던 때 그런 죽음을 맞았습니다. 그러니 무서운 일입니다. 모든 것은 무상합니다. 인간이 언제 이 세상을 떠날지는 알 수없습니다. 따라서 여러분도 언제나 마음의 준비를 갖추어야 합니다. 이것이 내가 말하는 ‘하루가 한 생〔一日一生〕’입니다. 내일도 살아 있다면 다시 온 힘을 다하겠다고 생각하십시오. 지금 젊다고 해도 알 수 없는 일입니다. 그러나 이런 말만 하면 분위기가 가라앉으니, 일단 내일도 살아 있을 셈으로 희망을 품고 힘내는 것입니다. 자기가 죽었는지 살았는지를 분명히 구별할 수 있는 사람은 많지 않습니다. ‘아, 내가 지금 죽는구나’ 하고 아는 사람은 훌륭합니다. GLA 사람 중에는 죽을 때를 알아 부모에게 효도하는 사람도 있습니다. 어떤 사람은 이틀 전에 이미 알고 이렇게 말했습니다.\n\n‘나는 이제 이틀밖에 남지 않았습니다. 여러분, 오랜 세월 정말 미안했습니다. 사실은 더 오래 살고 싶지만 이제는 어려운 것 같습니다. 이틀 뒤에는 이 세상을 떠날 테니 잘 부탁합니다. 모처럼 집도 지었으니 GLA에서 꼭 사용해 주십시오. 아내도 외로울 것 같습니다. 다음에 다시 태어날 때에는 올바르게 자신을 알아가겠습니다. 하지만 이번 생은 참으로 즐거웠습니다. 고맙습니다.’ 그렇게 돌아간 사람이 많이 있습니다. 그들은 시신이 전혀 굳지 않습니다. 살아 있을 때보다 더 아름다워집니다. 이것이 참된 성불입니다. 이렇게 딱딱하게 굳는 것은 모두 안 됩니다. 그러므로 여러분은 사람이 죽었을 때 살펴보십시오. 죽은 사람이 딱딱하게 굳었다면 ‘이 사람은 지옥에 갔구나’라고 생각하십시오.\n\n그때에는 ‘당신, 잠깐 여기 있으십시오’ 하고 말하십시오.\n\n‘당신은 이제 이 지상계를 떠납니다. 집착을 버리십시오. 이제 당신의 육체는 소멸합니다. 당신은 지금 새로운 육체를 얻습니다. 언제까지나 그런 일을 계속하면 당신은 지옥에 갑니다.’ 죽음은 대단히 큰 행사입니다. 지옥령들이 모두 찾아오기 때문입니다.” 의학적 맥락 주의: 사후경직은 근육의 생화학적 변화로 일어나는 정상적인 사후 현상이며, 시작 시점과 강도는 온도·신체 상태 등 여러 조건에 따라 달라진다. 시신의 경직 여부나 외관으로 고인의 도덕성·성불·사후세계를 판단할 수 있다는 위 발언은 의학적 사실이 아니다.",
