    "contentType": "",
    "summary": "신지 선생의 승천 1976년(쇼와 51년) 6월 25일, 다카하시 신지는 세상을 떠났다. 신지 선생의 저서 출판을 담당한 홋타 가즈나리 씨는 다음과 같이 썼다. “돌아가시기 약 4개월 전, 부처 앞에서 설법하는 격인 줄 알면서도 기회가 있을 때마다 쉬...",
    "body": "신지 선생의 승천 1976년(쇼와 51년) 6월 25일, 다카하시 신지는 세상을 떠났다. 신지 선생의 저서 출판을 담당한 홋타 가즈나리 씨는 다음과 같이 썼다.\n\n“돌아가시기 약 4개월 전, 부처 앞에서 설법하는 격인 줄 알면서도 기회가 있을 때마다 쉬시라고 권했습니다. 그럴 때 선생님은 이렇게 말씀하셨습니다.\n\n‘알고 있습니다. 내 몸은 내가 가장 잘 압니다. 하지만 해야 할 일을 하지 않으면 내 역할을 다할 수 없게 됩니다. 나는 그저 할 뿐입니다.’ 선생님은 죽음을 각오하고 있었습니다. 남은 시간을 어떻게 효과적으로 쓸 것인가, 오직 그것만이 마음을 지배하고 있던 듯합니다.\n\n‘선생님의 마음은 헤아립니다. 그러나 가늘고 길게 산다는 말도 있습니다. 지금 몸에는 휴식이 가장 필요하다고 생각합니다. 천천히 몸을 쉬게 하십시오.’ 나는 선생님께 거듭 그렇게 말씀드렸습니다. [……] 그러나 이미 때는 늦어, 6월 25일 오전 11시 28분 가족들이 지켜보는 가운데 그 짧은 생애를 마쳤습니다.” 원문은 이 인용의 출전을 홋타 가즈나리의 『마음에 법이 있어(心に法ありて)』로 밝힌다. 신지 선생의 아내 다카하시 가즈에는 다음과 같이 썼다.\n\n“‘자, 나를 일으켜 줘. 윗옷을 내줘. 나는 가야 한다. 모두가 기다리고 있다.’ 남편은 이불 속에서 계속 내게 그렇게 외쳤습니다. 자기 몸을 자유롭게 움직이지 못하면서도 마음만은 다음 날로 다가온 간사이 강연으로 이미 날아가 있는 듯했습니다. [……] 하지만 남편은 이미 며칠째 아무것도 먹지 못했습니다. 게다가 도호쿠 강연에서 몸을 완전히 소진한 데다, 바로 전날 어떤 분이 야오키 빌딩에 찾아온다고 하여 일부러 나가 밤 10시가 넘도록 이야기를 나누었습니다. 그 무리가 몸에 닥친 것이겠지요. [……] 지금 돌이켜 보면 그때 남편은 가족의 이해를 넘어서는 어떤 사명감 하나에 자기 혼을 불태우며 살았다고 생각합니다. 그로부터 열흘 남짓 지나 남편은 승천했습니다. [……]” 공식 GLA 자료와 외부 연구 자료에서도 다카하시 신지의 사망일은 1976년 6월 25일로 확인된다. 다만 이 항목의 세부 상황과 직접 발언은 홋타 가즈나리와 다카하시 가즈에의 회고에 근거한다.",
    "notes": "",
