    "title": "『진창세기·지옥편』의 「회상 속의 아버지」",
    "origTitle": "「高橋信次師物語」 真のメシヤの記録 231　八起正法先生編",
    "contentType": "",
    "summary": "회상 속의 아버지원문은 앞 항목에 이어 『진창세기·지옥편』의 글을 다음과 같이 인용한다. “아버지는 이제 자신의 육체를 믿을 수 없다고 말했습니다. 그러고는 음식이 아버지의 목을 넘어가지 않게 되었습니다. 아버지는 남은 힘을 모두 짜내 강연을 계속했고...",
    "body": "회상 속의 아버지원문은 앞 항목에 이어 『진창세기·지옥편』의 글을 다음과 같이 인용한다.\n\n“아버지는 이제 자신의 육체를 믿을 수 없다고 말했습니다. 그러고는 음식이 아버지의 목을 넘어가지 않게 되었습니다. 아버지는 남은 힘을 모두 짜내 강연을 계속했고, 마지막 책이 될 원고를 계속 썼습니다. 그 원고는 내 손에 있습니다. 아버지는 이 책이 세계를 움직이게 될 것이라고 줄곧 말했습니다. 손이 이상할 만큼 부어올라 식사조차 하기 어려웠는데도, 불편한 손으로 계속 펜을 들었습니다. 약속을 지킬 수 없다는 것을 안 아버지는 간사이 강연장이 있는 방향을 향해 엎드려 절했습니다.\n\n‘가지 못해서 여러분께 죄송합니…….’ 아버지는 눈물을 뚝뚝 흘리며 사과했습니다. 6월 18일, 죽기 일주일 전 혼자서는 움직일 수 없게 된 아버지는 자택에서 아사쿠사의 야오키 빌딩으로 옮겨 갔습니다. 죽기 사흘 전이 되어서야 아버지는 비로소 이불을 펴고 몸을 누였습니다.\n\n‘아, 이제야 나도 환자다워졌구나.’ 그것이 아버지의 소감이었습니다. 맥박이 흐트러지기 시작했을 때, 나는 여섯 시간만 더 살아 달라고 애원했습니다.\n\n그러자 모든 것이 정상으로 돌아왔고, 아버지는 정확히 여섯 시간을 더 살았습니다. 그리고 심장이 멈췄습니다. 그 순간 나도 위독한 아버지와 같은 상태가 되었습니다. 죽음과 동시에 육체를 떠난 아버지가 내 안으로 들어왔기 때문에 일어난 현상이었습니다. 그날 밤부터 아버지는 내 몸을 빌려 말하기 시작했습니다. 내게는 기억이 없지만, 완전히 아버지의 말투로 어머니와 이야기를 나누고 작별을 고했다고 합니다.” 자료 성격 주의: 이 글은 다카하시 게이코 명의로 출판된 『진창세기·지옥편』 속 회고로 제시된 내용이다. 230번 원문은 이 책의 실제 집필에 히라이 가즈마사가 관여했다는 주장을 함께 소개한다. 따라서 회고의 화자·집필자·사실성을 서로 같은 것으로 단정하지 않았다.",
    "notes": "",
