    "title": "신지 선생의 ‘마지막 영적 통신’",
    "origTitle": "「高橋信次師物語」 真のメシヤの記録 232　八起正法先生編",
    "contentType": "",
    "summary": "원문은 신지 선생의 의식이 전했다는 마지막 영적 통신을 다음과 같이 소개한다. “그대들은 자신의 사명을 다하십시오. 앞으로 어떤 일이 있더라도 마음을 흔들리게 해서는 안 됩니다. 내가 그대들의 마음속에서 계속 살아 있음을 아십시오. 나의 지상 생명은 ...",
    "body": "원문은 신지 선생의 의식이 전했다는 마지막 영적 통신을 다음과 같이 소개한다.\n\n“그대들은 자신의 사명을 다하십시오. 앞으로 어떤 일이 있더라도 마음을 흔들리게 해서는 안 됩니다. 내가 그대들의 마음속에서 계속 살아 있음을 아십시오. 나의 지상 생명은 곧 끝납니다.\n\n그러나 슬퍼해서는 안 됩니다. 자기 마음속에 법등(法灯)을 굳게 밝혀 가십시오. 이제부터는 그대들의 참된 사명을 다할 때입니다. 〔중략〕 그대들은 자기 마음을 만들어 가십시오. 마음속의 여러 잘못을 바로잡아 참된 자신을 만들고, 그 사랑을 넓혀 가는 것입니다. 이것이 내가 그대들에게 남기는 마지막 말입니다.” 이 항목은 영적 통신으로 전해졌다는 문장을 인용한 기록이다. 실제 음성 기록이나 독립적인 검증 자료가 제시된 것은 아니다.",
    "notes": "",
