    "title": "소노가시라 회장이 회고한 임종 당일",
    "origTitle": "「高橋信次師物語」 真のメシヤの記録 233　八起正法先生編",
    "contentType": "",
    "summary": "웹 편집자는 소노가시라 히로치카 회장이 신지 선생의 죽음을 어떻게 기록했는지 요약한다. 다카하시 신지 선생은 자신이 예언했다는 대로 6월 25일, 48세에 세상을 떠났다. 그보다 이틀 전인 23일, 이유는 말할 수 없지만 무조건 도쿄로 와 달라는 전화...",
    "body": "웹 편집자는 소노가시라 히로치카 회장이 신지 선생의 죽음을 어떻게 기록했는지 요약한다. 다카하시 신지 선생은 자신이 예언했다는 대로 6월 25일, 48세에 세상을 떠났다. 그보다 이틀 전인 23일, 이유는 말할 수 없지만 무조건 도쿄로 와 달라는 전화를 받고 소노가시라 회장이 상경했다. 그때 신지 선생은 이미 혼수상태였던 듯하다고 한다. 야오키 빌딩에는 당시 GLA 도쿄본부 이사들, GLA 간사이본부 이사 세 명, 당시 GLA 서일본본부장이던 소노가시라 회장이 모였다. 그 밖에 아내 다카하시 가즈에, 딸 다카하시 게이코, 친동생 다카하시 고와도 있었다고 한다. 사람은 죽을 때 어디에 있든 자기 집으로 돌아가 죽고 싶어 하는 법인데, 신지 선생은 일주일 전 야오키 빌딩으로 옮겨 평소 사용하던 방에 누워 있었다고 한다. 소노가시라 회장은 24일 밤에도 한숨도 자지 않고 신지 선생이 세상을 떠난 뒤의 일을 생각했던 듯하다고 원문은 전한다. 25일 아침, 친동생 고와가 “사우나 목욕이라도 하시지요”라고 권하자 간부 한 명이 “그러면 그렇게 하겠습니다”라며 일어섰다. 위대한 스승이 세상을 떠나기 직전에 너무도 경솔한 행동이라고 여긴 소노가시라 회장은 혼자 다른 행동을 했다.\n\n그는 생활과 활동의 기반이 바뀌어 새로운 결의로 행동을 시작해야 할 때면 늘 낡은 신발을 버리고 새 신발을 신었다고 한다. 다른 강사들이 사우나에 간다며 나간 사이, 소노가시라 회장은 혼자 신발 가게로 달려갔다. 새 신발을 신고 돌아온 지 얼마 지나지 않아 신지 선생이 세상을 떠났다고 한다. 이 항목은 소노가시라 회장의 관점과 웹 편집자의 요약을 옮긴 것이다. 함께 있던 다른 사람들의 생각이나 행동 이유까지 확인된 기록으로 확대하지 않았다.",
    "notes": "",
