    "title": "소노가시라 히로치카의 「위대한 출가」 전반부",
    "origTitle": "「高橋信次師物語」 真のメシヤの記録 234　八起正法先生編",
    "contentType": "",
    "summary": "「위대한 출가」 - 소노가시라 히로치카 “그리스도의 부활과 같은 기적이 일어나기를 계속 기도했지만 우리의 기도는 허망했습니다. 다카하시 선생님의 육체는 혹사로 인해 신체 생리의 한계를 넘어 회복할 수 없는 상태가 되어 있었습니다. 나는 그곳에서 여래의...",
    "body": "「위대한 출가」 - 소노가시라 히로치카\n\n“그리스도의 부활과 같은 기적이 일어나기를 계속 기도했지만 우리의 기도는 허망했습니다. 다카하시 선생님의 육체는 혹사로 인해 신체 생리의 한계를 넘어 회복할 수 없는 상태가 되어 있었습니다. 나는 그곳에서 여래의 자비로 가득한 숭고한 죽음을 보았습니다. 선생님은 자기 육체의 마지막 한 호흡까지도 중생을 위해 모두 바쳤습니다. 자신을 위해서는 살지 못한 것입니다. 찾는 사람이 있으면 이미 한계를 넘긴 몸을 혹사하면서도 ‘법’을 설하러 갔습니다. 지금으로부터 2,500년 전 인도에서 석존은 29세에 출가했습니다. 나는 이번에 다카하시 선생님이 왜 죽기 일주일 전 오모리의 자택을 떠났는지 생각했습니다.\n\n그때 내 머리에 떠오른 것은 ‘이것이 출가다’라는 생각이었습니다.\n\n‘위대한 출가다.’ 다카하시 선생님이 왜 오모리의 자택을 떠났는지 생각하기 시작한 지 1분도 되지 않아 나는 하늘의 음성을 들었습니다. 인도 시대의 출가는 29세였지만, 이번에는 48세에 죽기 직전 다시 출가한 것입니다.\n\n‘위대한 출가다.’ 하늘의 음성을 들은 순간 다카하시 선생님의 육체가 황금빛으로 빛났고, 바로 그때 허공에서 선생님의 황금빛 모습을 보았습니다.” 하늘의 음성과 황금빛 형상은 소노가시라 히로치카가 자신의 영적 체험으로 기록한 내용이다.",
