    "title": "「위대한 출가」 후반부와 혈연을 넘어선 정법",
    "origTitle": "",
    "contentType": "",
    "summary": "원제 표기: 「高橋信次師物語」 真のメシヤの記録 233 八起正法先生編 번호 주의: 정리 순서와 FC2 묶음의 실제 위치는 235번이지만, 원제에는 233번이 다시 적혀 있다. 번역에서는 항목을 235번으로 정리하되 원제의 중복 오기를 그대로 밝혔다. 소...",
    "body": "원제 표기: 「高橋信次師物語」 真のメシヤの記録 233　八起正法先生編 번호 주의: 정리 순서와 FC2 묶음의 실제 위치는 235번이지만, 원제에는 233번이 다시 적혀 있다. 번역에서는 항목을 235번으로 정리하되 원제의 중복 오기를 그대로 밝혔다. 소노가시라 히로치카의 「위대한 출가」는 다음과 같이 이어진다.\n\n“그 모습도 사라지고 그곳에는 보통 사람의 죽음과 다르지 않은 모습이 있었습니다. [……] 그렇다면 다카하시 선생님은 왜 마지막 순간이 다가오자 자택을 떠났던 것일까요? 나는 그곳에서 ‘위대한 출가’를 보았습니다. 우리는 이 지상을 떠날 때 이 지상의 그 무엇에도 집착해서는 안 된다는 가르침을 받았습니다. 돈·물건·지위·명예뿐 아니라 사람에게도 집착해서는 안 됩니다. [……] 다카하시 선생님의 자비는 전 인류에게 두루 미친다고 설해졌듯이, 선생님이 사랑한 대상은 가족만이 아니었습니다. 선생님이 가족만 사랑했다고 생각하는 사람이 있다면, 그것은 다카하시 신지 선생님을, 나아가 석존까지도 왜곡하는 일입니다. 다카하시 신지 선생님이 오모리 자택에서 돌아가셨다면 ‘다카하시 집안사람의 죽음’이라는 인상이 강해져, 선생님이 설한 ‘정법’까지 다카하시 집안의 것으로 사유화될 우려가 있었습니다. 다카하시 선생님이 설한 ‘정법’도, 선생님의 육체도 다카하시 집안의 것으로 사유화해서는 안 됩니다. [……] 다카하시 선생님은 전 인류의 스승이지, 단지 다카하시라는 한 씨족에 속한 분이 아니었습니다.\n\n‘나는 다카하시라는 한 씨족에 속한 인간이 아니다. 내 육체도 내 혼도 모두 전 인류의 것이다.’ 다카하시 신지 선생님의 ‘위대한 출가’는 정법을 부모·자녀·부부 같은 혈연에 집착시켜서는 안 된다는 사실을 가르쳤습니다. 혈연은 이 지상에서 육체를 가질 때 거치는 절차일 뿐이며, 혈연을 초월하고 거기에 사로잡히지 않은 채 정법을 정견(正見), 곧 바르게 보아야 한다는 가르침이었습니다.” 원문은 이 글의 출전을 월간 『정법(正法)』으로 밝힌다. 가족·육체·정법의 ‘사유화’에 관한 평가는 소노가시라 히로치카의 종교적 해석이다.",
    "notes": "",
