    "title": "[후기] 자료를 모아 ‘신지 사(信次師)’ 이야기로",
    "origTitle": "後記 - 資料を集めて「信次師」物語へ",
    "contentType": "웹 편집자의 집필 회고 및 감사 맺음말",
    "summary": "웹 편집자는 다카하시 신지 선생의 책을 낼 수 있으면 좋겠다고 생각하며 자료를 모으기 시작한 때가 첫 번째 뇌졸중에서 회복한 뒤인 쇼와 58년(1983년)이었고, 재활 치료 중에 결심했다고 회고한다. 그때 말조차 분명하지 않았던 자신의 정법 강의를 묵...",
    "body": "웹 편집자는 다카하시 신지 선생의 책을 낼 수 있으면 좋겠다고 생각하며 자료를 모으기 시작한 때가 첫 번째 뇌졸중에서 회복한 뒤인 쇼와 58년(1983년)이었고, 재활 치료 중에 결심했다고 회고한다.\n\n그때 말조차 분명하지 않았던 자신의 정법 강의를 묵묵히 들어 준 사람은 연로한 어머니였다고 한다. 이후의 기록과 취재 노트를 보면 여러 일이 있었다는 것을 알 수 있다고 했다. 그는 다카하시 신지를 가리키는 호칭을\n\n‘다카하시 신지 선생’, ‘다카하시 선생’, ‘다카하시 씨’, ‘다카하시 사(師)’, ‘신지’, ‘신지 씨’, ‘신지 선생’ 등으로 거듭 바꾸어 보다가, 이번의 ‘신지 사(信次師)’로 정착했다고 설명한다. 그동안 대형 출판사에 원고를 몇 번이나 가져갔지만 “종교와 관련된 것은……”이라며 냉정하게 거절당했다. 비용을 절반씩 부담한다면 가능하다는 제안도 있었으나, 그는 쉰이 넘어 새로 배우는 셈으로 인터넷에 빠져들었다. 라디오 제작이라면 자신 있었지만 컴퓨터는 처음이었으므로 홈페이지 제작 프로그램과 씨름하는 나날을 보냈다. 900만 자에 달하는 거대한 홈페이지를 만들며 어깨까지 상했고, 해커로 보이는 존재 때문에도 고생했다. 사이트를 세우면 사라지고 다시 세우면 또 사라지는 일이 5년 동안 여러 차례 있었다고 한다. 가장 자주 사라진 것은 「심행(心行)」과 「감사의 기도」뿐이었다. 편집자는 “누군가에게 몹시 불편한 내용이었던 모양”이라고 추측한다. 그러는 동안 반쯤 포기하고 흘러가는 대로 시간을 보냈다. 사라지면 언젠가 다시 올리겠다고 생각을 바꾸자 화도 나지 않고 마음이 편해졌다고 한다. 그렇게 5년째에는 방문자가 55만 명에 이르렀다. 그 기간에 다카하시 선생의 강연 비디오테이프를 많이 소장한 사람에게서 테이프 목록을 받아 강연 날짜와 제목을 덧붙였고, 그 덕분에 내용도 충실하게 만들 수 있었다. 온 힘을 다해 일하다 보니 “자력의 극한에는 타력이 있다”는 사실도 실감했다고 한다. 여러모로 힘을 보태는 사람이 어딘가에 있다는 생각에 용기가 솟았다고 적는다. 편집자는 두 차례 뇌출혈로 쓰러져 걸음이 불편하지만 자전거와 자동차는 탈 수 있고, 정밀한 라디오 제작을 해 온 덕분인지 신기하게도 손만은 온전히 남았다고 회고한다. 소노가시라 선생도 3년 동안 몸을 움직이거나 말을 하지 못했지만, 수십 년 동안 글을 써 온 덕분인지 손가락은 잘 움직여 필담을 할 수 있었다고 덧붙인다. 편집자는 부모가 자신의 이름에 “사람의 거울이 되어라”라는 훌륭하지만 책임도 무거운 뜻을 담아 주었다고 했다. 그러면서 남은 삶에는 “좋아, 할 수 있는 데까지 한번 해 볼까!”라고 생각한다고 글을 맺는다. 헤이세이 15년(2003년) 5월 16일, 합장(合掌)",
    "notes": "이상, 원문 맨 마지막에는 다시 合唱이라고 적혀 있다. 이는 ‘합창’을 뜻하는 말이며, 바로 앞 문맥과 통상적인 맺음말로 보아 合掌의 오기로 판단된다. 번역에서는 본문의 맺음말을 ‘합장’으로 옮기고 마지막 오기를 따로 밝혔다. 원문·자료 대조 참고\n\n• 231~236번은 두 첨부 강연 PDF에 수록된 강연 전문이 아니라, 책·월간지 인용과 웹 편집자의 해설·후기로 구성되어 있다.\n\n• 231~232번은 『진창세기·지옥편』에서 가져온 글로 소개되며, 230번의 저작 관련 문제 제기와 함께 읽어야 자료의 성격을 오해하지 않는다.\n\n• 235번 원제에는 233번이 중복 표기되어 있다. 정리 번호 235는 바로 앞 234번의 「위대한 출가」가 이어지는 실제 순서에 따라 확정했다.\n\n• 236번의 병든 장기는 기준 원문에는 ‘간과 신장’, 별도의 재수록 자료에는 ‘간과 췌장’으로 달리 적혀 있다. 번역은 기준 원문을 보존하고 차이만 밝혔다.\n\n• 236번의 3억 6,500여만 년, 전 세계 20퍼센트, 460여 건의 특허권 등은 원문 수치와 주장 그대로 옮겼으며 번역 과정에서 사실로 인증하지 않았다.\n\n• 원문의 마지막 合唱은 문맥상 合掌의 오기로 보아, 본문과 교정 주기를 분리했다.",
